INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('78', '78_physical_commerce.sql', 'd1e07fc004eaec6dc45c5c5279cce50fef9c5942112a12687c980333b99e252f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 79_stripe_account_reset.sql
/* A creator's payments connection can be reset without losing what it was: stripe_previous_account_id (the connected account Storelib was linked to before), stripe_account_reset_at (when that link was let go) and stripe_account_reset_reason (legacy_platform when Stripe says the account is not reachable from the current platform, which is what happens to every creator linked before Storelib moved to its new Stripe Connect platform; creator_disconnect when the creator chose Start over; incomplete_replaced when an unfinished account was swapped for one that stays inside Storelib). The live link stays stripe_account_id, which is cleared so the creator can set up a fresh account under the current platform instead of being stuck on one Storelib can no longer read. Orders, payouts, refunds and the ledger are never touched: each keeps the Stripe ids it was written with. Only the server writes these three, and they are private like the other Stripe columns (parts 63 and 77): the private list and the guard trigger are restated in full with them added. Safe to run more than once. Until it runs, a reset still happens and the old account id is written to the server log instead. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'stripe account reset: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_previous_account_id text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_reason text; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_stripe_account_reset_reason_check; ALTER TABLE public.creators ADD CONSTRAINT creators_stripe_account_reset_reason_check CHECK (stripe_account_reset_reason IS NULL OR stripe_account_reset_reason IN ('legacy_platform','creator_disconnect','incomplete_replaced')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('79', '79_stripe_account_reset.sql', 'db884bc84c36f58f1a9b50865612dbba59e10f8fac42619634b73cde48ce427b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 80_free_plan_fee_5pct.sql
/* The Storelib fee on the Free plan is 5% (it was 6%), and on small orders 11.25% (it was 12.25%). Checkout reads its fee rules from the active row of storelib_fee_rule_versions when there is one and from the code when there is not (lib/payments/fees/active.ts); the code says 5% now, and this makes the database say the same, so production moves whichever it is reading. The small-order rate moves with the standard one because it is not a separate price: under the threshold the fixed fee is dropped and the percentage carries it, so both move by the same point or the fee would fall as a price rose past the threshold ($3.99 would pay 49c and $4.00 45c). A new version is written and made the active one; the version that was active is retired, not changed, and everything it held is carried forward except the two Free rates: the per-currency thresholds and fixed fees, and the paid plan rates, which stay exactly as they were. Orders already paid keep the fee and the rule version they were charged under (each order row has its own). Stripe's processing fee is not set here. Nothing where the table does not exist (the code is then the rule, and says 5%). Safe to run more than once: once this version exists it is never written again, so a later version an admin activates is never overwritten by running this again. */
DO $$ DECLARE v_old_cfg jsonb; v_old_key text; v_cfg jsonb; BEGIN IF to_regclass('public.storelib_fee_rule_versions') IS NULL THEN RAISE NOTICE 'free plan fee: there are no fee versions in this database, so the code rule applies, and it is 5%%.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM public.storelib_fee_rule_versions WHERE version_key = '2026-10-storelib-v3-free-5pct') THEN RAISE NOTICE 'free plan fee: version 2026-10-storelib-v3-free-5pct is already written, nothing to do.'; RETURN; END IF; SELECT config, version_key INTO v_old_cfg, v_old_key FROM public.storelib_fee_rule_versions WHERE status = 'active' LIMIT 1; v_cfg := COALESCE(v_old_cfg, '{"versionKey":"2026-10-storelib-v3-free-5pct","freeStandardRate":0.05,"freeMicroRate":0.1125,"paidStandardRate":0.03,"paidMicroRate":0.0925,"currencies":[{"currency":"USD","microThresholdMinor":400,"fixedFeeMinor":25,"enabled":true},{"currency":"RON","microThresholdMinor":1840,"fixedFeeMinor":115,"enabled":true},{"currency":"EUR","microThresholdMinor":368,"fixedFeeMinor":23,"enabled":true},{"currency":"GBP","microThresholdMinor":316,"fixedFeeMinor":20,"enabled":true},{"currency":"CAD","microThresholdMinor":544,"fixedFeeMinor":34,"enabled":true},{"currency":"AUD","microThresholdMinor":600,"fixedFeeMinor":38,"enabled":true},{"currency":"JPY","microThresholdMinor":600,"fixedFeeMinor":40,"enabled":true}]}'::jsonb) || jsonb_build_object('versionKey', '2026-10-storelib-v3-free-5pct', 'freeStandardRate', 0.05, 'freeMicroRate', 0.1125); UPDATE public.storelib_fee_rule_versions SET status = 'retired' WHERE status = 'active'; INSERT INTO public.storelib_fee_rule_versions (version_key, status, config, created_by, change_summary) VALUES ('2026-10-storelib-v3-free-5pct', 'active', v_cfg, 'run-now part 80', 'Free plan Storelib fee 6% to 5% (small orders 12.25% to 11.25%). Currencies and paid plan rates carried forward unchanged.'); IF to_regclass('public.admin_payments_audit_log') IS NOT NULL THEN INSERT INTO public.admin_payments_audit_log (action, actor, before_state, after_state) VALUES ('fee_version_activated', 'run-now part 80', CASE WHEN v_old_key IS NULL THEN NULL ELSE jsonb_build_object('version_key', v_old_key) END, jsonb_build_object('version_key', '2026-10-storelib-v3-free-5pct', 'freeStandardRate', 0.05, 'freeMicroRate', 0.1125)); END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('80', '80_free_plan_fee_5pct.sql', 'a547e31745975933c58c7d9b9a0e44c34b17923e441a9ec625d5ff39084d450e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 81_communities.sql
/* Storelib Communities: a creator's own community with spaces, posts, comments, reactions, polls, chat, events, a classroom of course products, members with roles and tiers, points and levels, invites, reports, an append only audit log, an in app inbox per member and a job queue, all switched off until an admin turns them on. `platform_flags` holds platform switches, seeded with `communities` off. `communities` is one community (its address, name, who may join and how, what it shows); `community_tiers` the ways to belong (free, or sold by a membership or community product, prices stay on the product); `community_access_products` the products whose owners get a tier; `products.community_id` marks a product that sells a tier. `community_members` is one row per person per community with status, role, tier, where access came from, points and level; member_count counts active rows only and a trigger keeps it. Posts, comments, reactions, bookmarks, polls and votes, reports, invites and their uses, attached courses, events and RSVPs, chat messages and read marks, levels, point events, badges, activity, notifications, daily stats, videos and video webhook events each get their table, with counters kept by triggers and every repeatable action keyed so it happens once. Functions do the parts that must be atomic: a vote (one choice unless the poll allows more), an RSVP (a full event puts you on the waitlist), an invite redeemed (each person once, never past its limit), points awarded once per key, jobs claimed without two workers taking one, and a leaderboard summed over the last days. Every table is server only (row level security on, nothing granted to visitors) except three reads: a published public or unlisted community's public columns, chat messages of a space a signed in member may read (for realtime), and a member's own notifications. Needs parts 66 and 75 for the kept rows and the membership link. Until it runs, community pages say communities are not set up and nothing else changes. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.platform_flags (key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, note text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by text, CONSTRAINT platform_flags_key_shape CHECK (key ~ '^[a-z][a-z0-9_]{1,62}$'));
INSERT INTO public.platform_flags (key, enabled, note) VALUES ('communities', false, 'Communities, memberships in them, member feeds, events and community discovery across Storelib.') ON CONFLICT (key) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid REFERENCES public.creators(id) ON DELETE SET NULL, owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, slug text NOT NULL, name text NOT NULL, tagline text, description text, logo_url text, cover_url text, cover_video_id uuid, visibility text NOT NULL DEFAULT 'public', access text NOT NULL DEFAULT 'free', status text NOT NULL DEFAULT 'draft', category text, language text NOT NULL DEFAULT 'en', member_count integer NOT NULL DEFAULT 0, post_count integer NOT NULL DEFAULT 0, discovery_enabled boolean NOT NULL DEFAULT true, approval_required boolean NOT NULL DEFAULT false, default_role text NOT NULL DEFAULT 'member', directory_enabled boolean NOT NULL DEFAULT true, classroom_enabled boolean NOT NULL DEFAULT true, events_enabled boolean NOT NULL DEFAULT true, chat_enabled boolean NOT NULL DEFAULT true, gamification_enabled boolean NOT NULL DEFAULT false, rules jsonb NOT NULL DEFAULT '[]'::jsonb, faq jsonb NOT NULL DEFAULT '[]'::jsonb, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, links jsonb NOT NULL DEFAULT '[]'::jsonb, onboarding jsonb NOT NULL DEFAULT '{}'::jsonb, seo_title text, seo_description text, trending_score numeric NOT NULL DEFAULT 0, trending_at timestamptz, platform_hidden boolean NOT NULL DEFAULT false, suspended_at timestamptz, suspended_reason text, archived_at timestamptz, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT communities_slug_key UNIQUE (slug), CONSTRAINT communities_slug_shape CHECK (char_length(slug) BETWEEN 3 AND 48 AND slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'), CONSTRAINT communities_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT communities_tagline_len CHECK (tagline IS NULL OR char_length(tagline) <= 160), CONSTRAINT communities_description_len CHECK (description IS NULL OR char_length(description) <= 20000), CONSTRAINT communities_seo_len CHECK ((seo_title IS NULL OR char_length(seo_title) <= 200) AND (seo_description IS NULL OR char_length(seo_description) <= 500)), CONSTRAINT communities_visibility_check CHECK (visibility IN ('public', 'private', 'unlisted')), CONSTRAINT communities_access_check CHECK (access IN ('free', 'paid', 'invite_only', 'product', 'custom')), CONSTRAINT communities_status_check CHECK (status IN ('draft', 'published', 'archived', 'suspended')), CONSTRAINT communities_default_role_check CHECK (default_role IN ('member')), CONSTRAINT communities_counts_check CHECK (member_count >= 0 AND post_count >= 0), CONSTRAINT communities_json_shape CHECK (jsonb_typeof(rules) = 'array' AND jsonb_typeof(faq) = 'array' AND jsonb_typeof(benefits) = 'array' AND jsonb_typeof(links) = 'array' AND jsonb_typeof(onboarding) = 'object'));
CREATE INDEX IF NOT EXISTS communities_creator_idx ON public.communities (creator_id);
CREATE INDEX IF NOT EXISTS communities_owner_idx ON public.communities (owner_user_id);
CREATE INDEX IF NOT EXISTS communities_discover_idx ON public.communities (status, visibility, discovery_enabled, trending_score DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS communities_category_idx ON public.communities (category);
CREATE TABLE IF NOT EXISTS public.community_tiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, description text, position integer NOT NULL DEFAULT 0, kind text NOT NULL DEFAULT 'free', billing text, product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, benefits jsonb NOT NULL DEFAULT '[]'::jsonb, is_default boolean NOT NULL DEFAULT false, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_tiers_product_key UNIQUE (product_id), CONSTRAINT community_tiers_name_len CHECK (char_length(name) BETWEEN 1 AND 60), CONSTRAINT community_tiers_description_len CHECK (description IS NULL OR char_length(description) <= 500), CONSTRAINT community_tiers_kind_check CHECK (kind IN ('free', 'paid')), CONSTRAINT community_tiers_billing_check CHECK (billing IS NULL OR billing IN ('recurring', 'one_time')), CONSTRAINT community_tiers_benefits_shape CHECK (jsonb_typeof(benefits) = 'array'));
CREATE INDEX IF NOT EXISTS community_tiers_community_idx ON public.community_tiers (community_id, position);
CREATE UNIQUE INDEX IF NOT EXISTS community_tiers_one_default ON public.community_tiers (community_id) WHERE is_default;
CREATE TABLE IF NOT EXISTS public.community_access_products (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, tier_id uuid NOT NULL REFERENCES public.community_tiers(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tier_id, product_id));
CREATE INDEX IF NOT EXISTS community_access_products_product_idx ON public.community_access_products (product_id);
CREATE INDEX IF NOT EXISTS community_access_products_community_idx ON public.community_access_products (community_id);
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'communities: there is no products table, products.community_id is not added.'; RETURN; END IF; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS community_id uuid REFERENCES public.communities(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS products_community_idx ON public.products (community_id) WHERE community_id IS NOT NULL; END $do$;
CREATE TABLE IF NOT EXISTS public.community_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'active', role text NOT NULL DEFAULT 'member', tier_id uuid REFERENCES public.community_tiers(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'free', source_membership_id uuid REFERENCES public.memberships(id) ON DELETE SET NULL, source_product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, source_order_id uuid, invite_id uuid, invited_by uuid, request_note text, requested_at timestamptz, approved_by uuid, joined_at timestamptz, last_active_at timestamptz, expires_at timestamptz, points integer NOT NULL DEFAULT 0, level integer NOT NULL DEFAULT 1, muted_until timestamptz, ban_reason text, banned_at timestamptz, banned_by uuid, removed_at timestamptz, notify_level text NOT NULL DEFAULT 'important', email_announcements boolean NOT NULL DEFAULT true, email_events boolean NOT NULL DEFAULT true, onboarded_at timestamptz, bio text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_members_once UNIQUE (community_id, user_id), CONSTRAINT community_members_status_check CHECK (status IN ('pending', 'active', 'paused', 'cancelled', 'expired', 'banned', 'removed')), CONSTRAINT community_members_role_check CHECK (role IN ('owner', 'admin', 'moderator', 'member')), CONSTRAINT community_members_source_check CHECK (source IN ('owner', 'free', 'subscription', 'purchase', 'product', 'invite', 'manual', 'platform')), CONSTRAINT community_members_notify_check CHECK (notify_level IN ('all', 'important', 'mentions', 'none')), CONSTRAINT community_members_level_check CHECK (level BETWEEN 1 AND 20), CONSTRAINT community_members_note_len CHECK (request_note IS NULL OR char_length(request_note) <= 500), CONSTRAINT community_members_bio_len CHECK (bio IS NULL OR char_length(bio) <= 280));
CREATE INDEX IF NOT EXISTS community_members_user_idx ON public.community_members (user_id, status);
CREATE INDEX IF NOT EXISTS community_members_joined_idx ON public.community_members (community_id, status, joined_at DESC);
CREATE INDEX IF NOT EXISTS community_members_points_idx ON public.community_members (community_id, points DESC) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS community_members_active_idx ON public.community_members (community_id, last_active_at DESC);
CREATE INDEX IF NOT EXISTS community_members_membership_idx ON public.community_members (source_membership_id) WHERE source_membership_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.community_spaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, slug text NOT NULL, name text NOT NULL, description text, icon text, kind text NOT NULL DEFAULT 'feed', position integer NOT NULL DEFAULT 0, view_access jsonb NOT NULL DEFAULT '{}'::jsonb, post_role text NOT NULL DEFAULT 'member', comments_enabled boolean NOT NULL DEFAULT true, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_spaces_slug_once UNIQUE (community_id, slug), CONSTRAINT community_spaces_slug_shape CHECK (char_length(slug) BETWEEN 1 AND 48 AND slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'), CONSTRAINT community_spaces_name_len CHECK (char_length(name) BETWEEN 1 AND 40), CONSTRAINT community_spaces_description_len CHECK (description IS NULL OR char_length(description) <= 200), CONSTRAINT community_spaces_icon_len CHECK (icon IS NULL OR char_length(icon) <= 40), CONSTRAINT community_spaces_kind_check CHECK (kind IN ('feed', 'chat', 'announcements', 'resources')), CONSTRAINT community_spaces_post_role_check CHECK (post_role IN ('member', 'moderator', 'admin')), CONSTRAINT community_spaces_access_shape CHECK (jsonb_typeof(view_access) = 'object'));
CREATE INDEX IF NOT EXISTS community_spaces_community_idx ON public.community_spaces (community_id, position);
CREATE TABLE IF NOT EXISTS public.community_feed_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, kind text NOT NULL DEFAULT 'post', title text, body text NOT NULL DEFAULT '', body_text text NOT NULL DEFAULT '', media jsonb NOT NULL DEFAULT '[]'::jsonb, pinned boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, locked boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'published', removed_by uuid, removed_reason text, removed_at timestamptz, edited_at timestamptz, reaction_count integer NOT NULL DEFAULT 0, comment_count integer NOT NULL DEFAULT 0, last_activity_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT community_feed_posts_kind_check CHECK (kind IN ('post', 'announcement', 'poll', 'resource')), CONSTRAINT community_feed_posts_status_check CHECK (status IN ('published', 'removed', 'deleted')), CONSTRAINT community_feed_posts_title_len CHECK (title IS NULL OR char_length(title) <= 200), CONSTRAINT community_feed_posts_body_len CHECK (char_length(body) <= 20000 AND char_length(body_text) <= 20000), CONSTRAINT community_feed_posts_media_shape CHECK (jsonb_typeof(media) = 'array'));
CREATE INDEX IF NOT EXISTS community_feed_posts_latest_idx ON public.community_feed_posts (community_id, created_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS community_feed_posts_pinned_idx ON public.community_feed_posts (community_id, pinned DESC, created_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS community_feed_posts_space_idx ON public.community_feed_posts (space_id, created_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS community_feed_posts_author_idx ON public.community_feed_posts (author_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_feed_posts_popular_idx ON public.community_feed_posts (community_id, reaction_count DESC, created_at DESC) WHERE status = 'published';
CREATE TABLE IF NOT EXISTS public.community_feed_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_feed_posts(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, parent_id uuid REFERENCES public.community_feed_comments(id) ON DELETE SET NULL, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'published', reaction_count integer NOT NULL DEFAULT 0, removed_by uuid, removed_reason text, edited_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT community_feed_comments_status_check CHECK (status IN ('published', 'removed', 'deleted')), CONSTRAINT community_feed_comments_body_len CHECK (char_length(body) <= 5000));
CREATE INDEX IF NOT EXISTS community_feed_comments_post_idx ON public.community_feed_comments (post_id, created_at);
CREATE INDEX IF NOT EXISTS community_feed_comments_parent_idx ON public.community_feed_comments (parent_id);
CREATE TABLE IF NOT EXISTS public.community_reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, target_type text NOT NULL, target_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'like', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_reactions_once UNIQUE (target_type, target_id, user_id, kind), CONSTRAINT community_reactions_target_check CHECK (target_type IN ('post', 'comment', 'message')), CONSTRAINT community_reactions_kind_len CHECK (char_length(kind) BETWEEN 1 AND 32));
CREATE INDEX IF NOT EXISTS community_reactions_community_idx ON public.community_reactions (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_reactions_user_idx ON public.community_reactions (user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_bookmarks (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES public.community_feed_posts(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id));
CREATE INDEX IF NOT EXISTS community_bookmarks_user_idx ON public.community_bookmarks (user_id, community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_polls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_feed_posts(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, question text NOT NULL, multiple boolean NOT NULL DEFAULT false, closes_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_polls_post_key UNIQUE (post_id), CONSTRAINT community_polls_question_len CHECK (char_length(question) BETWEEN 1 AND 200));
CREATE TABLE IF NOT EXISTS public.community_poll_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), poll_id uuid NOT NULL REFERENCES public.community_polls(id) ON DELETE CASCADE, label text NOT NULL, position integer NOT NULL DEFAULT 0, vote_count integer NOT NULL DEFAULT 0, CONSTRAINT community_poll_options_label_len CHECK (char_length(label) BETWEEN 1 AND 100));
CREATE INDEX IF NOT EXISTS community_poll_options_poll_idx ON public.community_poll_options (poll_id, position);
CREATE TABLE IF NOT EXISTS public.community_poll_votes (poll_id uuid NOT NULL REFERENCES public.community_polls(id) ON DELETE CASCADE, option_id uuid NOT NULL REFERENCES public.community_poll_options(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (option_id, user_id));
CREATE INDEX IF NOT EXISTS community_poll_votes_user_idx ON public.community_poll_votes (poll_id, user_id);
CREATE TABLE IF NOT EXISTS public.community_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, reporter_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, note text, status text NOT NULL DEFAULT 'open', assigned_to uuid, resolution text, resolved_by uuid, resolved_at timestamptz, escalated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_reports_target_check CHECK (target_type IN ('post', 'comment', 'member', 'message')), CONSTRAINT community_reports_reason_check CHECK (reason IN ('spam', 'abuse', 'harassment', 'off_topic', 'illegal', 'other')), CONSTRAINT community_reports_status_check CHECK (status IN ('open', 'reviewing', 'resolved', 'dismissed')), CONSTRAINT community_reports_note_len CHECK ((note IS NULL OR char_length(note) <= 500) AND (resolution IS NULL OR char_length(resolution) <= 1000)));
CREATE UNIQUE INDEX IF NOT EXISTS community_reports_one_open ON public.community_reports (reporter_id, target_type, target_id) WHERE status IN ('open', 'reviewing');
CREATE INDEX IF NOT EXISTS community_reports_queue_idx ON public.community_reports (community_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS community_reports_escalated_idx ON public.community_reports (created_at DESC) WHERE escalated;
CREATE TABLE IF NOT EXISTS public.community_audit_log (id bigserial PRIMARY KEY, community_id uuid REFERENCES public.communities(id) ON DELETE SET NULL, actor_id uuid, actor_kind text NOT NULL DEFAULT 'member', action text NOT NULL, target_type text, target_id text, target_label text, reason text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_audit_log_actor_check CHECK (actor_kind IN ('member', 'platform', 'system')));
CREATE INDEX IF NOT EXISTS community_audit_log_community_idx ON public.community_audit_log (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, token_hash text NOT NULL, email text, tier_id uuid REFERENCES public.community_tiers(id) ON DELETE SET NULL, max_uses integer, uses integer NOT NULL DEFAULT 0, expires_at timestamptz, revoked_at timestamptz, created_by uuid, complimentary boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_invites_token_key UNIQUE (token_hash), CONSTRAINT community_invites_token_shape CHECK (token_hash ~ '^[0-9a-f]{64}$'), CONSTRAINT community_invites_email_lower CHECK (email IS NULL OR email = lower(email)), CONSTRAINT community_invites_uses_check CHECK (uses >= 0 AND (max_uses IS NULL OR max_uses >= 1)));
CREATE INDEX IF NOT EXISTS community_invites_community_idx ON public.community_invites (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_invite_uses (invite_id uuid NOT NULL REFERENCES public.community_invites(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (invite_id, user_id));
CREATE TABLE IF NOT EXISTS public.community_courses (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, position integer NOT NULL DEFAULT 0, access jsonb NOT NULL DEFAULT '{}'::jsonb, drip_days integer, added_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (community_id, product_id), CONSTRAINT community_courses_access_shape CHECK (jsonb_typeof(access) = 'object'), CONSTRAINT community_courses_drip_check CHECK (drip_days IS NULL OR drip_days BETWEEN 0 AND 3650));
CREATE INDEX IF NOT EXISTS community_courses_product_idx ON public.community_courses (product_id);
CREATE TABLE IF NOT EXISTS public.community_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, title text NOT NULL, description text, cover_url text, kind text NOT NULL DEFAULT 'online', starts_at timestamptz NOT NULL, ends_at timestamptz, timezone text NOT NULL DEFAULT 'UTC', location text, meeting_url text, livestream_url text, capacity integer, going_count integer NOT NULL DEFAULT 0, access jsonb NOT NULL DEFAULT '{}'::jsonb, host_id uuid, replay_video_id uuid, status text NOT NULL DEFAULT 'scheduled', reminder_24h_at timestamptz, reminder_1h_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_events_title_len CHECK (char_length(title) BETWEEN 1 AND 140), CONSTRAINT community_events_description_len CHECK (description IS NULL OR char_length(description) <= 10000), CONSTRAINT community_events_kind_check CHECK (kind IN ('online', 'in_person', 'live', 'workshop', 'ama', 'meetup')), CONSTRAINT community_events_times_check CHECK (ends_at IS NULL OR ends_at > starts_at), CONSTRAINT community_events_capacity_check CHECK (capacity IS NULL OR capacity >= 1), CONSTRAINT community_events_status_check CHECK (status IN ('scheduled', 'cancelled')), CONSTRAINT community_events_access_shape CHECK (jsonb_typeof(access) = 'object'));
CREATE INDEX IF NOT EXISTS community_events_community_idx ON public.community_events (community_id, starts_at);
CREATE INDEX IF NOT EXISTS community_events_upcoming_idx ON public.community_events (starts_at) WHERE status = 'scheduled';
CREATE TABLE IF NOT EXISTS public.community_event_rsvps (event_id uuid NOT NULL REFERENCES public.community_events(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'going', attended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (event_id, user_id), CONSTRAINT community_event_rsvps_status_check CHECK (status IN ('going', 'waitlist', 'cancelled')));
CREATE INDEX IF NOT EXISTS community_event_rsvps_queue_idx ON public.community_event_rsvps (event_id, status, updated_at);
CREATE INDEX IF NOT EXISTS community_event_rsvps_user_idx ON public.community_event_rsvps (user_id, community_id);
CREATE TABLE IF NOT EXISTS public.community_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, space_id uuid NOT NULL REFERENCES public.community_spaces(id) ON DELETE CASCADE, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL DEFAULT '', reply_to_id uuid REFERENCES public.community_messages(id) ON DELETE SET NULL, attachments jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'published', reaction_count integer NOT NULL DEFAULT 0, edited_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT community_messages_body_len CHECK (char_length(body) <= 4000), CONSTRAINT community_messages_status_check CHECK (status IN ('published', 'removed', 'deleted')), CONSTRAINT community_messages_attachments_shape CHECK (jsonb_typeof(attachments) = 'array'));
CREATE INDEX IF NOT EXISTS community_messages_space_idx ON public.community_messages (space_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_space_reads (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, space_id uuid NOT NULL REFERENCES public.community_spaces(id) ON DELETE CASCADE, last_read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, space_id));
CREATE TABLE IF NOT EXISTS public.community_levels (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, level integer NOT NULL, name text NOT NULL, min_points integer NOT NULL DEFAULT 0, reward text, PRIMARY KEY (community_id, level), CONSTRAINT community_levels_level_check CHECK (level BETWEEN 1 AND 20), CONSTRAINT community_levels_name_len CHECK (char_length(name) BETWEEN 1 AND 40), CONSTRAINT community_levels_points_check CHECK (min_points >= 0));
CREATE TABLE IF NOT EXISTS public.community_point_events (id bigserial PRIMARY KEY, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, points integer NOT NULL, reason text NOT NULL, source_key text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_point_events_once UNIQUE (community_id, user_id, source_key), CONSTRAINT community_point_events_reason_check CHECK (reason IN ('reaction_received', 'course_completed', 'event_attended', 'admin_award', 'admin_adjust')), CONSTRAINT community_point_events_points_check CHECK (points BETWEEN -100000 AND 100000), CONSTRAINT community_point_events_key_len CHECK (char_length(source_key) BETWEEN 1 AND 200));
CREATE INDEX IF NOT EXISTS community_point_events_recent_idx ON public.community_point_events (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_badges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, description text, icon text, kind text NOT NULL DEFAULT 'manual', rule jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_badges_name_len CHECK (char_length(name) BETWEEN 1 AND 60), CONSTRAINT community_badges_description_len CHECK (description IS NULL OR char_length(description) <= 300), CONSTRAINT community_badges_kind_check CHECK (kind IN ('manual', 'milestone', 'course', 'event', 'achievement')));
CREATE INDEX IF NOT EXISTS community_badges_community_idx ON public.community_badges (community_id);
CREATE TABLE IF NOT EXISTS public.community_member_badges (badge_id uuid NOT NULL REFERENCES public.community_badges(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, awarded_by uuid, awarded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (badge_id, user_id));
CREATE INDEX IF NOT EXISTS community_member_badges_member_idx ON public.community_member_badges (community_id, user_id);
CREATE TABLE IF NOT EXISTS public.community_activity (id bigserial PRIMARY KEY, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid, kind text NOT NULL, target_type text, target_id text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_activity_kind_check CHECK (kind IN ('joined', 'post', 'comment', 'reaction', 'lesson_completed', 'course_completed', 'rsvp', 'attended', 'level_up', 'left')));
CREATE INDEX IF NOT EXISTS community_activity_community_idx ON public.community_activity (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_activity_user_idx ON public.community_activity (user_id, created_at);
CREATE TABLE IF NOT EXISTS public.community_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, kind text NOT NULL, actor_id uuid, target_type text, target_id text, title text NOT NULL, body text, url text, read_at timestamptz, dedupe_key text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_notifications_dedupe_key UNIQUE (dedupe_key), CONSTRAINT community_notifications_kind_check CHECK (kind IN ('reaction', 'comment', 'reply', 'mention', 'announcement', 'event', 'event_reminder', 'course_available', 'level_up', 'membership', 'admin_message', 'report', 'join_request')), CONSTRAINT community_notifications_title_len CHECK (char_length(title) BETWEEN 1 AND 200), CONSTRAINT community_notifications_body_len CHECK (body IS NULL OR char_length(body) <= 500));
CREATE INDEX IF NOT EXISTS community_notifications_user_idx ON public.community_notifications (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_notifications_unread_idx ON public.community_notifications (user_id) WHERE read_at IS NULL;
CREATE TABLE IF NOT EXISTS public.community_jobs (id bigserial PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, run_at timestamptz NOT NULL DEFAULT now(), state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, lease_until timestamptz, idempotency_key text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, CONSTRAINT community_jobs_idempotency_key UNIQUE (idempotency_key), CONSTRAINT community_jobs_kind_check CHECK (kind IN ('fanout_announcement', 'fanout_event', 'event_reminder', 'recount', 'rollup', 'trending', 'video_poll')), CONSTRAINT community_jobs_state_check CHECK (state IN ('pending', 'running', 'done', 'failed')));
CREATE INDEX IF NOT EXISTS community_jobs_due_idx ON public.community_jobs (run_at, id) WHERE state = 'pending';
CREATE INDEX IF NOT EXISTS community_jobs_lease_idx ON public.community_jobs (lease_until) WHERE state = 'running';
CREATE TABLE IF NOT EXISTS public.community_daily_stats (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, day date NOT NULL, members integer NOT NULL DEFAULT 0, new_members integer NOT NULL DEFAULT 0, left_members integer NOT NULL DEFAULT 0, active_members integer NOT NULL DEFAULT 0, posts integer NOT NULL DEFAULT 0, comments integer NOT NULL DEFAULT 0, reactions integer NOT NULL DEFAULT 0, rsvps integer NOT NULL DEFAULT 0, lessons_completed integer NOT NULL DEFAULT 0, PRIMARY KEY (community_id, day));
CREATE TABLE IF NOT EXISTS public.media_videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, community_id uuid REFERENCES public.communities(id) ON DELETE SET NULL, provider text NOT NULL DEFAULT 'storage', status text NOT NULL DEFAULT 'uploading', storage_path text, provider_asset_id text, playback_id text, thumbnail_url text, duration_seconds integer, width integer, height integer, size_bytes bigint, mime text, captions_path text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT media_videos_provider_asset_once UNIQUE (provider, provider_asset_id), CONSTRAINT media_videos_provider_check CHECK (provider IN ('storage', 'mux', 'cloudflare', 'bunny')), CONSTRAINT media_videos_status_check CHECK (status IN ('uploading', 'processing', 'ready', 'failed')));
CREATE INDEX IF NOT EXISTS media_videos_creator_idx ON public.media_videos (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS media_videos_community_idx ON public.media_videos (community_id) WHERE community_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.media_video_events (provider text NOT NULL, event_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (provider, event_id));
CREATE OR REPLACE FUNCTION public.community_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN NEW.updated_at := now(); RETURN NEW; END $f$;
CREATE OR REPLACE FUNCTION public.community_member_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.community_id = NEW.community_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'active' THEN UPDATE public.communities SET member_count = greatest(member_count - 1, 0) WHERE id = OLD.community_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'active' THEN UPDATE public.communities SET member_count = member_count + 1 WHERE id = NEW.community_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_post_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.community_id = NEW.community_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'published' THEN UPDATE public.communities SET post_count = greatest(post_count - 1, 0) WHERE id = OLD.community_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'published' THEN UPDATE public.communities SET post_count = post_count + 1 WHERE id = NEW.community_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_comment_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.post_id = NEW.post_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'published' THEN UPDATE public.community_feed_posts SET comment_count = greatest(comment_count - 1, 0) WHERE id = OLD.post_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'published' THEN UPDATE public.community_feed_posts SET comment_count = comment_count + 1, last_activity_at = greatest(last_activity_at, NEW.created_at) WHERE id = NEW.post_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_reaction_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_type text; v_id uuid; v_step integer; BEGIN IF TG_OP = 'INSERT' THEN v_type := NEW.target_type; v_id := NEW.target_id; v_step := 1; ELSE v_type := OLD.target_type; v_id := OLD.target_id; v_step := -1; END IF; IF v_type = 'post' THEN UPDATE public.community_feed_posts SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; ELSIF v_type = 'comment' THEN UPDATE public.community_feed_comments SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; ELSIF v_type = 'message' THEN UPDATE public.community_messages SET reaction_count = greatest(reaction_count + v_step, 0) WHERE id = v_id; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_going_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.event_id = NEW.event_id THEN RETURN NULL; END IF; END IF; IF TG_OP IN ('UPDATE', 'DELETE') THEN IF OLD.status = 'going' THEN UPDATE public.community_events SET going_count = greatest(going_count - 1, 0) WHERE id = OLD.event_id; END IF; END IF; IF TG_OP IN ('INSERT', 'UPDATE') THEN IF NEW.status = 'going' THEN UPDATE public.community_events SET going_count = going_count + 1 WHERE id = NEW.event_id; END IF; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_vote_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE public.community_poll_options SET vote_count = vote_count + 1 WHERE id = NEW.option_id; ELSE UPDATE public.community_poll_options SET vote_count = greatest(vote_count - 1, 0) WHERE id = OLD.option_id; END IF; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_points_apply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_community uuid; v_user uuid; v_step integer; BEGIN IF TG_OP = 'INSERT' THEN v_community := NEW.community_id; v_user := NEW.user_id; v_step := NEW.points; ELSE v_community := OLD.community_id; v_user := OLD.user_id; v_step := -OLD.points; END IF; UPDATE public.community_members m SET points = m.points + v_step, level = coalesce((SELECT max(l.level) FROM public.community_levels l WHERE l.community_id = m.community_id AND l.min_points <= m.points + v_step), 1) WHERE m.community_id = v_community AND m.user_id = v_user; RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.community_audit_append_only() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.community_id IS NOT NULL AND NEW.community_id IS NULL AND (to_jsonb(NEW) - 'community_id') = (to_jsonb(OLD) - 'community_id') THEN RETURN NEW; END IF; END IF; RAISE EXCEPTION 'community_audit_log is append only: % is refused', lower(TG_OP) USING ERRCODE = '42501'; END $f$;
CREATE OR REPLACE FUNCTION public.community_cast_vote(p_poll uuid, p_user uuid, p_options uuid[]) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_poll public.community_polls%ROWTYPE; v_options uuid[]; v_valid integer; BEGIN SELECT * INTO v_poll FROM public.community_polls WHERE id = p_poll; IF NOT FOUND THEN RETURN 'not_found'; END IF; IF v_poll.closes_at IS NOT NULL AND v_poll.closes_at <= now() THEN RETURN 'closed'; END IF; v_options := ARRAY(SELECT DISTINCT o FROM unnest(coalesce(p_options, '{}'::uuid[])) AS o WHERE o IS NOT NULL); IF cardinality(v_options) > 1 AND NOT v_poll.multiple THEN RETURN 'too_many'; END IF; SELECT count(*) INTO v_valid FROM public.community_poll_options WHERE poll_id = p_poll AND id = ANY (v_options); IF v_valid <> cardinality(v_options) THEN RETURN 'bad_option'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('community_vote:' || p_poll::text || ':' || p_user::text, 0)); DELETE FROM public.community_poll_votes WHERE poll_id = p_poll AND user_id = p_user AND NOT (option_id = ANY (v_options)); INSERT INTO public.community_poll_votes (poll_id, option_id, user_id) SELECT p_poll, o, p_user FROM unnest(v_options) AS o ON CONFLICT (option_id, user_id) DO NOTHING; RETURN 'ok'; END $f$;
CREATE OR REPLACE FUNCTION public.community_rsvp(p_event uuid, p_user uuid, p_going boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_event public.community_events%ROWTYPE; v_current text; v_status text; v_going integer; BEGIN SELECT * INTO v_event FROM public.community_events WHERE id = p_event FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'community_rsvp: no event %', p_event USING ERRCODE = 'P0002'; END IF; SELECT status INTO v_current FROM public.community_event_rsvps WHERE event_id = p_event AND user_id = p_user; IF NOT p_going THEN IF v_current IS NULL OR v_current = 'cancelled' THEN RETURN 'cancelled'; END IF; UPDATE public.community_event_rsvps SET status = 'cancelled' WHERE event_id = p_event AND user_id = p_user; IF v_current = 'going' AND v_event.capacity IS NOT NULL AND v_event.status = 'scheduled' THEN UPDATE public.community_event_rsvps r SET status = 'going' FROM (SELECT user_id FROM public.community_event_rsvps WHERE event_id = p_event AND status = 'waitlist' ORDER BY updated_at, user_id LIMIT 1) w WHERE r.event_id = p_event AND r.user_id = w.user_id; END IF; RETURN 'cancelled'; END IF; IF v_event.status <> 'scheduled' THEN RETURN coalesce(nullif(v_current, 'cancelled'), 'cancelled'); END IF; IF v_current IN ('going', 'waitlist') THEN RETURN v_current; END IF; SELECT count(*) INTO v_going FROM public.community_event_rsvps WHERE event_id = p_event AND status = 'going'; v_status := CASE WHEN v_event.capacity IS NULL OR v_going < v_event.capacity THEN 'going' ELSE 'waitlist' END; INSERT INTO public.community_event_rsvps (event_id, user_id, community_id, status) VALUES (p_event, p_user, v_event.community_id, v_status) ON CONFLICT (event_id, user_id) DO UPDATE SET status = EXCLUDED.status; RETURN v_status; END $f$;
CREATE OR REPLACE FUNCTION public.community_redeem_invite(p_token_hash text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_invite public.community_invites%ROWTYPE; v_email text; v_used boolean; v_new boolean := false; BEGIN SELECT * INTO v_invite FROM public.community_invites WHERE token_hash = p_token_hash FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF; IF v_invite.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'revoked', 'community_id', v_invite.community_id); END IF; IF v_invite.expires_at IS NOT NULL AND v_invite.expires_at <= now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'expired', 'community_id', v_invite.community_id); END IF; IF v_invite.email IS NOT NULL THEN SELECT lower(u.email::text) INTO v_email FROM auth.users u WHERE u.id = p_user AND u.email_confirmed_at IS NOT NULL; IF v_email IS NULL OR v_email <> lower(v_invite.email) THEN RETURN jsonb_build_object('ok', false, 'reason', 'email_mismatch', 'community_id', v_invite.community_id); END IF; END IF; v_used := EXISTS (SELECT 1 FROM public.community_invite_uses WHERE invite_id = v_invite.id AND user_id = p_user); IF NOT v_used AND v_invite.max_uses IS NOT NULL AND v_invite.uses >= v_invite.max_uses THEN RETURN jsonb_build_object('ok', false, 'reason', 'used_up', 'community_id', v_invite.community_id); END IF; IF NOT v_used THEN INSERT INTO public.community_invite_uses (invite_id, user_id) VALUES (v_invite.id, p_user) ON CONFLICT (invite_id, user_id) DO NOTHING; v_new := FOUND; IF v_new THEN UPDATE public.community_invites SET uses = uses + 1 WHERE id = v_invite.id; END IF; END IF; RETURN jsonb_build_object('ok', true, 'community_id', v_invite.community_id, 'tier_id', v_invite.tier_id, 'complimentary', v_invite.complimentary, 'invite_id', v_invite.id, 'new', v_new); END $f$;
CREATE OR REPLACE FUNCTION public.community_award_points(p_community uuid, p_user uuid, p_points integer, p_reason text, p_source_key text, p_actor uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN INSERT INTO public.community_point_events (community_id, user_id, points, reason, source_key, actor_id) VALUES (p_community, p_user, p_points, p_reason, p_source_key, p_actor) ON CONFLICT (community_id, user_id, source_key) DO NOTHING; RETURN FOUND; END $f$;
CREATE OR REPLACE FUNCTION public.community_claim_jobs(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.community_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN UPDATE public.community_jobs SET state = 'failed', finished_at = now(), lease_until = NULL, last_error = coalesce(last_error, 'its lease ran out 5 times') WHERE state = 'running' AND lease_until < now() AND attempts >= 5; RETURN QUERY WITH picked AS (SELECT j.id FROM public.community_jobs j WHERE (j.state = 'pending' AND j.run_at <= now()) OR (j.state = 'running' AND j.lease_until < now()) ORDER BY j.run_at, j.id LIMIT greatest(coalesce(p_limit, 0), 0) FOR UPDATE SKIP LOCKED) UPDATE public.community_jobs j SET state = 'running', lease_until = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 60), 1)), attempts = j.attempts + 1 FROM picked WHERE j.id = picked.id RETURNING j.*; END $f$;
CREATE OR REPLACE FUNCTION public.community_leaderboard(p_community uuid, p_since timestamptz, p_limit integer) RETURNS TABLE (user_id uuid, points bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT e.user_id, sum(e.points)::bigint AS points FROM public.community_point_events e JOIN public.community_members m ON m.community_id = e.community_id AND m.user_id = e.user_id AND m.status = 'active' WHERE e.community_id = p_community AND e.created_at >= p_since GROUP BY e.user_id HAVING sum(e.points) > 0 ORDER BY 2 DESC, 1 LIMIT greatest(least(coalesce(p_limit, 20), 100), 0) $f$;
CREATE OR REPLACE FUNCTION public.community_role_of(p_community uuid, p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT m.role FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = p_user AND m.status = 'active' AND m.banned_at IS NULL $f$;
CREATE OR REPLACE FUNCTION public.community_can_read_space(p_space uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_uid uuid := auth.uid(); v_space record; v_member record; v_rule jsonb; v_tiers text[]; v_products text[]; v_roles text[]; v_min integer; BEGIN IF v_uid IS NULL OR p_space IS NULL THEN RETURN false; END IF; SELECT s.community_id, s.view_access, s.archived_at, c.status AS community_status, c.deleted_at, c.suspended_at INTO v_space FROM public.community_spaces s JOIN public.communities c ON c.id = s.community_id WHERE s.id = p_space; IF NOT FOUND OR v_space.archived_at IS NOT NULL OR v_space.deleted_at IS NOT NULL OR v_space.suspended_at IS NOT NULL OR v_space.community_status = 'suspended' THEN RETURN false; END IF; SELECT m.role, m.status, m.tier_id, m.level, m.banned_at INTO v_member FROM public.community_members m WHERE m.community_id = v_space.community_id AND m.user_id = v_uid; IF NOT FOUND OR v_member.status <> 'active' OR v_member.banned_at IS NOT NULL THEN RETURN false; END IF; IF v_member.role IN ('owner', 'admin', 'moderator') THEN RETURN true; END IF; v_rule := CASE WHEN jsonb_typeof(v_space.view_access) = 'object' THEN v_space.view_access ELSE '{}'::jsonb END; v_tiers := CASE WHEN jsonb_typeof(v_rule -> 'tierIds') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'tierIds')) ELSE '{}'::text[] END; v_products := CASE WHEN jsonb_typeof(v_rule -> 'productIds') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'productIds')) ELSE '{}'::text[] END; v_roles := CASE WHEN jsonb_typeof(v_rule -> 'roles') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'roles')) ELSE '{}'::text[] END; v_min := CASE WHEN jsonb_typeof(v_rule -> 'minLevel') = 'number' THEN floor((v_rule ->> 'minLevel')::numeric)::integer ELSE NULL END; IF v_min IS NOT NULL AND coalesce(v_member.level, 1) < v_min THEN RETURN false; END IF; IF cardinality(v_tiers) = 0 AND cardinality(v_products) = 0 AND cardinality(v_roles) = 0 THEN RETURN true; END IF; IF v_member.tier_id IS NOT NULL AND v_member.tier_id::text = ANY (v_tiers) THEN RETURN true; END IF; IF v_member.role = ANY (v_roles) THEN RETURN true; END IF; IF cardinality(v_products) > 0 THEN IF to_regclass('public.entitlements') IS NOT NULL AND EXISTS (SELECT 1 FROM public.entitlements e WHERE e.buyer_id = v_uid AND e.product_id::text = ANY (v_products)) THEN RETURN true; END IF; IF to_regclass('public.memberships') IS NOT NULL AND EXISTS (SELECT 1 FROM public.memberships ms WHERE ms.buyer_id = v_uid AND ms.product_id::text = ANY (v_products) AND public.membership_grants_access(ms.status, ms.current_period_end, ms.past_due_since, now())) THEN RETURN true; END IF; END IF; RETURN false; END $f$;
