INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('134', '134_storelib_reviews.sql', 'eb9e12375cee76a8f92245172d2a83e3593ac83ecf54294fe6ba7e57ce4b83f3') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 135_store_team.sql
/* A store's team. A new server only table `store_team_members`: one row per person the owner invites to their store (Settings > Team), with the email it was sent to, the role (manager or staff), whether they have accepted (invited, then active once they open the link signed in with their own Storelib account, which sets user_id), who sent it and when, and the invite link's token kept only as its SHA-256 (the link itself is in the email and nowhere else). One row per email per store. Only the service role reads or writes it: no policy for visitors or signed in users, so a member can never list a team or change a role from the browser; every check goes through the server (lib/team). Changes no existing row. Until it runs, Settings > Team says the team is not set up yet and everything else works as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'store team: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.store_team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL, status text NOT NULL DEFAULT 'invited', token_hash text, invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, invited_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, accepted_at timestamptz, CONSTRAINT store_team_members_role_check CHECK (role IN ('manager', 'staff')), CONSTRAINT store_team_members_status_check CHECK (status IN ('invited', 'active')), CONSTRAINT store_team_members_email_check CHECK (email = lower(email) AND char_length(email) BETWEEN 3 AND 254 AND position('@' in email) > 1), CONSTRAINT store_team_members_active_user CHECK (status <> 'active' OR user_id IS NOT NULL), CONSTRAINT store_team_members_one_email UNIQUE (creator_id, email)); CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_token_idx ON public.store_team_members (token_hash) WHERE token_hash IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_one_user ON public.store_team_members (creator_id, user_id) WHERE user_id IS NOT NULL; CREATE INDEX IF NOT EXISTS store_team_members_user_idx ON public.store_team_members (user_id) WHERE user_id IS NOT NULL; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('135', '135_store_team.sql', '74bfd159b80d9db8a918ee388de5e53e007e102b24dce63135b4f5a1b3cb0883') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 136_markets_languages.sql
/* Markets and languages for a creator's own website (Settings > Markets and languages; lib/markets). Three new server only tables. `store_localization`: one row per store, the website's default language, its other languages (each published or not) and its markets (groups of countries, each with the currency prices are shown in, the language a visitor starts in, a price adjustment and rounding; one primary market, the store's home, in its own currency), checked whole by the app before it is saved. `site_translations`: one row per piece of text per language (a section's heading, a product's title, a menu label), keyed as lib/markets/translate.ts says, with the text, a fingerprint of the original it was written for (so a changed original shows as outdated and is never overwritten), draft or approved, and whether a person or the AI wrote it. `fx_rates`: the European Central Bank's daily reference rates, one row per day, read only when fresh. Only the service role reads or writes them: every read and write goes through the app's server, which checks the store's owner (or a team member whose role has the area). The creator page, Explore and their prices are not touched. Changes no existing row. Until it runs, Settings > Markets and languages says it is not set up yet and every website works as before, in one language. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'markets: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.store_localization (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, default_language text NOT NULL DEFAULT 'en', languages jsonb NOT NULL DEFAULT '[]'::jsonb, markets jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT store_localization_language_check CHECK (char_length(default_language) BETWEEN 2 AND 35), CONSTRAINT store_localization_languages_array CHECK (jsonb_typeof(languages) = 'array'), CONSTRAINT store_localization_markets_array CHECK (jsonb_typeof(markets) = 'array')); CREATE TABLE IF NOT EXISTS public.site_translations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, locale text NOT NULL, key text NOT NULL, value text NOT NULL, source_hash text NOT NULL, status text NOT NULL DEFAULT 'draft', source text NOT NULL DEFAULT 'manual', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT site_translations_locale_check CHECK (char_length(locale) BETWEEN 2 AND 35), CONSTRAINT site_translations_key_check CHECK (char_length(key) BETWEEN 3 AND 300), CONSTRAINT site_translations_value_check CHECK (char_length(value) <= 20000), CONSTRAINT site_translations_hash_check CHECK (source_hash ~ '^[0-9a-f]{8}$'), CONSTRAINT site_translations_status_check CHECK (status IN ('draft', 'approved')), CONSTRAINT site_translations_source_check CHECK (source IN ('manual', 'ai')), CONSTRAINT site_translations_one UNIQUE (creator_id, locale, key)); CREATE INDEX IF NOT EXISTS site_translations_store_locale ON public.site_translations (creator_id, locale); CREATE TABLE IF NOT EXISTS public.fx_rates (as_of date PRIMARY KEY, base text NOT NULL DEFAULT 'EUR', rates jsonb NOT NULL, source text NOT NULL DEFAULT 'ecb', fetched_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fx_rates_object CHECK (jsonb_typeof(rates) = 'object')); ALTER TABLE public.store_localization ENABLE ROW LEVEL SECURITY; ALTER TABLE public.site_translations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.fx_rates ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_localization FROM PUBLIC, anon, authenticated; REVOKE ALL ON public.site_translations FROM PUBLIC, anon, authenticated; REVOKE ALL ON public.fx_rates FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_localization TO service_role; GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_translations TO service_role; GRANT SELECT, INSERT, UPDATE, DELETE ON public.fx_rates TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('136', '136_markets_languages.sql', '2f619d5a3af1925e8298b157d068c8f2d5e5e7d7db9de14b24baed620ea4b34a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 150_products_sales_limit.sql
/* Limit sales for downloads: `products.sales_limit`, the most copies of a product that can ever be sold (a limited run of 100 sample packs), set under Settings in the product editor. 1 to 1,000,000, or null for no limit; no rows change. A checkout takes a place under the limit before anything is charged, in one statement that locks the product's row (`hold_product_sale`), so two buyers paying for the last copy cannot both pass; the place is given back when the payment will not happen (`release_product_sale`) and otherwise lapses after 35 minutes. Sold is counted from the orders themselves (`product_copies_sold`): paid ones, and partly refunded ones, whose buyer keeps the product; a fully refunded order gives its copy back. `product_sales_status` is what the editor and the shop read. Server only. Needs part 78 (orders.quantity). Until it runs, the editor saves everything else and says a typed limit needs this part, and nothing is limited. Safe to run again. */
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS sales_limit integer;
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_sales_limit_check;
ALTER TABLE public.products ADD CONSTRAINT products_sales_limit_check CHECK (sales_limit IS NULL OR (sales_limit >= 1 AND sales_limit <= 1000000));
CREATE TABLE IF NOT EXISTS public.product_sale_holds ( product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, holder text NOT NULL CHECK (char_length(holder) BETWEEN 1 AND 200), quantity integer NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 1000), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (product_id, holder) );
ALTER TABLE public.product_sale_holds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.product_sale_holds FROM PUBLIC;
REVOKE ALL ON TABLE public.product_sale_holds FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.product_sale_holds TO service_role;
/* Copies sold: paid orders, and orders refunded in part (the buyer keeps the product). An order refunded in full gives its copy back. A basket line of several copies counts each one. */
CREATE OR REPLACE FUNCTION public.product_copies_sold(p_product uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce(sum(greatest(1, coalesce(o.quantity, 1))), 0)::integer FROM public.orders o WHERE o.product_id = p_product AND (o.status = 'completed' OR (o.status = 'refunded' AND coalesce(o.refund_amount_cents, 0) > 0 AND o.refund_amount_cents < coalesce(o.amount_cents, 0))) $$;
/* Takes or refreshes a holder's place for p_quantity copies. The product's row is locked first (FOR NO KEY UPDATE, so orders can still be written beside it), so two calls for one product run one after the other and the second counts the first one's place. Expired places are cleared on the way. True when there is room (always, with no limit, and then nothing is held); false when there is none, or no such product. Called when a payment starts, and again when a paid payment becomes its order, so a place that lapsed in between is taken again only while there is room. */
CREATE OR REPLACE FUNCTION public.hold_product_sale(p_product uuid, p_holder text, p_quantity integer, p_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE lim integer; sold integer; others integer; q integer := greatest(1, least(coalesce(p_quantity, 1), 1000)); BEGIN IF p_holder IS NULL OR char_length(p_holder) NOT BETWEEN 1 AND 200 THEN RETURN false; END IF; SELECT p.sales_limit INTO lim FROM public.products p WHERE p.id = p_product FOR NO KEY UPDATE; IF NOT FOUND THEN RETURN false; END IF; DELETE FROM public.product_sale_holds h WHERE h.product_id = p_product AND h.expires_at < now(); IF lim IS NULL THEN RETURN true; END IF; sold := public.product_copies_sold(p_product); SELECT coalesce(sum(h.quantity), 0) INTO others FROM public.product_sale_holds h WHERE h.product_id = p_product AND h.holder <> p_holder; IF sold + others + q > lim THEN RETURN false; END IF; INSERT INTO public.product_sale_holds (product_id, holder, quantity, expires_at) VALUES (p_product, p_holder, q, now() + make_interval(secs => greatest(60, least(coalesce(p_seconds, 2100), 86400)))) ON CONFLICT (product_id, holder) DO UPDATE SET quantity = excluded.quantity, expires_at = excluded.expires_at; RETURN true; END $$;
/* A place given back: the payment it was for will not happen, or its order now counts the copy. */
CREATE OR REPLACE FUNCTION public.release_product_sale(p_product uuid, p_holder text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ DELETE FROM public.product_sale_holds WHERE product_id = p_product AND holder = p_holder $$;
/* What the editor and the shop show, for the products with a limit among those asked about: the limit, copies sold, and copies held by payments in progress. */
CREATE OR REPLACE FUNCTION public.product_sales_status(p_products uuid[]) RETURNS TABLE (product_id uuid, sales_limit integer, sold integer, held integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id, p.sales_limit, public.product_copies_sold(p.id), (SELECT coalesce(sum(h.quantity), 0)::integer FROM public.product_sale_holds h WHERE h.product_id = p.id AND h.expires_at >= now()) FROM public.products p WHERE p.id = ANY ((coalesce(p_products, '{}'::uuid[]))[1:500]) AND p.sales_limit IS NOT NULL $$;
/* Only the server counts, holds and gives back places. */
REVOKE ALL ON FUNCTION public.product_copies_sold(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.product_copies_sold(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.product_copies_sold(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_product_sale(uuid, text, integer, integer) TO service_role;
REVOKE ALL ON FUNCTION public.release_product_sale(uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.release_product_sale(uuid, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_product_sale(uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.product_sales_status(uuid[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.product_sales_status(uuid[]) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.product_sales_status(uuid[]) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('150', '150_products_sales_limit.sql', '0ccb84e7c42b7e1e7e8abd3ac09bf139b1d9f233f1b406594962db46509eac18') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 153_store_business_and_tax_names.sql
/* A store's business on its receipts, and each tax named as it was charged. `store_settings.legal` (part 109's table): the business behind the store as Settings › Store details › Business details keeps it, its legal name, address and tax number (VAT number, EIN, ABN), which the receipt page, the order page and the invoice PDF print under "Sold by"; one small object, null until the store fills it in. `orders.tax_label`: what the tax on an order (part 110's `tax_cents`) was called when it was charged, "VAT 19%" or "Sales tax 8.25%", as Settings › Taxes names the region, so the receipt, the PDF and the creator's order say it in the same words; a physical order keeps the same words on its checkout's `shipping_rate`. No rows change. Needs part 109 for the first; skips it with a notice where store_settings is not there. Until it runs, receipts carry the store's name and contact alone, and the tax line reads "Tax". */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'store business: store_settings is not there yet (part 109).'; RETURN; END IF; ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS legal jsonb; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_legal_check; ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_legal_check CHECK (legal IS NULL OR (jsonb_typeof(legal) = 'object' AND pg_column_size(legal) < 4096)); END $do$;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tax_label text;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_tax_label_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_tax_label_check CHECK (tax_label IS NULL OR length(tax_label) BETWEEN 1 AND 80) NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('153', '153_store_business_and_tax_names.sql', '5d22c6d35ab107846df5d617b477ea419082cdac4c83fcdd0fb7d5a24d7abcb4') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 154_local_delivery_and_pickup_hours.sql
/* Local delivery and pickup hours on a location (Settings > Locations): the seller brings orders to buyers whose postal code starts with one of the location's codes, in its country, for its price (free from its free over value, when the order reaches its minimum); and the opening hours buyers can collect in. New columns on inventory_locations only, every one with a default, so no row changes. Server only, as the table already is. Needs part 78. Until it runs, a location saves as before and says local delivery and pickup hours turn on after this part. Safe to run again. */
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS pickup_hours text;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_codes text[] NOT NULL DEFAULT '{}'::text[];
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_price_cents integer NOT NULL DEFAULT 0;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_min_cents integer;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_free_over_cents integer;
ALTER TABLE public.inventory_locations ADD COLUMN IF NOT EXISTS local_delivery_note text;
ALTER TABLE public.inventory_locations DROP CONSTRAINT IF EXISTS inventory_locations_local_delivery_check;
ALTER TABLE public.inventory_locations ADD CONSTRAINT inventory_locations_local_delivery_check CHECK ((pickup_hours IS NULL OR char_length(pickup_hours) <= 300) AND cardinality(local_delivery_codes) <= 500 AND local_delivery_price_cents BETWEEN 0 AND 10000000 AND (local_delivery_min_cents IS NULL OR local_delivery_min_cents BETWEEN 0 AND 10000000) AND (local_delivery_free_over_cents IS NULL OR local_delivery_free_over_cents BETWEEN 0 AND 10000000) AND (local_delivery_note IS NULL OR char_length(local_delivery_note) <= 500)) NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('154', '154_local_delivery_and_pickup_hours.sql', '3d3eceb865c91ddbab84277fe420c41a9ba8a2c87b2a1389dddd0ef6204f8fc2') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 160_courier_tracking.sql
/* Courier tracking: Storelib follows every shipment with a tracking number through a tracking aggregator (AfterShip or 17TRACK), with Storelib's own account for every store or a store's own. New columns on fulfillments, every one with a default or empty, so no row changes: which aggregator and account follow it, the aggregator's id and the number it was registered with, the carrier's code, its state (info received, in transit, out for delivery, ready to collect, delivery attempted, problem, delivered, returned to sender, expired), the finer state, the estimated delivery, when it was read last and is read next, failures and the last error, when following stopped, and the seller's switch to pause it on one shipment. An index on the next look for open shipments only, so the ten minute job reads nothing else. `commerce_tracking_accounts` keeps a store's own AfterShip or 17TRACK key, sealed by the app before it is stored, one row per store, written and read by the server only. The carrier's scans go on fulfillment_events, which already keeps an external id once per shipment. Needs part 78. Until it runs, shipments keep the statuses the seller sets and the carrier's own link, and the job says tracking is not available yet. Safe to run again. */
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_provider text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_account text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_ref text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_ref_number text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_carrier_code text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_status text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_substatus text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS estimated_delivery_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_checked_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_next_check_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_last_event_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_failures integer NOT NULL DEFAULT 0;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_error text;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_stopped_at timestamptz;
ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS tracking_auto boolean NOT NULL DEFAULT true;
ALTER TABLE public.fulfillments DROP CONSTRAINT IF EXISTS fulfillments_tracking_check;
ALTER TABLE public.fulfillments ADD CONSTRAINT fulfillments_tracking_check CHECK ((tracking_provider IS NULL OR tracking_provider IN ('aftership', '17track')) AND (tracking_account IS NULL OR tracking_account IN ('platform', 'own')) AND (tracking_ref IS NULL OR char_length(tracking_ref) <= 200) AND (tracking_ref_number IS NULL OR char_length(tracking_ref_number) <= 120) AND (tracking_carrier_code IS NULL OR char_length(tracking_carrier_code) <= 60) AND (tracking_status IS NULL OR tracking_status IN ('pending', 'not_found', 'info_received', 'in_transit', 'out_for_delivery', 'available_for_pickup', 'attempt_failed', 'exception', 'delivered', 'returned', 'expired')) AND (tracking_substatus IS NULL OR char_length(tracking_substatus) <= 60) AND tracking_failures BETWEEN 0 AND 1000 AND (tracking_error IS NULL OR char_length(tracking_error) <= 300)) NOT VALID;
CREATE INDEX IF NOT EXISTS fulfillments_tracking_due_idx ON public.fulfillments (tracking_next_check_at NULLS FIRST) WHERE tracking_number IS NOT NULL AND tracking_stopped_at IS NULL AND status IN ('shipped', 'in_transit', 'out_for_delivery', 'failed');
CREATE INDEX IF NOT EXISTS fulfillments_tracking_number_idx ON public.fulfillments (tracking_number) WHERE tracking_number IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.commerce_tracking_accounts (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('aftership', '17track')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'error')), secret_ciphertext text NOT NULL CHECK (length(secret_ciphertext) <= 4096), webhook_secret_ciphertext text CHECK (webhook_secret_ciphertext IS NULL OR length(webhook_secret_ciphertext) <= 4096), last_error text CHECK (last_error IS NULL OR length(last_error) <= 300), verified_at timestamptz, last_webhook_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.commerce_tracking_accounts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.commerce_tracking_accounts FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.commerce_tracking_accounts TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('160', '160_courier_tracking.sql', 'f08bc042674e33a9447a2173ad8d7ab099863c209b16ff05f8d66721e07ad4e2') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 161_physical_products_ship_by_default.sql
/* A physical product ships unless its seller turns "This product is shipped" off in the product editor: `products.requires_shipping` now defaults to true, as the editor, the shop and the checkout already read a product that never said. It was false since part 78, so a physical product whose row was written without the editor's shipping card (a save that stopped part way, an import, an agent) sold with no address, no shipping and no delivery at checkout. No rows change: a seller's own choice is kept. To see physical products that are not shipped, run: select id, title from public.products where type = 'physical' and requires_shipping = false; and turn "This product is shipped" on for the ones that should ship. Needs part 78. Safe to run again. */
ALTER TABLE public.products ALTER COLUMN requires_shipping SET DEFAULT true;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('161', '161_physical_products_ship_by_default.sql', '2473fb0a27083ca1d23173f7562c2547efa01f70279b20da742a1e042641fe2e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 162_physical_readiness_state.sql
/* What each store selling physical products last looked like to the readiness check (lib/physical/readiness-server.ts): whether something on sale had a gap that stops a checkout or a shipment, how many times it has gone from fine to that (each time is one notice and one reminder, never more), which gaps, and how many products were on sale. One row per store, written by the server only, so a store that breaks after it was ready is told once, and a store that stays broken is not told again. Needs part 40 for the notices. Until it runs the banners and Settings' checklist still show, and nothing is emailed from it. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.physical_readiness_state ( creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, broken boolean NOT NULL DEFAULT false, episode integer NOT NULL DEFAULT 0 CHECK (episode >= 0), signature text NOT NULL DEFAULT '' CHECK (char_length(signature) <= 300), live integer NOT NULL DEFAULT 0 CHECK (live >= 0), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.physical_readiness_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.physical_readiness_state FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('162', '162_physical_readiness_state.sql', '1289f783a1b9a5dea336a917e51864469fe87d9987ecf8718b23ab4520e647cd') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 163_shipping_labels_and_shipstation.sql
/* Shipping apps (Settings > Integrations: Shippo, EasyPost, ShipStation). A label bought from an order with Shippo or EasyPost is kept on that order: the provider's ids, the carrier and service, the tracking number, the label's https PDF, what it cost the seller (never charged to the buyer), test or live, and whether it was voided; one label per quoted provider shipment, so two presses of Buy never buy two. Server only, as the other order tables are. And the job queue takes any well formed job kind, so ShipStation's shipstation_push and shipstation_sync (and other new kinds) are let in: the old fixed list refused them. No rows change. Needs part 78. Until it runs, Buy a label says labels turn on after this part and nothing is bought; ShipStation orders are not sent. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.shipping_labels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, checkout_id uuid NOT NULL REFERENCES public.commerce_checkouts(id) ON DELETE CASCADE, fulfillment_id uuid REFERENCES public.fulfillments(id) ON DELETE SET NULL, provider text NOT NULL CHECK (provider IN ('shippo', 'easypost')), provider_shipment_id text NOT NULL CHECK (char_length(provider_shipment_id) BETWEEN 1 AND 120), provider_label_id text NOT NULL CHECK (char_length(provider_label_id) BETWEEN 1 AND 120), carrier text CHECK (carrier IS NULL OR char_length(carrier) <= 60), service text CHECK (service IS NULL OR char_length(service) <= 120), tracking_number text CHECK (tracking_number IS NULL OR char_length(tracking_number) <= 80), label_url text CHECK (label_url IS NULL OR (char_length(label_url) <= 2000 AND label_url LIKE 'https://%')), cost_cents integer NOT NULL DEFAULT 0 CHECK (cost_cents BETWEEN 0 AND 100000000), currency text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'), package jsonb CHECK (package IS NULL OR (jsonb_typeof(package) = 'object' AND pg_column_size(package) <= 1024)), test_mode boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'buying' CHECK (status IN ('buying', 'purchased', 'void_pending', 'voided', 'void_rejected')), voided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS shipping_labels_shipment_key ON public.shipping_labels (provider, provider_shipment_id);
CREATE INDEX IF NOT EXISTS shipping_labels_checkout_idx ON public.shipping_labels (checkout_id, created_at);
CREATE INDEX IF NOT EXISTS shipping_labels_creator_idx ON public.shipping_labels (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS shipping_labels_fulfillment_idx ON public.shipping_labels (fulfillment_id) WHERE fulfillment_id IS NOT NULL;
ALTER TABLE public.shipping_labels ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.shipping_labels FROM anon, authenticated;
GRANT ALL ON public.shipping_labels TO service_role;
ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check;
ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind ~ '^[a-z][a-z0-9_]{2,39}$') NOT VALID;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('163', '163_shipping_labels_and_shipstation.sql', '6f9ebfd4c2ce1edbf996aae5eec4959afb25af0de7db86d0f0a318349605d7fc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 164_buyer_contact_and_cart_attributes.sql
/* Buyers reach the shop, and a cart's attributes reach the order. On a case (part 117): three more topics a buyer can write about (a question, changing the address, cancelling) beside the ones there were, and photos with a message (`order_case_messages.photos`, at most four, each the path of a picture in the private `order-case-photos` bucket, never a public address; the server checks every picture and strips its location before it is kept, and shows it through a link that lasts an hour). On an order: `commerce_checkouts.cart_attributes`, what an imported Shopify theme's cart asked the buyer (a gift message, a delivery date) as Shopify's cart.attributes keep it, shown to the seller on the order and in the new order email. On a shipment: `fulfillments.delivery_unconfirmed_at`, set when a tracked parcel was never marked delivered 60 days after it shipped, so the seller follows it up; its index lets the daily pass find those quickly. No rows change; the topic check is rebuilt NOT VALID, so no stored row is read again. Server only, as these tables already are. Needs parts 78 and 117; skips what it needs with a notice where they did not run. Until it runs, a message on one of the new topics is filed under Something else with the topic in its first line, photos say they can't be kept yet, attributes are not kept, and the shipment pass writes the order timeline only. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.order_cases') IS NULL THEN RAISE NOTICE 'part 164: order_cases is missing (part 117), the topics are left.'; RETURN; END IF; ALTER TABLE public.order_cases DROP CONSTRAINT IF EXISTS order_cases_reason_check; ALTER TABLE public.order_cases ADD CONSTRAINT order_cases_reason_check CHECK (reason IN ('question', 'change_address', 'cancel', 'not_arrived', 'damaged', 'wrong_item', 'missing_item', 'return', 'refund', 'access', 'other')) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.order_case_messages') IS NULL THEN RAISE NOTICE 'part 164: order_case_messages is missing (part 117), photos are left.'; RETURN; END IF; ALTER TABLE public.order_case_messages ADD COLUMN IF NOT EXISTS photos jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.order_case_messages DROP CONSTRAINT IF EXISTS order_case_messages_photos_check; ALTER TABLE public.order_case_messages ADD CONSTRAINT order_case_messages_photos_check CHECK (jsonb_typeof(photos) = 'array' AND jsonb_array_length(photos) <= 4 AND pg_column_size(photos) <= 4096) NOT VALID; END $do$;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('order-case-photos', 'order-case-photos', false, 8388608, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif']) ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 8388608, allowed_mime_types = ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'part 164: commerce_checkouts is missing (part 78), cart attributes are left.'; RETURN; END IF; ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS cart_attributes jsonb; ALTER TABLE public.commerce_checkouts DROP CONSTRAINT IF EXISTS commerce_checkouts_cart_attributes_check; ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_cart_attributes_check CHECK (cart_attributes IS NULL OR (jsonb_typeof(cart_attributes) = 'object' AND pg_column_size(cart_attributes) <= 8192)) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.fulfillments') IS NULL THEN RAISE NOTICE 'part 164: fulfillments is missing (part 78), the unconfirmed mark is left.'; RETURN; END IF; ALTER TABLE public.fulfillments ADD COLUMN IF NOT EXISTS delivery_unconfirmed_at timestamptz; CREATE INDEX IF NOT EXISTS fulfillments_unconfirmed_scan_idx ON public.fulfillments (shipped_at) WHERE delivered_at IS NULL AND delivery_unconfirmed_at IS NULL AND status IN ('shipped', 'in_transit', 'out_for_delivery'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('164', '164_buyer_contact_and_cart_attributes.sql', '63b61f7aec70533a994c268b7e42e8a1947e4bc9a995cadbeb7f4b12620272cf') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 165_columns_production_has.sql
/* Columns production has that no file here ever created, so a database built from this repository matches it. They were made in the Supabase dashboard before the repository kept SQL, and the app has read and written them since: creators.support_email (Settings > Store details' contact email, where receipts and seller emails reply to), profiles.welcome_completed (signup and onboarding), the Address card's profiles.address_line1, address_line2, city, state, postal_code, country and the payout form's first_name, last_name, onepages.seller_id (whose store a OnePage subscribes to) and products.inventory_count (a counted product's stock, read by the shop's lists). Each is added only where it is missing, nullable, with no default except welcome_completed's false, so no existing row changes. onepages is skipped where that table is not there. Then the column grants part 63 keeps are applied again (storelib_share_public_columns), as they were when these columns already existed in production. Needs nothing else. Safe to run again. */
ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS support_email text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS welcome_completed boolean DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS first_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS last_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line1 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line2 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS city text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS state text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS postal_code text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS country text;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS inventory_count integer;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'onepages.seller_id skipped: public.onepages does not exist here'; RETURN; END IF; ALTER TABLE public.onepages ADD COLUMN IF NOT EXISTS seller_id uuid; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('165', '165_columns_production_has.sql', '44bbe4e6fbc321a6df1fe59acc3e0000ebba6b91c0316804e1fe386fb0121ef8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 166_marketing_sync.sql
/* Klaviyo and Omnisend connected (Settings > Integrations): a store's private key kept sealed in commerce_integrations (provider klaviyo or omnisend, category marketing), the marketing_sync job on the commerce job queue, and marketing_sync_items, the record of what was sent to each (a subscriber's state, an order event, an unsubscribe read back) so nothing goes twice and the integration card can count it. The three checks are rebuilt with every value they already allow plus the new ones, read from the database (as ARRAY['a'::text] or as '{a,b}'), so a part run before or after this one that added its own values keeps them; rebuilt NOT VALID, no row is read again. A check that is already a pattern (part 163 makes the jobs check one) lets every name in and is left as it is, so running this part again never turns it back into a list. No rows change. Server only. Needs part 78; without it the first three lines say so and change nothing. Until it runs, connecting says it needs this part and the onsite scripts work as before. Safe to run again. */
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_jobs') IS NULL THEN RAISE NOTICE 'commerce_jobs is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_jobs'::regclass AND conname = 'commerce_jobs_kind_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_jobs_kind_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_jobs'::regclass AND c.conname = 'commerce_jobs_kind_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['forward_fulfillment', 'supplier_email', 'webhook_delivery', 'tracking_sync', 'inventory_sync', 'send_email', 'marketing_sync']) AS x ORDER BY x); ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check; EXECUTE format('ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_provider_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_provider_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost', 'klaviyo', 'omnisend']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_provider_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_category_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_category_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_category_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['fulfillment', 'print_on_demand', 'dropshipping', 'supplier', 'shipping', 'marketing']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_category_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_category_check CHECK (category = ANY (%L::text[])) NOT VALID', v); END $do$;
CREATE TABLE IF NOT EXISTS public.marketing_sync_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('klaviyo', 'omnisend')), item_key text NOT NULL CHECK (char_length(item_key) BETWEEN 1 AND 200), state text NOT NULL CHECK (state IN ('subscribed', 'unsubscribed', 'customer', 'sent', 'line', 'pulled')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, provider, item_key));
CREATE INDEX IF NOT EXISTS marketing_sync_items_state_idx ON public.marketing_sync_items (creator_id, provider, state);
ALTER TABLE public.marketing_sync_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.marketing_sync_items FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.marketing_sync_items TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('166', '166_marketing_sync.sql', '26216965ff281ff80206377c69109afdc43aa5dd8c040f791a05bfe149e3c380') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 167_partner_variant_links.sql
/* Gelato and CJ Dropshipping matches (Settings > Integrations > Match products): which of the partner's own products each Storelib variant is, a CJ variant id or a Gelato product UID with its print file, so a paid order is sent with exactly that and never a guess; and, for CJ, whether the product's stock follows CJ's warehouses (the last number read, when, and why a read failed). One new table, server only (row level security on, no policy for anon or signed in users; the app reads and writes it with the service role). Needs part 78. Until it runs, Match products says it turns on after this part, CJ orders go only by a SKU CJ confirms, and Gelato orders are marked to send by hand. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.product_variants') IS NULL OR to_regclass('public.products') IS NULL THEN RAISE NOTICE 'partner variant links: products or product_variants is not there yet, run part 78 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.fulfilment_variant_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES public.product_variants(id) ON DELETE CASCADE, provider_variant_id text NOT NULL, provider_product_id text, provider_sku text, label text, file_url text, stock_sync boolean NOT NULL DEFAULT false, stock_level integer, stock_synced_at timestamptz, stock_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fulfilment_variant_links_once UNIQUE (creator_id, provider, variant_id), CONSTRAINT fulfilment_variant_links_provider_check CHECK (provider IN ('gelato', 'cj_dropshipping', 'printful', 'printify')), CONSTRAINT fulfilment_variant_links_shape CHECK (char_length(provider_variant_id) BETWEEN 1 AND 250 AND (provider_product_id IS NULL OR char_length(provider_product_id) <= 100) AND (provider_sku IS NULL OR char_length(provider_sku) <= 100) AND (label IS NULL OR char_length(label) <= 200) AND (file_url IS NULL OR (char_length(file_url) <= 1000 AND file_url LIKE 'https://%')) AND (stock_level IS NULL OR stock_level BETWEEN 0 AND 1000000000) AND (stock_error IS NULL OR char_length(stock_error) <= 300))); CREATE INDEX IF NOT EXISTS fulfilment_variant_links_product_idx ON public.fulfilment_variant_links (creator_id, provider, product_id); CREATE INDEX IF NOT EXISTS fulfilment_variant_links_stock_idx ON public.fulfilment_variant_links (creator_id, provider, provider_variant_id) WHERE stock_sync; ALTER TABLE public.fulfilment_variant_links ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.fulfilment_variant_links FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.fulfilment_variant_links TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('167', '167_partner_variant_links.sql', '66112769cbeba7a1f5656a8223d4b161f87b3d101ca9808ed3db7428c416e205') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 168_physical_products_ship_once.sql
/* Physical products saved while `products.requires_shipping` defaulted to false (parts 78 to 160) are turned back to shipped, once: a row the product editor's create wrote without the shipping card (the card not mounted, a save that stopped part way, an import, an agent) sold with no address, no delivery and no shipping at checkout, so the order could not be fulfilled. Part 161 changed only the default; this changes the rows, one time only (it does nothing once part 168 is in storelib_applied_parts), so a seller who turns "This product is shipped" off after it ran keeps that choice. Before it has run, those products keep selling with no address. To see what it changed, run: select id, title from public.products where type = 'physical' and requires_shipping = true and updated_at >= (select applied_at from public.storelib_applied_parts where part = '168'); Needs parts 67 and 78. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.storelib_applied_parts') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.storelib_applied_parts WHERE part = '168') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'requires_shipping') THEN UPDATE public.products SET requires_shipping = true, updated_at = now() WHERE type = 'physical' AND requires_shipping = false; END IF; END $do$;
ALTER TABLE public.products ALTER COLUMN requires_shipping SET DEFAULT true;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('168', '168_physical_products_ship_once.sql', '924f750b2d20b00ac189ee281689f155f7b2b3449cbae7844492db5a0cee673f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 173_visitor_language_and_ga_status.sql
/* Show visitors their own language, and whether Google Analytics is receiving data. `store_localization.visitor_language` (part 136's table): Settings › Markets and languages' switch "Show visitors their own language", false unless the store turns it on; with it on, a first visit to the website or the creator page opens in the published language the browser asks for, once, or offers the nearest one. `store_settings.tracking_seen` (part 109's table): for the store's Google Analytics measurement ID, when a visitor's page last saw Google take a hit with it and when the owner's Check in Settings › Integrations last did, so Settings says "Connected, receiving data" with the time; an object, small, nothing about any visitor. Server only, as both tables already are. No rows change. Each step skips itself with a notice where its table is not there (run 136 or 109 first). Until it runs, the switch says it needs this part and stays off, and Google Analytics shows the Check's answer without a last event time. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'visitor language: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS visitor_language boolean NOT NULL DEFAULT false; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'Google Analytics status: store_settings is not there yet, run part 109 first.'; ELSE ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS tracking_seen jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_settings_tracking_seen_small') THEN ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_tracking_seen_small CHECK (jsonb_typeof(tracking_seen) = 'object' AND pg_column_size(tracking_seen) < 4096) NOT VALID; END IF; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('173', '173_visitor_language_and_ga_status.sql', '9554d8d7c34885965cb4fd80ebf573145cb5ac467362bb311798d39d483d5951') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 174_cash_on_delivery.sql
/* Cash on delivery (Settings › Checkout, "Cash on delivery"): a physical order a buyer pays in cash when it is delivered or picked up. commerce_checkouts.provider takes 'cod' beside 'stripe' and 'free' (the column's check is found by what it checks, replaced, and allows every value already in the table too, so no row can fail it), and cod_collected_at is when the seller marked the cash received (null: still to collect). The switch itself is a key of the store's checkout settings, no column. No fee is taken and nothing goes on the payout ledger: the money never passes through Storelib. Safe to run again. */
DO $do$ DECLARE c record; allowed text; BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'cash on delivery: commerce_checkouts is not there yet, run the physical commerce parts first.'; RETURN; END IF; FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.commerce_checkouts'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ~ '\mprovider\M' LOOP EXECUTE format('ALTER TABLE public.commerce_checkouts DROP CONSTRAINT %I', c.conname); END LOOP; SELECT string_agg(quote_literal(v), ', ' ORDER BY v) INTO allowed FROM (SELECT unnest(ARRAY['stripe', 'free', 'cod']) AS v UNION SELECT DISTINCT provider FROM public.commerce_checkouts WHERE provider IS NOT NULL) s; EXECUTE format('ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_provider_check CHECK (provider IN (%s))', allowed); ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS cod_collected_at timestamptz; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('174', '174_cash_on_delivery.sql', '22ac0fb6bf82a00c8b217b62c7d472090d03f211ecdca7c96f5d9352aecc77f8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 175_automatic_translation.sql
/* Translate new text automatically. `store_localization.auto_translate` (part 136's table): Settings › Markets and languages' switch "Translate changes automatically", false unless the store turns it on; with it on, a job each hour (/api/cron/translations) has Storelib AI translate the website's text that is new or changed since it was last translated, into each of the store's languages, and puts it live. A translation the merchant wrote or edited is never replaced. `store_localization.auto_translate_run`: what the last run did (when, how many, how many are left, and a short reason when it could not), an object, small, so the switch can say it. Server only, as the table already is. No rows change. Skips itself with a notice where the table is not there (run 136 first). Until it runs, the switch says it needs this part and stays off. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'automatic translation: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate boolean NOT NULL DEFAULT false; ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS auto_translate_run jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_localization_auto_translate_run_small') THEN ALTER TABLE public.store_localization ADD CONSTRAINT store_localization_auto_translate_run_small CHECK (jsonb_typeof(auto_translate_run) = 'object' AND pg_column_size(auto_translate_run) < 2048) NOT VALID; END IF; CREATE INDEX IF NOT EXISTS idx_store_localization_auto_translate ON public.store_localization (creator_id) WHERE auto_translate; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('175', '175_automatic_translation.sql', '0d05562cb7156cf271782f0ee76a6e79e699d2f75ba6072aa4b599073b60d978') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 176_store_currency.sql
/* A store's own selling currency (Settings › Store details › Country & Currency). `store_settings.currency`: the currency the store prices its catalog in and its website charges, as a three letter code; empty means the platform's currency, which is what every store sold in before, so nothing changes for a store until it chooses. Changing it goes through one function, `store_change_currency`, in one transaction: either the prices keep their numbers ("keep": 100 EUR becomes 100 USD) or every price the store owns is converted at the rate the merchant was shown ("convert"): products (price, compare-at, pay what you want minimum and suggestion), options (price, compare-at, the older added price), option costs, shipping rates (price, free over, the order value ranges and steps of a rate by order value), local delivery (price, minimum, free over), fixed coupons and their minimums, and the cash on delivery fee. Orders, refunds, invoices, payouts and the wallet keep the currency they were made in and are never touched. `store_currency_changes` records each change once per request key, so a second press or a retry returns the first result instead of converting twice. `store_currency_snapshots` keeps every converted value as it was, so `store_currency_restore` can put the prices back exactly (only the store's latest change, so a later one is never overwritten). All three are server only. Safe to run again. */
ALTER TABLE public.store_settings ADD COLUMN IF NOT EXISTS currency text;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_settings_currency_code') THEN ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_currency_code CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.store_currency_changes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, from_currency text NOT NULL CHECK (from_currency ~ '^[A-Z]{3}$'), to_currency text NOT NULL CHECK (to_currency ~ '^[A-Z]{3}$'), previous_currency text CHECK (previous_currency IS NULL OR previous_currency ~ '^[A-Z]{3}$'), mode text NOT NULL CHECK (mode IN ('keep', 'convert')), rate numeric(24, 12) CHECK (rate IS NULL OR rate > 0), rate_as_of date, counts jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(counts) = 'object'), request_key text NOT NULL CHECK (length(request_key) BETWEEN 8 AND 120), created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), restored_at timestamptz, CONSTRAINT store_currency_changes_rate_when_converting CHECK (mode = 'keep' OR rate IS NOT NULL), CONSTRAINT store_currency_changes_once UNIQUE (creator_id, request_key) );
ALTER TABLE public.store_currency_changes ADD COLUMN IF NOT EXISTS previous_currency text;
CREATE INDEX IF NOT EXISTS store_currency_changes_creator_idx ON public.store_currency_changes (creator_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.store_currency_snapshots ( change_id uuid NOT NULL REFERENCES public.store_currency_changes(id) ON DELETE CASCADE, table_name text NOT NULL, row_id uuid NOT NULL, before jsonb NOT NULL CHECK (jsonb_typeof(before) = 'object'), PRIMARY KEY (change_id, table_name, row_id) );
ALTER TABLE public.store_currency_changes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_currency_snapshots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_currency_changes FROM anon, authenticated;
REVOKE ALL ON public.store_currency_snapshots FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.store_currency_targets() RETURNS TABLE (table_name text, key_column text, store_filter text, money_columns text[]) LANGUAGE sql IMMUTABLE AS $fn$ VALUES ('products', 'id', 'creator_id = $1', ARRAY['price_cents', 'compare_at_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents']), ('product_variants', 'id', 'product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = $1)', ARRAY['price_cents', 'compare_at_price_cents', 'additional_price_cents']), ('product_variant_costs', 'variant_id', 'creator_id = $1', ARRAY['cost_cents']), ('shipping_rates', 'id', 'creator_id = $1', ARRAY['price_cents', 'free_over_cents']), ('inventory_locations', 'id', 'creator_id = $1', ARRAY['local_delivery_price_cents', 'local_delivery_min_cents', 'local_delivery_free_over_cents']), ('coupons', 'id', 'creator_id = $1', ARRAY['min_purchase_cents']) $fn$;
CREATE OR REPLACE FUNCTION public.store_change_currency(p_creator uuid, p_from text, p_to text, p_mode text, p_rate numeric, p_rate_as_of date, p_key text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_prev public.store_currency_changes%ROWTYPE; v_stored text; v_change uuid := gen_random_uuid(); v_counts jsonb := '{}'::jsonb; v_target record; v_cols text[]; v_set text; v_snap text; v_n integer; BEGIN IF p_creator IS NULL THEN RAISE EXCEPTION 'store_currency: no store' USING ERRCODE = '22023'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from !~ '^[A-Z]{3}$' OR p_to !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'store_currency: a currency is not a code' USING ERRCODE = '22023'; END IF; IF p_from = p_to THEN RAISE EXCEPTION 'store_currency: the store already sells in %', p_to USING ERRCODE = '22023'; END IF; IF p_mode IS NULL OR p_mode NOT IN ('keep', 'convert') THEN RAISE EXCEPTION 'store_currency: mode is keep or convert' USING ERRCODE = '22023'; END IF; IF p_mode = 'convert' AND (p_rate IS NULL OR p_rate <= 0 OR p_rate > 1000000) THEN RAISE EXCEPTION 'store_currency: converting needs a rate' USING ERRCODE = '22023'; END IF; IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 120 THEN RAISE EXCEPTION 'store_currency: a request key is needed' USING ERRCODE = '22023'; END IF; INSERT INTO public.store_settings (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT currency INTO v_stored FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_prev FROM public.store_currency_changes WHERE creator_id = p_creator AND request_key = p_key; IF FOUND THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'id', v_prev.id, 'from', v_prev.from_currency, 'to', v_prev.to_currency, 'mode', v_prev.mode, 'rate', v_prev.rate, 'counts', v_prev.counts); END IF; IF coalesce(v_stored, p_from) <> p_from THEN RAISE EXCEPTION 'store_currency: the store now sells in %', v_stored USING ERRCODE = '40001'; END IF; INSERT INTO public.store_currency_changes (id, creator_id, from_currency, to_currency, previous_currency, mode, rate, rate_as_of, request_key, created_by) VALUES (v_change, p_creator, p_from, p_to, v_stored, p_mode, CASE WHEN p_mode = 'convert' THEN p_rate END, CASE WHEN p_mode = 'convert' THEN p_rate_as_of END, p_key, p_user); IF p_mode = 'convert' THEN FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(c ORDER BY c) INTO v_cols FROM unnest(v_target.money_columns) AS c WHERE EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = v_target.table_name AND ic.column_name = c); IF v_target.table_name = 'shipping_rates' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['min_value', 'max_value', 'tiers', 'kind']; ELSIF v_target.table_name = 'coupons' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; END IF; IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN CONTINUE; END IF; v_snap := format('INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT $2, %L, t.%I, jsonb_build_object(%s) FROM public.%I t WHERE %s', v_target.table_name, v_target.key_column, (SELECT string_agg(format('%L, t.%I', c, c), ', ') FROM unnest(v_cols) AS c), v_target.table_name, v_target.store_filter); EXECUTE v_snap USING p_creator, v_change; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_target.table_name = 'shipping_rates' THEN v_set := concat_ws(', ', CASE WHEN 'price_cents' = ANY (v_cols) THEN 'price_cents = round(price_cents * $2)::integer' END, CASE WHEN 'free_over_cents' = ANY (v_cols) THEN 'free_over_cents = CASE WHEN free_over_cents IS NULL THEN NULL ELSE round(free_over_cents * $2)::integer END' END, 'min_value = CASE WHEN kind = ''price'' AND min_value IS NOT NULL THEN round(min_value * $2)::integer ELSE min_value END', 'max_value = CASE WHEN kind = ''price'' AND max_value IS NOT NULL THEN round(max_value * $2)::integer ELSE max_value END', 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' THEN x || jsonb_strip_nulls(jsonb_build_object(''priceCents'', CASE WHEN x ? ''priceCents'' THEN round((x->>''priceCents'')::numeric * $2)::integer END, ''from'', CASE WHEN kind = ''price'' AND x ? ''from'' THEN round((x->>''from'')::numeric * $2)::integer END)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END'); ELSIF v_target.table_name = 'coupons' THEN v_set := concat_ws(', ', CASE WHEN 'min_purchase_cents' = ANY (v_cols) THEN 'min_purchase_cents = CASE WHEN min_purchase_cents IS NULL THEN NULL ELSE round(min_purchase_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(0.01, round(discount_value * $2, 2)) ELSE discount_value END'); ELSE SELECT string_agg(format('%1$I = CASE WHEN %1$I IS NULL THEN NULL ELSE round(%1$I * $2)::integer END', c), ', ') INTO v_set FROM unnest(v_cols) AS c; END IF; EXECUTE format('UPDATE public.%I SET %s WHERE %s', v_target.table_name, v_set, v_target.store_filter) USING p_creator, p_rate; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT v_change, 'store_settings', s.creator_id, jsonb_build_object('codFeeCents', s.checkout->'codFeeCents') FROM public.store_settings s WHERE s.creator_id = p_creator AND jsonb_typeof(s.checkout->'codFeeCents') = 'number'; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_n > 0 THEN UPDATE public.store_settings SET checkout = jsonb_set(checkout, '{codFeeCents}', to_jsonb(round((checkout->>'codFeeCents')::numeric * p_rate)::integer)) WHERE creator_id = p_creator; v_counts := v_counts || jsonb_build_object('cod_fee', 1); END IF; END IF; UPDATE public.store_settings SET currency = p_to, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET counts = v_counts WHERE id = v_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'id', v_change, 'from', p_from, 'to', p_to, 'mode', p_mode, 'rate', CASE WHEN p_mode = 'convert' THEN p_rate END, 'counts', v_counts); END $fn$;
CREATE OR REPLACE FUNCTION public.store_currency_restore(p_creator uuid, p_change uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_change public.store_currency_changes%ROWTYPE; v_latest uuid; v_target record; v_cols text[]; v_set text; v_counts jsonb := '{}'::jsonb; v_n integer; BEGIN PERFORM 1 FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_change FROM public.store_currency_changes WHERE id = p_change AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'store_currency: no such change' USING ERRCODE = '22023'; END IF; IF v_change.restored_at IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'currency', v_change.from_currency); END IF; SELECT id INTO v_latest FROM public.store_currency_changes WHERE creator_id = p_creator AND restored_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 1; IF v_latest IS DISTINCT FROM p_change THEN RAISE EXCEPTION 'store_currency: only the latest change can be undone' USING ERRCODE = '40001'; END IF; FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(DISTINCT k) INTO v_cols FROM public.store_currency_snapshots s, jsonb_object_keys(s.before) AS k WHERE s.change_id = p_change AND s.table_name = v_target.table_name AND k NOT IN ('kind', 'discount_type'); IF v_cols IS NULL THEN CONTINUE; END IF; SELECT string_agg( CASE c WHEN 'tiers' THEN 'tiers = s.before->''tiers''' WHEN 'discount_value' THEN 'discount_value = (s.before->>''discount_value'')::numeric' ELSE format('%1$I = (s.before->>%1$L)::integer', c) END, ', ') INTO v_set FROM unnest(v_cols) AS c; EXECUTE format('UPDATE public.%I t SET %s FROM public.store_currency_snapshots s WHERE s.change_id = $1 AND s.table_name = %L AND t.%I = s.row_id', v_target.table_name, v_set, v_target.table_name, v_target.key_column) USING p_change; GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; UPDATE public.store_settings t SET checkout = jsonb_set(t.checkout, '{codFeeCents}', s.before->'codFeeCents') FROM public.store_currency_snapshots s WHERE s.change_id = p_change AND s.table_name = 'store_settings' AND t.creator_id = s.row_id; UPDATE public.store_settings SET currency = v_change.previous_currency, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET restored_at = now() WHERE id = p_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'currency', v_change.from_currency, 'counts', v_counts); END $fn$;
REVOKE ALL ON FUNCTION public.store_currency_targets() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_currency_restore(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_currency_targets() TO service_role;
GRANT EXECUTE ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.store_currency_restore(uuid, uuid) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('176', '176_store_currency.sql', '5fb8d6d92a03988dde5a5d25abb4ba48386afbb000d9b854d8dd62645258a4ec') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 177_translation_jobs.sql
/* Translate with AI in the background. `store_translation_jobs`: one row per store and language while Storelib AI translates its website into it (Settings › Languages, the translation sheet), so the work goes on after the page is closed, a refresh shows where it is, and a second press joins the running job instead of starting another. `status` is running, done or failed; `done` and `total` are the language's texts that have a translation and all of them, for a progress bar that counts real work; `drafted` is what this job wrote; `lease_until` is how long the run that holds it may keep it, so a run cut off is picked up again by the next (/api/cron/translation-jobs) and never two at once. Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.store_translation_jobs ( creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, locale text NOT NULL CHECK (locale ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,4})?$'), status text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'failed')), done integer NOT NULL DEFAULT 0 CHECK (done >= 0), total integer NOT NULL DEFAULT 0 CHECK (total >= 0), drafted integer NOT NULL DEFAULT 0 CHECK (drafted >= 0), rounds integer NOT NULL DEFAULT 0 CHECK (rounds >= 0), error text CHECK (error IS NULL OR length(error) <= 500), started_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, PRIMARY KEY (creator_id, locale) );
CREATE INDEX IF NOT EXISTS store_translation_jobs_running_idx ON public.store_translation_jobs (lease_until) WHERE status = 'running';
ALTER TABLE public.store_translation_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_translation_jobs FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('177', '177_translation_jobs.sql', '18b0172c415ba12483c37e036aacc24d62831504f1716d509da7af07f36888ae') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 178_translation_memory.sql
/* Translation memory: every run of words an open translation model (LibreTranslate, or Hugging Face's opus-mt and NLLB) has translated, kept for good, so the same words are never sent twice: "Add to cart" into French is translated once for every store, a website translated again after a small edit sends only the new words, and a language translated after a failure picks up where it stopped. Keyed by the languages and the sha256 of the words; the words themselves are kept beside it for checking. Only website text that is already public goes in, never a customer's details. Server only. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.translation_memory ( source_lang text NOT NULL CHECK (length(source_lang) BETWEEN 2 AND 12), target_lang text NOT NULL CHECK (length(target_lang) BETWEEN 2 AND 12), source_hash text NOT NULL CHECK (source_hash ~ '^[0-9a-f]{64}$'), source_text text NOT NULL CHECK (length(source_text) <= 20000), translated text NOT NULL CHECK (length(translated) <= 40000), provider text NOT NULL DEFAULT 'libretranslate' CHECK (provider IN ('gemini', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai')), created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (source_lang, target_lang, source_hash) );
ALTER TABLE public.translation_memory DROP CONSTRAINT IF EXISTS translation_memory_provider_check;
ALTER TABLE public.translation_memory ADD CONSTRAINT translation_memory_provider_check CHECK (provider IN ('gemini', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai'));
ALTER TABLE public.translation_memory ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.translation_memory FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('178', '178_translation_memory.sql', 'ed0097c2b24f1aba1a2479d6ec000d376159572fd3ffc7a9228d7d069bdd9e52') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 179_cache_invalidation_pings.sql
/* A store's caches are cleared when its products change in the database, whoever changed them: the product editor, the course builder and the OnePage's products tab write products straight from the browser, and a sale changes stock in a function, so no route was told and the website and Explore showed the old price or stock until their minute ran out. A trigger on products, product_variants, inventory_levels, product_collections and product_collection_items posts one small message per store, kind and product, per transaction, to Storelib's /api/internal/invalidate through pg_net, after the write commits; it never slows or stops the write, and does nothing until pg_net is enabled and the address and secret are set in the server only table storelib_cache_invalidation (one row: url, secret; the secret is the same value as the CACHE_INVALIDATE_SECRET environment variable on Vercel). Without pg_net the triggers are skipped with a notice; enable pg_net in Database > Extensions and run this part again. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.storelib_cache_invalidation (id boolean PRIMARY KEY DEFAULT true CHECK (id), url text CHECK (url IS NULL OR (url ~ '^https?://' AND length(url) <= 500)), secret text CHECK (secret IS NULL OR length(secret) BETWEEN 32 AND 200), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.storelib_cache_invalidation ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.storelib_cache_invalidation FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_cache_invalidation (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
CREATE OR REPLACE FUNCTION public.storelib_cache_ping() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE r jsonb; v_kind text := TG_ARGV[0]; v_creator uuid; v_product uuid; v_slug text; v_url text; v_secret text; v_key text; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RETURN NULL; END IF; SELECT c.url, c.secret INTO v_url, v_secret FROM public.storelib_cache_invalidation c WHERE c.id; IF coalesce(v_url, '') !~ '^https?://' OR coalesce(v_secret, '') = '' THEN RETURN NULL; END IF; BEGIN IF TG_OP = 'DELETE' THEN r := to_jsonb(OLD); ELSE r := to_jsonb(NEW); END IF; IF v_kind = 'product' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; v_product := nullif(r ->> 'id', '')::uuid; v_slug := r ->> 'slug'; ELSIF v_kind = 'variant' THEN v_product := nullif(r ->> 'product_id', '')::uuid; SELECT p.creator_id, p.slug INTO v_creator, v_slug FROM public.products p WHERE p.id = v_product; ELSIF v_kind = 'inventory' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; SELECT v.product_id, p.slug INTO v_product, v_slug FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = nullif(r ->> 'variant_id', '')::uuid; ELSIF v_kind = 'collection' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; IF v_creator IS NULL THEN SELECT c.creator_id INTO v_creator FROM public.product_collections c WHERE c.id = nullif(r ->> 'collection_id', '')::uuid; END IF; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; v_key := 'storelib_cache_ping.k' || md5(v_kind || ':' || v_creator::text || ':' || coalesce(v_product::text, '')); IF current_setting(v_key, true) = '1' THEN RETURN NULL; END IF; PERFORM set_config(v_key, '1', true); PERFORM net.http_post(url := v_url, body := jsonb_build_object('creatorId', v_creator, 'kind', v_kind, 'productId', v_product, 'slug', v_slug, 'op', TG_OP), params := '{}'::jsonb, headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret), timeout_milliseconds := 3000); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'storelib cache ping skipped: %', SQLERRM; END; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_cache_ping() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the products trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 179: products is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.products; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('product'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_variants trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_variants') IS NULL THEN RAISE NOTICE 'part 179: product_variants is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_variants; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('variant'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the inventory_levels trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.inventory_levels') IS NULL THEN RAISE NOTICE 'part 179: inventory_levels is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.inventory_levels; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.inventory_levels FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('inventory'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collections trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collections') IS NULL THEN RAISE NOTICE 'part 179: product_collections is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collections; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collections FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collection_items trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collection_items') IS NULL THEN RAISE NOTICE 'part 179: product_collection_items is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collection_items; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collection_items FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('179', '179_cache_invalidation_pings.sql', '6782ec428c895abef8920e6daf39916bf42010018170c2e29d8c0325a2e6dddc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 180_site_releases.sql
/* Every Publish kept as a release that never changes: `site_releases`, one row per publish of a website (its creator, its install, when, and a manifest of the live theme settings, every page's live sections and every live theme file by path with the sha256 of its text), `theme_file_blobs`, each file's text kept once by its sha256 however many releases and websites share it, and `site_live_releases`, which release a website is drawn from now. A trigger `site_live_release_forget` on `store_theme_custom_files`, `store_theme_settings` and `store_theme_pages` lets go of that pointer whenever a live file, setting or page changes any other way than a publish (a file deleted or renamed in the code editor, a live setting saved), so the website is then drawn from its rows exactly as before until the next Publish. Draft saves do not touch it. Server only: row level security on, nothing for visitors or signed in users. Changes no existing row. Needs the theme tables (RUN_CREATOR_PAGE_AND_SITES); without them it skips itself with a notice. Until it runs, Publish and the live website work exactly as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_file_blobs (sha256 text PRIMARY KEY CHECK (sha256 ~ '^[0-9a-f]{64}$'), content text NOT NULL, size integer NOT NULL DEFAULT 0 CHECK (size >= 0), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.theme_file_blobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.theme_file_blobs FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'part 180: store_theme_installs is missing, site_releases is skipped. Run the theme tables first, then this part again.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL, install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), manifest jsonb NOT NULL CHECK (jsonb_typeof(manifest) = 'object'), file_count integer NOT NULL DEFAULT 0 CHECK (file_count >= 0), total_bytes bigint NOT NULL DEFAULT 0 CHECK (total_bytes >= 0)); CREATE INDEX IF NOT EXISTS idx_site_releases_install_created ON public.site_releases (install_id, created_at DESC); ALTER TABLE public.site_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_releases FROM PUBLIC, anon, authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.site_releases') IS NULL THEN RAISE NOTICE 'part 180: site_releases is missing, site_live_releases is skipped.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_live_releases (install_id uuid PRIMARY KEY REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, creator_id uuid NOT NULL, release_id uuid REFERENCES public.site_releases(id) ON DELETE SET NULL, rev bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_site_live_releases_creator ON public.site_live_releases (creator_id); ALTER TABLE public.site_live_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_live_releases FROM PUBLIC, anon, authenticated; END $do$;
CREATE OR REPLACE FUNCTION public.site_live_release_forget() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$ DECLARE v_old uuid; v_new uuid; v_flag text; BEGIN IF to_regclass('public.site_live_releases') IS NULL THEN RETURN NULL; END IF; IF TG_OP <> 'INSERT' THEN v_old := OLD.install_id; END IF; IF TG_OP <> 'DELETE' THEN v_new := NEW.install_id; END IF; IF TG_ARGV[0] = 'file' THEN IF TG_OP = 'INSERT' AND coalesce(NEW.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'DELETE' AND coalesce(OLD.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'UPDATE' AND NEW.content IS NOT DISTINCT FROM OLD.content AND NEW.path IS NOT DISTINCT FROM OLD.path AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'settings' THEN IF TG_OP = 'UPDATE' AND NEW.settings IS NOT DISTINCT FROM OLD.settings AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'page' THEN IF TG_OP = 'UPDATE' AND NEW.sections IS NOT DISTINCT FROM OLD.sections AND NEW.page_key IS NOT DISTINCT FROM OLD.page_key AND v_old = v_new THEN RETURN NULL; END IF; END IF; IF v_old IS NULL OR v_new IS NULL OR v_old = v_new THEN v_flag := coalesce(current_setting('storelib.release_forgot', true), ''); IF position(coalesce(v_new, v_old)::text IN v_flag) > 0 THEN RETURN NULL; END IF; PERFORM set_config('storelib.release_forgot', v_flag || ',' || coalesce(v_new, v_old)::text, true); END IF; UPDATE public.site_live_releases SET release_id = NULL, rev = rev + 1, updated_at = now() WHERE install_id = v_old OR install_id = v_new; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.site_live_release_forget() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'part 180: store_theme_custom_files is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_custom_files; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF content, path, install_id ON public.store_theme_custom_files FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('file'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_settings') IS NULL THEN RAISE NOTICE 'part 180: store_theme_settings is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_settings; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF settings, install_id ON public.store_theme_settings FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('settings'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_pages') IS NULL THEN RAISE NOTICE 'part 180: store_theme_pages is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_pages; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF sections, page_key, install_id ON public.store_theme_pages FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('page'); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('180', '180_site_releases.sql', '1bffcf1f0aff9d8c9f3edbd913ec0b4e3b928afcbd38f1264bf253dd085e1a76') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 184_community_analytics.sql
/* Community analytics, run after parts 81, 85, 87 and 102. What a community's Analytics in /app counts that nothing kept before. A visit to a community's page (one a visitor a day, part 87) now also keeps how the visitor arrived (a source such as Search, Instagram or Explore, and the site that sent them), the kind of device, the country, and whether they were already a member: four new columns on the server only table `community_view_days`, written by the new server only function `community_record_visit`, which counts the view exactly as `community_record_view` does. The nightly count adds each day's visitors and visitors who were not members to `community_daily_stats` (two new columns, empty until counted) and keeps the day's sources, sites, devices and countries as counts in the new server only table `community_daily_traffic`, so nothing about a visitor is kept past the three days part 87 keeps. A member who opens their community is written once a day to the new server only table `community_member_days` (the community, the member, the day), which is how active members are counted for a day, a week, a month or any period. The server only function `community_analytics` counts, per hour, day or month of the viewer's time zone, the joins, leaves, posts, comments, reactions, RSVPs, lessons completed, members who took part and members active, and for the period shown the top contributors, the busiest spaces, how many members who joined in each of the last six months are still in, and each program's progress. Two indexes, `community_feed_posts_community_created_idx` and `community_feed_comments_community_created_idx` (community, newest first), so those counts read only the period: building them holds new posts and comments back for a moment on a large community. No existing rows change. Until it runs, Analytics shows the figures the nightly count already keeps, without visits, sources, devices, countries, active members over time, top contributors, spaces, retention and program progress. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_view_days') IS NULL THEN RAISE NOTICE 'community analytics: there is no community_view_days table, run part 87 first.'; RETURN; END IF; ALTER TABLE public.community_view_days ADD COLUMN IF NOT EXISTS source text, ADD COLUMN IF NOT EXISTS referrer text, ADD COLUMN IF NOT EXISTS device text, ADD COLUMN IF NOT EXISTS country text, ADD COLUMN IF NOT EXISTS member boolean; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_view_days_facts_check') THEN ALTER TABLE public.community_view_days ADD CONSTRAINT community_view_days_facts_check CHECK ((source IS NULL OR char_length(source) BETWEEN 1 AND 40) AND (referrer IS NULL OR char_length(referrer) BETWEEN 1 AND 120) AND (device IS NULL OR device IN ('mobile', 'tablet', 'desktop')) AND (country IS NULL OR country ~ '^[A-Z]{2}$')); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_daily_stats') IS NULL THEN RAISE NOTICE 'community analytics: there is no community_daily_stats table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_daily_stats ADD COLUMN IF NOT EXISTS visitors integer, ADD COLUMN IF NOT EXISTS prospects integer; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_daily_stats_visitors_check') THEN ALTER TABLE public.community_daily_stats ADD CONSTRAINT community_daily_stats_visitors_check CHECK ((visitors IS NULL OR visitors >= 0) AND (prospects IS NULL OR prospects >= 0)); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_daily_traffic (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, day date NOT NULL, dimension text NOT NULL, key text NOT NULL, visitors integer NOT NULL DEFAULT 0, CONSTRAINT community_daily_traffic_pkey PRIMARY KEY (community_id, day, dimension, key), CONSTRAINT community_daily_traffic_dimension_check CHECK (dimension IN ('source', 'referrer', 'device', 'country')), CONSTRAINT community_daily_traffic_key_len CHECK (char_length(key) BETWEEN 1 AND 120), CONSTRAINT community_daily_traffic_visitors_check CHECK (visitors >= 0));
ALTER TABLE public.community_daily_traffic ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_daily_traffic FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_daily_traffic TO service_role;
CREATE TABLE IF NOT EXISTS public.community_member_days (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, day date NOT NULL, CONSTRAINT community_member_days_pkey PRIMARY KEY (community_id, day, user_id));
ALTER TABLE public.community_member_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_member_days FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.community_member_days TO service_role;
CREATE INDEX IF NOT EXISTS community_feed_posts_community_created_idx ON public.community_feed_posts (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_feed_comments_community_created_idx ON public.community_feed_comments (community_id, created_at DESC);
CREATE OR REPLACE FUNCTION public.community_record_visit(p_community uuid, p_visitor text, p_source text, p_referrer text, p_device text, p_country text, p_member boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_new integer; BEGIN IF p_community IS NULL OR p_visitor IS NULL OR char_length(p_visitor) NOT BETWEEN 16 AND 128 THEN RETURN false; END IF; INSERT INTO public.community_view_days (community_id, visitor_key, day, source, referrer, device, country, member) SELECT c.id, p_visitor, (now() AT TIME ZONE 'UTC')::date, CASE WHEN char_length(p_source) BETWEEN 1 AND 40 THEN p_source END, CASE WHEN char_length(p_referrer) BETWEEN 1 AND 120 THEN lower(p_referrer) END, CASE WHEN p_device IN ('mobile', 'tablet', 'desktop') THEN p_device END, CASE WHEN p_country ~ '^[A-Z]{2}$' THEN p_country END, p_member FROM public.communities c WHERE c.id = p_community ON CONFLICT (community_id, visitor_key, day) DO NOTHING; GET DIAGNOSTICS v_new = ROW_COUNT; IF v_new = 0 THEN RETURN false; END IF; UPDATE public.communities SET view_count = view_count + 1 WHERE id = p_community; RETURN true; END $f$;
REVOKE ALL ON FUNCTION public.community_record_visit(uuid, text, text, text, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_record_visit(uuid, text, text, text, text, text, boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.community_analytics(p_community uuid, p_from timestamptz, p_to timestamptz, p_tz text DEFAULT 'UTC', p_grain text DEFAULT 'day', p_detail boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_grain text := 'day'; v_fmt text; v_owner uuid; v_out jsonb; v_detail jsonb := '{}'::jsonb; v_end_month date; BEGIN IF p_community IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '800 days' THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; IF p_grain IN ('hour', 'day', 'month') THEN v_grain := p_grain; END IF; v_fmt := CASE v_grain WHEN 'hour' THEN 'YYYY-MM-DD"T"HH24' WHEN 'day' THEN 'YYYY-MM-DD' ELSE 'YYYY-MM' END; SELECT owner_user_id INTO v_owner FROM public.communities WHERE id = p_community; WITH act AS (SELECT kind, user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_activity WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND kind IN ('joined', 'left', 'post', 'comment', 'reaction', 'lesson_completed', 'course_completed')), posts AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_posts WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), comments AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_comments WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), reactions AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_reactions WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), rsvps AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_event_rsvps WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), days AS (SELECT user_id, CASE v_grain WHEN 'month' THEN to_char(day, 'YYYY-MM') ELSE to_char(day, 'YYYY-MM-DD') END AS b FROM public.community_member_days WHERE community_id = p_community AND day >= (p_from AT TIME ZONE v_tz)::date AND day <= ((p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date) SELECT jsonb_build_object('joined', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'joined' AND user_id IS DISTINCT FROM v_owner GROUP BY b) x), 'left', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'left' GROUP BY b) x), 'posts', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM posts GROUP BY b) x), 'comments', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM comments GROUP BY b) x), 'reactions', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM reactions GROUP BY b) x), 'rsvps', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM rsvps GROUP BY b) x), 'lessons', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'lesson_completed' GROUP BY b) x), 'contributors', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM act WHERE kind IN ('post', 'comment', 'reaction') AND user_id IS NOT NULL GROUP BY b) x), 'active', CASE WHEN v_grain = 'hour' THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM days GROUP BY b) x) END, 'totals', jsonb_build_object('contributors', (SELECT count(DISTINCT user_id) FROM act WHERE kind IN ('post', 'comment', 'reaction') AND user_id IS NOT NULL), 'posters', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'post' AND user_id IS NOT NULL), 'commenters', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'comment' AND user_id IS NOT NULL), 'reactors', (SELECT count(DISTINCT user_id) FROM act WHERE kind = 'reaction' AND user_id IS NOT NULL), 'active', (SELECT count(DISTINCT user_id) FROM days), 'courses', (SELECT count(*) FROM act WHERE kind = 'course_completed')), 'active_since', (SELECT min(day) FROM public.community_member_days WHERE community_id = p_community)) INTO v_out; IF p_detail THEN v_end_month := date_trunc('month', (p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date; v_detail := jsonb_build_object('top_contributors', (SELECT coalesce(jsonb_agg(x ORDER BY x.score DESC, x.user_id), '[]'::jsonb) FROM (SELECT u.user_id, sum(u.posts)::int AS posts, sum(u.comments)::int AS comments, sum(u.posts) * 2 + sum(u.comments) AS score FROM (SELECT author_id AS user_id, 1 AS posts, 0 AS comments FROM public.community_feed_posts WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to UNION ALL SELECT author_id, 0, 1 FROM public.community_feed_comments WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to) u GROUP BY u.user_id ORDER BY score DESC, u.user_id LIMIT 10) x), 'top_spaces', (SELECT coalesce(jsonb_agg(x ORDER BY (x.posts + x.comments) DESC, x.name), '[]'::jsonb) FROM (SELECT s.id, s.name, s.slug, (SELECT count(*) FROM public.community_feed_posts p WHERE p.space_id = s.id AND p.status = 'published' AND p.created_at >= p_from AND p.created_at < p_to)::int AS posts, (SELECT count(*) FROM public.community_feed_comments c JOIN public.community_feed_posts p ON p.id = c.post_id WHERE p.space_id = s.id AND c.status = 'published' AND c.created_at >= p_from AND c.created_at < p_to)::int AS comments FROM public.community_spaces s WHERE s.community_id = p_community AND s.archived_at IS NULL) x WHERE x.posts + x.comments > 0), 'cohorts', (SELECT coalesce(jsonb_agg(x ORDER BY x.month DESC), '[]'::jsonb) FROM (SELECT to_char(date_trunc('month', m.joined_at AT TIME ZONE v_tz), 'YYYY-MM') AS month, count(*)::int AS joined, count(*) FILTER (WHERE m.status = 'active')::int AS stayed, count(*) FILTER (WHERE m.status = 'active' AND greatest(m.last_seen_at, m.last_active_at) >= now() - interval '30 days')::int AS active FROM public.community_members m WHERE m.community_id = p_community AND m.role <> 'owner' AND m.joined_at IS NOT NULL AND m.joined_at AT TIME ZONE v_tz >= (v_end_month - interval '5 months') AND m.joined_at AT TIME ZONE v_tz < (v_end_month + interval '1 month') GROUP BY 1) x), 'programs', (SELECT coalesce(jsonb_agg(x ORDER BY x.started DESC, x.title), '[]'::jsonb) FROM (SELECT cc.id, coalesce(nullif(cc.title, ''), pr.title, 'Program') AS title, count(e.id)::int AS started, count(e.completed_at)::int AS completed, coalesce(round(avg(e.percent))::int, 0) AS percent, (SELECT count(*) FROM public.community_activity a WHERE a.community_id = p_community AND a.kind = 'lesson_completed' AND a.created_at >= p_from AND a.created_at < p_to AND a.target_id IN (cc.id::text, cc.product_id::text))::int AS lessons FROM public.community_courses cc LEFT JOIN public.products pr ON pr.id = cc.product_id LEFT JOIN public.courses co ON co.id = coalesce(cc.course_id, (SELECT c2.id FROM public.courses c2 WHERE c2.product_id = cc.product_id ORDER BY c2.created_at LIMIT 1)) LEFT JOIN public.course_enrollments e ON e.course_id = co.id AND EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = e.buyer_id AND m.status = 'active') WHERE cc.community_id = p_community AND coalesce(cc.status, 'published') = 'published' GROUP BY cc.id, cc.title, pr.title, cc.product_id LIMIT 20) x)); END IF; RETURN v_out || v_detail; END $f$;
REVOKE ALL ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('184', '184_community_analytics.sql', 'ffcb48cf432c715b31c848adf4ea22bf8bedd3ff1bb62ad1b643c87dd6131654') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 185_community_domains.sql
/* A connected domain can serve one community (round 31), run after part 22. Two new nullable columns on `custom_domains`, `target_type` ('community') and `target_id` (the community's id, so a renamed community keeps its domain), empty for every other domain; 'community' joins the allowed purposes; a check that a community domain names its community and is never primary, and that no other domain names anything; and one domain per community, held by a unique index. No existing row changes: all of them have empty targets and a purpose that was already allowed. Until it runs, Settings › Domains does not offer Community and the routes refuse it. Safe to run again. */
ALTER TABLE public.custom_domains ADD COLUMN IF NOT EXISTS target_type TEXT;
ALTER TABLE public.custom_domains ADD COLUMN IF NOT EXISTS target_id UUID;
ALTER TABLE public.custom_domains DROP CONSTRAINT IF EXISTS custom_domains_purpose_check;
ALTER TABLE public.custom_domains ADD CONSTRAINT custom_domains_purpose_check CHECK (purpose IN ('website', 'creator_page', 'community')) NOT VALID;
ALTER TABLE public.custom_domains DROP CONSTRAINT IF EXISTS custom_domains_target_check;
ALTER TABLE public.custom_domains ADD CONSTRAINT custom_domains_target_check CHECK ((purpose = 'community' AND target_type = 'community' AND target_id IS NOT NULL AND is_primary = false) OR (purpose <> 'community' AND target_type IS NULL AND target_id IS NULL)) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS custom_domains_one_per_target ON public.custom_domains (target_type, target_id) WHERE target_id IS NOT NULL;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('185', '185_community_domains.sql', 'cf8fc37d786bd7be59817e7b064c366971d71119b19ae548f46eb21328c50329') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 186_translation_queue.sql
/* Translate changes within minutes of a publish. `store_localization.translate_dirty_at` (part 136's table): when a store with "Translate changes automatically" on publishes its website, saves a menu, a product or a collection, the server writes the time here. The translation run every three minutes (/api/cron/translation-jobs) takes the stores whose last change is a couple of minutes old, so a burst of edits is translated once, and clears it when the store is up to date; the hourly sweep (/api/cron/translations) only queues a store nothing has queued for a day. `store_localization.translate_lease_until`: while one run translates a store no other run takes it. Both empty for every store until something is saved. A translation the merchant wrote or edited is never replaced. Server only, as the table already is. No rows change. Skips itself with a notice where the table is not there (run 136 first). Until it runs, the hourly run works through the stores as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'translation queue: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS translate_dirty_at timestamptz; ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS translate_lease_until timestamptz; CREATE INDEX IF NOT EXISTS idx_store_localization_translate_dirty ON public.store_localization (translate_dirty_at) WHERE translate_dirty_at IS NOT NULL; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('186', '186_translation_queue.sql', 'd67972ebbb1121f9e66e154be23eb3a9163853a153279140c48dd91a77cf5421') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 187_hot_path_indexes.sql
/* Indexes for reads that searched a whole table on every call, found by reading the code against every index in the repository. orders by stripe_session_id (the Stripe webhook's duplicate check, the receipt, success and thank you pages, a cart's sibling lines) and by stripe_payment_intent_id (refund and dispute webhooks); commerce_checkouts by receipt_token (a buyer's order page, its cancel button, a support case) and by session_fingerprint (the receipt of a cart a code made free); profiles by email (every paid checkout links the buyer's account by email, and the password reset and account checks ask the same); membership_invoices by order_id (the buyer's library); community_bookmarks by post_id (the community feed counts saves per post); community_feed_posts by space_id whatever the status (the community's Feed and Spaces pages in /app count the posts in each space). Nothing else changes: no row, column, rule or function. Each index is made only when its table is there and the index is not, with a notice naming what was skipped. A plain CREATE INDEX stops writes to its table while it builds, and the editor holds that until the whole paste ends: on a large orders, profiles or commerce_checkouts table run supabase/sql/RUN_HOT_PATH_INDEXES_CONCURRENTLY.sql first, line by line, and this part then finds every index made and takes no lock. Before it runs the app works the same, only slower as those tables grow. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders_stripe_session_idx skipped: public.orders does not exist here'; RETURN; END IF; IF to_regclass('public.orders_stripe_session_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_stripe_session_idx ON public.orders (stripe_session_id) WHERE stripe_session_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders_stripe_payment_intent_idx skipped: public.orders does not exist here'; RETURN; END IF; IF to_regclass('public.orders_stripe_payment_intent_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_stripe_payment_intent_idx ON public.orders (stripe_payment_intent_id) WHERE stripe_payment_intent_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'commerce_checkouts_receipt_token_idx skipped: public.commerce_checkouts does not exist here'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_receipt_token_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_checkouts_receipt_token_idx ON public.commerce_checkouts (receipt_token) WHERE receipt_token IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'commerce_checkouts_session_fingerprint_idx skipped: public.commerce_checkouts does not exist here'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_session_fingerprint_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_checkouts_session_fingerprint_idx ON public.commerce_checkouts (session_fingerprint) WHERE session_fingerprint IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profiles_email_idx skipped: public.profiles does not exist here'; RETURN; END IF; IF to_regclass('public.profiles_email_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS profiles_email_idx ON public.profiles (email); END $do$;
DO $do$ BEGIN IF to_regclass('public.membership_invoices') IS NULL THEN RAISE NOTICE 'membership_invoices_order_idx skipped: public.membership_invoices does not exist here (part 75)'; RETURN; END IF; IF to_regclass('public.membership_invoices_order_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS membership_invoices_order_idx ON public.membership_invoices (order_id) WHERE order_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_bookmarks') IS NULL THEN RAISE NOTICE 'community_bookmarks_post_idx skipped: public.community_bookmarks does not exist here (part 81)'; RETURN; END IF; IF to_regclass('public.community_bookmarks_post_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_bookmarks_post_idx ON public.community_bookmarks (post_id); END $do$;
DO $do$ BEGIN IF to_regclass('public.community_feed_posts') IS NULL THEN RAISE NOTICE 'community_feed_posts_space_any_status_idx skipped: public.community_feed_posts does not exist here (part 81)'; RETURN; END IF; IF to_regclass('public.community_feed_posts_space_any_status_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_feed_posts_space_any_status_idx ON public.community_feed_posts (space_id) WHERE space_id IS NOT NULL; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('187', '187_hot_path_indexes.sql', '37a80bad2b7c44971ea2d5ad16f4fa50da1c38f10fd11b14c8e7586bf3fe71dd') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 188_site_release_rollback.sql
/* Put an earlier published version of a website live again (Website settings › Backups & Versions › Published versions), run after parts 130 and 180. A new server only function `rollback_site_release(install, creator, release)` writes that release back into the live rows in one transaction, under the same per creator lock Publish takes (part 130): the live theme settings, every page's live sections (a page the release did not have is removed) and every theme file from `theme_file_blobs` (a file the release did not have is removed), each draft cleared, this website switched live as Publish switches it, then the same manifest kept as a new release marked `restored_from` and the website pointed at it, its `rev` counted up so a release still being written by an earlier Publish cannot take the pointer back. Refuses a release of another website or creator, one it cannot read, and one with a file whose text is missing, changing nothing. Adds `site_releases.restored_from`. Only the service role can call it. Changes no existing row. Needs the theme tables and part 180; without them it skips itself with a notice. Until it runs, Published versions does not show and nothing else changes. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.site_releases') IS NULL OR to_regclass('public.site_live_releases') IS NULL OR to_regclass('public.theme_file_blobs') IS NULL OR to_regclass('public.store_theme_installs') IS NULL OR to_regclass('public.store_theme_pages') IS NULL OR to_regclass('public.store_theme_settings') IS NULL OR to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'part 188: the theme tables or part 180 are not there yet, rollback is skipped. Run them, then this part again.'; RETURN; END IF; ALTER TABLE public.site_releases ADD COLUMN IF NOT EXISTS restored_from uuid; ALTER TABLE public.store_theme_installs ADD COLUMN IF NOT EXISTS published_at timestamptz; ALTER TABLE public.store_theme_custom_files ADD COLUMN IF NOT EXISTS draft_content text; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.rollback_site_release(p_install uuid, p_creator uuid, p_release uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $body$ DECLARE v_from public.site_releases%ROWTYPE; v_m jsonb; v_missing integer; v_files jsonb; v_was jsonb; v_settings jsonb; v_new uuid; BEGIN IF NOT EXISTS (SELECT 1 FROM public.store_theme_installs WHERE id = p_install AND creator_id = p_creator) THEN RAISE EXCEPTION 'rollback: this website is not this creator''s' USING ERRCODE = 'P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('storelib-publish:' || p_creator::text, 0)); SELECT * INTO v_from FROM public.site_releases WHERE id = p_release AND install_id = p_install AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'rollback: no such release of this website' USING ERRCODE = 'P0002'; END IF; v_m := v_from.manifest; IF (v_m->>'v') IS DISTINCT FROM '1' OR jsonb_typeof(v_m->'files') IS DISTINCT FROM 'array' OR jsonb_typeof(v_m->'pages') IS DISTINCT FROM 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'pages') p WHERE jsonb_typeof(p->'page_key') IS DISTINCT FROM 'string') OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'files') f WHERE jsonb_typeof(f->'path') IS DISTINCT FROM 'string' OR jsonb_typeof(f->'sha256') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'rollback: the release cannot be read' USING ERRCODE = '22023'; END IF; SELECT count(*) INTO v_missing FROM jsonb_array_elements(v_m->'files') f WHERE NOT EXISTS (SELECT 1 FROM public.theme_file_blobs b WHERE b.sha256 = f->>'sha256'); IF v_missing > 0 THEN RAISE EXCEPTION 'rollback: % files of the release are missing', v_missing USING ERRCODE = '22023'; END IF; SELECT COALESCE(jsonb_agg(jsonb_build_object('path', f->>'path', 'content', b.content)), '[]'::jsonb) INTO v_files FROM jsonb_array_elements(v_m->'files') f JOIN public.theme_file_blobs b ON b.sha256 = f->>'sha256' LEFT JOIN public.store_theme_custom_files c ON c.install_id = p_install AND c.path = f->>'path' WHERE c.content IS DISTINCT FROM b.content; IF jsonb_typeof(v_m->'settings') = 'object' THEN INSERT INTO public.store_theme_settings (install_id, settings, draft_settings) VALUES (p_install, v_m->'settings', NULL) ON CONFLICT (install_id) DO UPDATE SET settings = EXCLUDED.settings, draft_settings = NULL; ELSE UPDATE public.store_theme_settings SET settings = '{}'::jsonb, draft_settings = NULL WHERE install_id = p_install; END IF; DELETE FROM public.store_theme_pages t WHERE t.install_id = p_install AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'pages') p WHERE p->>'page_key' = t.page_key); INSERT INTO public.store_theme_pages (install_id, page_key, sections, draft_sections) SELECT DISTINCT ON (p->>'page_key') p_install, p->>'page_key', COALESCE(NULLIF(p->'sections', 'null'::jsonb), '[]'::jsonb), NULL FROM jsonb_array_elements(v_m->'pages') p ORDER BY p->>'page_key' ON CONFLICT (install_id, page_key) DO UPDATE SET sections = EXCLUDED.sections, draft_sections = NULL; DELETE FROM public.store_theme_custom_files c WHERE c.install_id = p_install AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_m->'files') f WHERE f->>'path' = c.path); INSERT INTO public.store_theme_custom_files (install_id, path, content, draft_content) SELECT DISTINCT ON (f->>'path') p_install, f->>'path', b.content, NULL FROM jsonb_array_elements(v_m->'files') f JOIN public.theme_file_blobs b ON b.sha256 = f->>'sha256' ORDER BY f->>'path' ON CONFLICT (install_id, path) DO UPDATE SET content = EXCLUDED.content, draft_content = NULL; WITH down AS (UPDATE public.store_theme_installs SET status = 'unpublished' WHERE creator_id = p_creator AND status = 'published' AND id <> p_install RETURNING id) SELECT COALESCE(jsonb_agg(id), '[]'::jsonb) INTO v_was FROM down; UPDATE public.store_theme_installs SET status = 'published', published_at = now() WHERE id = p_install; SELECT settings INTO v_settings FROM public.store_theme_settings WHERE install_id = p_install; INSERT INTO public.site_releases (creator_id, install_id, manifest, file_count, total_bytes, restored_from) VALUES (p_creator, p_install, jsonb_set(v_m, '{settings}', COALESCE(v_settings, 'null'::jsonb)), v_from.file_count, v_from.total_bytes, p_release) RETURNING id INTO v_new; INSERT INTO public.site_live_releases (install_id, creator_id, release_id, rev, updated_at) VALUES (p_install, p_creator, v_new, 1, now()) ON CONFLICT (install_id) DO UPDATE SET release_id = EXCLUDED.release_id, creator_id = EXCLUDED.creator_id, rev = public.site_live_releases.rev + 1, updated_at = now(); RETURN jsonb_build_object('release_id', v_new, 'was_live', v_was, 'files', v_files); END $body$$fn$; REVOKE ALL ON FUNCTION public.rollback_site_release(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.rollback_site_release(uuid, uuid, uuid) TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('188', '188_site_release_rollback.sql', '1aaf18e28e87f0fe06a91e07be428873b582ccf2be2c51258faed9f511b486d5') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 189_username_history_and_flow_log_locked.sql
/* Two tables a browser could change or read with the public key (round 32, tenant isolation). `username_history` (an old handle and the one it became, which every old /@link follows) had one policy, "Service role can manage username_history", FOR ALL USING (true) WITH CHECK (true) and no role named, so it applied to everybody: anybody, signed in or not, could add a row for any account, rewrite one or delete one, and so send any old handle's links to a profile of their choosing. That policy goes. Reading stays open to everybody, as it was (the old and new handle is what each redirect already shows). Adding a row stays open to a signed in person for their own account and their own current username only, which is the row Settings writes from the browser just before it saves a new username (components/app/settings-form-new.tsx); changing and deleting rows, and anything at all without signing in, are taken away. The server writes it with its own key (app/api/profile/username), which row level security does not stop. `flow_execution_log` (the older email automation runs, with each recipient's address) never had row level security; it is turned on with no policy and taken from anon and authenticated, since only the server reads or writes it. Either table missing is skipped with a notice. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.username_history') IS NULL THEN RAISE NOTICE 'username_history is not there: nothing to lock.'; RETURN; END IF; ALTER TABLE public.username_history ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Service role can manage username_history" ON public.username_history; DROP POLICY IF EXISTS username_history_read ON public.username_history; CREATE POLICY username_history_read ON public.username_history FOR SELECT TO anon, authenticated USING (true); DROP POLICY IF EXISTS username_history_add_own ON public.username_history; CREATE POLICY username_history_add_own ON public.username_history FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND lower(old_username) = lower((SELECT p.username FROM public.profiles p WHERE p.id = (SELECT auth.uid())))); REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.username_history FROM PUBLIC, anon; REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.username_history FROM authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.flow_execution_log') IS NULL THEN RAISE NOTICE 'flow_execution_log is not there: nothing to lock.'; RETURN; END IF; ALTER TABLE public.flow_execution_log ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.flow_execution_log FROM PUBLIC, anon, authenticated; GRANT ALL ON public.flow_execution_log TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('189', '189_username_history_and_flow_log_locked.sql', '1e39a172ce209b1bf0dc17729c22eb27ac7ae5098354e69bdd31178bd7f97e84') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 190_orders_one_row_per_payment_line.sql
/* One order row per line of a payment. The Stripe webhook looks an order up by orders.stripe_session_id before it writes one, so a second delivery of the same payment writes nothing, but two deliveries at the same moment both find nothing and both write, and nothing in the database refused the second. A plain unique index on stripe_session_id would be wrong: a basket (lib/checkout/fulfil-cart-item.ts) and a physical order (lib/physical/checkout-server.ts) write one row per line, all with the same session. What tells those lines apart is receipt_token: a basket's line has cartReceiptToken(session, its place in the basket), and a single product's order has the token the checkout put in the session's metadata, the same on every delivery. So the key is (stripe_session_id, receipt_token), only where both are set: the second insert of a line fails with 23505, and the webhook reads the first one back. Made only when no line is already written twice; otherwise it skips itself with a notice giving the count and the query to see them, and changes nothing. Changes no row. Nothing where there is no orders table. Needs nothing else. LOCK: a plain CREATE UNIQUE INDEX stops inserts, updates and deletes on orders while it builds (seconds on a large table), and the editor holds that until the paste ends. Until it runs, orders are written as before. Safe to run again. */
DO $do$ DECLARE n bigint; BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'part 190: there is no orders table, nothing to do.'; RETURN; END IF; IF to_regclass('public.orders_stripe_session_line_key') IS NOT NULL THEN RETURN; END IF; SELECT count(*) INTO n FROM (SELECT 1 FROM public.orders WHERE stripe_session_id IS NOT NULL AND receipt_token IS NOT NULL GROUP BY stripe_session_id, receipt_token HAVING count(*) > 1) d; IF n > 0 THEN RAISE NOTICE 'part 190 skipped: % payment lines are written more than once, so the one row per payment line index was not made. See them with: select stripe_session_id, receipt_token, count(*), array_agg(id order by created_at) from public.orders where stripe_session_id is not null and receipt_token is not null group by 1, 2 having count(*) > 1;', n; RETURN; END IF; CREATE UNIQUE INDEX IF NOT EXISTS orders_stripe_session_line_key ON public.orders (stripe_session_id, receipt_token) WHERE stripe_session_id IS NOT NULL AND receipt_token IS NOT NULL; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('190', '190_orders_one_row_per_payment_line.sql', '65db81be6dcbad2ed985f8a7a390d03a7207318775817d6641b019e8bec6b69c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 192_community_join_questions.sql
/* Questions before joining (round 32), run after part 81. A community's owner or admins write up to eight questions people answer when they join (a short answer, a paragraph, one choice, several choices or an email address, each required or not), kept in the new server only table `community_join_forms`, one row per community; what each person answered is kept in the new server only table `community_join_answers`, one row per community and person, with the words of each question as it was asked, so a question changed later does not change an answer already given. The join flow shows the questions, a request waits with its answers for an admin in Requests, and the answers can be downloaded. No existing row changes. Until it runs, joining asks nothing new and Settings shows that the questions need this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_join_forms (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, questions jsonb NOT NULL DEFAULT '[]'::jsonb, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_forms_pkey PRIMARY KEY (community_id), CONSTRAINT community_join_forms_questions_check CHECK (jsonb_typeof(questions) = 'array' AND jsonb_array_length(questions) <= 8 AND pg_column_size(questions) <= 32768));
ALTER TABLE public.community_join_forms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_forms FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_forms TO service_role;
CREATE TABLE IF NOT EXISTS public.community_join_answers (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, answers jsonb NOT NULL DEFAULT '[]'::jsonb, submitted_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_answers_pkey PRIMARY KEY (community_id, user_id), CONSTRAINT community_join_answers_check CHECK (jsonb_typeof(answers) = 'array' AND jsonb_array_length(answers) <= 8 AND pg_column_size(answers) <= 65536));
CREATE INDEX IF NOT EXISTS community_join_answers_submitted_idx ON public.community_join_answers (community_id, submitted_at DESC);
ALTER TABLE public.community_join_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_answers FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_answers TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('192', '192_community_join_questions.sql', '7090be8e994a23906b2beffd6652bcf66372812378d007614c9e0c2e16f0fab6') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 193_community_onboarding_checklist.sql
/* A new member's first steps (round 32), run after part 81. The welcome message needs member messages (part 83) and Chat on; without them it is not sent. A community's owner or admins choose a short list of first steps a new member sees on the feed (introduce yourself, add a line about yourself, read the rules, comment on a post, start a program, RSVP to an event, or a step of their own with a link), and a welcome message sent to each new member as a direct message from the person who runs it: both kept in the new server only table `community_onboarding`, one row per community. What each member has done is the new server only table `community_onboarding_progress`, one row per community, member and step, which also records that the welcome message was sent (once per member) and that the member hid the list. Steps a member does anyway (a post, a comment, a lesson, an RSVP) are read from `community_activity`, which gets an index by community, member and kind for it. No existing row changes. Until it runs, the feed shows the welcome alone, as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_onboarding (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, steps jsonb NOT NULL DEFAULT '[]'::jsonb, dm_enabled boolean NOT NULL DEFAULT false, dm_body text NOT NULL DEFAULT '', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_onboarding_pkey PRIMARY KEY (community_id), CONSTRAINT community_onboarding_steps_check CHECK (jsonb_typeof(steps) = 'array' AND jsonb_array_length(steps) <= 8 AND pg_column_size(steps) <= 16384), CONSTRAINT community_onboarding_dm_check CHECK (char_length(dm_body) <= 2000));
ALTER TABLE public.community_onboarding ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_onboarding FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_onboarding TO service_role;
CREATE TABLE IF NOT EXISTS public.community_onboarding_progress (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, step text NOT NULL, done_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_onboarding_progress_pkey PRIMARY KEY (community_id, user_id, step), CONSTRAINT community_onboarding_progress_step_check CHECK (step ~ '^[a-z0-9_]{1,40}$'));
ALTER TABLE public.community_onboarding_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_onboarding_progress FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_onboarding_progress TO service_role;
CREATE INDEX IF NOT EXISTS community_activity_member_kind_idx ON public.community_activity (community_id, user_id, kind);
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('193', '193_community_onboarding_checklist.sql', '19fe42e5fb23479e25f4d2b2a38c5eed4fc096f093f39612e4d6b4a39d83a7fa') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 194_community_scheduled_posts.sql
/* Scheduled posts and drafts (round 32), run after part 81. The people who run a community write a post now and choose when it goes up, or keep it as a draft: the new server only table `community_scheduled_posts`, one row per post waiting, with its space, title and words, when it goes up, and what happened (draft, scheduled, publishing, published with the post it became, or failed with the reason). Every five minutes the community job run publishes what is due through the ordinary post path, as its author, so members hear about it exactly as if it had been posted then; a row is taken by one run only (its status changes from scheduled to publishing in one update), and one that stopped part way is marked failed rather than posted twice. Two indexes: what is due, and a community's list. No existing row changes. Until it runs, Feed shows that scheduling needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_scheduled_posts (id uuid NOT NULL DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft', publish_at timestamptz, post_id uuid REFERENCES public.community_feed_posts(id) ON DELETE SET NULL, error text, attempts integer NOT NULL DEFAULT 0, claimed_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_scheduled_posts_pkey PRIMARY KEY (id), CONSTRAINT community_scheduled_posts_status_check CHECK (status IN ('draft', 'scheduled', 'publishing', 'published', 'failed')), CONSTRAINT community_scheduled_posts_when_check CHECK (status <> 'scheduled' OR publish_at IS NOT NULL), CONSTRAINT community_scheduled_posts_length_check CHECK (char_length(title) <= 200 AND char_length(body) <= 20000 AND (error IS NULL OR char_length(error) <= 500) AND attempts >= 0));
CREATE INDEX IF NOT EXISTS community_scheduled_posts_due_idx ON public.community_scheduled_posts (publish_at) WHERE status = 'scheduled';
CREATE INDEX IF NOT EXISTS community_scheduled_posts_list_idx ON public.community_scheduled_posts (community_id, status, publish_at);
ALTER TABLE public.community_scheduled_posts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_scheduled_posts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_scheduled_posts TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('194', '194_community_scheduled_posts.sql', '2e9c7de668bfb4a99aa3afe878ee06710cc3a8f1d2694bd6fd3c31d58b642c12') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 200_learn_access_types.sql
/* Learn: who opens a program, its rich description, and covers for modules and lessons (round 33), run after parts 74 and 102. A program in a community's Learn gets `access_mode`, the creator's choice of who opens it (free for every member, from a level, bought once, a number of days after joining, or only the members picked), `member_ids`, the members picked for a private program (up to 1,000 account ids, read and written by the server only, since community_courses is server only since part 81), and `description`, the program's description as the cleaned HTML the product editor's rich text field writes (pictures, emoji, formatting; summary keeps the plain text for the cards). A course module and a course lesson each get `cover_url`, a picture from Storelib's own storage. All columns are new and empty or default, so no existing row changes meaning: a row with no access_mode is read as before, from its price, level and drip days. Until it runs, programs keep the three earlier choices and the plain description, and covers cannot be set. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_courses') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_courses' AND column_name = 'id') THEN RAISE NOTICE 'learn access: community_courses has no id yet, run part 102 first.'; RETURN; END IF; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS access_mode text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS member_ids uuid[] NOT NULL DEFAULT '{}'::uuid[]; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS description text; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_access_mode_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_access_mode_check CHECK (access_mode IS NULL OR access_mode IN ('free', 'level', 'paid', 'time', 'private')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_member_ids_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_member_ids_check CHECK (cardinality(member_ids) <= 1000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_description_length' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_description_length CHECK (description IS NULL OR char_length(description) <= 60000); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.course_modules') IS NULL OR to_regclass('public.course_lessons') IS NULL THEN RAISE NOTICE 'learn covers: there are no course modules and lessons, run part 74 first.'; RETURN; END IF; ALTER TABLE public.course_modules ADD COLUMN IF NOT EXISTS cover_url text; ALTER TABLE public.course_lessons ADD COLUMN IF NOT EXISTS cover_url text; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'course_modules_cover_url_length' AND conrelid = 'public.course_modules'::regclass) THEN ALTER TABLE public.course_modules ADD CONSTRAINT course_modules_cover_url_length CHECK (cover_url IS NULL OR (char_length(cover_url) <= 1000 AND cover_url LIKE 'https://%')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'course_lessons_cover_url_length' AND conrelid = 'public.course_lessons'::regclass) THEN ALTER TABLE public.course_lessons ADD CONSTRAINT course_lessons_cover_url_length CHECK (cover_url IS NULL OR (char_length(cover_url) <= 1000 AND cover_url LIKE 'https://%')); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('200', '200_learn_access_types.sql', '9959b7a0fcad7ce8025c05e4d4f168319aeba2b57b48d8fcc5d1823b35e0a38b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 202_community_deletion_and_setup.sql
/* Deleting a community members still pay for, and a new admin's setup list (round 33), run after part 81. Three server only tables. `community_deletions`, one row per community whose deletion is scheduled: how (at the end of what members paid for, or now with refunds), when it is deleted, who asked, what the community was before (so Undo brings it back as it was), and whether it was completed or undone. `community_deletion_members`, one row per paid membership the deletion stopped: its subscription, when its paid time ends, whether the member had already cancelled, and, for a deletion now, the payment refunded and the Stripe refund (so a retry never refunds twice), with when the member was emailed and, after an Undo, when the membership was resumed. `community_setup_progress`, what each owner or admin skipped or finished by hand on the setup list (the intro video watched, the app installed, a step skipped, the list hidden). One index finds the deletions that are due for the community job run. No existing row changes. Until it runs, a community nobody pays for is still deleted at once, a paid one says this part is needed, and the setup list works without skips. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_deletions (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, state text NOT NULL DEFAULT 'scheduled', mode text NOT NULL, delete_at timestamptz NOT NULL, requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, requested_at timestamptz NOT NULL DEFAULT now(), prior_status text NOT NULL, prior_archived_at timestamptz, members_total integer NOT NULL DEFAULT 0, undone_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, undone_at timestamptz, completed_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_deletions_pkey PRIMARY KEY (community_id), CONSTRAINT community_deletions_state_check CHECK (state IN ('scheduled', 'completed', 'undone')), CONSTRAINT community_deletions_mode_check CHECK (mode IN ('period_end', 'now')), CONSTRAINT community_deletions_error_check CHECK (last_error IS NULL OR char_length(last_error) <= 500));
CREATE INDEX IF NOT EXISTS community_deletions_due_idx ON public.community_deletions (delete_at) WHERE state = 'scheduled';
ALTER TABLE public.community_deletions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_deletions FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_deletions TO service_role;
CREATE TABLE IF NOT EXISTS public.community_deletion_members (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, membership_id uuid NOT NULL, stripe_subscription_id text, buyer_id uuid, buyer_email text, mode text NOT NULL, period_end timestamptz, was_cancelling boolean NOT NULL DEFAULT false, cancelled_at timestamptz, refund_order_id uuid, refund_cents integer, stripe_refund_id text, refunded_at timestamptz, emailed_at timestamptz, resumed_at timestamptz, attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_deletion_members_pkey PRIMARY KEY (community_id, membership_id), CONSTRAINT community_deletion_members_mode_check CHECK (mode IN ('period_end', 'now')), CONSTRAINT community_deletion_members_refund_check CHECK (refund_cents IS NULL OR refund_cents >= 0), CONSTRAINT community_deletion_members_error_check CHECK (error IS NULL OR char_length(error) <= 500));
ALTER TABLE public.community_deletion_members ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_deletion_members FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_deletion_members TO service_role;
CREATE TABLE IF NOT EXISTS public.community_setup_progress (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, step text NOT NULL, done_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_setup_progress_pkey PRIMARY KEY (community_id, user_id, step), CONSTRAINT community_setup_progress_step_check CHECK (char_length(step) BETWEEN 1 AND 40));
ALTER TABLE public.community_setup_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_setup_progress FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_setup_progress TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('202', '202_community_deletion_and_setup.sql', 'b6e795089e00c8b3518e66167fcc8517cd53837addd43ace41876e99108a1c92') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 210_site_web_performance.sql
/* Website settings › Performance (round V): how fast each published website is for its visitors. `site_rum_events`, one row per measured page view (the site, the time, the page path with ids taken out, the kind of page, phone or computer, the browser family, the country the edge reported, the connection type and up to six numbers; nothing about the visitor), kept 30 days. `site_rum_counters`, every page view that arrived per site and UTC day, which decides the sampling (all up to 1000 a day, then one in ten, then one in a hundred, each kept row with its weight) and marks a day rolled up. `site_rum_daily`, per site, day, device and one of page, page type, browser or country, a histogram per metric, kept 13 months. `site_lab_tests`, the latest Google PageSpeed Insights result per site and strategy. A creator reads only their own sites (row level security); only the server writes. Functions: `record_site_rum` (the write), `site_rum_window` (a window of days summed, as the asker), `site_rum_replace_day` (the rollup, a day replaced whole), `site_rum_cleanup` (retention). Run after `06`. No existing row changes. Until it runs, visitors' measurements are dropped and the Performance tab says it is not set up yet. Safe to run again. */
create table if not exists public.site_rum_events ( id bigint generated always as identity primary key, install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, at timestamptz not null default now(), path text not null check (char_length(path) between 1 and 160 and left(path, 1) = '/'), page_type text not null check (page_type in ('home', 'product', 'collection', 'page', 'policy', 'blog', 'search', 'cart', 'account', 'checkout', 'other')), device text not null check (device in ('mobile', 'desktop')), browser text not null check (char_length(browser) between 1 and 24), country text check (country ~ '^[A-Z]{2}$'), conn text check (conn in ('slow-2g', '2g', '3g', '4g')), kind text not null default 'load' check (kind in ('load', 'soft')), lcp_ms integer check (lcp_ms between 0 and 60000), inp_ms integer check (inp_ms between 0 and 60000), cls real check (cls between 0 and 10), fcp_ms integer check (fcp_ms between 0 and 60000), ttfb_ms integer check (ttfb_ms between 0 and 60000), nav_ms integer check (nav_ms between 0 and 60000), weight real not null default 1 check (weight >= 1 and weight <= 1000) );
create index if not exists site_rum_events_install_at on public.site_rum_events (install_id, at);
create index if not exists site_rum_events_at on public.site_rum_events (at);
create table if not exists public.site_rum_counters ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, day date not null, creator_id uuid not null references public.creators(id) on delete cascade, seen integer not null default 0, rolled_at timestamptz, primary key (install_id, day) );
create table if not exists public.site_rum_daily ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, day date not null, device text not null check (device in ('mobile', 'desktop')), dim text not null check (dim in ('all', 'path', 'type', 'browser', 'country')), key text not null default '' check (char_length(key) <= 160), views real not null default 0, samples integer not null default 0, lcp_h real[] not null default '{}', lcp_n integer not null default 0, inp_h real[] not null default '{}', inp_n integer not null default 0, cls_h real[] not null default '{}', cls_n integer not null default 0, fcp_h real[] not null default '{}', fcp_n integer not null default 0, ttfb_h real[] not null default '{}', ttfb_n integer not null default 0, nav_h real[] not null default '{}', nav_n integer not null default 0, primary key (install_id, day, device, dim, key) );
create index if not exists site_rum_daily_install_dim_day on public.site_rum_daily (install_id, dim, day);
create table if not exists public.site_lab_tests ( install_id uuid not null references public.store_theme_installs(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, strategy text not null check (strategy in ('mobile', 'desktop')), url text not null check (char_length(url) <= 600), ran_at timestamptz not null default now(), result jsonb not null, primary key (install_id, strategy) );
alter table public.site_rum_events enable row level security;
alter table public.site_rum_counters enable row level security;
alter table public.site_rum_daily enable row level security;
alter table public.site_lab_tests enable row level security;
drop policy if exists "creators read their own site page views" on public.site_rum_events;
create policy "creators read their own site page views" on public.site_rum_events for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own site page view counts" on public.site_rum_counters;
create policy "creators read their own site page view counts" on public.site_rum_counters for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own site speed by day" on public.site_rum_daily;
create policy "creators read their own site speed by day" on public.site_rum_daily for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
drop policy if exists "creators read their own lab tests" on public.site_lab_tests;
create policy "creators read their own lab tests" on public.site_lab_tests for select to authenticated using (creator_id in (select c.id from public.creators c where c.user_id = auth.uid()));
revoke insert, update, delete on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests from anon, authenticated;
revoke all on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests from anon;
grant select on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests to authenticated;
grant select, insert, update, delete on public.site_rum_events, public.site_rum_counters, public.site_rum_daily, public.site_lab_tests to service_role;
create or replace function public.record_site_rum(p_install uuid, p_creator uuid, p_path text, p_type text, p_device text, p_browser text, p_country text, p_conn text, p_kind text, p_lcp integer, p_inp integer, p_cls real, p_fcp integer, p_ttfb integer, p_nav integer, p_full integer default 1000, p_mid integer default 10000, p_mid_rate real default 0.1, p_far_rate real default 0.01) returns boolean language plpgsql security definer set search_path = public as $$ declare v_day date := (now() at time zone 'utc')::date; v_seen integer; v_rate real; begin if p_device not in ('mobile', 'desktop') then return false; end if; insert into public.site_rum_counters (install_id, day, creator_id, seen) values (p_install, v_day, p_creator, 1) on conflict (install_id, day) do update set seen = public.site_rum_counters.seen + 1, rolled_at = null returning seen into v_seen; v_rate := case when v_seen <= p_full then 1 when v_seen <= p_mid then greatest(p_mid_rate, 0.001) else greatest(p_far_rate, 0.001) end; if v_rate < 1 and random() >= v_rate then return false; end if; insert into public.site_rum_events (install_id, creator_id, path, page_type, device, browser, country, conn, kind, lcp_ms, inp_ms, cls, fcp_ms, ttfb_ms, nav_ms, weight) values (p_install, p_creator, p_path, p_type, p_device, p_browser, p_country, p_conn, p_kind, case when p_lcp between 0 and 60000 then p_lcp end, case when p_inp between 0 and 60000 then p_inp end, case when p_cls between 0 and 10 then p_cls end, case when p_fcp between 0 and 60000 then p_fcp end, case when p_ttfb between 0 and 60000 then p_ttfb end, case when p_nav between 0 and 60000 then p_nav end, 1.0 / v_rate); return true; end; $$;
revoke all on function public.record_site_rum(uuid, uuid, text, text, text, text, text, text, text, integer, integer, real, integer, integer, integer, integer, integer, real, real) from public, anon, authenticated;
grant execute on function public.record_site_rum(uuid, uuid, text, text, text, text, text, text, text, integer, integer, real, integer, integer, integer, integer, integer, real, real) to service_role;
create or replace function public.site_rum_hadd(a real[], b real[]) returns real[] language sql immutable parallel safe as $$ select case when a is null then b when b is null then a else array(select coalesce(a[i], 0) + coalesce(b[i], 0) from generate_series(1, greatest(cardinality(a), cardinality(b))) as i order by i) end $$;
create or replace aggregate public.site_rum_hsum(real[]) (sfunc = public.site_rum_hadd, stype = real[]);
create or replace function public.site_rum_window(p_install uuid, p_from date, p_to date) returns table (device text, dim text, key text, views double precision, samples bigint, lcp_h real[], lcp_n bigint, inp_h real[], inp_n bigint, cls_h real[], cls_n bigint, fcp_h real[], fcp_n bigint, ttfb_h real[], ttfb_n bigint, nav_h real[], nav_n bigint) language sql stable security invoker set search_path = public as $$ select d.device, d.dim, d.key, sum(d.views)::double precision, sum(d.samples)::bigint, public.site_rum_hsum(d.lcp_h), sum(d.lcp_n)::bigint, public.site_rum_hsum(d.inp_h), sum(d.inp_n)::bigint, public.site_rum_hsum(d.cls_h), sum(d.cls_n)::bigint, public.site_rum_hsum(d.fcp_h), sum(d.fcp_n)::bigint, public.site_rum_hsum(d.ttfb_h), sum(d.ttfb_n)::bigint, public.site_rum_hsum(d.nav_h), sum(d.nav_n)::bigint from public.site_rum_daily d where d.install_id = p_install and d.day between p_from and p_to group by d.device, d.dim, d.key $$;
revoke all on function public.site_rum_window(uuid, date, date) from public, anon;
grant execute on function public.site_rum_window(uuid, date, date) to authenticated, service_role;
create or replace function public.site_rum_replace_day(p_install uuid, p_day date, p_rows jsonb) returns integer language plpgsql security definer set search_path = public as $$ declare v_creator uuid; v_n integer; begin select i.creator_id into v_creator from public.store_theme_installs i where i.id = p_install; if v_creator is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if; delete from public.site_rum_daily where install_id = p_install and day = p_day; insert into public.site_rum_daily (install_id, creator_id, day, device, dim, key, views, samples, lcp_h, lcp_n, inp_h, inp_n, cls_h, cls_n, fcp_h, fcp_n, ttfb_h, ttfb_n, nav_h, nav_n) select p_install, v_creator, p_day, r->>'device', r->>'dim', left(coalesce(r->>'key', ''), 160), coalesce((r->>'views')::real, 0), coalesce((r->>'samples')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'lcp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'lcp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'inp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'inp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'cls_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'cls_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'fcp_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'fcp_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'ttfb_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'ttfb_n')::integer, 0), array(select x::real from jsonb_array_elements_text(coalesce(r->'nav_h', '[]')) with ordinality t(x, o) order by o), coalesce((r->>'nav_n')::integer, 0) from jsonb_array_elements(p_rows) r where r->>'device' in ('mobile', 'desktop') and r->>'dim' in ('all', 'path', 'type', 'browser', 'country') on conflict (install_id, day, device, dim, key) do nothing; get diagnostics v_n = row_count; update public.site_rum_counters set rolled_at = now() where install_id = p_install and day = p_day; return v_n; end; $$;
revoke all on function public.site_rum_replace_day(uuid, date, jsonb) from public, anon, authenticated;
grant execute on function public.site_rum_replace_day(uuid, date, jsonb) to service_role;
create or replace function public.site_rum_cleanup(p_raw_days integer default 30, p_rollup_days integer default 400) returns integer language plpgsql security definer set search_path = public as $$ declare v_today date := (now() at time zone 'utc')::date; v_n integer; v_total integer := 0; begin delete from public.site_rum_events e where e.at < ((v_today - p_raw_days)::timestamp at time zone 'utc') and (e.at < ((v_today - p_raw_days - 5)::timestamp at time zone 'utc') or exists (select 1 from public.site_rum_counters c where c.install_id = e.install_id and c.day = (e.at at time zone 'utc')::date and c.rolled_at is not null)); get diagnostics v_n = row_count; v_total := v_total + v_n; delete from public.site_rum_daily where day < v_today - p_rollup_days; get diagnostics v_n = row_count; v_total := v_total + v_n; delete from public.site_rum_counters where day < v_today - p_rollup_days; get diagnostics v_n = row_count; v_total := v_total + v_n; return v_total; end; $$;
revoke all on function public.site_rum_cleanup(integer, integer) from public, anon, authenticated;
grant execute on function public.site_rum_cleanup(integer, integer) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('210', '210_site_web_performance.sql', 'f981e728234406931585b37160e9c360fe35fd44e918140472ffa942a2346c19') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 211_product_translation_settings.sql
/* A product shown in its own words in every language (round V8), run after part 136. `product_translation_settings`: one row per product, `show_original` set from Products › Translations › Always show the original; on, the website draws that product's title, description, search engine text and option names as the merchant wrote them in every language, and Storelib AI never translates it. Its translations stay in `site_translations` (part 136) and come back when it is turned off. Server only, as part 136's tables are: the owner writes it through the server, which checks the store is theirs. RLS is on, with one policy that names the store's owner, and no client role is granted the table. No existing row changes. Skips itself with a notice where products, creators or part 136 are not there. Until it runs, the switch says it needs this part and every product reads its translations as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL OR to_regclass('public.creators') IS NULL OR to_regclass('public.site_translations') IS NULL THEN RAISE NOTICE 'product translation settings: products, creators or site_translations is not there yet, run part 136 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.product_translation_settings (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, show_original boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS product_translation_settings_store_original ON public.product_translation_settings (creator_id) WHERE show_original; ALTER TABLE public.product_translation_settings ENABLE ROW LEVEL SECURITY; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_translation_settings' AND policyname = 'product_translation_settings_owner') THEN CREATE POLICY product_translation_settings_owner ON public.product_translation_settings FOR ALL TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))) WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))); END IF; REVOKE ALL ON public.product_translation_settings FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_translation_settings TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('211', '211_product_translation_settings.sql', '384b00c81f3d1424e58ce15ff1db64b16d7a66901f1e3cf64914092fad7d640a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 212_checkout_text_overrides.sql
/* A store's own checkout words, per language (Settings > Checkout > Checkout text; lib/checkout-text), run after part 136. One new server only table, `checkout_text_overrides`: one row per store, language and reworded text (`text_id`, a stable id from lib/checkout-text/registry.ts such as `buttons.pay_amount`, never the English sentence, so a row survives the English being reworded), the store's words (`value`, one line, up to 200 characters, checked by the server before it is written: same placeholders as the English, no HTML, no links, no amounts) and `default_text`, what the checkout showed for it when the store saved, so the editor can say "Default changed since you edited" when Storelib's own wording changes later. Only the sentences the registry lists can be stored; legal and consent text, amounts, payment status and the payment provider's words are never editable. Read and written by the server only (RLS on, no client grants), like site_translations. Until it runs, the checkout shows Storelib's words and the editor says it needs this part. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'checkout text: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.checkout_text_overrides (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, locale text NOT NULL, text_id text NOT NULL, value text NOT NULL, default_text text NOT NULL DEFAULT '', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT checkout_text_overrides_pkey PRIMARY KEY (creator_id, locale, text_id), CONSTRAINT checkout_text_overrides_locale_check CHECK (char_length(locale) BETWEEN 2 AND 35), CONSTRAINT checkout_text_overrides_id_check CHECK (text_id ~ '^[a-z_]+\.[a-z_]+$' AND char_length(text_id) <= 64), CONSTRAINT checkout_text_overrides_value_check CHECK (char_length(value) BETWEEN 1 AND 200 AND value !~ '[<>]'), CONSTRAINT checkout_text_overrides_default_check CHECK (char_length(default_text) <= 400)); END $do$;
ALTER TABLE IF EXISTS public.checkout_text_overrides ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF to_regclass('public.checkout_text_overrides') IS NULL THEN RETURN; END IF; REVOKE ALL ON public.checkout_text_overrides FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.checkout_text_overrides TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('212', '212_checkout_text_overrides.sql', 'ba6d49d827ec612e877a4c9caa5b2ed2d486f62a6c4d7120f39146c9eba81b50') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 213_translation_rules.sql
/* A store's own rules for automatic translation (Settings > Markets and languages > Glossary; lib/markets/translation-rules.ts). `store_localization.translation_rules` (part 136's table): a glossary (terms kept as written in every language, like a brand name, or with a fixed translation per language), the texts never translated automatically, by key (Don't translate), and whether product names are left as written. Only Storelib AI reads it: a translation the merchant wrote is never changed by a rule. An object, empty for every store until one is saved, capped in size. Server only, as the table already is: every read and write goes through the app's server, which checks the store's owner. No rows change. Skips itself with a notice where the table is not there (run 136 first). Until it runs, translating works as before with no glossary, and saving one says this part is needed. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_localization') IS NULL THEN RAISE NOTICE 'translation rules: store_localization is not there yet, run part 136 first.'; ELSE ALTER TABLE public.store_localization ADD COLUMN IF NOT EXISTS translation_rules jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_localization_translation_rules_check') THEN ALTER TABLE public.store_localization ADD CONSTRAINT store_localization_translation_rules_check CHECK (jsonb_typeof(translation_rules) = 'object' AND pg_column_size(translation_rules) <= 262144); END IF; REVOKE ALL ON public.store_localization FROM PUBLIC, anon, authenticated; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('213', '213_translation_rules.sql', '99085c8146d594da4765cc420c5a3e2ef6530aa28d97b40ba305aef322700e9e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 214_inventory_and_files.sql
/* Part 214 (round V, track 11): inventory that keeps track of everything, and a file's alt text. Run after part 78. Statements are separated by a blank line; supabase/sql/run-now/214_inventory_and_files.sql is the same statements, one per line. No existing row changes and nothing is dropped except a CHECK replaced by a wider one. Until it runs, the app adjusts stock and moves transfers the way it did before (step by step), keeps one low stock line per product, says who changed stock only as "You" or "Storelib", and says alt text needs this part. Safe to run again. */
/* 1. A low stock line per variant. NULL: the product's own line, else the shop's default. */
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS low_stock_threshold integer CHECK (low_stock_threshold IS NULL OR low_stock_threshold BETWEEN 0 AND 1000000);
/* 2. The history says who: the signed in person (the owner or a team member) behind a manual change. No foreign key, so a member who leaves the team stays in the history. */
ALTER TABLE public.inventory_movements ADD COLUMN IF NOT EXISTS actor_user_id uuid;
CREATE INDEX IF NOT EXISTS inventory_movements_ref_idx ON public.inventory_movements (creator_id, ref_type, ref_id) WHERE ref_type IS NOT NULL;
/* 3. Two more reasons: Other (a manual change that fits no other reason) and a transfer cancelled on its way, whose units go back to where they left. The old list is kept whole inside the new one. */
ALTER TABLE public.inventory_movements DROP CONSTRAINT IF EXISTS inventory_movements_reason_check;
ALTER TABLE public.inventory_movements ADD CONSTRAINT inventory_movements_reason_check CHECK (reason IN ('initial', 'received', 'correction', 'count', 'damaged', 'theft_or_loss', 'promotion_or_donation', 'returned_restock', 'sale_fulfilled', 'order_reserved', 'reservation_released', 'order_cancelled', 'transfer_out', 'transfer_in', 'incoming_added', 'incoming_cancelled', 'provider_sync', 'other', 'transfer_cancelled'));
/* 4. The history is append only. A row is never edited or deleted; the one change allowed is a product, location or shop that is deleted clearing its own id (ON DELETE SET NULL), so the history outlives what it was about. */
CREATE OR REPLACE FUNCTION public.inventory_movements_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'inventory_movements is append only' USING ERRCODE = 'P0001'; END IF; IF (to_jsonb(NEW) - 'creator_id' - 'variant_id' - 'location_id') IS DISTINCT FROM (to_jsonb(OLD) - 'creator_id' - 'variant_id' - 'location_id') OR (NEW.creator_id IS NOT NULL AND NEW.creator_id IS DISTINCT FROM OLD.creator_id) OR (NEW.variant_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM OLD.variant_id) OR (NEW.location_id IS NOT NULL AND NEW.location_id IS DISTINCT FROM OLD.location_id) THEN RAISE EXCEPTION 'inventory_movements is append only' USING ERRCODE = 'P0001'; END IF; RETURN NEW; END $f$;
DROP TRIGGER IF EXISTS inventory_movements_append_only ON public.inventory_movements;
CREATE TRIGGER inventory_movements_append_only BEFORE UPDATE OR DELETE ON public.inventory_movements FOR EACH ROW EXECUTE FUNCTION public.inventory_movements_append_only();
/* 5. One stock change, written down with who made it. The same as part 78's physical_inventory_apply, plus the person, and the key checked again once the level is locked, so two presses at the same moment are one change. */
CREATE OR REPLACE FUNCTION public.physical_inventory_move(p_creator uuid, p_variant uuid, p_location uuid, p_on_hand integer, p_committed integer, p_incoming integer, p_reason text, p_ref_type text, p_ref_id text, p_key text, p_actor text, p_actor_user uuid, p_note text, p_guard boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE lvl public.inventory_levels%ROWTYPE; owner uuid; loc_owner uuid; n_on integer; n_com integer; n_inc integer; BEGIN SELECT p.creator_id INTO owner FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = p_variant; SELECT creator_id INTO loc_owner FROM public.inventory_locations WHERE id = p_location; IF owner IS NULL OR owner IS DISTINCT FROM p_creator OR loc_owner IS NULL OR loc_owner IS DISTINCT FROM p_creator THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (p_variant, p_location, p_creator) ON CONFLICT (variant_id, location_id) DO NOTHING; SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false, 'repeat', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed); END IF; n_on := lvl.on_hand + coalesce(p_on_hand, 0); n_com := greatest(lvl.committed + coalesce(p_committed, 0), 0); n_inc := greatest(lvl.incoming + coalesce(p_incoming, 0), 0); IF p_guard AND (n_on - n_com) < 0 AND (coalesce(p_on_hand, 0) < 0 OR coalesce(p_committed, 0) > 0) THEN RETURN jsonb_build_object('applied', false, 'error', 'insufficient', 'available', lvl.on_hand - lvl.committed, 'on_hand', lvl.on_hand); END IF; UPDATE public.inventory_levels SET on_hand = n_on, committed = n_com, incoming = n_inc, updated_at = now() WHERE variant_id = p_variant AND location_id = p_location; INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_on_hand, delta_committed, delta_incoming, on_hand_after, committed_after, incoming_after, reason, ref_type, ref_id, note, actor, actor_user_id, idempotency_key) VALUES (p_creator, p_variant, p_location, n_on - lvl.on_hand, n_com - lvl.committed, n_inc - lvl.incoming, n_on, n_com, n_inc, p_reason, p_ref_type, p_ref_id, left(p_note, 500), coalesce(p_actor, 'system'), p_actor_user, p_key); RETURN jsonb_build_object('applied', true, 'on_hand', n_on, 'committed', n_com, 'incoming', n_inc, 'available', n_on - n_com, 'on_hand_before', lvl.on_hand, 'incoming_before', lvl.incoming); END $f$;
/* 6. Adjust: add, remove or set on hand (or what is on order), worked out under the level's lock, so a count typed while an order ships is still the count. Taking away more than is on hand is refused; a reason outside the manual list is a correction. */
CREATE OR REPLACE FUNCTION public.physical_inventory_adjust(p_creator uuid, p_variant uuid, p_location uuid, p_field text, p_mode text, p_quantity integer, p_reason text, p_note text, p_key text, p_actor_user uuid, p_ref_type text) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE lvl public.inventory_levels%ROWTYPE; owner uuid; loc_owner uuid; cur integer; delta integer; why text; done jsonb; BEGIN IF p_field IS NULL OR p_field NOT IN ('on_hand', 'incoming') OR p_mode IS NULL OR p_mode NOT IN ('add', 'remove', 'set') THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_input'); END IF; IF p_quantity IS NULL OR p_quantity < 0 OR p_quantity > 1000000 THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_quantity'); END IF; SELECT p.creator_id INTO owner FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = p_variant; SELECT creator_id INTO loc_owner FROM public.inventory_locations WHERE id = p_location; IF owner IS NULL OR owner IS DISTINCT FROM p_creator OR loc_owner IS NULL OR loc_owner IS DISTINCT FROM p_creator THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (p_variant, p_location, p_creator) ON CONFLICT (variant_id, location_id) DO NOTHING; SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false, 'repeat', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed); END IF; cur := CASE WHEN p_field = 'incoming' THEN lvl.incoming ELSE lvl.on_hand END; delta := CASE p_mode WHEN 'add' THEN p_quantity WHEN 'remove' THEN -p_quantity ELSE p_quantity - cur END; IF delta < 0 AND cur + delta < 0 THEN RETURN jsonb_build_object('applied', false, 'error', 'below_zero', 'current', cur); END IF; IF delta = 0 THEN RETURN jsonb_build_object('applied', false, 'unchanged', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed, 'before', cur, 'after', cur); END IF; IF p_field = 'incoming' THEN why := CASE WHEN delta > 0 THEN 'incoming_added' ELSE 'incoming_cancelled' END; ELSIF p_reason IN ('received', 'correction', 'count', 'damaged', 'theft_or_loss', 'promotion_or_donation', 'returned_restock', 'other') THEN why := p_reason; ELSE why := 'correction'; END IF; done := public.physical_inventory_move(p_creator, p_variant, p_location, CASE WHEN p_field = 'on_hand' THEN delta ELSE 0 END, 0, CASE WHEN p_field = 'incoming' THEN delta ELSE 0 END, why, p_ref_type, NULL, p_key, 'creator', p_actor_user, p_note, false); RETURN done || jsonb_build_object('before', cur, 'after', cur + delta, 'delta', delta); END $f$;
/* 7. A transfer sent: every item leaves the origin and shows as incoming at the destination, all in one transaction. One item short and nothing moves. */
CREATE OR REPLACE FUNCTION public.physical_transfer_ship(p_creator uuid, p_transfer uuid, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; r jsonb; n integer := 0; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status <> 'draft' THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.origin_location_id IS NULL OR t.destination_location_id IS NULL THEN RETURN jsonb_build_object('applied', false, 'error', 'no_location'); END IF; FOR it IN SELECT id, variant_id, quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer AND variant_id IS NOT NULL ORDER BY variant_id LOOP r := public.physical_inventory_move(p_creator, it.variant_id, t.origin_location_id, -it.quantity, 0, 0, 'transfer_out', 'transfer', p_transfer::text, 'transfer_out:' || it.id, 'creator', p_actor_user, NULL, true); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_short:%:%', it.variant_id, greatest(coalesce((r->>'available')::integer, 0), 0) USING ERRCODE = 'P0001'; END IF; r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, 0, 0, it.quantity, 'incoming_added', 'transfer', p_transfer::text, 'transfer_incoming:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; n := n + 1; END LOOP; IF n = 0 THEN RETURN jsonb_build_object('applied', false, 'error', 'empty'); END IF; UPDATE public.inventory_transfers SET status = 'in_transit', shipped_at = now(), updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'status', 'in_transit', 'items', n); END $f$;
/* 8. A transfer received, all or part: what arrived moves from incoming to on hand at the destination. More than is still on its way is taken as all of it. */
CREATE OR REPLACE FUNCTION public.physical_transfer_receive(p_creator uuid, p_transfer uuid, p_items jsonb, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; want integer; r jsonb; got integer := 0; next_status text; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status NOT IN ('in_transit', 'partially_received') THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.destination_location_id IS NULL THEN RETURN jsonb_build_object('applied', false, 'error', 'no_location'); END IF; IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_input'); END IF; FOR it IN SELECT id, variant_id, quantity, received_quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer ORDER BY variant_id FOR UPDATE LOOP SELECT coalesce(sum(CASE WHEN (e->>'quantity') ~ '^[0-9]{1,7}$' THEN (e->>'quantity')::integer ELSE 0 END), 0)::integer INTO want FROM jsonb_array_elements(p_items) e WHERE e->>'item_id' = it.id::text; want := least(want, it.quantity - it.received_quantity); IF want <= 0 OR it.variant_id IS NULL THEN CONTINUE; END IF; r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, want, 0, -want, 'transfer_in', 'transfer', p_transfer::text, 'transfer_in:' || it.id || ':' || (it.received_quantity + want), 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; UPDATE public.inventory_transfer_items SET received_quantity = received_quantity + want WHERE id = it.id; got := got + want; END LOOP; SELECT CASE WHEN bool_and(received_quantity >= quantity) THEN 'received' WHEN bool_or(received_quantity > 0) THEN 'partially_received' ELSE t.status END INTO next_status FROM public.inventory_transfer_items WHERE transfer_id = p_transfer; UPDATE public.inventory_transfers SET status = coalesce(next_status, t.status), received_at = CASE WHEN next_status = 'received' THEN now() ELSE received_at END, updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', got > 0, 'status', coalesce(next_status, t.status), 'received', got); END $f$;
/* 9. A transfer cancelled. A draft only changes its status. One on its way gives back what has not arrived: on hand again at the origin, no longer incoming at the destination. What already arrived stays. */
CREATE OR REPLACE FUNCTION public.physical_transfer_cancel(p_creator uuid, p_transfer uuid, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; open_qty integer; r jsonb; back integer := 0; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status IN ('received', 'cancelled') THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.status <> 'draft' THEN FOR it IN SELECT id, variant_id, quantity, received_quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer AND variant_id IS NOT NULL ORDER BY variant_id LOOP open_qty := it.quantity - it.received_quantity; IF open_qty <= 0 THEN CONTINUE; END IF; IF t.origin_location_id IS NOT NULL THEN r := public.physical_inventory_move(p_creator, it.variant_id, t.origin_location_id, open_qty, 0, 0, 'transfer_cancelled', 'transfer', p_transfer::text, 'transfer_cancel_out:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; END IF; IF t.destination_location_id IS NOT NULL THEN r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, 0, 0, -open_qty, 'incoming_cancelled', 'transfer', p_transfer::text, 'transfer_cancel_in:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; END IF; back := back + open_qty; END LOOP; END IF; UPDATE public.inventory_transfers SET status = 'cancelled', updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'status', 'cancelled', 'returned', back); END $f$;
/* 10. The new functions are the server's alone, like part 78's. */
REVOKE ALL ON FUNCTION public.physical_inventory_move(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, uuid, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_inventory_move(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, uuid, text, boolean) TO service_role;
REVOKE ALL ON FUNCTION public.physical_inventory_adjust(uuid, uuid, uuid, text, text, integer, text, text, text, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_inventory_adjust(uuid, uuid, uuid, text, text, integer, text, text, text, uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_ship(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_ship(uuid, uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_receive(uuid, uuid, jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_receive(uuid, uuid, jsonb, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_cancel(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_cancel(uuid, uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.inventory_movements_append_only() FROM PUBLIC, anon, authenticated;
/* 11. A file's alt text (Files), keyed by where the file is stored. Written by the server only, for the shop whose folder the path is in; the owner may read their own. */
CREATE TABLE IF NOT EXISTS public.file_details (bucket text NOT NULL CHECK (bucket IN ('store-builder-images', 'product-images')), path text NOT NULL CHECK (length(path) BETWEEN 3 AND 300), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, alt_text text CHECK (alt_text IS NULL OR length(alt_text) <= 500), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT file_details_pkey PRIMARY KEY (bucket, path));
CREATE INDEX IF NOT EXISTS file_details_creator_idx ON public.file_details (creator_id);
ALTER TABLE public.file_details ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_details FROM PUBLIC, anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.file_details FROM authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.file_details TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads file_details" ON public.file_details; CREATE POLICY "storelib owner reads file_details" ON public.file_details FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = file_details.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('214', '214_inventory_and_files.sql', 'c6a6d2e5ac71572cd294f4ae99f5947f1f13a99b507bd2fd6f6a47d6dcd1888c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 215_reviews_manage.sql
/* Storelib Reviews managed in one place (round K5): the integration's own page with Overview, Reviews, Requests, Analytics and Settings. `review_imports`: one row per CSV import a store ran (the file's name, how many rows were imported and skipped, and a short report of each row's outcome), so the Reviews tab can list recent imports and undo one; server only. `reviews.import_id`: the import a review came from (null for every other review), so undoing an import deletes exactly its own rows, which are always unverified and never in a Storelib rating. `review_requests.delivered_at`, `opened_at` and `clicked_at`: when the mail provider said the review request was delivered, opened and its link pressed (the provider's webhook, matched by the request id the email carries), and `manual`: true when the store sent it by hand from the Requests tab. Indexes so the Reviews tab pages, filters and counts on the server: by rating, by where a review stands on the website, and the requests list by status. Changes no row. Needs part 134. Until it runs, the page shows reviews and requests as before, without import history, undo or open tracking. */
DO $do$ BEGIN IF to_regclass('public.reviews') IS NULL OR to_regclass('public.review_requests') IS NULL THEN RAISE NOTICE 'reviews manage: run part 52 and part 134 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.review_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, file_name text CHECK (file_name IS NULL OR char_length(file_name) <= 200), imported integer NOT NULL DEFAULT 0 CHECK (imported >= 0), skipped integer NOT NULL DEFAULT 0 CHECK (skipped >= 0), report jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(report) = 'array' AND pg_column_size(report) < 262144), undone_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS review_imports_creator ON public.review_imports (creator_id, created_at DESC); ALTER TABLE public.review_imports ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.review_imports FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.review_imports TO service_role; END $do$;
DO $do$ BEGIN IF to_regclass('public.review_imports') IS NULL THEN RETURN; END IF; ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_id uuid REFERENCES public.review_imports(id) ON DELETE SET NULL; GRANT SELECT (import_id) ON public.reviews TO anon, authenticated; CREATE INDEX IF NOT EXISTS reviews_import ON public.reviews (import_id) WHERE import_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.reviews') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS reviews_creator_rating ON public.reviews (creator_id, rating, created_at DESC); IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'reviews' AND column_name = 'site_status') THEN CREATE INDEX IF NOT EXISTS reviews_creator_site ON public.reviews (creator_id, site_status, status, created_at DESC); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.review_requests') IS NULL THEN RETURN; END IF; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS delivered_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS opened_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS clicked_at timestamptz; ALTER TABLE public.review_requests ADD COLUMN IF NOT EXISTS manual boolean NOT NULL DEFAULT false; CREATE INDEX IF NOT EXISTS review_requests_creator_status ON public.review_requests (creator_id, status, created_at DESC); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('215', '215_reviews_manage.sql', '50c6777de9bf2236675c3392cc0795455e9366cfa28b85a429ef3d6f1fc62eca') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 216_review_widget_configs.sql
/* Storelib Reviews widgets (round K): `review_widget_configs`, one row per named look of a review widget a store saved in Storelib Reviews › Widgets (the product's reviews, the stars under a title, a grid, a carousel, testimonials, a photo wall, a strip that scrolls by, a trust badge, a rating summary): its type, its name and its settings, a small object of values from fixed lists and ranges that the app cleans before it writes and again when it reads. A section on the website names the look it draws with. Row level security on: the store's owner can read their own rows, nobody else can; every write goes through the server with its own key after the owner is checked, and a website reads the looks through the server only. One index for a store's list. No existing row changes. Until it runs, Storelib Reviews › Widgets says saving needs this part and every widget draws with its own defaults. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.review_widget_configs (id uuid NOT NULL DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, type text NOT NULL, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT review_widget_configs_pkey PRIMARY KEY (id), CONSTRAINT review_widget_configs_type_check CHECK (type IN ('product_reviews', 'star_badge', 'rating_summary', 'grid', 'carousel', 'testimonials', 'media_wall', 'marquee', 'trust_badge')), CONSTRAINT review_widget_configs_name_check CHECK (char_length(name) BETWEEN 1 AND 60), CONSTRAINT review_widget_configs_settings_check CHECK (jsonb_typeof(settings) = 'object' AND pg_column_size(settings) < 16384));
CREATE INDEX IF NOT EXISTS review_widget_configs_creator_idx ON public.review_widget_configs (creator_id, updated_at DESC);
ALTER TABLE public.review_widget_configs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_widget_configs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.review_widget_configs TO authenticated;
DROP POLICY IF EXISTS review_widget_configs_owner_read ON public.review_widget_configs;
CREATE POLICY review_widget_configs_owner_read ON public.review_widget_configs FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.review_widget_configs TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('216', '216_review_widget_configs.sql', '0798f57a409af7bf17ec74d261e7e1be6de2e89d6d377319e3bc14be73afd992') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 217_round_ag.sql
/* Round AG (run after part 221): community plans and members. A free trial is none or 7 to 90 days (plans saved with 1 to 6 days get 7). A deleted account's email can sign up again (storelib_release_auth_identities, server only, and a cleanup of accounts closed before). Storage cleanup never removes a file a row still names with a space written as %20. A module of a community's program sold on its own (course_modules.price_cents, community_module_access, server only). Email your members, at most one a day per community (community_broadcasts, server only), and a community's own subject, heading and opening line on its emails (community_email_templates, server only). Changes no money row. Safe to run again. */
UPDATE public.membership_plans SET trial_days = 7, updated_at = now() WHERE trial_days BETWEEN 1 AND 6;
ALTER TABLE public.membership_plans DROP CONSTRAINT IF EXISTS membership_plans_trial;
ALTER TABLE public.membership_plans ADD CONSTRAINT membership_plans_trial CHECK (trial_days = 0 OR trial_days BETWEEN 7 AND 90);
CREATE OR REPLACE FUNCTION public.storelib_release_auth_identities(p_user uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $fn$ DECLARE v_email text; n integer; BEGIN SELECT email INTO v_email FROM auth.users WHERE id = p_user; IF v_email IS NULL OR v_email NOT LIKE 'deleted-%@deleted.storelib.invalid' THEN RAISE EXCEPTION 'storelib: only a closed account''s sign in methods are released'; END IF; DELETE FROM auth.identities WHERE user_id = p_user AND provider <> 'email'; GET DIAGNOSTICS n = ROW_COUNT; UPDATE auth.identities SET identity_data = jsonb_set(coalesce(identity_data, '{}'::jsonb), '{email}', to_jsonb(v_email)), updated_at = now() WHERE user_id = p_user AND provider = 'email'; RETURN n; END $fn$;
REVOKE ALL ON FUNCTION public.storelib_release_auth_identities(uuid) FROM PUBLIC;
DO $do$ BEGIN EXECUTE 'REVOKE ALL ON FUNCTION public.storelib_release_auth_identities(uuid) FROM anon, authenticated'; EXCEPTION WHEN undefined_object THEN NULL; END $do$;
GRANT EXECUTE ON FUNCTION public.storelib_release_auth_identities(uuid) TO service_role;
DO $do$ BEGIN IF to_regclass('public.account_deletions') IS NULL THEN RETURN; END IF; UPDATE auth.users u SET email = 'deleted-' || u.id || '@deleted.storelib.invalid', banned_until = now() + interval '100 years', raw_user_meta_data = coalesce(u.raw_user_meta_data, '{}'::jsonb) || '{"deleted": true}'::jsonb, updated_at = now() WHERE u.email NOT LIKE 'deleted-%@deleted.storelib.invalid' AND EXISTS (SELECT 1 FROM public.account_deletions d WHERE d.user_id = u.id AND d.mode = 'removed') AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = u.id); END $do$;
DO $do$ BEGIN DELETE FROM auth.identities i USING auth.users u WHERE i.user_id = u.id AND u.email LIKE 'deleted-%@deleted.storelib.invalid' AND i.provider <> 'email'; END $do$;
UPDATE auth.identities i SET identity_data = jsonb_set(coalesce(i.identity_data, '{}'::jsonb), '{email}', to_jsonb(u.email)), updated_at = now() FROM auth.users u WHERE i.user_id = u.id AND u.email LIKE 'deleted-%@deleted.storelib.invalid' AND i.provider = 'email' AND coalesce(i.identity_data->>'email', '') <> u.email;
DO $do$ BEGIN DELETE FROM public.community_members m USING auth.users u WHERE m.user_id = u.id AND u.email LIKE 'deleted-%@deleted.storelib.invalid' AND m.role <> 'owner'; END $do$;
create or replace function public.storage_cleanup_candidates(p_limit integer default 200, p_image_from_days integer default 32) returns table (bucket_id text, name text, reason text) language plpgsql stable security definer set search_path = public, storage as $$ begin if to_regclass('public.digital_assets') is null or to_regclass('public.product_bundles') is null then return; end if; return query with imports as ( select o.bucket_id::text, o.name::text, 'theme-import'::text as reason, o.created_at from storage.objects o where o.bucket_id = 'digital-products' and o.name ~ '^[0-9a-fA-F-]{36}/theme-imports/[0-9a-fA-F-]{36}\.zip$' and o.created_at < now() - interval '1 day' order by o.created_at limit p_limit ), digital as ( select o.bucket_id::text, o.name::text, 'digital-orphan'::text, o.created_at from storage.objects o where o.bucket_id in ('digital-products', 'product-files') and (o.name like '%/digital-products/%' or o.name like 'products/%') and o.created_at < now() - interval '3 days' and not exists ( select 1 from public.digital_assets da where da.file_path in (o.name, o.bucket_id || '/' || o.name) ) and not exists ( select 1 from public.digital_assets da where da.file_path like '%://%' and position(o.name in da.file_path) > 0 ) order by o.created_at limit p_limit ), bundles as ( select o.bucket_id::text, o.name::text, 'bundle-orphan'::text, o.created_at from storage.objects o where o.bucket_id = 'digital-products' and o.name like '%/bundles/%.zip' and o.created_at < now() - interval '3 days' and not exists (select 1 from public.product_bundles pb where pb.zip_path = o.name) order by o.created_at limit p_limit ), descriptions as ( select o.bucket_id::text, o.name::text, 'description-image'::text, o.created_at from storage.objects o where o.bucket_id = 'product-images' and o.name like '%\_description\_%' escape '\' and o.created_at < now() - interval '14 days' and o.created_at > now() - make_interval(days => greatest(p_image_from_days, 15)) and not public.storage_object_referenced(o.bucket_id, o.name) and not public.storage_object_referenced(o.bucket_id, replace(o.name, ' ', '%20')) order by o.created_at limit p_limit ), removed as ( select o.bucket_id::text, o.name::text, 'removed-image'::text, o.created_at from storage.objects o where o.bucket_id = 'product-images' and o.name ~ '^[0-9a-fA-F-]{36}/([0-9a-fA-F-]{36}|temp)/' and o.name not like '%\_description\_%' escape '\' and o.created_at < now() - interval '30 days' and o.created_at > now() - make_interval(days => greatest(p_image_from_days, 31)) and not public.storage_object_referenced(o.bucket_id, o.name) and not public.storage_object_referenced(o.bucket_id, replace(o.name, ' ', '%20')) order by o.created_at limit p_limit ) select c.bucket_id, c.name, c.reason from ( select * from imports union all select * from digital union all select * from bundles union all select * from descriptions union all select * from removed ) c order by c.created_at limit p_limit; end; $$;
DO $do$ BEGIN IF to_regclass('public.course_modules') IS NULL THEN RAISE NOTICE 'module sales: there are no course modules, run part 74 first.'; RETURN; END IF; ALTER TABLE public.course_modules ADD COLUMN IF NOT EXISTS price_cents integer; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'course_modules_price_cents_range' AND conrelid = 'public.course_modules'::regclass) THEN ALTER TABLE public.course_modules ADD CONSTRAINT course_modules_price_cents_range CHECK (price_cents IS NULL OR price_cents BETWEEN 100 AND 1000000); END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_module_access (module_id uuid NOT NULL REFERENCES public.course_modules(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, program_id uuid, community_id uuid REFERENCES public.communities(id) ON DELETE CASCADE, source text NOT NULL DEFAULT 'purchase' CHECK (source IN ('purchase', 'grant')), checkout_session_id text, payment_intent_id text, amount_cents integer, currency text, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (module_id, user_id));
CREATE INDEX IF NOT EXISTS community_module_access_user ON public.community_module_access (user_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS community_module_access_intent ON public.community_module_access (payment_intent_id) WHERE payment_intent_id IS NOT NULL;
ALTER TABLE public.community_module_access ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_module_access FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_module_access TO service_role;
CREATE TABLE IF NOT EXISTS public.community_broadcasts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, subject text NOT NULL CHECK (char_length(subject) BETWEEN 3 AND 120), message text NOT NULL CHECK (char_length(message) BETWEEN 10 AND 4000), status text NOT NULL DEFAULT 'sending' CHECK (status IN ('sending', 'sent', 'failed')), sent_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz );
CREATE INDEX IF NOT EXISTS community_broadcasts_community_created ON public.community_broadcasts (community_id, created_at DESC);
ALTER TABLE public.community_broadcasts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_broadcasts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_broadcasts TO service_role;
CREATE TABLE IF NOT EXISTS public.community_email_templates ( community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('welcome', 'join_approved', 'invite', 'announcement', 'event_reminder', 'course_available')), subject text CHECK (subject IS NULL OR char_length(subject) <= 120), heading text CHECK (heading IS NULL OR char_length(heading) <= 120), intro text CHECK (intro IS NULL OR char_length(intro) <= 600), updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (community_id, kind) );
ALTER TABLE public.community_email_templates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_email_templates FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_email_templates TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('217', '217_round_ag.sql', '5494ba3b379376963ca17f8181293734a233882a8ee84089a52931722481b4d9') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 220_community_summary_and_member_links.sql
/* A community's short description and its member links (round 26), run after part 81. Two new columns on `communities`. `summary`, the short description a visitor reads on the community's card: plain text, at most 160 characters, null when the creator has not written one (the card then falls back to the tagline, then to the start of the description; nothing is filled in for existing communities). `member_links`, up to four shortcuts members see inside the community (each an object with an id, a name, an address, an optional icon and whether it is hidden), an empty list by default. Both are server only: neither is one of the columns members and visitors can read with the browser's keys, and only the service role reads and writes them, after the owner and admin checks in the app; the member links reach a member only through the server, for an active member. No existing row changes beyond the empty defaults. Until it runs, the Page editor says the short description and member links need this update, and everything else on the page saves as before. Where part 81 is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'summary and member links: there is no communities table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS summary text; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS member_links jsonb NOT NULL DEFAULT '[]'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_summary_length' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_summary_length CHECK (summary IS NULL OR char_length(summary) <= 160); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_member_links_shape' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_member_links_shape CHECK (CASE WHEN jsonb_typeof(member_links) = 'array' THEN jsonb_array_length(member_links) <= 4 AND pg_column_size(member_links) <= 16384 ELSE false END); END IF; REVOKE SELECT (summary, member_links), INSERT (summary, member_links), UPDATE (summary, member_links) ON public.communities FROM PUBLIC, anon, authenticated; GRANT SELECT (summary, member_links), UPDATE (summary, member_links) ON public.communities TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('220', '220_community_summary_and_member_links.sql', 'cfe2288f90605cd9accfd06f3a80edb536dfdee0dda1b14f80baa15a655bbac7') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 221_community_member_link_clicks.sql
/* Presses on a community's member links (round 26), run after part 81. A community keeps up to four links for its members (its member links, part 220), shown only inside the community; this counts how often members use them, for the Page editor to show beside each link. One new server only table, `community_member_link_clicks`: one row per member, link and day (UTC), so pressing a link again the same day, a double tap or a retried request is still one row, and the count per link is the number of rows. The member's own rows go with their account and a community's with the community. No policy: nobody's browser reads or writes it; the server writes a row when a member presses a link and counts them for the creator. No existing row changes. Until it runs, links work and presses are simply not counted. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_member_link_clicks (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, link_id text NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, day date NOT NULL DEFAULT ((now() AT TIME ZONE 'utc')::date), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_member_link_clicks_pkey PRIMARY KEY (community_id, link_id, user_id, day), CONSTRAINT community_member_link_clicks_link_check CHECK (link_id ~ '^[A-Za-z0-9_-]{1,40}$'));
CREATE INDEX IF NOT EXISTS community_member_link_clicks_user_idx ON public.community_member_link_clicks (user_id);
ALTER TABLE public.community_member_link_clicks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_member_link_clicks FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_member_link_clicks TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('221', '221_community_member_link_clicks.sql', 'b95b7142884f1f94d6ab3b5339d8b9b1dc8f593f163caad51bd6cfc87ab6eeee') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 222_community_scheduled_post_media.sql
/* What a scheduled post or a draft carries (round 27), run after part 194. The people who run a community can now schedule a post, or keep a draft, with everything Post would send now: pictures, a video, files, GIFs, videos by link, a link card and a poll. Two new columns on `community_scheduled_posts`: `media`, the same list a post keeps in `community_feed_posts.media` (an empty list by default, at most 40 entries and 64 KB), and `poll`, a poll's question, choices, whether several can be picked, and how many days it runs once the post goes up (null when there is none, at most 16 KB). The table stays server only, as part 194 made it: only the service role reads and writes it, after the app's checks (the media is checked as a post's when it is saved and again, as its author, when it goes up). No existing row changes: every scheduled post and draft keeps its words and gets an empty list and no poll. Until it runs, scheduling works as before with words only, and the writer says this part is needed for a post that carries something. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_scheduled_posts') IS NULL THEN RAISE NOTICE 'scheduled post media: there is no community_scheduled_posts table, run part 194 first.'; RETURN; END IF; ALTER TABLE public.community_scheduled_posts ADD COLUMN IF NOT EXISTS media jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.community_scheduled_posts ADD COLUMN IF NOT EXISTS poll jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_scheduled_posts_media_check' AND conrelid = 'public.community_scheduled_posts'::regclass) THEN ALTER TABLE public.community_scheduled_posts ADD CONSTRAINT community_scheduled_posts_media_check CHECK (jsonb_typeof(media) = 'array' AND jsonb_array_length(media) <= 40 AND octet_length(media::text) <= 65536); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_scheduled_posts_poll_check' AND conrelid = 'public.community_scheduled_posts'::regclass) THEN ALTER TABLE public.community_scheduled_posts ADD CONSTRAINT community_scheduled_posts_poll_check CHECK (poll IS NULL OR (jsonb_typeof(poll) = 'object' AND octet_length(poll::text) <= 16384)); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('222', '222_community_scheduled_post_media.sql', '9fdb6056abf29d9fb2ecf2a6bd5e70257b3a04507cfcd28d1423235bb18264d7') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 224_orders_seller_seen.sql
/* Orders the seller has not opened yet (round 27): `orders.seller_seen_at`, when someone on the store first opened the order on the Orders page, which puts a small dot on an order nobody has opened. Added once, with every order already there counted as seen at that moment (a default read when the column is made, then dropped, so no row is rewritten and the table is not held), so the dot is on orders that come in from now on, not on a store's whole history. A second run changes nothing. Written by the server only, as the rest of an order. Needs nothing else. Until it runs, the Orders page shows no dot and opening an order changes nothing. Safe to run again. */
DO $$ BEGIN IF to_regclass('public.orders') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'seller_seen_at') THEN ALTER TABLE public.orders ADD COLUMN seller_seen_at timestamptz DEFAULT now(); ALTER TABLE public.orders ALTER COLUMN seller_seen_at DROP DEFAULT; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('224', '224_orders_seller_seen.sql', '68d352cd6bde1e10053beb52a11a5336d0fe3acf4e57fb20b92eb62ea1537cb9') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 230_store_offers_settings.sql
/* Upsells and bundles, every setting (round V): on `store_offers`, the trigger collections of a checkout offer (a product from any of them in the cart qualifies it), where each offer shows (`placements`: product page, cart, checkout), its start and end, whether a discount code can be used on top (`combines_with_codes`, true by default; when false the buyer gets whichever saves more), a limit per order (complete sets for a bundle, units for a checkout offer), a minimum for the rest of the cart, and free shipping as a discount. Existing offers keep what they did: shown everywhere, no dates, combining with codes, no limits. Owner reads, only the server writes, as part 116 set. Safe to run again. */
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS trigger_collection_ids uuid[] NOT NULL DEFAULT '{}'::uuid[];
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS placements text[] NOT NULL DEFAULT ARRAY['product', 'cart', 'checkout']::text[];
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS starts_at timestamptz;
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS ends_at timestamptz;
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS combines_with_codes boolean NOT NULL DEFAULT true;
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS max_per_order integer;
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS min_subtotal_cents integer;
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.store_offers'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%discount_type%' AND pg_get_constraintdef(oid) LIKE '%''none''%' AND pg_get_constraintdef(oid) NOT LIKE '%free_shipping%' LOOP EXECUTE format('ALTER TABLE public.store_offers DROP CONSTRAINT %I', c.conname); END LOOP; END $$;
ALTER TABLE public.store_offers DROP CONSTRAINT IF EXISTS store_offers_discount_type_check;
ALTER TABLE public.store_offers ADD CONSTRAINT store_offers_discount_type_check CHECK (discount_type IN ('percent', 'fixed', 'free_shipping', 'none'));
ALTER TABLE public.store_offers DROP CONSTRAINT IF EXISTS store_offers_settings_shape;
ALTER TABLE public.store_offers ADD CONSTRAINT store_offers_settings_shape CHECK (cardinality(trigger_collection_ids) <= 20 AND placements <@ ARRAY['product', 'cart', 'checkout']::text[] AND cardinality(placements) BETWEEN 1 AND 3 AND (max_per_order IS NULL OR max_per_order BETWEEN 1 AND 99) AND (min_subtotal_cents IS NULL OR min_subtotal_cents BETWEEN 0 AND 10000000) AND (starts_at IS NULL OR ends_at IS NULL OR ends_at > starts_at));
ALTER TABLE public.store_offers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS store_offers_owner_read ON public.store_offers;
CREATE POLICY store_offers_owner_read ON public.store_offers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = store_offers.creator_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.store_offers FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('230', '230_store_offers_settings.sql', '9715ba52c7854fed848def4e4eb70b8570a650dc69bd1481ceeeec7901dcc062') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 231_ai_memory_sources.sql
/* AI Memory for each website and for connected agents (V round), run after 106. Adds to `ai_memories`: `kind` (voice, design, like, dislike, fact or preference), `source_name` (which connected agent kept a note, up to 80 characters), and a third source, 'agent', for a note kept by Claude Code, Codex or another tool connected over MCP. A second index finds one website's notes. Row level security is unchanged: a signed in person reads, adds and deletes only their own, and a website's notes only for a website of theirs; nobody can change one in place. No existing row changes. Until it runs, notes keep their words and scope without a kind, and a connected agent's note is kept as Storelib AI's. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.ai_memories') IS NULL THEN RAISE NOTICE 'ai memory sources: run part 106 first.'; RETURN; END IF; ALTER TABLE public.ai_memories ADD COLUMN IF NOT EXISTS kind text; ALTER TABLE public.ai_memories ADD COLUMN IF NOT EXISTS source_name text; ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_kind_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_kind_check CHECK (kind IS NULL OR kind IN ('voice', 'design', 'like', 'dislike', 'fact', 'preference')); ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_source_name_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_source_name_check CHECK (source_name IS NULL OR length(source_name) BETWEEN 1 AND 80); ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_source_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_source_check CHECK (source IN ('creator', 'assistant', 'agent')); CREATE INDEX IF NOT EXISTS ai_memories_install_idx ON public.ai_memories (install_id, created_at DESC) WHERE install_id IS NOT NULL; ALTER TABLE public.ai_memories ENABLE ROW LEVEL SECURITY; REVOKE UPDATE ON public.ai_memories FROM authenticated, anon; REVOKE ALL ON public.ai_memories FROM anon; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('231', '231_ai_memory_sources.sql', 'b84c2855cfbbe2742da0936b0723e71662cc91fda99ccd3f80deba9f166a7153') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 232_review_imports_from_apps.sql
/* Review imports from other apps (Reviews › Import, round V), on part 215's `review_imports` and `reviews.import_id` rather than beside them. On `review_imports`: `platform` (the app the file came from: Judge.me, Yotpo, Loox, Stamped.io, Okendo, Shopify Product Reviews, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews, Rivyo or other), `created_by`, `total_rows`, `duplicates` (rows already on the store), `errors` (rows that could not be read), `finished_at` and `undone_count`; the table stays server only, as part 215 made it. On `reviews`: `import_key` (the app's own id for the review, as "judgeme:123", one per store, so the same file imported twice adds nothing), `content_hash` (the review's product, stars, words, name and day, so the same review exported by two apps is found too), `import_platform`, `import_verified` (the app said it was a verified purchase: shown to the store in Reviews, never as Verified purchase on the website and never in a Storelib rating) and `videos` (web addresses of a review's videos, at most two). The new columns are not readable by the public (part 134 grants reviews column by column). Run after part 215. Changes no row. Until it runs, Import works with part 215's history and Undo, finds duplicates from the reviews already imported, and keeps no app ids, videos or app verified flags. */
DO $do$ BEGIN IF to_regclass('public.review_imports') IS NULL THEN RAISE NOTICE 'review imports from apps: run part 215 first.'; RETURN; END IF; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS platform text NOT NULL DEFAULT 'other'; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS created_by uuid; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS total_rows integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS duplicates integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS errors integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS finished_at timestamptz; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS undone_count integer; ALTER TABLE public.review_imports DROP CONSTRAINT IF EXISTS review_imports_apps_check; ALTER TABLE public.review_imports ADD CONSTRAINT review_imports_apps_check CHECK (char_length(platform) BETWEEN 1 AND 40 AND total_rows >= 0 AND duplicates >= 0 AND errors >= 0 AND (undone_count IS NULL OR undone_count >= 0)) NOT VALID; ALTER TABLE public.review_imports ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.review_imports FROM PUBLIC, anon, authenticated; END $do$;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_key text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS content_hash text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_platform text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_verified boolean NOT NULL DEFAULT false;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS videos jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_import_values_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_import_values_check CHECK (char_length(coalesce(import_key, '')) <= 200 AND char_length(coalesce(content_hash, '')) <= 64 AND char_length(coalesce(import_platform, '')) <= 40 AND jsonb_typeof(videos) = 'array' AND jsonb_array_length(videos) <= 2 AND pg_column_size(videos) < 4096) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS reviews_import_key_once ON public.reviews (creator_id, import_key) WHERE import_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS reviews_content_hash ON public.reviews (creator_id, content_hash) WHERE content_hash IS NOT NULL;
REVOKE SELECT (import_key, content_hash, import_platform, import_verified, videos) ON public.reviews FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('232', '232_review_imports_from_apps.sql', 'bd1804b3c359fdd1760274c721c67704d7e70f6ea566aeda76cf786031df9b5b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 233_physical_carrier_prefs.sql
/* A shop's carriers (carrier selector): `physical_carrier_prefs`, one row per store holding the carriers it starred (up to 12 names), the one it set as its default, the one it last shipped with, and the carriers it added itself because no list has them (up to 20, each a name and an optional tracking link with {tracking} where the number goes). Names only: no prices, services or delivery times are kept here, those come from the shop's connected shipping app each time. Row level security on: the store's owner can read their own row, nobody else can; every write goes through the server with its own key after the owner is checked. No existing row changes, and a shipment's saved carrier and tracking link are untouched. Until it runs, the carrier picker still lists every carrier and the shop's connected ones, and starring, a default and a carrier of its own are not offered. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.physical_carrier_prefs (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, favourites text[] NOT NULL DEFAULT '{}'::text[], default_carrier text, last_carrier text, custom_carriers jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT physical_carrier_prefs_pkey PRIMARY KEY (creator_id), CONSTRAINT physical_carrier_prefs_favourites_check CHECK (cardinality(favourites) <= 12), CONSTRAINT physical_carrier_prefs_names_check CHECK ((default_carrier IS NULL OR char_length(default_carrier) BETWEEN 1 AND 60) AND (last_carrier IS NULL OR char_length(last_carrier) BETWEEN 1 AND 60)), CONSTRAINT physical_carrier_prefs_custom_check CHECK (CASE WHEN jsonb_typeof(custom_carriers) = 'array' THEN jsonb_array_length(custom_carriers) <= 20 AND pg_column_size(custom_carriers) < 16384 ELSE false END));
ALTER TABLE public.physical_carrier_prefs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.physical_carrier_prefs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.physical_carrier_prefs TO authenticated;
DROP POLICY IF EXISTS physical_carrier_prefs_owner_read ON public.physical_carrier_prefs;
CREATE POLICY physical_carrier_prefs_owner_read ON public.physical_carrier_prefs FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.physical_carrier_prefs TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('233', '233_physical_carrier_prefs.sql', 'eaa6a5203efae49b04b943cf8be771a9227bb22f7d9e168a330a42a6a32ccc8b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 243_shipped_order_tax_on_orders.sql
/* The tax on orders from the shipped goods checkout, on the order rows themselves (Taxes, round X4). Since part 110 each order line has kept its tax in `orders.tax_cents` (and part 129 `tax_included`, part 153 `tax_label`), which is what Settings › Taxes' Tax collected, its CSV, the receipt and the business invoice read. The shipped goods checkout kept a line's tax only inside `orders.product_snapshot`, so those orders were missing from Tax collected and their invoice had no tax line. The code now writes the columns for every new order; this copies the same figure from each older line's own snapshot into the empty columns, and the country from its checkout's tax facts or delivery address. Only rows with a checkout, no tax recorded yet and a tax in their snapshot change, and only those empty columns; no amount, status or other column moves. Safe to run again: a second run finds nothing to copy. Until it runs, older shipped orders stay out of Tax collected and new ones are counted. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL OR to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'shipped order tax: no orders or checkouts yet.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_cents') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_country') THEN RAISE NOTICE 'shipped order tax: run part 110 first.'; RETURN; END IF; UPDATE public.orders o SET tax_cents = LEAST((o.product_snapshot->>'tax_cents')::bigint, GREATEST(o.amount_cents, 0)), tax_country = COALESCE(o.tax_country, (SELECT upper(COALESCE(NULLIF(c.shipping_rate->>'tax_country', ''), c.shipping_address->>'country')) FROM public.commerce_checkouts c WHERE c.id = o.checkout_id AND upper(COALESCE(NULLIF(c.shipping_rate->>'tax_country', ''), c.shipping_address->>'country', '')) ~ '^[A-Z]{2}$')) WHERE o.checkout_id IS NOT NULL AND COALESCE(o.tax_cents, 0) = 0 AND jsonb_typeof(o.product_snapshot) = 'object' AND (o.product_snapshot->>'tax_cents') ~ '^[0-9]{1,12}$' AND (o.product_snapshot->>'tax_cents')::bigint > 0; END $do$;
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_included') THEN EXECUTE $q$UPDATE public.orders SET tax_included = true WHERE checkout_id IS NOT NULL AND COALESCE(tax_cents, 0) > 0 AND tax_included IS DISTINCT FROM true AND jsonb_typeof(product_snapshot) = 'object' AND product_snapshot->>'tax_included' = 'true'$q$; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_label') THEN EXECUTE $q$UPDATE public.orders SET tax_label = left(btrim(product_snapshot->>'tax_label'), 80) WHERE checkout_id IS NOT NULL AND COALESCE(tax_cents, 0) > 0 AND tax_label IS NULL AND jsonb_typeof(product_snapshot) = 'object' AND COALESCE(btrim(product_snapshot->>'tax_label'), '') <> ''$q$; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('243', '243_shipped_order_tax_on_orders.sql', '8bc7f1bf450c4e71d04d3e7e0a63c40bca9658e0518575453719d136765c541d') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 244_marketplace_pricing.sql
/* How a price was made, and a creator's own dollar price for the marketplace (currency round AM). Storelib's marketplace (Explore, creator pages, product pages on Storelib, communities) shows and charges US dollars once the switch MARKETPLACE_USD is on for a store; a store's website, OnePage and shared checkout links keep its own currency. Each order now notes where its price came from: `pricing_context` (merchant or marketplace), the store's own price and currency (`list_currency`, `list_amount_cents`), and for a marketplace dollar price its source (`price_source`: converted at the ECB rate, or the creator's own approved dollar price) and the rate day and rate behind it (`fx_as_of`, `fx_rate`). The order's own `currency` and amounts stay as charged. Products and their options get `marketplace_usd_cents` with `marketplace_usd_approved_at`: a dollar price the creator set themselves, used only once they approved it. Columns only, all nullable, with checks; no row changes, no amount moves. The code writes them as a separate update that may fail, so orders are made the same before and after this runs. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'marketplace pricing: no orders table yet.'; RETURN; END IF; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS pricing_context text, ADD COLUMN IF NOT EXISTS list_currency text, ADD COLUMN IF NOT EXISTS list_amount_cents bigint, ADD COLUMN IF NOT EXISTS price_source text, ADD COLUMN IF NOT EXISTS fx_as_of date, ADD COLUMN IF NOT EXISTS fx_rate numeric(20,10); IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_pricing_context_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_pricing_context_check CHECK (pricing_context IS NULL OR pricing_context IN ('merchant', 'marketplace')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_price_source_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_price_source_check CHECK (price_source IS NULL OR price_source IN ('native', 'fixed', 'converted')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_list_amount_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_list_amount_check CHECK ((list_amount_cents IS NULL OR list_amount_cents >= 0) AND (list_currency IS NULL OR list_currency ~ '^[a-z]{3}$') AND (fx_rate IS NULL OR fx_rate > 0)) NOT VALID; END IF; END $do$;
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products', 'product_variants'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS marketplace_usd_cents integer, ADD COLUMN IF NOT EXISTS marketplace_usd_approved_at timestamptz', t); IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = t || '_marketplace_usd_check' AND conrelid = ('public.' || t)::regclass) THEN EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (marketplace_usd_cents IS NULL OR (marketplace_usd_cents >= 0 AND marketplace_usd_cents <= 100000000)) NOT VALID', t, t || '_marketplace_usd_check'); END IF; END LOOP; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('244', '244_marketplace_pricing.sql', 'f376d726c3a87c965d4c3cb3c18fd172765b6b49d41f5104df41b9dde74c96e7') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 245_price_corrections.sql
/* A record of every price Storelib corrects for a creator (currency round AO). scripts/price-restore.mjs undoes the 4.6 multiplication of supabase/sql/RUN_CURRENCY_RON.sql only for a product its own order proves was multiplied (scripts/price-audit.mjs), and writes one row here BEFORE each change: which product or option, which field, the value before and after, the proof, and who approved it. An undo (--undo) reads these rows back. Orders and payments are never touched. Admin only: row level security on, no policy for anyone but the service role. Only adds a table; safe to run again. */
CREATE TABLE IF NOT EXISTS public.price_corrections (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), batch text NOT NULL CHECK (length(batch) BETWEEN 6 AND 80), product_id uuid NOT NULL, variant_id uuid, field text NOT NULL CHECK (field IN ('price_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents', 'compare_at_cents', 'variant_price_cents')), before_cents bigint NOT NULL CHECK (before_cents >= 0), after_cents bigint NOT NULL CHECK (after_cents >= 0), proof text NOT NULL CHECK (length(proof) BETWEEN 10 AND 600), approved_by text NOT NULL CHECK (length(approved_by) BETWEEN 2 AND 120), applied_at timestamptz, undone_at timestamptz);
CREATE INDEX IF NOT EXISTS price_corrections_product ON public.price_corrections (product_id, created_at DESC);
ALTER TABLE public.price_corrections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_corrections FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('245', '245_price_corrections.sql', 'a4013f33c2ab3fc84dc078c16173ddbc21dfd9f4cba680c3d86c5d25bb871e78') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 252_theme_marketplace_and_plan_overrides.sql
/* The theme marketplace and a plan set from /admin (round Z5). `theme_marketplace_listings`: one row per theme in the library's Browse themes and at storelib.com/themes, with its name, author and author photo, category, tier (free, paid with a price, or Pro plan only), cover, screenshots, the private path of its zip (checked and parsed by the import pipeline at upload), an optional demo store, published or hidden, and its place in the order. Anyone may read a published row; every write is the admin's, through the server. `creator_plan_overrides`: a plan an admin assigns a creator, over what they pay for, with the paid plan and status kept beside it. `admin_set_plan_override` writes the row and the creator's `subscription_plan_id` and `subscription_status` together, which every plan check already reads, and puts the paid plan back when it is cleared; the trigger `creators_plan_override_hold` keeps the override in those columns when a Stripe webhook or the billing sync writes a plan, and keeps the plan they wrote as the paid one. Stripe is never touched. The creator can read their own row, and it is in the realtime publication so their open app refreshes. Changes no existing row. Until it runs, the library and marketplace show Storelib's own theme, /admin/themes says to run it, and assigning a plan is refused with that reason. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_marketplace_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,62}[a-z0-9])?$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), author_name text NOT NULL DEFAULT 'Storelib' CHECK (char_length(author_name) BETWEEN 1 AND 80), author_avatar_url text, category text NOT NULL DEFAULT 'general', tier text NOT NULL DEFAULT 'free' CHECK (tier IN ('free', 'paid', 'pro')), price_cents integer NOT NULL DEFAULT 0 CHECK (price_cents >= 0 AND price_cents <= 1000000), cover_url text, screenshots text[] NOT NULL DEFAULT '{}', package_path text, package_kind text CHECK (package_kind IS NULL OR package_kind IN ('storelib', 'shopify', 'export')), builtin_theme_id uuid, demo_url text CHECK (demo_url IS NULL OR demo_url ~ '^https://'), published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.theme_marketplace_listings ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'theme_marketplace_listings' AND policyname = 'theme_marketplace_listings_read_published') THEN CREATE POLICY theme_marketplace_listings_read_published ON public.theme_marketplace_listings FOR SELECT TO anon, authenticated USING (published); END IF; END $do$;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.theme_marketplace_listings FROM anon, authenticated;
CREATE INDEX IF NOT EXISTS theme_marketplace_listings_order ON public.theme_marketplace_listings (published, sort_order);
CREATE TABLE IF NOT EXISTS public.creator_plan_overrides (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, plan_id text CHECK (plan_id IS NULL OR plan_id IN ('free', 'growth', 'pro')), paid_plan_id text, paid_status text, set_at timestamptz NOT NULL DEFAULT now(), set_by text NOT NULL DEFAULT 'admin session');
ALTER TABLE public.creator_plan_overrides ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'creator_plan_overrides' AND policyname = 'creator_plan_overrides_read_own') THEN CREATE POLICY creator_plan_overrides_read_own ON public.creator_plan_overrides FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = auth.uid())); END IF; END $do$;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.creator_plan_overrides FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_plan_override_hold() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE o record; BEGIN IF coalesce(current_setting('storelib.plan_override_write', true), '') = 'on' THEN RETURN NEW; END IF; IF NEW.subscription_plan_id IS NOT DISTINCT FROM OLD.subscription_plan_id AND NEW.subscription_status IS NOT DISTINCT FROM OLD.subscription_status THEN RETURN NEW; END IF; SELECT plan_id, paid_plan_id, paid_status INTO o FROM public.creator_plan_overrides WHERE creator_id = NEW.id; IF NOT FOUND OR o.plan_id IS NULL THEN RETURN NEW; END IF; UPDATE public.creator_plan_overrides SET paid_plan_id = CASE WHEN NEW.subscription_plan_id IS DISTINCT FROM OLD.subscription_plan_id THEN NEW.subscription_plan_id ELSE paid_plan_id END, paid_status = CASE WHEN NEW.subscription_plan_id IS DISTINCT FROM OLD.subscription_plan_id OR NEW.subscription_status IS DISTINCT FROM OLD.subscription_status THEN NEW.subscription_status ELSE paid_status END WHERE creator_id = NEW.id; NEW.subscription_plan_id := o.plan_id; NEW.subscription_status := 'active'; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.storelib_plan_override_hold() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_plan_override_hold ON public.creators; CREATE TRIGGER creators_plan_override_hold BEFORE UPDATE OF subscription_plan_id, subscription_status ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_plan_override_hold(); END IF; END $do$;
CREATE OR REPLACE FUNCTION public.admin_set_plan_override(p_creator uuid, p_plan text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE c record; o record; v_had boolean; v_from text; v_paid text; BEGIN IF p_plan IS NOT NULL AND p_plan NOT IN ('free', 'growth', 'pro') THEN RAISE EXCEPTION 'unknown plan %', p_plan; END IF; SELECT id, subscription_plan_id, subscription_status INTO c FROM public.creators WHERE id = p_creator FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'no creator %', p_creator; END IF; SELECT plan_id, paid_plan_id, paid_status INTO o FROM public.creator_plan_overrides WHERE creator_id = p_creator FOR UPDATE; v_had := FOUND AND o.plan_id IS NOT NULL; PERFORM set_config('storelib.plan_override_write', 'on', true); IF p_plan IS NULL THEN IF NOT v_had THEN PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', NULL, 'to', NULL, 'paid_plan_id', c.subscription_plan_id, 'changed', false); END IF; UPDATE public.creators SET subscription_plan_id = coalesce(o.paid_plan_id, 'free'), subscription_status = coalesce(o.paid_status, 'active') WHERE id = p_creator; UPDATE public.creator_plan_overrides SET plan_id = NULL, set_at = now() WHERE creator_id = p_creator; PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', o.plan_id, 'to', NULL, 'paid_plan_id', coalesce(o.paid_plan_id, 'free'), 'changed', true); END IF; IF v_had THEN v_from := o.plan_id; v_paid := o.paid_plan_id; UPDATE public.creator_plan_overrides SET plan_id = p_plan, set_at = now() WHERE creator_id = p_creator; ELSE v_from := coalesce(c.subscription_plan_id, 'free'); v_paid := c.subscription_plan_id; INSERT INTO public.creator_plan_overrides (creator_id, plan_id, paid_plan_id, paid_status, set_at) VALUES (p_creator, p_plan, c.subscription_plan_id, c.subscription_status, now()) ON CONFLICT (creator_id) DO UPDATE SET plan_id = EXCLUDED.plan_id, paid_plan_id = EXCLUDED.paid_plan_id, paid_status = EXCLUDED.paid_status, set_at = now(); END IF; UPDATE public.creators SET subscription_plan_id = p_plan, subscription_status = 'active' WHERE id = p_creator; PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', v_from, 'to', p_plan, 'paid_plan_id', v_paid, 'changed', true); END $f$;
REVOKE ALL ON FUNCTION public.admin_set_plan_override(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_set_plan_override(uuid, text) TO service_role;
DO $do$ BEGIN IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'creator_plan_overrides') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.creator_plan_overrides; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('252', '252_theme_marketplace_and_plan_overrides.sql', 'eb32aeb3b3bb61e161d40572b03ad31e396502a8b35fb2b463044183ba1ebe02') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 253_analytics_audience.sql
/* Analytics: systems, page titles and carts (round Z6). analytics_events gets page_title, the title of the page a view was of, so Top pages names each path by its title; nullable, at most 200 characters, checked for new rows only (NOT VALID). analytics_audience counts, for one creator, one property (or all of them), optionally one product and one period: unique visitors and page views by operating system (iOS, Android, Windows, macOS, Linux, ChromeOS and the rest as stored), the unique visitors who added something to the cart (buy_click), and the latest title of each page viewed. It reads analytics_events through the indexes part 25 and part 61 made (creator, event type, time; creator, property, event type, time), so no new index is needed. Server only: not SECURITY DEFINER, and only the service role may run it. No row changes. Until it runs, Analytics counts the same figures from the rows. Safe to run again. */
ALTER TABLE IF EXISTS public.analytics_events ADD COLUMN IF NOT EXISTS page_title text;
DO $do$ BEGIN IF to_regclass('public.analytics_events') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'analytics_events_page_title_length') THEN ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_page_title_length CHECK (page_title IS NULL OR length(page_title) <= 200) NOT VALID; END IF; END $do$;
CREATE OR REPLACE FUNCTION public.analytics_audience(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_start timestamptz, p_end timestamptz) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $f$ WITH e AS (SELECT a.event_type, a.os, a.property_type, a.property_id, a.path, a.page_title, a.created_at, coalesce(nullif(a.visitor_id, ''), nullif(a.session_id, ''), 'e:' || a.id::text) AS who FROM public.analytics_events a WHERE a.creator_id = p_creator_id AND a.event_type IN ('view', 'buy_click') AND a.created_at >= p_start AND a.created_at < p_end AND (p_property_type IS NULL OR (a.property_type = p_property_type AND (p_property_type <> 'website' OR a.property_id = p_property_id OR (a.property_id IS NULL AND p_default_website IS NOT NULL AND p_property_id = p_default_website)))) AND (p_product_id IS NULL OR a.product_id = p_product_id)), v AS (SELECT * FROM e WHERE e.event_type = 'view') SELECT jsonb_build_object('os', coalesce((SELECT jsonb_agg(jsonb_build_array(o.k, o.people, o.views) ORDER BY o.people DESC, o.k) FROM (SELECT coalesce(nullif(btrim(v.os), ''), 'unknown') AS k, count(DISTINCT v.who)::int AS people, count(*)::int AS views FROM v GROUP BY 1 ORDER BY 2 DESC, 1 LIMIT 40) o), '[]'::jsonb), 'carts', (SELECT count(DISTINCT e.who)::int FROM e WHERE e.event_type = 'buy_click'), 'titles', coalesce((SELECT jsonb_agg(jsonb_build_array(t.property_type, t.property_id, t.path, t.page_title)) FROM (SELECT DISTINCT ON (v.property_type, v.property_id, v.path) v.property_type, v.property_id, v.path, v.page_title FROM v WHERE v.page_title IS NOT NULL AND v.path IS NOT NULL ORDER BY v.property_type, v.property_id, v.path, v.created_at DESC LIMIT 2000) t), '[]'::jsonb)) $f$;
REVOKE ALL ON FUNCTION public.analytics_audience(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_audience(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('253', '253_analytics_audience.sql', '3416d9b85c004861fae4a0a2912c43a3e27af776a7dd33f3b7830237c9f6a5d2') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 254_analytics_report_layouts.sql
/* Analytics: the reports a seller adds (round ana-1021). `analytics_report_layouts`: one row per creator, `reports` the reports they added to /app/analytics as cards of their own, in their order (page views, visits, link clicks, OnePage links, refunded orders, downloads; at most twenty ids, a JSON array of short text), and when it last changed. Kept with the seller, so their phone and their laptop show the same cards and the page draws them on its first paint. Server only: row level security on and no policy, every client role refused; the app reads and writes the signed in seller's own row through the server (app/api/analytics/layout, app/app/analytics/page.tsx). Removed with its creator. Changes no existing row. Until it runs, the page keeps the choice in the browser, as it did. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.analytics_report_layouts (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, reports jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_report_layouts_reports_list CHECK (jsonb_typeof(reports) = 'array' AND jsonb_array_length(reports) <= 20));
ALTER TABLE public.analytics_report_layouts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.analytics_report_layouts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.analytics_report_layouts TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('254', '254_analytics_report_layouts.sql', 'b74e92a4b18105508f3d240ecd8913af09103d94fe35e5c8c50290636d029f11') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 256_company_invoices_setting.sql
/* Company invoices at checkout, a store's choice (round chk-1021): "Buying for a business", the box where a buyer adds a company's name, tax number and address for an invoice made out to it, is now shown only where Settings › Checkout › Company invoices is on, kept as `businessInvoice` in the checkout object `store_settings.checkout` (part 109), off for a new store (lib/store/checkout-config.ts). Every checkout used to show it. This turns it on, once, for the stores that already relied on it: a store that has had an order with company details (`orders.business_details`, part 36; `orders.creator_id`, part 32), and a store that filled in its own tax number in Store details › Business details (`store_settings.legal`, part 153), the sign of a business that issues invoices. A store that has set it either way is left as it chose. Every other store reads it as off, as a new one does. Writes only that one key of the checkout object, adding a settings row where a store with company orders had none; no order and no other setting changes. Needs part 109, and skips with a notice where store_settings is not there; reads only the columns of parts 32, 36 and 153 that exist. Safe to run again: a second run finds every such store already set. Until it runs, every store reads it as off and its checkout hides the box. */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'company invoices: store_settings is not there yet (part 109).'; RETURN; END IF; IF to_regclass('public.orders') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'business_details') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN INSERT INTO public.store_settings (creator_id, checkout) SELECT DISTINCT o.creator_id, '{"businessInvoice": true}'::jsonb FROM public.orders o JOIN public.creators c ON c.id = o.creator_id WHERE o.business_details IS NOT NULL ON CONFLICT (creator_id) DO UPDATE SET checkout = public.store_settings.checkout || '{"businessInvoice": true}'::jsonb, updated_at = now() WHERE NOT (public.store_settings.checkout ? 'businessInvoice'); END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_settings' AND column_name = 'legal') THEN UPDATE public.store_settings s SET checkout = s.checkout || '{"businessInvoice": true}'::jsonb, updated_at = now() WHERE NOT (s.checkout ? 'businessInvoice') AND jsonb_typeof(s.legal) = 'object' AND coalesce(btrim(s.legal ->> 'taxId'), '') <> ''; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('256', '256_company_invoices_setting.sql', '22efee92c499c6d83c1bf6738378e3828ccd779d7e73ea614d2d3cac76ac7795') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 257_site_route_facts.sql
/* What a website's every request asks before it can be routed, in one round trip (live site speed, Oct 21). proxy.ts asks of a name, on every page of a website the server has not seen in the last half minute: its creator (profiles, then creators), its published install and whether that theme was imported (store_theme_installs with its settings), its languages and markets (store_localization, then store_settings), and on a subdomain whether the website has a domain of its own (custom_domains): five or six reads, four of them one after another, before a page held at the edge could be sent. `site_route_facts(name)` answers all of them at once, as jsonb: creator_id, published, compat, localization (its default language, languages, markets and visitor language, or null), store (default_country and currency), website_domain (the primary active website domain and its ssl_status, or null). It reads optional tables and columns through to_jsonb and to_regclass, so a database without parts 22, 136 or 173 answers as the separate reads would. Read only, server only: SECURITY DEFINER, executable by service_role alone. Until it runs, the proxy reads the rows one by one as before. Safe to run again. */
CREATE OR REPLACE FUNCTION public.site_route_facts(p_name text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$ DECLARE v_name text := lower(coalesce(p_name, '')); v_creator uuid; v_install uuid; v_kind text; v_loc jsonb; v_store jsonb; v_domain jsonb; BEGIN IF v_name = '' THEN RETURN jsonb_build_object('creator_id', NULL, 'published', false, 'compat', false); END IF; SELECT c.id INTO v_creator FROM public.profiles p JOIN public.creators c ON c.user_id = p.id WHERE p.username = v_name LIMIT 1; IF v_creator IS NULL THEN SELECT c.id INTO v_creator FROM public.creators c WHERE c.slug = v_name LIMIT 1; END IF; IF v_creator IS NULL THEN RETURN jsonb_build_object('creator_id', NULL, 'published', false, 'compat', false); END IF; SELECT i.id, s.settings -> 'compat' ->> 'kind' INTO v_install, v_kind FROM public.store_theme_installs i LEFT JOIN public.store_theme_settings s ON s.install_id = i.id WHERE i.creator_id = v_creator AND i.status = 'published' ORDER BY i.sort_order ASC LIMIT 1; IF to_regclass('public.store_localization') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''default_language'', j -> ''default_language'', ''languages'', j -> ''languages'', ''markets'', j -> ''markets'', ''visitor_language'', j -> ''visitor_language'') FROM (SELECT to_jsonb(l) AS j FROM public.store_localization l WHERE l.creator_id = $1 LIMIT 1) x' INTO v_loc USING v_creator; END IF; IF to_regclass('public.store_settings') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''default_country'', to_jsonb(s) -> ''default_country'', ''currency'', to_jsonb(s) -> ''currency'') FROM public.store_settings s WHERE s.creator_id = $1 LIMIT 1' INTO v_store USING v_creator; END IF; IF v_install IS NOT NULL AND to_regclass('public.custom_domains') IS NOT NULL THEN EXECUTE 'SELECT jsonb_build_object(''domain'', d.domain, ''ssl_status'', to_jsonb(d) ->> ''ssl_status'') FROM public.custom_domains d WHERE d.creator_id = $1 AND d.status = ''active'' AND to_jsonb(d) ->> ''purpose'' = ''website'' AND (to_jsonb(d) ->> ''is_primary'') = ''true'' LIMIT 1' INTO v_domain USING v_creator; END IF; RETURN jsonb_build_object('creator_id', v_creator, 'published', v_install IS NOT NULL, 'compat', coalesce(v_kind = 'shopify', false), 'localization', v_loc, 'store', v_store, 'website_domain', v_domain); END $f$;
REVOKE ALL ON FUNCTION public.site_route_facts(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.site_route_facts(text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('257', '257_site_route_facts.sql', 'dc43d0972f98c92e69c0e3547b3c2d4442a069c8129fbf6abbd80aa2976b1c53') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 258_store_currency_plans_offers_collections.sql
/* A store's currency change converts what it should and nothing else (part 176 again, three functions replaced). Membership and community plans are priced and billed in US dollars whatever the store sells in (lib/money/product-currency), so a change no longer converts those products' prices: a $10 plan stayed $10 at Stripe while its card read $49.70 after a change to lei. Offers' fixed amounts off and their minimum basket (store_offers.discount_value when fixed, min_subtotal_cents) and a smart collection's price and compare-at price conditions (product_collections.rules) are in the store's currency and are now converted with everything else, kept in the change's snapshots and put back by Undo, so a €5 off bundle does not become 5 lei off and a "price under 30" collection still holds the same products. Orders, refunds and payouts are still never touched. Needs part 176. Safe to run again. */
CREATE OR REPLACE FUNCTION public.store_currency_targets() RETURNS TABLE (table_name text, key_column text, store_filter text, money_columns text[]) LANGUAGE sql IMMUTABLE AS $fn$ VALUES ('products', 'id', 'creator_id = $1 AND coalesce(type, '''') NOT IN (''membership'', ''community'')', ARRAY['price_cents', 'compare_at_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents']), ('product_variants', 'id', 'product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = $1 AND coalesce(p.type, '''') NOT IN (''membership'', ''community''))', ARRAY['price_cents', 'compare_at_price_cents', 'additional_price_cents']), ('product_variant_costs', 'variant_id', 'creator_id = $1', ARRAY['cost_cents']), ('shipping_rates', 'id', 'creator_id = $1', ARRAY['price_cents', 'free_over_cents']), ('inventory_locations', 'id', 'creator_id = $1', ARRAY['local_delivery_price_cents', 'local_delivery_min_cents', 'local_delivery_free_over_cents']), ('coupons', 'id', 'creator_id = $1', ARRAY['min_purchase_cents']), ('store_offers', 'id', 'creator_id = $1', ARRAY['min_subtotal_cents']), ('product_collections', 'id', 'creator_id = $1 AND kind = ''smart'' AND EXISTS (SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>''field'' IN (''price'', ''compare_at_price''))', ARRAY[]::text[]) $fn$;
CREATE OR REPLACE FUNCTION public.store_change_currency(p_creator uuid, p_from text, p_to text, p_mode text, p_rate numeric, p_rate_as_of date, p_key text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_prev public.store_currency_changes%ROWTYPE; v_stored text; v_change uuid := gen_random_uuid(); v_counts jsonb := '{}'::jsonb; v_target record; v_cols text[]; v_set text; v_snap text; v_n integer; BEGIN IF p_creator IS NULL THEN RAISE EXCEPTION 'store_currency: no store' USING ERRCODE = '22023'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from !~ '^[A-Z]{3}$' OR p_to !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'store_currency: a currency is not a code' USING ERRCODE = '22023'; END IF; IF p_from = p_to THEN RAISE EXCEPTION 'store_currency: the store already sells in %', p_to USING ERRCODE = '22023'; END IF; IF p_mode IS NULL OR p_mode NOT IN ('keep', 'convert') THEN RAISE EXCEPTION 'store_currency: mode is keep or convert' USING ERRCODE = '22023'; END IF; IF p_mode = 'convert' AND (p_rate IS NULL OR p_rate <= 0 OR p_rate > 1000000) THEN RAISE EXCEPTION 'store_currency: converting needs a rate' USING ERRCODE = '22023'; END IF; IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 120 THEN RAISE EXCEPTION 'store_currency: a request key is needed' USING ERRCODE = '22023'; END IF; INSERT INTO public.store_settings (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT currency INTO v_stored FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_prev FROM public.store_currency_changes WHERE creator_id = p_creator AND request_key = p_key; IF FOUND THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'id', v_prev.id, 'from', v_prev.from_currency, 'to', v_prev.to_currency, 'mode', v_prev.mode, 'rate', v_prev.rate, 'counts', v_prev.counts); END IF; IF coalesce(v_stored, p_from) <> p_from THEN RAISE EXCEPTION 'store_currency: the store now sells in %', v_stored USING ERRCODE = '40001'; END IF; INSERT INTO public.store_currency_changes (id, creator_id, from_currency, to_currency, previous_currency, mode, rate, rate_as_of, request_key, created_by) VALUES (v_change, p_creator, p_from, p_to, v_stored, p_mode, CASE WHEN p_mode = 'convert' THEN p_rate END, CASE WHEN p_mode = 'convert' THEN p_rate_as_of END, p_key, p_user); IF p_mode = 'convert' THEN FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(c ORDER BY c) INTO v_cols FROM unnest(v_target.money_columns) AS c WHERE EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = v_target.table_name AND ic.column_name = c); IF v_target.table_name = 'shipping_rates' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['min_value', 'max_value', 'tiers', 'kind']; ELSIF v_target.table_name = 'coupons' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'store_offers' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'product_collections' THEN v_cols := ARRAY['rules']; END IF; IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN CONTINUE; END IF; v_snap := format('INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT $2, %L, t.%I, jsonb_build_object(%s) FROM public.%I t WHERE %s', v_target.table_name, v_target.key_column, (SELECT string_agg(format('%L, t.%I', c, c), ', ') FROM unnest(v_cols) AS c), v_target.table_name, v_target.store_filter); EXECUTE v_snap USING p_creator, v_change; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_target.table_name = 'shipping_rates' THEN v_set := concat_ws(', ', CASE WHEN 'price_cents' = ANY (v_cols) THEN 'price_cents = round(price_cents * $2)::integer' END, CASE WHEN 'free_over_cents' = ANY (v_cols) THEN 'free_over_cents = CASE WHEN free_over_cents IS NULL THEN NULL ELSE round(free_over_cents * $2)::integer END' END, 'min_value = CASE WHEN kind = ''price'' AND min_value IS NOT NULL THEN round(min_value * $2)::integer ELSE min_value END', 'max_value = CASE WHEN kind = ''price'' AND max_value IS NOT NULL THEN round(max_value * $2)::integer ELSE max_value END', 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' THEN x || jsonb_strip_nulls(jsonb_build_object(''priceCents'', CASE WHEN x ? ''priceCents'' THEN round((x->>''priceCents'')::numeric * $2)::integer END, ''from'', CASE WHEN kind = ''price'' AND x ? ''from'' THEN round((x->>''from'')::numeric * $2)::integer END)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END'); ELSIF v_target.table_name = 'coupons' THEN v_set := concat_ws(', ', CASE WHEN 'min_purchase_cents' = ANY (v_cols) THEN 'min_purchase_cents = CASE WHEN min_purchase_cents IS NULL THEN NULL ELSE round(min_purchase_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(0.01, round(discount_value * $2, 2)) ELSE discount_value END'); ELSIF v_target.table_name = 'store_offers' THEN v_set := concat_ws(', ', CASE WHEN 'min_subtotal_cents' = ANY (v_cols) THEN 'min_subtotal_cents = CASE WHEN min_subtotal_cents IS NULL THEN NULL ELSE round(min_subtotal_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(1, round(discount_value * $2))::integer ELSE discount_value END'); ELSIF v_target.table_name = 'product_collections' THEN v_set := 'rules = (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' AND x->>''field'' IN (''price'', ''compare_at_price'') AND (x->>''value'') ~ ''^\s*[0-9]+(\.[0-9]+)?\s*$'' THEN jsonb_set(x, ''{value}'', to_jsonb(regexp_replace(regexp_replace(round(btrim(x->>''value'')::numeric * $2, 2)::text, ''0+$'', ''''), ''\.$'', ''''))) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(rules) WITH ORDINALITY AS e(x, o))'; ELSE SELECT string_agg(format('%1$I = CASE WHEN %1$I IS NULL THEN NULL ELSE round(%1$I * $2)::integer END', c), ', ') INTO v_set FROM unnest(v_cols) AS c; END IF; EXECUTE format('UPDATE public.%I SET %s WHERE %s', v_target.table_name, v_set, v_target.store_filter) USING p_creator, p_rate; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT v_change, 'store_settings', s.creator_id, jsonb_build_object('codFeeCents', s.checkout->'codFeeCents') FROM public.store_settings s WHERE s.creator_id = p_creator AND jsonb_typeof(s.checkout->'codFeeCents') = 'number'; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_n > 0 THEN UPDATE public.store_settings SET checkout = jsonb_set(checkout, '{codFeeCents}', to_jsonb(round((checkout->>'codFeeCents')::numeric * p_rate)::integer)) WHERE creator_id = p_creator; v_counts := v_counts || jsonb_build_object('cod_fee', 1); END IF; END IF; UPDATE public.store_settings SET currency = p_to, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET counts = v_counts WHERE id = v_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'id', v_change, 'from', p_from, 'to', p_to, 'mode', p_mode, 'rate', CASE WHEN p_mode = 'convert' THEN p_rate END, 'counts', v_counts); END $fn$;
CREATE OR REPLACE FUNCTION public.store_currency_restore(p_creator uuid, p_change uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_change public.store_currency_changes%ROWTYPE; v_latest uuid; v_target record; v_cols text[]; v_set text; v_counts jsonb := '{}'::jsonb; v_n integer; BEGIN PERFORM 1 FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_change FROM public.store_currency_changes WHERE id = p_change AND creator_id = p_creator; IF NOT FOUND THEN RAISE EXCEPTION 'store_currency: no such change' USING ERRCODE = '22023'; END IF; IF v_change.restored_at IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'currency', v_change.from_currency); END IF; SELECT id INTO v_latest FROM public.store_currency_changes WHERE creator_id = p_creator AND restored_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 1; IF v_latest IS DISTINCT FROM p_change THEN RAISE EXCEPTION 'store_currency: only the latest change can be undone' USING ERRCODE = '40001'; END IF; FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(DISTINCT k) INTO v_cols FROM public.store_currency_snapshots s, jsonb_object_keys(s.before) AS k WHERE s.change_id = p_change AND s.table_name = v_target.table_name AND k NOT IN ('kind', 'discount_type'); IF v_cols IS NULL THEN CONTINUE; END IF; SELECT string_agg( CASE c WHEN 'tiers' THEN 'tiers = s.before->''tiers''' WHEN 'rules' THEN 'rules = s.before->''rules''' WHEN 'discount_value' THEN 'discount_value = (s.before->>''discount_value'')::numeric' ELSE format('%1$I = (s.before->>%1$L)::integer', c) END, ', ') INTO v_set FROM unnest(v_cols) AS c; EXECUTE format('UPDATE public.%I t SET %s FROM public.store_currency_snapshots s WHERE s.change_id = $1 AND s.table_name = %L AND t.%I = s.row_id', v_target.table_name, v_set, v_target.table_name, v_target.key_column) USING p_change; GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; UPDATE public.store_settings t SET checkout = jsonb_set(t.checkout, '{codFeeCents}', s.before->'codFeeCents') FROM public.store_currency_snapshots s WHERE s.change_id = p_change AND s.table_name = 'store_settings' AND t.creator_id = s.row_id; UPDATE public.store_settings SET currency = v_change.previous_currency, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET restored_at = now() WHERE id = p_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'currency', v_change.from_currency, 'counts', v_counts); END $fn$;
REVOKE ALL ON FUNCTION public.store_currency_targets() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_currency_restore(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_currency_targets() TO service_role;
GRANT EXECUTE ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.store_currency_restore(uuid, uuid) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('258', '258_store_currency_plans_offers_collections.sql', 'a65180faf8172e1acc8dcc1d064eebd72b8f8ea2133af637d465ffb42d7c4ab3') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 259_checkout_business_details.sql
/* The company a buyer bought for, on a checkout that ships (round chk-1021): `commerce_checkouts.business_details`, the company's legal name, tax number and address as the website's checkout checked them (lib/checkout/business.ts), only where Settings › Checkout › Company invoices is on (part 256). The paid checkout writes it on every order line it becomes (`orders.business_details`, part 36), as a basket of downloads already does, so the invoice, the receipt and the seller's copy of the invoice are made out to the company for a cart that ships, or ships with downloads in it. Before this a shipped cart's company was checked and then dropped. Adds one column, empty on every checkout already there; changes no rows. Written by the server only, as every checkout column is. Needs part 78's table, and skips with a notice where it is not there. Until it runs, a shipped order is made as before, without the company. */
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'checkout company: commerce_checkouts is not there yet (part 78).'; RETURN; END IF; ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS business_details jsonb; ALTER TABLE public.commerce_checkouts DROP CONSTRAINT IF EXISTS commerce_checkouts_business_details_shape; ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_business_details_shape CHECK (business_details IS NULL OR (jsonb_typeof(business_details) = 'object' AND pg_column_size(business_details) <= 4096)) NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('259', '259_checkout_business_details.sql', 'b22b22aa829bacdcc1e77b91b26d6fbc06b99e30ed7f143246258fd792108bee') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 270_community_chat_realtime.sql
/* Community chat, complete (round 37), run after parts 81 and 83. `community_chat_settings` is one row per community for what its admins set in Settings, Chat: who may message whom (dm_policy everyone, staff or off), who may start a group (groups_policy members, staff or off), whether files and pictures can be sent, whether a phone's banner shows the words of a message (push_previews), and the chat rules a member accepts once before their first message (rules, rules_version; a new version asks again). `community_spaces.slow_mode_seconds` is a chat channel's own slow mode, 0 to 3600. `community_members` gets the member's own choice of who may message them (chat_dms everyone, staff or nobody), the rules version they accepted and when, and a chat only mute or ban set by a moderator (chat_muted_until, chat_banned_at, with who and why), so a member can be kept out of chat and still read the feed. `community_chat_groups`, `community_chat_group_members` and `community_chat_group_messages` are group chats made inside a community, with their people (owner or member, each with their own read mark) and messages; `public.community_in_group` says whether the signed in person is an active member of the community and in the group, and is the only way their rows are read. Messages in channels, conversations and groups take `client_id`, the sender's own id for a message, unique per author, so a send retried after a dropped connection is written once; direct messages also take `attachments` and `reply_to_id`. `community_chat_prefs` is a person's mute and notification choice for one channel, conversation or group, and `community_member_blocks` who a person has blocked (no messages either way). Reports can name a group message. `public.community_chat_topic_ok` lets a member join the typing channel of a chat they may read (realtime broadcast with private channels), added to realtime.messages when this role may. The three group tables join the supabase_realtime publication. RLS is on for every new table; members read only groups they are in, everything else is the server's. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_chat_settings (community_id uuid PRIMARY KEY REFERENCES public.communities(id) ON DELETE CASCADE, dm_policy text NOT NULL DEFAULT 'everyone', groups_policy text NOT NULL DEFAULT 'members', attachments_enabled boolean NOT NULL DEFAULT true, push_previews boolean NOT NULL DEFAULT true, rules text NOT NULL DEFAULT '', rules_version integer NOT NULL DEFAULT 0, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_settings_dm_policy CHECK (dm_policy IN ('everyone', 'staff', 'off')), CONSTRAINT community_chat_settings_groups_policy CHECK (groups_policy IN ('members', 'staff', 'off')), CONSTRAINT community_chat_settings_rules_len CHECK (char_length(rules) <= 4000), CONSTRAINT community_chat_settings_rules_version CHECK (rules_version >= 0));
ALTER TABLE public.community_spaces ADD COLUMN IF NOT EXISTS slow_mode_seconds integer NOT NULL DEFAULT 0;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_spaces_slow_mode_range') THEN ALTER TABLE public.community_spaces ADD CONSTRAINT community_spaces_slow_mode_range CHECK (slow_mode_seconds BETWEEN 0 AND 3600) NOT VALID; END IF; END $do$;
ALTER TABLE public.community_members ADD COLUMN IF NOT EXISTS chat_dms text NOT NULL DEFAULT 'everyone', ADD COLUMN IF NOT EXISTS chat_rules_version integer, ADD COLUMN IF NOT EXISTS chat_rules_accepted_at timestamptz, ADD COLUMN IF NOT EXISTS chat_muted_until timestamptz, ADD COLUMN IF NOT EXISTS chat_banned_at timestamptz, ADD COLUMN IF NOT EXISTS chat_restricted_by uuid, ADD COLUMN IF NOT EXISTS chat_restriction_reason text;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_members_chat_dms_check') THEN ALTER TABLE public.community_members ADD CONSTRAINT community_members_chat_dms_check CHECK (chat_dms IN ('everyone', 'staff', 'nobody')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_members_chat_reason_len') THEN ALTER TABLE public.community_members ADD CONSTRAINT community_members_chat_reason_len CHECK (chat_restriction_reason IS NULL OR char_length(chat_restriction_reason) <= 500) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, member_count integer NOT NULL DEFAULT 0, last_message_at timestamptz, last_author_id uuid, last_body text NOT NULL DEFAULT '', archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_groups_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT community_chat_groups_last_body_len CHECK (char_length(last_body) <= 200), CONSTRAINT community_chat_groups_member_count CHECK (member_count >= 0));
CREATE INDEX IF NOT EXISTS community_chat_groups_community_idx ON public.community_chat_groups (community_id, last_message_at DESC);
CREATE TABLE IF NOT EXISTS public.community_chat_group_members (group_id uuid NOT NULL REFERENCES public.community_chat_groups(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'member', added_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, last_read_at timestamptz, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (group_id, user_id), CONSTRAINT community_chat_group_members_role CHECK (role IN ('owner', 'member')));
CREATE INDEX IF NOT EXISTS community_chat_group_members_user_idx ON public.community_chat_group_members (user_id, community_id);
CREATE TABLE IF NOT EXISTS public.community_chat_group_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES public.community_chat_groups(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, kind text NOT NULL DEFAULT 'message', body text NOT NULL DEFAULT '', attachments jsonb NOT NULL DEFAULT '[]'::jsonb, reply_to_id uuid REFERENCES public.community_chat_group_messages(id) ON DELETE SET NULL, client_id text, status text NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz, CONSTRAINT community_chat_group_messages_kind CHECK (kind IN ('message', 'event')), CONSTRAINT community_chat_group_messages_status CHECK (status IN ('published', 'deleted', 'removed')), CONSTRAINT community_chat_group_messages_body_len CHECK (char_length(body) <= 4000), CONSTRAINT community_chat_group_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64), CONSTRAINT community_chat_group_messages_attachments_array CHECK (jsonb_typeof(attachments) = 'array'));
CREATE INDEX IF NOT EXISTS community_chat_group_messages_group_idx ON public.community_chat_group_messages (group_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS community_chat_group_messages_client_key ON public.community_chat_group_messages (author_id, client_id) WHERE client_id IS NOT NULL;
ALTER TABLE public.community_messages ADD COLUMN IF NOT EXISTS client_id text;
CREATE UNIQUE INDEX IF NOT EXISTS community_messages_client_key ON public.community_messages (author_id, client_id) WHERE client_id IS NOT NULL;
ALTER TABLE public.community_direct_messages ADD COLUMN IF NOT EXISTS attachments jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS reply_to_id uuid REFERENCES public.community_direct_messages(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS client_id text;
CREATE UNIQUE INDEX IF NOT EXISTS community_direct_messages_client_key ON public.community_direct_messages (author_id, client_id) WHERE client_id IS NOT NULL;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_messages_client_len') THEN ALTER TABLE public.community_messages ADD CONSTRAINT community_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_direct_messages_client_len') THEN ALTER TABLE public.community_direct_messages ADD CONSTRAINT community_direct_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_prefs (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, chat_type text NOT NULL, chat_id uuid NOT NULL, notify text NOT NULL DEFAULT 'default', muted_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, chat_type, chat_id), CONSTRAINT community_chat_prefs_type CHECK (chat_type IN ('space', 'dm', 'group')), CONSTRAINT community_chat_prefs_notify CHECK (notify IN ('default', 'all', 'mentions', 'none')));
CREATE INDEX IF NOT EXISTS community_chat_prefs_chat_idx ON public.community_chat_prefs (chat_type, chat_id, notify);
CREATE TABLE IF NOT EXISTS public.community_member_blocks (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, blocked_id), CONSTRAINT community_member_blocks_not_self CHECK (user_id <> blocked_id));
CREATE INDEX IF NOT EXISTS community_member_blocks_blocked_idx ON public.community_member_blocks (blocked_id);
ALTER TABLE public.community_reports DROP CONSTRAINT IF EXISTS community_reports_target_check, ADD CONSTRAINT community_reports_target_check CHECK (target_type IN ('post', 'comment', 'member', 'message', 'group_message')) NOT VALID;
CREATE OR REPLACE FUNCTION public.community_in_group(p_group uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT EXISTS (SELECT 1 FROM public.community_chat_group_members gm JOIN public.community_chat_groups g ON g.id = gm.group_id JOIN public.community_members m ON m.community_id = g.community_id AND m.user_id = gm.user_id JOIN public.communities k ON k.id = g.community_id WHERE gm.group_id = p_group AND gm.user_id = auth.uid() AND g.archived_at IS NULL AND m.status = 'active' AND m.banned_at IS NULL AND m.chat_banned_at IS NULL AND k.deleted_at IS NULL AND k.suspended_at IS NULL AND k.chat_enabled) $f$;
CREATE OR REPLACE FUNCTION public.community_chat_topic_ok(p_topic text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF auth.uid() IS NULL OR p_topic IS NULL THEN RETURN false; END IF; IF p_topic ~ '^chat:space:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_can_read_space(substr(p_topic, 12)::uuid); END IF; IF p_topic ~ '^chat:dm:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_in_conversation(substr(p_topic, 9)::uuid); END IF; IF p_topic ~ '^chat:group:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_in_group(substr(p_topic, 12)::uuid); END IF; RETURN false; END $f$;
CREATE OR REPLACE FUNCTION public.community_chat_group_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE public.community_chat_groups SET member_count = member_count + 1, updated_at = now() WHERE id = NEW.group_id; RETURN NEW; END IF; UPDATE public.community_chat_groups SET member_count = greatest(member_count - 1, 0), updated_at = now() WHERE id = OLD.group_id; RETURN OLD; END $f$;
DROP TRIGGER IF EXISTS community_chat_group_members_count ON public.community_chat_group_members;
CREATE TRIGGER community_chat_group_members_count AFTER INSERT OR DELETE ON public.community_chat_group_members FOR EACH ROW EXECUTE FUNCTION public.community_chat_group_count();
ALTER TABLE public.community_chat_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_groups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_group_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_group_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_prefs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_member_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_chat_settings, public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages, public.community_chat_prefs, public.community_member_blocks FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_chat_settings, public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages, public.community_chat_prefs, public.community_member_blocks TO service_role;
REVOKE ALL ON FUNCTION public.community_in_group(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.community_chat_topic_ok(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.community_chat_group_count() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_in_group(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.community_chat_topic_ok(text) TO authenticated, service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their groups" ON public.community_chat_groups; CREATE POLICY "storelib members read their groups" ON public.community_chat_groups FOR SELECT TO authenticated USING (public.community_in_group(id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their group people" ON public.community_chat_group_members; CREATE POLICY "storelib members read their group people" ON public.community_chat_group_members FOR SELECT TO authenticated USING (public.community_in_group(group_id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their group messages" ON public.community_chat_group_messages; CREATE POLICY "storelib members read their group messages" ON public.community_chat_group_messages FOR SELECT TO authenticated USING (public.community_in_group(group_id)); END $do$;
DO $do$ BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL THEN RAISE NOTICE 'community chat: realtime.messages is not here, typing shows nothing and every message still arrives.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib chat typing read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib chat typing read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''broadcast'' AND public.community_chat_topic_ok(realtime.topic()))'; EXECUTE 'DROP POLICY IF EXISTS "storelib chat typing send" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib chat typing send" ON realtime.messages FOR INSERT TO authenticated WITH CHECK (realtime.messages.extension = ''broadcast'' AND public.community_chat_topic_ok(realtime.topic()))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'community chat: this role may not add policies to realtime.messages, typing shows nothing and every message still arrives.'; END; END $do$;
DO $do$ DECLARE v_owner oid; v_table text; BEGIN SELECT pubowner INTO v_owner FROM pg_publication WHERE pubname = 'supabase_realtime'; IF NOT FOUND THEN RAISE NOTICE 'community chat: there is no supabase_realtime publication, group messages show when the chat asks again.'; RETURN; END IF; IF NOT pg_has_role(current_user, v_owner, 'MEMBER') THEN RAISE NOTICE 'community chat: this role does not own supabase_realtime, add community_chat_groups, community_chat_group_members and community_chat_group_messages to it in Database, Publications.'; RETURN; END IF; FOREACH v_table IN ARRAY ARRAY['community_chat_groups', 'community_chat_group_members', 'community_chat_group_messages', 'community_messages', 'community_conversations', 'community_direct_messages'] LOOP IF to_regclass('public.' || v_table) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_table) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table); END IF; END LOOP; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('270', '270_community_chat_realtime.sql', '9d263c54d12513dfdc92bd621f27121316d553998bc01979b2652f249029c0d6') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 271_community_analytics_tracking.sql
/* Community analytics tracking (round 37), run after part 184. A community's Analytics now counts by the hour, so every day of its chart starts at midnight in the viewer's own time zone, not at midnight in London. The nightly count keeps each hour's visitors and visitors who were not members in the new server only table `community_visit_hours` (the community, the hour, two counts; nothing about a visitor), and this part fills it from the visits still kept (the last three days). A member who opens their community or does anything in it is now also written once an hour to the new server only table `community_member_hours` (the community, the member, the hour), beside the day row part 184 writes, so active members are counted by the viewer's own days, and by the hour too. `community_analytics` is replaced, with the same arguments and the same answer: members who took part are now read from the posts, comments and reactions themselves (a like on one's own post was left out before), a post or comment the safety check held back is not counted as one, active members come from the hours once they are kept (the days before that from part 184's days), and a new `joined_by_visit` counts the joins a visitor made themselves (free, paid, bought or by invite; not those added by the team, by Storelib or by owning a product), which is what the join rate divides. No existing rows change. Until it runs, Analytics counts as part 184 does. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_visit_hours (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, hour timestamptz NOT NULL, visitors integer NOT NULL DEFAULT 0, prospects integer NOT NULL DEFAULT 0, CONSTRAINT community_visit_hours_pkey PRIMARY KEY (community_id, hour), CONSTRAINT community_visit_hours_counts_check CHECK (visitors >= 0 AND prospects >= 0 AND prospects <= visitors));
ALTER TABLE public.community_visit_hours ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_visit_hours FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_visit_hours TO service_role;
CREATE TABLE IF NOT EXISTS public.community_member_hours (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, hour timestamptz NOT NULL, CONSTRAINT community_member_hours_pkey PRIMARY KEY (community_id, hour, user_id));
ALTER TABLE public.community_member_hours ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_member_hours FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.community_member_hours TO service_role;
CREATE INDEX IF NOT EXISTS community_member_hours_user_idx ON public.community_member_hours (community_id, user_id, hour);
DO $do$ BEGIN IF to_regclass('public.community_view_days') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_view_days' AND column_name = 'member') THEN RAISE NOTICE 'community analytics tracking: community_view_days has no member column, run part 184 first. Nothing to fill.'; RETURN; END IF; INSERT INTO public.community_visit_hours (community_id, hour, visitors, prospects) SELECT v.community_id, date_trunc('hour', v.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC', count(*)::int, (count(*) FILTER (WHERE v.member IS NOT TRUE))::int FROM public.community_view_days v WHERE v.day < (now() AT TIME ZONE 'UTC')::date GROUP BY 1, 2 ON CONFLICT (community_id, hour) DO UPDATE SET visitors = excluded.visitors, prospects = excluded.prospects; END $do$;
CREATE OR REPLACE FUNCTION public.community_analytics(p_community uuid, p_from timestamptz, p_to timestamptz, p_tz text DEFAULT 'UTC', p_grain text DEFAULT 'day', p_detail boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_grain text := 'day'; v_fmt text; v_owner uuid; v_out jsonb; v_detail jsonb := '{}'::jsonb; v_end_month date; v_first_hour timestamptz; v_cut timestamptz; v_cut_day date; BEGIN IF p_community IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '800 days' THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; IF p_grain IN ('hour', 'day', 'month') THEN v_grain := p_grain; END IF; v_fmt := CASE v_grain WHEN 'hour' THEN 'YYYY-MM-DD"T"HH24' WHEN 'day' THEN 'YYYY-MM-DD' ELSE 'YYYY-MM' END; SELECT owner_user_id INTO v_owner FROM public.communities WHERE id = p_community; SELECT min(hour) INTO v_first_hour FROM public.community_member_hours WHERE community_id = p_community; IF v_first_hour IS NOT NULL THEN v_cut_day := (v_first_hour AT TIME ZONE 'UTC')::date + 1; v_cut := v_cut_day::timestamp AT TIME ZONE 'UTC'; END IF; WITH act AS (SELECT kind, user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_activity WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND kind IN ('joined', 'left', 'lesson_completed', 'course_completed')), joins AS (SELECT a.b FROM act a LEFT JOIN public.community_members m ON m.community_id = p_community AND m.user_id = a.user_id WHERE a.kind = 'joined' AND a.user_id IS DISTINCT FROM v_owner AND coalesce(m.source, 'free') NOT IN ('manual', 'platform', 'product', 'owner')), posts AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_posts WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), comments AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_comments WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), reactions AS (SELECT user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_reactions WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), took AS (SELECT user_id, b, 'post' AS k FROM posts WHERE user_id IS NOT NULL UNION ALL SELECT user_id, b, 'comment' FROM comments WHERE user_id IS NOT NULL UNION ALL SELECT user_id, b, 'reaction' FROM reactions WHERE user_id IS NOT NULL), rsvps AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_event_rsvps WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), hours AS (SELECT user_id, to_char(hour AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_member_hours WHERE community_id = p_community AND v_cut IS NOT NULL AND hour >= greatest(p_from, v_cut) AND hour < p_to), days AS (SELECT user_id, CASE v_grain WHEN 'month' THEN to_char(day, 'YYYY-MM') ELSE to_char(day, 'YYYY-MM-DD') END AS b FROM public.community_member_days WHERE community_id = p_community AND day >= (p_from AT TIME ZONE v_tz)::date AND day <= ((p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date AND (v_cut_day IS NULL OR day < v_cut_day)), here AS (SELECT user_id, b FROM hours UNION ALL SELECT user_id, b FROM days WHERE v_grain <> 'hour') SELECT jsonb_build_object('joined', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'joined' AND user_id IS DISTINCT FROM v_owner GROUP BY b) x), 'joined_by_visit', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM joins GROUP BY b) x), 'left', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'left' GROUP BY b) x), 'posts', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM posts GROUP BY b) x), 'comments', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM comments GROUP BY b) x), 'reactions', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM reactions GROUP BY b) x), 'rsvps', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM rsvps GROUP BY b) x), 'lessons', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'lesson_completed' GROUP BY b) x), 'contributors', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM took GROUP BY b) x), 'active', CASE WHEN v_grain = 'hour' AND (v_cut IS NULL OR v_cut > p_from) THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM here GROUP BY b) x) END, 'totals', jsonb_build_object('contributors', (SELECT count(DISTINCT user_id) FROM took), 'posters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'post'), 'commenters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'comment'), 'reactors', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'reaction'), 'active', (SELECT count(DISTINCT user_id) FROM (SELECT user_id FROM hours UNION SELECT user_id FROM days) u), 'courses', (SELECT count(*) FROM act WHERE kind = 'course_completed')), 'active_since', (SELECT min(day) FROM public.community_member_days WHERE community_id = p_community), 'active_hours_since', v_cut) INTO v_out; IF p_detail THEN v_end_month := date_trunc('month', (p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date; v_detail := jsonb_build_object('top_contributors', (SELECT coalesce(jsonb_agg(x ORDER BY x.score DESC, x.user_id), '[]'::jsonb) FROM (SELECT u.user_id, sum(u.posts)::int AS posts, sum(u.comments)::int AS comments, sum(u.posts) * 2 + sum(u.comments) AS score FROM (SELECT author_id AS user_id, 1 AS posts, 0 AS comments FROM public.community_feed_posts WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to UNION ALL SELECT author_id, 0, 1 FROM public.community_feed_comments WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to) u GROUP BY u.user_id ORDER BY score DESC, u.user_id LIMIT 10) x), 'top_spaces', (SELECT coalesce(jsonb_agg(x ORDER BY (x.posts + x.comments) DESC, x.name), '[]'::jsonb) FROM (SELECT s.id, s.name, s.slug, (SELECT count(*) FROM public.community_feed_posts p WHERE p.space_id = s.id AND p.status = 'published' AND p.created_at >= p_from AND p.created_at < p_to)::int AS posts, (SELECT count(*) FROM public.community_feed_comments c JOIN public.community_feed_posts p ON p.id = c.post_id WHERE p.space_id = s.id AND c.status = 'published' AND c.created_at >= p_from AND c.created_at < p_to)::int AS comments FROM public.community_spaces s WHERE s.community_id = p_community AND s.archived_at IS NULL) x WHERE x.posts + x.comments > 0), 'cohorts', (SELECT coalesce(jsonb_agg(x ORDER BY x.month DESC), '[]'::jsonb) FROM (SELECT to_char(date_trunc('month', m.joined_at AT TIME ZONE v_tz), 'YYYY-MM') AS month, count(*)::int AS joined, count(*) FILTER (WHERE m.status = 'active')::int AS stayed, count(*) FILTER (WHERE m.status = 'active' AND greatest(m.last_seen_at, m.last_active_at) >= now() - interval '30 days')::int AS active FROM public.community_members m WHERE m.community_id = p_community AND m.role <> 'owner' AND m.joined_at IS NOT NULL AND m.joined_at AT TIME ZONE v_tz >= (v_end_month - interval '5 months') AND m.joined_at AT TIME ZONE v_tz < (v_end_month + interval '1 month') GROUP BY 1) x), 'programs', (SELECT coalesce(jsonb_agg(x ORDER BY x.started DESC, x.title), '[]'::jsonb) FROM (SELECT cc.id, coalesce(nullif(cc.title, ''), pr.title, 'Program') AS title, count(e.id)::int AS started, count(e.completed_at)::int AS completed, coalesce(round(avg(e.percent))::int, 0) AS percent, (SELECT count(*) FROM public.community_activity a WHERE a.community_id = p_community AND a.kind = 'lesson_completed' AND a.created_at >= p_from AND a.created_at < p_to AND a.target_id IN (cc.id::text, cc.product_id::text))::int AS lessons FROM public.community_courses cc LEFT JOIN public.products pr ON pr.id = cc.product_id LEFT JOIN public.courses co ON co.id = coalesce(cc.course_id, (SELECT c2.id FROM public.courses c2 WHERE c2.product_id = cc.product_id ORDER BY c2.created_at LIMIT 1)) LEFT JOIN public.course_enrollments e ON e.course_id = co.id AND EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = e.buyer_id AND m.status = 'active') WHERE cc.community_id = p_community AND coalesce(cc.status, 'published') = 'published' GROUP BY cc.id, cc.title, pr.title, cc.product_id LIMIT 20) x)); END IF; RETURN v_out || v_detail; END $f$;
REVOKE ALL ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('271', '271_community_analytics_tracking.sql', 'c8ea262d70e4c835ab8caeaae7f9ec1bb6927700314d626336d5733b5254e9c8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 272_community_chat_automations.sql
/* Community chat, round 38, run after part 270. `community_chat_settings` gets who may START a conversation beyond everyone, the team only or off: members from a points level (dm_policy level, dm_min_level) or after some days in the community (dm_policy days, dm_min_days), whether members may write to the team (dm_to_staff), whether the community shows a Chat tab (chat_tab) and which channel it opens (main_space_id, null for the first). `community_spaces` gets a channel's points level to post (post_min_level, 0 for none; the team only is post_role as before) and its pinned message (pinned_message_id, pinned_at, pinned_by). `community_chat_automations` are messages a community sends by itself: on a join, a level reached, some days after joining, a paid membership started or cancelled, or once to members or a part of them (a level, a tier, joined lately), now or at a time; into each member's messages or into a channel, from a member of the team. `community_chat_automation_deliveries` is one row per automation and member (unique, so nobody gets one twice; a channel message is the one row with no member), each sent by the server in small batches and written once however often it is retried. RLS on both new tables and nothing granted to members: only the server reads and writes them. No rows change. Safe to run again. */
ALTER TABLE public.community_chat_settings ADD COLUMN IF NOT EXISTS dm_min_level integer NOT NULL DEFAULT 2, ADD COLUMN IF NOT EXISTS dm_min_days integer NOT NULL DEFAULT 7, ADD COLUMN IF NOT EXISTS dm_to_staff boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS chat_tab boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS main_space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL;
ALTER TABLE public.community_chat_settings DROP CONSTRAINT IF EXISTS community_chat_settings_dm_policy, ADD CONSTRAINT community_chat_settings_dm_policy CHECK (dm_policy IN ('everyone', 'level', 'days', 'staff', 'off'));
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_chat_settings_dm_min_level') THEN ALTER TABLE public.community_chat_settings ADD CONSTRAINT community_chat_settings_dm_min_level CHECK (dm_min_level BETWEEN 1 AND 100); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_chat_settings_dm_min_days') THEN ALTER TABLE public.community_chat_settings ADD CONSTRAINT community_chat_settings_dm_min_days CHECK (dm_min_days BETWEEN 1 AND 365); END IF; END $do$;
ALTER TABLE public.community_spaces ADD COLUMN IF NOT EXISTS post_min_level integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS pinned_message_id uuid REFERENCES public.community_messages(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS pinned_at timestamptz, ADD COLUMN IF NOT EXISTS pinned_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_spaces_post_min_level_range') THEN ALTER TABLE public.community_spaces ADD CONSTRAINT community_spaces_post_min_level_range CHECK (post_min_level BETWEEN 0 AND 100) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_automations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, trigger text NOT NULL, trigger_level integer, trigger_days integer, segment jsonb NOT NULL DEFAULT '{}'::jsonb, target text NOT NULL DEFAULT 'dm', space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, sender_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL, status text NOT NULL DEFAULT 'active', send_at timestamptz, cursor_at timestamptz, cursor_user uuid, fanned_out_at timestamptz, sent_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, last_sent_at timestamptz, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_automations_trigger CHECK (trigger IN ('join', 'level', 'days', 'paid_start', 'paid_cancel', 'broadcast')), CONSTRAINT community_chat_automations_target CHECK (target IN ('dm', 'channel')), CONSTRAINT community_chat_automations_status CHECK (status IN ('active', 'paused', 'scheduled', 'sending', 'done')), CONSTRAINT community_chat_automations_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT community_chat_automations_body_len CHECK (char_length(body) BETWEEN 1 AND 4000), CONSTRAINT community_chat_automations_level CHECK (trigger_level IS NULL OR trigger_level BETWEEN 2 AND 100), CONSTRAINT community_chat_automations_days CHECK (trigger_days IS NULL OR trigger_days BETWEEN 1 AND 365), CONSTRAINT community_chat_automations_segment_object CHECK (jsonb_typeof(segment) = 'object'), CONSTRAINT community_chat_automations_counts CHECK (sent_count >= 0 AND failed_count >= 0));
CREATE INDEX IF NOT EXISTS community_chat_automations_community_idx ON public.community_chat_automations (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_chat_automations_due_idx ON public.community_chat_automations (trigger, status, send_at);
CREATE TABLE IF NOT EXISTS public.community_chat_automation_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), automation_id uuid NOT NULL REFERENCES public.community_chat_automations(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, due_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, sent_at timestamptz, message_id uuid, error text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_automation_deliveries_status CHECK (status IN ('pending', 'sending', 'sent', 'failed', 'skipped')), CONSTRAINT community_chat_automation_deliveries_attempts CHECK (attempts >= 0), CONSTRAINT community_chat_automation_deliveries_error_len CHECK (error IS NULL OR char_length(error) <= 300), CONSTRAINT community_chat_automation_deliveries_once UNIQUE (automation_id, user_id));
CREATE UNIQUE INDEX IF NOT EXISTS community_chat_automation_deliveries_channel_once ON public.community_chat_automation_deliveries (automation_id) WHERE user_id IS NULL;
CREATE INDEX IF NOT EXISTS community_chat_automation_deliveries_waiting_idx ON public.community_chat_automation_deliveries (status, due_at) WHERE status IN ('pending', 'sending');
CREATE INDEX IF NOT EXISTS community_chat_automation_deliveries_automation_idx ON public.community_chat_automation_deliveries (automation_id, status);
ALTER TABLE public.community_chat_automations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_automation_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_chat_automations, public.community_chat_automation_deliveries FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_chat_automations, public.community_chat_automation_deliveries TO service_role;
