-- part 274_community_analytics_accuracy.sql
/* Community analytics, counted more exactly (round 38), run after part 271. `community_analytics` is replaced with the same arguments and the same answer, with three changes. The community's owner is no longer one of the members who took part (posted, commented or reacted), one of the active members, or one of the top contributors: those figures are about the members, as visitors already were. A new `left_of_start` counts, for each bucket of the chart and for the whole period, the members who left and had been members when it began (no join of theirs earlier in it), each person once, so churn is the share of the members at the start who left, never inflated by someone who joined and left inside the period. Nothing else changes, and no rows change. Until it runs, Analytics counts as part 271 does. Safe to run again. */
CREATE OR REPLACE FUNCTION public.community_analytics(p_community uuid, p_from timestamptz, p_to timestamptz, p_tz text DEFAULT 'UTC', p_grain text DEFAULT 'day', p_detail boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_grain text := 'day'; v_fmt text; v_owner uuid; v_out jsonb; v_detail jsonb := '{}'::jsonb; v_end_month date; v_first_hour timestamptz; v_cut timestamptz; v_cut_day date; BEGIN IF p_community IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '800 days' THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; IF p_grain IN ('hour', 'day', 'month') THEN v_grain := p_grain; END IF; v_fmt := CASE v_grain WHEN 'hour' THEN 'YYYY-MM-DD"T"HH24' WHEN 'day' THEN 'YYYY-MM-DD' ELSE 'YYYY-MM' END; SELECT owner_user_id INTO v_owner FROM public.communities WHERE id = p_community; SELECT min(hour) INTO v_first_hour FROM public.community_member_hours WHERE community_id = p_community; IF v_first_hour IS NOT NULL THEN v_cut_day := (v_first_hour AT TIME ZONE 'UTC')::date + 1; v_cut := v_cut_day::timestamp AT TIME ZONE 'UTC'; END IF; WITH act AS (SELECT kind, user_id, created_at, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_activity WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND kind IN ('joined', 'left', 'lesson_completed', 'course_completed')), joins AS (SELECT a.b FROM act a LEFT JOIN public.community_members m ON m.community_id = p_community AND m.user_id = a.user_id WHERE a.kind = 'joined' AND a.user_id IS DISTINCT FROM v_owner AND coalesce(m.source, 'free') NOT IN ('manual', 'platform', 'product', 'owner')), posts AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_posts WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), comments AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_comments WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), reactions AS (SELECT user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_reactions WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), took AS (SELECT user_id, b, 'post' AS k FROM posts WHERE user_id IS NOT NULL AND user_id IS DISTINCT FROM v_owner UNION ALL SELECT user_id, b, 'comment' FROM comments WHERE user_id IS NOT NULL AND user_id IS DISTINCT FROM v_owner UNION ALL SELECT user_id, b, 'reaction' FROM reactions WHERE user_id IS NOT NULL AND user_id IS DISTINCT FROM v_owner), rsvps AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_event_rsvps WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), hours AS (SELECT user_id, to_char(hour AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_member_hours WHERE community_id = p_community AND user_id IS DISTINCT FROM v_owner AND v_cut IS NOT NULL AND hour >= greatest(p_from, v_cut) AND hour < p_to), days AS (SELECT user_id, CASE v_grain WHEN 'month' THEN to_char(day, 'YYYY-MM') ELSE to_char(day, 'YYYY-MM-DD') END AS b FROM public.community_member_days WHERE community_id = p_community AND user_id IS DISTINCT FROM v_owner AND day >= (p_from AT TIME ZONE v_tz)::date AND day <= ((p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date AND (v_cut_day IS NULL OR day < v_cut_day)), here AS (SELECT user_id, b FROM hours UNION ALL SELECT user_id, b FROM days WHERE v_grain <> 'hour') SELECT jsonb_build_object('joined', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'joined' AND user_id IS DISTINCT FROM v_owner GROUP BY b) x), 'joined_by_visit', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM joins GROUP BY b) x), 'left', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'left' GROUP BY b) x), 'left_of_start', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT l.b, count(DISTINCT l.user_id) AS n FROM act l WHERE l.kind = 'left' AND l.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM act j WHERE j.kind = 'joined' AND j.user_id = l.user_id AND j.b = l.b AND j.created_at < l.created_at) GROUP BY l.b) x), 'posts', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM posts GROUP BY b) x), 'comments', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM comments GROUP BY b) x), 'reactions', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM reactions GROUP BY b) x), 'rsvps', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM rsvps GROUP BY b) x), 'lessons', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'lesson_completed' GROUP BY b) x), 'contributors', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM took GROUP BY b) x), 'active', CASE WHEN v_grain = 'hour' AND (v_cut IS NULL OR v_cut > p_from) THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM here GROUP BY b) x) END, 'totals', jsonb_build_object('contributors', (SELECT count(DISTINCT user_id) FROM took), 'posters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'post'), 'commenters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'comment'), 'reactors', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'reaction'), 'active', (SELECT count(DISTINCT user_id) FROM (SELECT user_id FROM hours UNION SELECT user_id FROM days) u), 'courses', (SELECT count(*) FROM act WHERE kind = 'course_completed'), 'left_of_start', (SELECT count(DISTINCT l.user_id) FROM act l WHERE l.kind = 'left' AND l.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM act j WHERE j.kind = 'joined' AND j.user_id = l.user_id AND j.created_at < l.created_at))), 'active_since', (SELECT min(day) FROM public.community_member_days WHERE community_id = p_community), 'active_hours_since', v_cut) INTO v_out; IF p_detail THEN v_end_month := date_trunc('month', (p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date; v_detail := jsonb_build_object('top_contributors', (SELECT coalesce(jsonb_agg(x ORDER BY x.score DESC, x.user_id), '[]'::jsonb) FROM (SELECT u.user_id, sum(u.posts)::int AS posts, sum(u.comments)::int AS comments, sum(u.posts) * 2 + sum(u.comments) AS score FROM (SELECT author_id AS user_id, 1 AS posts, 0 AS comments FROM public.community_feed_posts WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND author_id IS DISTINCT FROM v_owner AND created_at >= p_from AND created_at < p_to UNION ALL SELECT author_id, 0, 1 FROM public.community_feed_comments WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND author_id IS DISTINCT FROM v_owner AND created_at >= p_from AND created_at < p_to) u GROUP BY u.user_id ORDER BY score DESC, u.user_id LIMIT 10) x), 'top_spaces', (SELECT coalesce(jsonb_agg(x ORDER BY (x.posts + x.comments) DESC, x.name), '[]'::jsonb) FROM (SELECT s.id, s.name, s.slug, (SELECT count(*) FROM public.community_feed_posts p WHERE p.space_id = s.id AND p.status = 'published' AND p.created_at >= p_from AND p.created_at < p_to)::int AS posts, (SELECT count(*) FROM public.community_feed_comments c JOIN public.community_feed_posts p ON p.id = c.post_id WHERE p.space_id = s.id AND c.status = 'published' AND c.created_at >= p_from AND c.created_at < p_to)::int AS comments FROM public.community_spaces s WHERE s.community_id = p_community AND s.archived_at IS NULL) x WHERE x.posts + x.comments > 0), 'cohorts', (SELECT coalesce(jsonb_agg(x ORDER BY x.month DESC), '[]'::jsonb) FROM (SELECT to_char(date_trunc('month', m.joined_at AT TIME ZONE v_tz), 'YYYY-MM') AS month, count(*)::int AS joined, count(*) FILTER (WHERE m.status = 'active')::int AS stayed, count(*) FILTER (WHERE m.status = 'active' AND greatest(m.last_seen_at, m.last_active_at) >= now() - interval '30 days')::int AS active FROM public.community_members m WHERE m.community_id = p_community AND m.role <> 'owner' AND m.joined_at IS NOT NULL AND m.joined_at AT TIME ZONE v_tz >= (v_end_month - interval '5 months') AND m.joined_at AT TIME ZONE v_tz < (v_end_month + interval '1 month') GROUP BY 1) x), 'programs', (SELECT coalesce(jsonb_agg(x ORDER BY x.started DESC, x.title), '[]'::jsonb) FROM (SELECT cc.id, coalesce(nullif(cc.title, ''), pr.title, 'Program') AS title, count(e.id)::int AS started, count(e.completed_at)::int AS completed, coalesce(round(avg(e.percent))::int, 0) AS percent, (SELECT count(*) FROM public.community_activity a WHERE a.community_id = p_community AND a.kind = 'lesson_completed' AND a.created_at >= p_from AND a.created_at < p_to AND a.target_id IN (cc.id::text, cc.product_id::text))::int AS lessons FROM public.community_courses cc LEFT JOIN public.products pr ON pr.id = cc.product_id LEFT JOIN public.courses co ON co.id = coalesce(cc.course_id, (SELECT c2.id FROM public.courses c2 WHERE c2.product_id = cc.product_id ORDER BY c2.created_at LIMIT 1)) LEFT JOIN public.course_enrollments e ON e.course_id = co.id AND EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = e.buyer_id AND m.status = 'active') WHERE cc.community_id = p_community AND coalesce(cc.status, 'published') = 'published' GROUP BY cc.id, cc.title, pr.title, cc.product_id LIMIT 20) x)); END IF; RETURN v_out || v_detail; END $f$;
REVOKE ALL ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('274', '274_community_analytics_accuracy.sql', 'b0336007e05064ae31fa787d6707cf0ab60e758e857d7ab83315c8b6809c79f9') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 275_community_chat_states.sql
/* Community chat, round 39 (run after part 270): a message's delivered state and who is online. `community_conversations` gets `a_delivered_at` and `b_delivered_at`, and `community_chat_group_members` gets `delivered_at`: when each person's own Storelib last had everything sent to them, which turns the sender's one tick into two. `public.community_mark_delivered(community, user)` writes those marks in one call, only where something newer from somebody else is waiting, so the realtime update it causes reaches the sender once; the server calls it after a member's list of conversations is read (server only, never the browser). `public.community_online_topic_ok(topic, write)` decides who may use a member's presence topic `online:<community>:<user>` on realtime: an active member of a live community with chat on may watch another active member's topic, and only that member may say they are here on it; added to realtime.messages for presence when this role may. Nothing is stored for presence. No rows change; until it runs messages show sent and seen as before, and a person's last heartbeat stands in for online. Safe to run again. */
ALTER TABLE public.community_conversations ADD COLUMN IF NOT EXISTS a_delivered_at timestamptz, ADD COLUMN IF NOT EXISTS b_delivered_at timestamptz;
ALTER TABLE public.community_chat_group_members ADD COLUMN IF NOT EXISTS delivered_at timestamptz;
CREATE OR REPLACE FUNCTION public.community_mark_delivered(p_community uuid, p_user uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_total integer := 0; v_n integer := 0; BEGIN IF p_community IS NULL OR p_user IS NULL THEN RETURN 0; END IF; UPDATE public.community_conversations SET a_delivered_at = now() WHERE community_id = p_community AND user_a = p_user AND last_message_at IS NOT NULL AND last_author_id IS DISTINCT FROM p_user AND (a_delivered_at IS NULL OR a_delivered_at < last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; v_total := v_total + v_n; UPDATE public.community_conversations SET b_delivered_at = now() WHERE community_id = p_community AND user_b = p_user AND last_message_at IS NOT NULL AND last_author_id IS DISTINCT FROM p_user AND (b_delivered_at IS NULL OR b_delivered_at < last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; v_total := v_total + v_n; UPDATE public.community_chat_group_members gm SET delivered_at = now() FROM public.community_chat_groups g WHERE g.id = gm.group_id AND gm.community_id = p_community AND gm.user_id = p_user AND g.archived_at IS NULL AND g.last_message_at IS NOT NULL AND g.last_author_id IS DISTINCT FROM p_user AND (gm.delivered_at IS NULL OR gm.delivered_at < g.last_message_at); GET DIAGNOSTICS v_n = ROW_COUNT; RETURN v_total + v_n; END $f$;
CREATE OR REPLACE FUNCTION public.community_online_topic_ok(p_topic text, p_write boolean) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_community uuid; v_user uuid; BEGIN IF auth.uid() IS NULL OR p_topic IS NULL OR p_topic !~ '^online:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF; v_community := substr(p_topic, 8, 36)::uuid; v_user := substr(p_topic, 45, 36)::uuid; IF p_write AND v_user <> auth.uid() THEN RETURN false; END IF; RETURN EXISTS (SELECT 1 FROM public.communities k WHERE k.id = v_community AND k.deleted_at IS NULL AND k.suspended_at IS NULL AND k.chat_enabled) AND public.community_role_of(v_community, auth.uid()) IS NOT NULL AND public.community_role_of(v_community, v_user) IS NOT NULL; END $f$;
REVOKE ALL ON FUNCTION public.community_mark_delivered(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_mark_delivered(uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.community_online_topic_ok(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.community_online_topic_ok(text, boolean) TO authenticated, service_role;
DO $do$ BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL THEN RAISE NOTICE 'community chat: realtime.messages is not here, online shows the last heartbeat instead.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib member online read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib member online read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''presence'' AND public.community_online_topic_ok(realtime.topic(), false))'; EXECUTE 'DROP POLICY IF EXISTS "storelib member online write" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib member online write" ON realtime.messages FOR INSERT TO authenticated WITH CHECK (realtime.messages.extension = ''presence'' AND public.community_online_topic_ok(realtime.topic(), true))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'community chat: this role may not add policies to realtime.messages, online shows the last heartbeat instead.'; END; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('275', '275_community_chat_states.sql', '417da8f4d5264b3ad485fa3618771a8247e4955c241be4dbda36152664c97b8a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 278_community_library.sql
/* Community Library (round 39), run after part 81 (communities) and part 270. A community's admin turns on a Library (`community_library_settings`, one row per community, off until turned on) and fills it with items (`community_library_items`): one of the creator's own Storelib products attached (product_id, kind product), or files and links uploaded straight into it (kind resource, the files in the community's own folder of Storelib storage, the record their ids). Each item has a title, a description from the product editor's rich text, a cover, a section (`community_library_sections`), its place in the order, draft or published, and who opens it: free for members, members of some tiers, from a points level, bought (a price), or picked members. An uploaded item that is sold becomes a product made for the community (made_product, products.community_id), so a purchase is an ordinary Storelib order with its receipt, payout, refund and place in the buyer's library. `community_library_purchases` keeps which order bought which item (one row per payment, unique), and a full refund marks it. `community_library_activity` counts views (a member once a day) and downloads, through `community_library_touch`, which also keeps the item's two counters. RLS on every new table and nothing granted to members or visitors: only the server reads and writes them, after its own access checks. No existing row changes. Until it runs the Library stays off and says it needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_library_settings (community_id uuid PRIMARY KEY REFERENCES public.communities(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.community_library_sections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_library_sections_name_len CHECK (char_length(name) BETWEEN 1 AND 40));
CREATE INDEX IF NOT EXISTS community_library_sections_community_idx ON public.community_library_sections (community_id, position);
CREATE TABLE IF NOT EXISTS public.community_library_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, section_id uuid REFERENCES public.community_library_sections(id) ON DELETE SET NULL, kind text NOT NULL DEFAULT 'resource', product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, made_product boolean NOT NULL DEFAULT false, title text NOT NULL, summary text, description text, cover_url text, files jsonb NOT NULL DEFAULT '[]'::jsonb, links jsonb NOT NULL DEFAULT '[]'::jsonb, access_mode text NOT NULL DEFAULT 'free', tier_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], min_level integer, price_cents integer, currency text, member_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], status text NOT NULL DEFAULT 'draft', position integer NOT NULL DEFAULT 0, view_count integer NOT NULL DEFAULT 0, download_count integer NOT NULL DEFAULT 0, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, CONSTRAINT community_library_items_kind CHECK (kind IN ('resource', 'product')), CONSTRAINT community_library_items_mode CHECK (access_mode IN ('free', 'tier', 'level', 'paid', 'private')), CONSTRAINT community_library_items_status CHECK (status IN ('draft', 'published')), CONSTRAINT community_library_items_title_len CHECK (char_length(title) BETWEEN 1 AND 120), CONSTRAINT community_library_items_summary_len CHECK (summary IS NULL OR char_length(summary) <= 2000), CONSTRAINT community_library_items_description_len CHECK (description IS NULL OR char_length(description) <= 60000), CONSTRAINT community_library_items_cover_len CHECK (cover_url IS NULL OR char_length(cover_url) <= 2000), CONSTRAINT community_library_items_files CHECK (jsonb_typeof(files) = 'array' AND jsonb_array_length(files) <= 20), CONSTRAINT community_library_items_links CHECK (jsonb_typeof(links) = 'array' AND jsonb_array_length(links) <= 10), CONSTRAINT community_library_items_tiers CHECK (cardinality(tier_ids) <= 50), CONSTRAINT community_library_items_members CHECK (cardinality(member_ids) <= 1000), CONSTRAINT community_library_items_level CHECK (min_level IS NULL OR min_level BETWEEN 2 AND 100), CONSTRAINT community_library_items_price CHECK (price_cents IS NULL OR price_cents BETWEEN 50 AND 99999999), CONSTRAINT community_library_items_currency CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'), CONSTRAINT community_library_items_counts CHECK (view_count >= 0 AND download_count >= 0));
CREATE INDEX IF NOT EXISTS community_library_items_community_idx ON public.community_library_items (community_id, position);
CREATE INDEX IF NOT EXISTS community_library_items_product_idx ON public.community_library_items (product_id) WHERE product_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.community_library_purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, item_id uuid REFERENCES public.community_library_items(id) ON DELETE SET NULL, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL, payment_intent_id text NOT NULL, checkout_session_id text, amount_cents integer NOT NULL DEFAULT 0, currency text, created_at timestamptz NOT NULL DEFAULT now(), refunded_at timestamptz, CONSTRAINT community_library_purchases_intent_once UNIQUE (payment_intent_id), CONSTRAINT community_library_purchases_amount CHECK (amount_cents >= 0), CONSTRAINT community_library_purchases_intent_len CHECK (char_length(payment_intent_id) BETWEEN 3 AND 255));
CREATE INDEX IF NOT EXISTS community_library_purchases_item_idx ON public.community_library_purchases (item_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_library_purchases_community_idx ON public.community_library_purchases (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_library_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.community_library_items(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL, day date NOT NULL DEFAULT current_date, hits integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_library_activity_kind CHECK (kind IN ('view', 'download')), CONSTRAINT community_library_activity_hits CHECK (hits >= 1), CONSTRAINT community_library_activity_once UNIQUE (item_id, user_id, kind, day));
CREATE INDEX IF NOT EXISTS community_library_activity_community_idx ON public.community_library_activity (community_id, day DESC);
CREATE OR REPLACE FUNCTION public.community_library_touch(p_item uuid, p_user uuid, p_kind text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $fn$ DECLARE v_community uuid; v_first boolean; BEGIN IF p_item IS NULL OR p_user IS NULL OR p_kind IS NULL OR p_kind NOT IN ('view', 'download') THEN RETURN; END IF; SELECT community_id INTO v_community FROM public.community_library_items WHERE id = p_item; IF v_community IS NULL THEN RETURN; END IF; INSERT INTO public.community_library_activity AS a (item_id, community_id, user_id, kind, day) VALUES (p_item, v_community, p_user, p_kind, current_date) ON CONFLICT (item_id, user_id, kind, day) DO UPDATE SET hits = a.hits + 1 RETURNING (xmax = 0) INTO v_first; IF p_kind = 'view' AND v_first THEN UPDATE public.community_library_items SET view_count = view_count + 1 WHERE id = p_item; ELSIF p_kind = 'download' THEN UPDATE public.community_library_items SET download_count = download_count + 1 WHERE id = p_item; END IF; END $fn$;
ALTER TABLE public.community_library_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_sections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_activity ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_library_settings, public.community_library_sections, public.community_library_items, public.community_library_purchases, public.community_library_activity FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_library_settings, public.community_library_sections, public.community_library_items, public.community_library_purchases, public.community_library_activity TO service_role;
REVOKE ALL ON FUNCTION public.community_library_touch(uuid, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_library_touch(uuid, uuid, text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('278', '278_community_library.sql', 'd926a3a6713c87983469a04c9f9ed7e6eebfe10a0205e4f63e168575c276f31e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 280_files_keep_what_is_used.sql
/* Files keeps what is still used (round 39). Deleting a file in Files that a product, a website page or anything else of the shop's still shows takes it out of Files and keeps the stored picture: file_details gets hidden_at, the time it left Files. And public.storage_object_referenced, which the daily storage cleanup and Files' delete ask, no longer counts a file_details row (a picture's alt text, or that hidden_at) as a use, so a picture nothing shows any more is still cleaned up. Needs part 214 (file_details) and part 18. No row changes. Until it runs, Files keeps a file in use in its list and says so. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.file_details') IS NOT NULL THEN ALTER TABLE public.file_details ADD COLUMN IF NOT EXISTS hidden_at timestamptz; CREATE INDEX IF NOT EXISTS file_details_hidden_idx ON public.file_details (creator_id) WHERE hidden_at IS NOT NULL; END IF; END $do$;
create or replace function public.storage_object_referenced(p_bucket text, p_name text) returns boolean language plpgsql stable security definer set search_path = public as $$ declare owner_key text := split_part(p_name, '/', 1); pattern text; v_creator uuid; v_user uuid; t record; q text; found boolean := false; skip text[] := array['rate_limit_hits', 'download_events', 'upload_events', 'product_views', 'product_analytics_daily', 'analytics_daily_rollups', 'security_events', 'email_events', 'email_logs', 'email_usage', 'ledger_events', 'seller_ledger', 'signup_attempts', 'site_web_vitals', 'blog_post_views', 'message_push_log', 'flow_execution_log', 'campaign_recipients', 'account_delete_codes', 'oauth_bridge_tokens', 'profile_username_history', 'username_history', 'website_address_history', 'admin_actions', 'admin_moderation_log', 'file_details']; begin if owner_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return true; end if; pattern := '%' || replace(replace(replace(p_name, '\', '\\'), '%', '\%'), '_', '\_') || '%'; select c.id, c.user_id into v_creator, v_user from public.creators c where c.id = owner_key::uuid or c.user_id = owner_key::uuid limit 1; if v_creator is null then v_user := owner_key::uuid; end if; if to_regclass('public.profiles') is not null then execute 'select exists (select 1 from public.profiles x where x.id = $1 and x::text like $2)' into found using v_user, pattern; if found then return true; end if; end if; for t in select c.table_name, c.column_name, (c.data_type = 'uuid') as is_uuid from information_schema.columns c join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name where c.table_schema = 'public' and tb.table_type = 'BASE TABLE' and c.column_name in ('creator_id', 'owner_id', 'user_id', 'product_id', 'install_id', 'site_id') and not (c.table_name = any(skip)) order by c.table_name, c.column_name loop q := case when t.column_name = 'creator_id' and v_creator is not null then format('select exists (select 1 from public.%I x where x.creator_id%s = $1%s and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name in ('owner_id', 'user_id') and v_user is not null then format('select exists (select 1 from public.%I x where x.%I%s = $2%s and x::text like $3)', t.table_name, t.column_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'product_id' and v_creator is not null and to_regclass('public.products') is not null then format('select exists (select 1 from public.%I x join public.products p on p.id%s = x.product_id%s where p.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'install_id' and v_creator is not null and to_regclass('public.store_theme_installs') is not null then format('select exists (select 1 from public.%I x join public.store_theme_installs i on i.id%s = x.install_id%s where i.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'site_id' and v_creator is not null and to_regclass('public.sites') is not null then format('select exists (select 1 from public.%I x join public.sites s on s.id%s = x.site_id%s where s.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) else null end; continue when q is null; begin execute q into found using v_creator, v_user, pattern; exception when others then found := true; end; if found then return true; end if; end loop; return false; end; $$;
revoke all on function public.storage_object_referenced(text, text) from public, anon, authenticated;
grant execute on function public.storage_object_referenced(text, text) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('280', '280_files_keep_what_is_used.sql', '55ea5be7ab95f2d3409e42473b4794eb10963f327dbcb8bb30a9f0c87ad4d8ff') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 281_onepage_leads_country.sql
/* OnePage signups keep the visitor's country. /api/onepage/leads has written country_code and country_name on public.onepage_leads since January (the country on OnePage analytics), but no SQL file in this repository creates them: the table was made by hand. This adds them only where they are missing, so a database without them stops depending on the route's fallback (it saves the signup without the country). No row changes. Does nothing if public.onepage_leads does not exist. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NOT NULL THEN ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS country_code text; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS country_name text; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('281', '281_onepage_leads_country.sql', 'e5c1eabe25ba626ea777af9239f94d41f5287ea6f755f8f2115b57acb51b320e') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 282_onepage_media_uploads.sql
/* OnePage pictures and videos upload (round 11): the onepage-assets bucket (profile photo and video, logo, wallpaper picture and video, link thumbnails, image blocks) takes a video up to 2 GB (at least 2147483648 bytes, so a file a phone calls "2 GB" fits; a higher limit already set is kept) and every type the editor sends: JPEG, PNG, WebP, GIF, AVIF, MP4, MOV (video/quicktime), WebM and M4V (video/x-m4v). Types it already allowed stay allowed; a bucket that allows every type (no list) is left that way. The editor now sends large files by TUS resumable upload with the signed in person's own session, which needs the same four owner-folder policies part 90 makes ("storelib owner ... public buckets"); this creates any of the four that is missing, exactly as part 90 writes them, and if the SQL editor's role may not create storage policies it says so in a NOTICE and changes nothing there (part 90 or README Route 1 does it then). NOT SQL: the project's own upload limit caps every bucket and is 50 MB until raised: Supabase dashboard > Storage > Settings > "Upload file size limit", set it to 2 GB (Pro plan or above). Safe to run again. */
DO $do$ DECLARE needed text[] := array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif', 'video/mp4', 'video/quicktime', 'video/webm', 'video/x-m4v']; BEGIN IF to_regclass('storage.buckets') IS NULL THEN RAISE NOTICE 'part 282: there is no storage.buckets here, nothing to set.'; RETURN; END IF; INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('onepage-assets', 'onepage-assets', true, 2147483648, needed) ON CONFLICT (id) DO NOTHING; UPDATE storage.buckets SET public = true, file_size_limit = greatest(coalesce(file_size_limit, 0), 2147483648), allowed_mime_types = CASE WHEN allowed_mime_types IS NULL THEN NULL ELSE array(SELECT DISTINCT t FROM unnest(allowed_mime_types || needed) AS t ORDER BY t) END WHERE id = 'onepage-assets' AND (public IS DISTINCT FROM true OR file_size_limit IS NULL OR file_size_limit < 2147483648 OR (allowed_mime_types IS NOT NULL AND NOT allowed_mime_types @> needed)); END $do$;
DO $do$ DECLARE public_list text := '''product-images'', ''avatars'', ''covers'', ''store-builder-images'', ''onepage-assets'', ''lead-form-files-v2'', ''lead-form-files'', ''product-videos'', ''email-images'''; owner_expr text; BEGIN IF to_regclass('storage.objects') IS NULL THEN RAISE NOTICE 'part 282: there is no storage.objects here, no policies to check.'; RETURN; END IF; IF to_regprocedure('public.storage_owns_path(text)') IS NULL THEN RAISE NOTICE 'part 282: public.storage_owns_path is missing; run part 15 first, then this again.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'storage' AND table_name = 'objects' AND column_name = 'owner_id') THEN owner_expr := 'owner_id = (select auth.uid())::text'; ELSE owner_expr := 'owner = (select auth.uid())'; END IF; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner read public buckets') THEN EXECUTE format('create policy %I on storage.objects for select to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner read public buckets', public_list, owner_expr); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner insert public buckets') THEN EXECUTE format('create policy %I on storage.objects for insert to authenticated with check (bucket_id = any (array[%s]) and public.storage_owns_path(name))', 'storelib owner insert public buckets', public_list); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner update public buckets') THEN EXECUTE format('create policy %I on storage.objects for update to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s)) with check (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner update public buckets', public_list, owner_expr, public_list, owner_expr); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner delete public buckets') THEN EXECUTE format('create policy %I on storage.objects for delete to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner delete public buckets', public_list, owner_expr); END IF; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'part 282: this role may not create storage policies (%). Uploads use the owner-folder policies part 90 makes: run part 90, or README Route 1.', SQLERRM; END; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('282', '282_onepage_media_uploads.sql', '0ae8e813310ea85e24029d446eb82cb5c7e36d3d9bbd922543e756b13347ef15') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 283_size_charts.sql
/* Size charts for physical products (round BC): a store keeps its size tables in size_charts (a name, the unit the numbers were typed in, cm or in, its columns as a list of {name, measure}, its rows as a list of lists of text, an optional note and picture), and product_size_charts says which chart a product shows, one row per product that has one (a chart serves many products; deleting a chart or a product takes its links with it). Read by the product page on a Storelib theme (the Size chart block and the Size guide link beside the size option) and on an imported Shopify theme (product.metafields.storelib.size_chart, an app block and a link beside the size), and written by Products > Size charts and the product editor's Size chart card through /api/size-charts. Row level security on both: visitors (anon) are granted nothing, a signed in owner reads their own, and only the server writes, after its owner checks; the storefront reads through the server. Before it runs the product editor says size charts need this part and every product page simply has no chart. Additive: nothing is dropped, renamed or changed. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.size_charts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL, unit text NOT NULL DEFAULT 'cm', columns jsonb NOT NULL DEFAULT '[]'::jsonb, rows jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, image_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT size_charts_name_len CHECK (char_length(btrim(name)) BETWEEN 1 AND 80), CONSTRAINT size_charts_unit CHECK (unit IN ('cm', 'in')), CONSTRAINT size_charts_columns_list CHECK (jsonb_typeof(columns) = 'array' AND jsonb_array_length(columns) BETWEEN 1 AND 10), CONSTRAINT size_charts_rows_list CHECK (jsonb_typeof(rows) = 'array' AND jsonb_array_length(rows) <= 40), CONSTRAINT size_charts_notes_len CHECK (notes IS NULL OR char_length(notes) <= 1500), CONSTRAINT size_charts_image_len CHECK (image_url IS NULL OR char_length(image_url) <= 2048), CONSTRAINT size_charts_size CHECK (pg_column_size(rows) < 65536));
CREATE INDEX IF NOT EXISTS size_charts_creator_idx ON public.size_charts (creator_id, name);
CREATE TABLE IF NOT EXISTS public.product_size_charts (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, size_chart_id uuid NOT NULL REFERENCES public.size_charts(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_size_charts_chart_idx ON public.product_size_charts (size_chart_id);
CREATE INDEX IF NOT EXISTS product_size_charts_creator_idx ON public.product_size_charts (creator_id);
DO $do$ BEGIN IF to_regprocedure('public.update_updated_at_column()') IS NULL THEN CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END $fn$; END IF; DROP TRIGGER IF EXISTS size_charts_touch ON public.size_charts; CREATE TRIGGER size_charts_touch BEFORE UPDATE ON public.size_charts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); END $do$;
ALTER TABLE public.size_charts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_size_charts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.size_charts, public.product_size_charts FROM PUBLIC, anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.size_charts, public.product_size_charts FROM authenticated;
GRANT SELECT ON public.size_charts, public.product_size_charts TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.size_charts, public.product_size_charts TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads size_charts" ON public.size_charts; CREATE POLICY "storelib owner reads size_charts" ON public.size_charts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = size_charts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads product_size_charts" ON public.product_size_charts; CREATE POLICY "storelib owner reads product_size_charts" ON public.product_size_charts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = product_size_charts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('283', '283_size_charts.sql', '5e662db000bddcebcdfefab26f7534b907fba7939cc7741361a8ee86449e13cf') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 284_direct_message_notifications.sql
/* Messages in the bell (round BC): user_notifications (part 85) takes one more kind, 'direct_message', so a message between members is one row in the recipient's bell per conversation, rewritten in place as more messages arrive and read when the conversation is opened (lib/notifications/dm-notify-shared.ts). Every kind it took before is kept. Before this has run the table's check refuses the kind and messages are told the way they were, by the push alone; nothing breaks. Needs part 85 (it says so and changes nothing without it). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.user_notifications') IS NULL THEN RAISE NOTICE 'part 284: there is no user_notifications here, run part 85 first.'; RETURN; END IF; ALTER TABLE public.user_notifications DROP CONSTRAINT IF EXISTS user_notifications_kind_check, ADD CONSTRAINT user_notifications_kind_check CHECK (kind IN ('new_follower', 'followed_new_product', 'followed_new_community', 'membership_post', 'purchased_creator_new_product', 'system', 'direct_message')); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('284', '284_direct_message_notifications.sql', '3a81084309c8ce51cd138d1a9d4caa479fffa196a6c60ff5df8faba638816a14') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 285_order_buyer_note.sql
/* The buyer's note on an order that ships nothing (round BC, SQL part 285): `orders.buyer_note`, what the buyer wrote for the shop at the website's checkout, or in an imported theme's cart ("Add order note", Shopify's cart note), kept on every line of a basket of downloads (lib/checkout/fulfil-cart-session.ts). A cart that ships already keeps it on its checkout (`commerce_checkouts.buyer_note`, part 78), so this is the same words for the rest: plain text, line breaks kept, at most 1000 characters (lib/checkout/site-checkout.ts orderNote). The order page shows it (app/app/orders/order-detail.tsx, read by app/api/app/orders/[id]/activity) and the seller's sale email lists it. Adds one column, empty on every order already there; changes no rows. Written by the server only. Until it runs the order is written as before, the note goes only into the seller's email, and the order page shows none. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'order buyer note: orders is not there yet.'; RETURN; END IF; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS buyer_note text; ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_buyer_note_length; ALTER TABLE public.orders ADD CONSTRAINT orders_buyer_note_length CHECK (buyer_note IS NULL OR length(buyer_note) <= 1000) NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('285', '285_order_buyer_note.sql', '5c287d3575044586882b1f91528f6a29668f1c87f2061dd5af4b273d5d217825') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 286_product_option_swatches.sql
/* A colour option's own swatches. A seller can set each value of a colour option (Products › Variants, the dot beside a value) to a colour of their own or to its variant's photo, instead of the colour its name says; every product page's swatches draw it, in a Storelib theme and in an imported Shopify theme (lib/products/option-swatches.ts). Kept on the option as `product_options.swatches`, a small object from a value to "#rrggbb" or "photo", empty for an option with none; the product editor writes only values the option has. Until this runs, options save and read without it and swatches come from the values' names and photos as before. No row changes. Does nothing if public.product_options does not exist (part 78). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.product_options') IS NOT NULL THEN ALTER TABLE public.product_options ADD COLUMN IF NOT EXISTS swatches jsonb NOT NULL DEFAULT '{}'::jsonb; ALTER TABLE public.product_options DROP CONSTRAINT IF EXISTS product_options_swatches_check; ALTER TABLE public.product_options ADD CONSTRAINT product_options_swatches_check CHECK (jsonb_typeof(swatches) = 'object' AND pg_column_size(swatches) <= 8192) NOT VALID; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('286', '286_product_option_swatches.sql', 'bd0e67207ac979b4d41f6ce1bc0742007fb7b36f757a7debb051aa5a43d62563') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 287_site_customer_addresses.sql
/* Customer accounts on websites, round BC: a customer keeps their own phone number and their own address book on the website they signed in to (add, change, delete, pick the default), and checkout fills in the default one. Two optional columns on site_customers: phone (at most 40 characters) and addresses (a JSON list of at most 10; NULL means never changed, so the account shows the addresses their orders went to). Server only, like the rest of the table. Run after 33. Until it runs, the account shows the addresses of past orders and saving one says it could not be saved. Source: supabase/migrations/20270215_site_customer_addresses.sql. */
ALTER TABLE public.site_customers ADD COLUMN IF NOT EXISTS phone text;
ALTER TABLE public.site_customers ADD COLUMN IF NOT EXISTS addresses jsonb;
ALTER TABLE public.site_customers DROP CONSTRAINT IF EXISTS site_customers_phone_size;
ALTER TABLE public.site_customers ADD CONSTRAINT site_customers_phone_size CHECK (char_length(coalesce(phone, '')) <= 40);
ALTER TABLE public.site_customers DROP CONSTRAINT IF EXISTS site_customers_addresses_shape;
ALTER TABLE public.site_customers ADD CONSTRAINT site_customers_addresses_shape CHECK (addresses IS NULL OR (jsonb_typeof(addresses) = 'array' AND jsonb_array_length(addresses) <= 10 AND pg_column_size(addresses) <= 32768));
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('287', '287_site_customer_addresses.sql', '183a5bb6156220865f0374940aba7950be3e3d56c1e9dceb014a1d565229df56') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 300_order_followups.sql
/* Order follow-ups (round AE): what happens after a paid checkout writes its order (the customer, the seller's ledger, the emails, the library entry, the sales count) is recorded step by step in order_followups, one row per order and step, so a webhook retry or the ten minute sweep (app/api/cron/physical) finishes the steps a crash left undone and never repeats one that was done. New table only: no existing row or column is changed. Row level security on; the server writes with the service key; a creator may read the rows of their own orders. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.order_followups (order_id uuid NOT NULL, step text NOT NULL, state text NOT NULL DEFAULT 'claimed' CHECK (state IN ('claimed', 'done', 'failed')), kind text, ref text, attempts integer NOT NULL DEFAULT 1, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (order_id, step));
CREATE INDEX IF NOT EXISTS order_followups_open_idx ON public.order_followups (created_at) WHERE step = 'begun';
ALTER TABLE public.order_followups ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'order_followups' AND policyname = 'creator reads own order followups') THEN CREATE POLICY "creator reads own order followups" ON public.order_followups FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.orders o JOIN public.products p ON p.id = o.product_id JOIN public.creators c ON c.id = p.creator_id WHERE o.id = order_followups.order_id AND c.user_id = (select auth.uid()))); END IF; END $do$;
REVOKE ALL ON public.order_followups FROM anon;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('300', '300_order_followups.sql', '71ed8663c0da3363fd4db66f10d61537713ca2d7ec06637e6e3ccaa58f15fa84') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 301_community_email_words.sql
/* A community's own words on every email it sends (run after part 217): community_email_templates takes the four ticket emails (event_ticket, event_ticket_invite, event_refund, event_cancelled) and the seven emails of a paid plan (membership_started, membership_renewed, membership_renewal_reminder, membership_payment_failed, membership_canceled, membership_plan_changed, membership_ended) beside the welcome, an approved request and an invite, and a button label of up to 40 characters (a new nullable column). The kinds saved before stay allowed, so no row is refused. No row changes. The table stays server only, row level security on, nothing granted to anon or signed in users. Until it runs, Emails › Customer emails › Communities saves the welcome, an approved request and an invite without a button, and says this part is needed for the others. Safe to run again. */
DO $do$ DECLARE c record; BEGIN IF to_regclass('public.community_email_templates') IS NULL THEN RAISE NOTICE 'part 301: community_email_templates is not here yet; run part 217 first, then this again.'; RETURN; END IF; FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.community_email_templates'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%kind%' LOOP EXECUTE format('ALTER TABLE public.community_email_templates DROP CONSTRAINT %I', c.conname); END LOOP; ALTER TABLE public.community_email_templates ADD CONSTRAINT community_email_templates_kind_check CHECK (kind IN ('welcome', 'join_approved', 'invite', 'announcement', 'event_reminder', 'course_available', 'event_ticket', 'event_ticket_invite', 'event_refund', 'event_cancelled', 'membership_started', 'membership_renewed', 'membership_renewal_reminder', 'membership_payment_failed', 'membership_canceled', 'membership_plan_changed', 'membership_ended')); ALTER TABLE public.community_email_templates ADD COLUMN IF NOT EXISTS button text; ALTER TABLE public.community_email_templates DROP CONSTRAINT IF EXISTS community_email_templates_button_check; ALTER TABLE public.community_email_templates ADD CONSTRAINT community_email_templates_button_check CHECK (button IS NULL OR char_length(button) <= 40); ALTER TABLE public.community_email_templates ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_email_templates FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_email_templates TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('301', '301_community_email_words.sql', '3c6c53ab690c870b21690cc25d73e1b780ee781c9c47f2a1d3caf54c0e7c9bb1') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 304_store_offers_quantity_breaks.sql
/* Quantity breaks and Buy X get Y free (round AF, run after 116 and 230): `store_offers` takes a third kind, `quantity_break`, for one product (one id in `product_ids`) or every product of one collection (no product, the collection in `trigger_collection_ids`), with its tiers in a new `tiers` column (jsonb, a list of up to six { quantity, freeQuantity, discountType percent, amount or none, discountValue, label, badge }; `[]` for every other offer). The kind check and the shape check are replaced with ones that keep every row they took before. No existing row changes. Owner reads, only the server writes, as part 116 set. Safe to run again. */
ALTER TABLE public.store_offers ADD COLUMN IF NOT EXISTS tiers jsonb NOT NULL DEFAULT '[]'::jsonb;
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.store_offers'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%kind%' AND pg_get_constraintdef(oid) LIKE '%''checkout''%' AND pg_get_constraintdef(oid) NOT LIKE '%quantity_break%' AND pg_get_constraintdef(oid) NOT LIKE '%cardinality%' LOOP EXECUTE format('ALTER TABLE public.store_offers DROP CONSTRAINT %I', c.conname); END LOOP; END $$;
ALTER TABLE public.store_offers DROP CONSTRAINT IF EXISTS store_offers_kind_check;
ALTER TABLE public.store_offers ADD CONSTRAINT store_offers_kind_check CHECK (kind IN ('bundle', 'checkout', 'quantity_break'));
ALTER TABLE public.store_offers DROP CONSTRAINT IF EXISTS store_offers_shape;
ALTER TABLE public.store_offers ADD CONSTRAINT store_offers_shape CHECK ((kind = 'bundle' AND cardinality(product_ids) BETWEEN 2 AND 5) OR (kind = 'checkout' AND cardinality(product_ids) = 1) OR (kind = 'quantity_break' AND cardinality(product_ids) <= 1));
ALTER TABLE public.store_offers DROP CONSTRAINT IF EXISTS store_offers_tiers;
ALTER TABLE public.store_offers ADD CONSTRAINT store_offers_tiers CHECK (jsonb_typeof(tiers) = 'array' AND jsonb_array_length(tiers) <= 6 AND (kind <> 'quantity_break' OR jsonb_array_length(tiers) >= 1));
ALTER TABLE public.store_offers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS store_offers_owner_read ON public.store_offers;
CREATE POLICY store_offers_owner_read ON public.store_offers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = store_offers.creator_id AND c.user_id = auth.uid()));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.store_offers FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('304', '304_store_offers_quantity_breaks.sql', 'bd8f9d79f6d0c948e6b93a90b61b2ed27efbcd46231abe0fd441663750925d16') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 305_translation_providers.sql
/* Translation that keeps working on free allowances (round 13): translation_provider_state keeps, per translator (Gemini, Cloudflare Workers AI and the others), the models it read from the provider's own list today, which models are resting and until when (asked too fast, today's free allowance used, retired), and its last success and last failure, so every run and every server instance skips a model another found out of allowance instead of asking it again; translation_provider_usage counts calls, texts, characters and tokens per day, translator and model, for /admin/translations, through translation_usage_add; translation_refusals keeps, by language pair and the sha256 of a text, a text whose every machine translation failed the checks (a price changed, words added, a placeholder lost), so it waits an hour, then longer each time, instead of being sent again every few minutes. translation_memory may now also keep what Cloudflare Workers AI translated. New tables and one function; no existing row changes. Server only: row level security on, nothing granted to anon or signed in users. Until it runs, translating works as before, each server instance keeping its own rests, and /admin/translations says this part is needed. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.translation_provider_state (provider text PRIMARY KEY CHECK (length(provider) BETWEEN 2 AND 40), models jsonb, models_hash text, listed_at timestamptz, rests jsonb NOT NULL DEFAULT '{}'::jsonb, last_ok_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 600), last_error_kind text, last_error_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.translation_provider_usage (day date NOT NULL, provider text NOT NULL CHECK (length(provider) BETWEEN 2 AND 40), model text NOT NULL CHECK (length(model) BETWEEN 1 AND 120), calls integer NOT NULL DEFAULT 0, ok integer NOT NULL DEFAULT 0, failed integer NOT NULL DEFAULT 0, limited integer NOT NULL DEFAULT 0, strings integer NOT NULL DEFAULT 0, chars bigint NOT NULL DEFAULT 0, input_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (day, provider, model));
CREATE INDEX IF NOT EXISTS translation_provider_usage_day_idx ON public.translation_provider_usage (day DESC);
CREATE TABLE IF NOT EXISTS public.translation_refusals (source_lang text NOT NULL CHECK (length(source_lang) BETWEEN 2 AND 12), target_lang text NOT NULL CHECK (length(target_lang) BETWEEN 2 AND 12), source_hash text NOT NULL CHECK (source_hash ~ '^[0-9a-f]{64}$'), tries integer NOT NULL DEFAULT 1, retry_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (source_lang, target_lang, source_hash));
ALTER TABLE public.translation_provider_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.translation_provider_usage ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.translation_refusals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.translation_provider_state FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.translation_provider_usage FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.translation_refusals FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_provider_state TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_provider_usage TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.translation_refusals TO service_role;
CREATE OR REPLACE FUNCTION public.translation_usage_add(p_day date, p_provider text, p_model text, p_calls integer DEFAULT 0, p_ok integer DEFAULT 0, p_failed integer DEFAULT 0, p_limited integer DEFAULT 0, p_strings integer DEFAULT 0, p_chars bigint DEFAULT 0, p_input_tokens bigint DEFAULT 0, p_output_tokens bigint DEFAULT 0) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $f$ INSERT INTO public.translation_provider_usage AS u (day, provider, model, calls, ok, failed, limited, strings, chars, input_tokens, output_tokens, updated_at) VALUES (p_day, left(p_provider, 40), left(coalesce(nullif(p_model, ''), '-'), 120), greatest(p_calls, 0), greatest(p_ok, 0), greatest(p_failed, 0), greatest(p_limited, 0), greatest(p_strings, 0), greatest(p_chars, 0), greatest(p_input_tokens, 0), greatest(p_output_tokens, 0), now()) ON CONFLICT (day, provider, model) DO UPDATE SET calls = u.calls + excluded.calls, ok = u.ok + excluded.ok, failed = u.failed + excluded.failed, limited = u.limited + excluded.limited, strings = u.strings + excluded.strings, chars = u.chars + excluded.chars, input_tokens = u.input_tokens + excluded.input_tokens, output_tokens = u.output_tokens + excluded.output_tokens, updated_at = now(); $f$;
REVOKE ALL ON FUNCTION public.translation_usage_add(date, text, text, integer, integer, integer, integer, integer, bigint, bigint, bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.translation_usage_add(date, text, text, integer, integer, integer, integer, integer, bigint, bigint, bigint) TO service_role;
DO $do$ BEGIN IF to_regclass('public.translation_memory') IS NOT NULL THEN ALTER TABLE public.translation_memory DROP CONSTRAINT IF EXISTS translation_memory_provider_check; ALTER TABLE public.translation_memory ADD CONSTRAINT translation_memory_provider_check CHECK (provider IN ('gemini', 'cloudflare', 'deepl', 'libretranslate', 'huggingface', 'llm', 'mymemory', 'openai')); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('305', '305_translation_providers.sql', 'e8d071fe57690c58f4de5ca4f51a53a5ffd9eaac02ff2ba75075fe50597b2369') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 306_store_currency_quantity_breaks.sql
/* A store's currency change converts its quantity breaks too (round AG, run after 258 and 304). A quantity break's tier with an amount off (store_offers.tiers, discountValue when discountType is amount) is in the store's currency, like a bundle's fixed amount and a checkout offer's minimum, which part 258 already converts: a change now converts each such tier at the same rate and rounding as the prices (round(amount * rate)), keeps the tiers in the change's snapshot, and Undo puts them back exactly as they were (part 258's restore already restores a snapshot's tiers). Percent and free unit tiers do not move. Two functions are replaced and keep everything else they did. Orders, refunds and payouts are still never touched. Needs parts 176, 258 and 304. Safe to run again. */
CREATE OR REPLACE FUNCTION public.store_currency_targets() RETURNS TABLE (table_name text, key_column text, store_filter text, money_columns text[]) LANGUAGE sql IMMUTABLE AS $fn$ VALUES ('products', 'id', 'creator_id = $1 AND coalesce(type, '''') NOT IN (''membership'', ''community'')', ARRAY['price_cents', 'compare_at_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents']), ('product_variants', 'id', 'product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = $1 AND coalesce(p.type, '''') NOT IN (''membership'', ''community''))', ARRAY['price_cents', 'compare_at_price_cents', 'additional_price_cents']), ('product_variant_costs', 'variant_id', 'creator_id = $1', ARRAY['cost_cents']), ('shipping_rates', 'id', 'creator_id = $1', ARRAY['price_cents', 'free_over_cents']), ('inventory_locations', 'id', 'creator_id = $1', ARRAY['local_delivery_price_cents', 'local_delivery_min_cents', 'local_delivery_free_over_cents']), ('coupons', 'id', 'creator_id = $1', ARRAY['min_purchase_cents']), ('store_offers', 'id', 'creator_id = $1', ARRAY['min_subtotal_cents', 'tiers']), ('product_collections', 'id', 'creator_id = $1 AND kind = ''smart'' AND EXISTS (SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>''field'' IN (''price'', ''compare_at_price''))', ARRAY[]::text[]) $fn$;
CREATE OR REPLACE FUNCTION public.store_change_currency(p_creator uuid, p_from text, p_to text, p_mode text, p_rate numeric, p_rate_as_of date, p_key text, p_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $fn$ DECLARE v_prev public.store_currency_changes%ROWTYPE; v_stored text; v_change uuid := gen_random_uuid(); v_counts jsonb := '{}'::jsonb; v_target record; v_cols text[]; v_set text; v_snap text; v_n integer; BEGIN IF p_creator IS NULL THEN RAISE EXCEPTION 'store_currency: no store' USING ERRCODE = '22023'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from !~ '^[A-Z]{3}$' OR p_to !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'store_currency: a currency is not a code' USING ERRCODE = '22023'; END IF; IF p_from = p_to THEN RAISE EXCEPTION 'store_currency: the store already sells in %', p_to USING ERRCODE = '22023'; END IF; IF p_mode IS NULL OR p_mode NOT IN ('keep', 'convert') THEN RAISE EXCEPTION 'store_currency: mode is keep or convert' USING ERRCODE = '22023'; END IF; IF p_mode = 'convert' AND (p_rate IS NULL OR p_rate <= 0 OR p_rate > 1000000) THEN RAISE EXCEPTION 'store_currency: converting needs a rate' USING ERRCODE = '22023'; END IF; IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 120 THEN RAISE EXCEPTION 'store_currency: a request key is needed' USING ERRCODE = '22023'; END IF; INSERT INTO public.store_settings (creator_id) VALUES (p_creator) ON CONFLICT (creator_id) DO NOTHING; SELECT currency INTO v_stored FROM public.store_settings WHERE creator_id = p_creator FOR UPDATE; SELECT * INTO v_prev FROM public.store_currency_changes WHERE creator_id = p_creator AND request_key = p_key; IF FOUND THEN RETURN jsonb_build_object('ok', true, 'repeat', true, 'id', v_prev.id, 'from', v_prev.from_currency, 'to', v_prev.to_currency, 'mode', v_prev.mode, 'rate', v_prev.rate, 'counts', v_prev.counts); END IF; IF coalesce(v_stored, p_from) <> p_from THEN RAISE EXCEPTION 'store_currency: the store now sells in %', v_stored USING ERRCODE = '40001'; END IF; INSERT INTO public.store_currency_changes (id, creator_id, from_currency, to_currency, previous_currency, mode, rate, rate_as_of, request_key, created_by) VALUES (v_change, p_creator, p_from, p_to, v_stored, p_mode, CASE WHEN p_mode = 'convert' THEN p_rate END, CASE WHEN p_mode = 'convert' THEN p_rate_as_of END, p_key, p_user); IF p_mode = 'convert' THEN FOR v_target IN SELECT * FROM public.store_currency_targets() LOOP IF to_regclass('public.' || v_target.table_name) IS NULL THEN CONTINUE; END IF; SELECT array_agg(c ORDER BY c) INTO v_cols FROM unnest(v_target.money_columns) AS c WHERE EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = v_target.table_name AND ic.column_name = c); IF v_target.table_name = 'shipping_rates' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['min_value', 'max_value', 'tiers', 'kind']; ELSIF v_target.table_name = 'coupons' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'store_offers' THEN v_cols := coalesce(v_cols, ARRAY[]::text[]) || ARRAY['discount_value', 'discount_type']; ELSIF v_target.table_name = 'product_collections' THEN v_cols := ARRAY['rules']; END IF; IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN CONTINUE; END IF; v_snap := format('INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT $2, %L, t.%I, jsonb_build_object(%s) FROM public.%I t WHERE %s', v_target.table_name, v_target.key_column, (SELECT string_agg(format('%L, t.%I', c, c), ', ') FROM unnest(v_cols) AS c), v_target.table_name, v_target.store_filter); EXECUTE v_snap USING p_creator, v_change; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_target.table_name = 'shipping_rates' THEN v_set := concat_ws(', ', CASE WHEN 'price_cents' = ANY (v_cols) THEN 'price_cents = round(price_cents * $2)::integer' END, CASE WHEN 'free_over_cents' = ANY (v_cols) THEN 'free_over_cents = CASE WHEN free_over_cents IS NULL THEN NULL ELSE round(free_over_cents * $2)::integer END' END, 'min_value = CASE WHEN kind = ''price'' AND min_value IS NOT NULL THEN round(min_value * $2)::integer ELSE min_value END', 'max_value = CASE WHEN kind = ''price'' AND max_value IS NOT NULL THEN round(max_value * $2)::integer ELSE max_value END', 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' THEN x || jsonb_strip_nulls(jsonb_build_object(''priceCents'', CASE WHEN x ? ''priceCents'' THEN round((x->>''priceCents'')::numeric * $2)::integer END, ''from'', CASE WHEN kind = ''price'' AND x ? ''from'' THEN round((x->>''from'')::numeric * $2)::integer END)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END'); ELSIF v_target.table_name = 'coupons' THEN v_set := concat_ws(', ', CASE WHEN 'min_purchase_cents' = ANY (v_cols) THEN 'min_purchase_cents = CASE WHEN min_purchase_cents IS NULL THEN NULL ELSE round(min_purchase_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(0.01, round(discount_value * $2, 2)) ELSE discount_value END'); ELSIF v_target.table_name = 'store_offers' THEN v_set := concat_ws(', ', CASE WHEN 'min_subtotal_cents' = ANY (v_cols) THEN 'min_subtotal_cents = CASE WHEN min_subtotal_cents IS NULL THEN NULL ELSE round(min_subtotal_cents * $2)::integer END' END, 'discount_value = CASE WHEN discount_type = ''fixed'' THEN greatest(1, round(discount_value * $2))::integer ELSE discount_value END', CASE WHEN 'tiers' = ANY (v_cols) THEN 'tiers = CASE WHEN jsonb_typeof(tiers) = ''array'' AND jsonb_array_length(tiers) > 0 THEN (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' AND x->>''discountType'' = ''amount'' AND (x->>''discountValue'') ~ ''^\s*[0-9]+(\.[0-9]+)?\s*$'' THEN jsonb_set(x, ''{discountValue}'', to_jsonb(least(10000000, round((x->>''discountValue'')::numeric * $2))::integer)) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(tiers) WITH ORDINALITY AS e(x, o)) ELSE tiers END' END); ELSIF v_target.table_name = 'product_collections' THEN v_set := 'rules = (SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(x) = ''object'' AND x->>''field'' IN (''price'', ''compare_at_price'') AND (x->>''value'') ~ ''^\s*[0-9]+(\.[0-9]+)?\s*$'' THEN jsonb_set(x, ''{value}'', to_jsonb(regexp_replace(regexp_replace(round(btrim(x->>''value'')::numeric * $2, 2)::text, ''0+$'', ''''), ''\.$'', ''''))) ELSE x END ORDER BY o), ''[]''::jsonb) FROM jsonb_array_elements(rules) WITH ORDINALITY AS e(x, o))'; ELSE SELECT string_agg(format('%1$I = CASE WHEN %1$I IS NULL THEN NULL ELSE round(%1$I * $2)::integer END', c), ', ') INTO v_set FROM unnest(v_cols) AS c; END IF; EXECUTE format('UPDATE public.%I SET %s WHERE %s', v_target.table_name, v_set, v_target.store_filter) USING p_creator, p_rate; v_counts := v_counts || jsonb_build_object(v_target.table_name, v_n); END LOOP; INSERT INTO public.store_currency_snapshots (change_id, table_name, row_id, before) SELECT v_change, 'store_settings', s.creator_id, jsonb_build_object('codFeeCents', s.checkout->'codFeeCents') FROM public.store_settings s WHERE s.creator_id = p_creator AND jsonb_typeof(s.checkout->'codFeeCents') = 'number'; GET DIAGNOSTICS v_n = ROW_COUNT; IF v_n > 0 THEN UPDATE public.store_settings SET checkout = jsonb_set(checkout, '{codFeeCents}', to_jsonb(round((checkout->>'codFeeCents')::numeric * p_rate)::integer)) WHERE creator_id = p_creator; v_counts := v_counts || jsonb_build_object('cod_fee', 1); END IF; END IF; UPDATE public.store_settings SET currency = p_to, updated_at = now() WHERE creator_id = p_creator; UPDATE public.store_currency_changes SET counts = v_counts WHERE id = v_change; RETURN jsonb_build_object('ok', true, 'repeat', false, 'id', v_change, 'from', p_from, 'to', p_to, 'mode', p_mode, 'rate', CASE WHEN p_mode = 'convert' THEN p_rate END, 'counts', v_counts); END $fn$;
REVOKE ALL ON FUNCTION public.store_currency_targets() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_currency_targets() TO service_role;
GRANT EXECUTE ON FUNCTION public.store_change_currency(uuid, text, text, text, numeric, date, text, uuid) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('306', '306_store_currency_quantity_breaks.sql', '129ee1c7070dcad6ea2e4106b9926112dc15783d8e7527e258ce4b321cb96514') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 307_product_personalization.sql
/* Personalization fields on products that ship (round 13): one column on products, personalization, the list of what a buyer is asked when buying (a name to engrave, a message, a photo to print; up to five fields, each a label, a type of text, long text or photo, required or not, a character limit, a hint), written by the product editor's Personalization card and read by every product page (the Storelib theme's product section, the storelib.com product page, an imported theme's product.metafields.storelib.personalization). A list under 16 KB; NOT VALID, so no old row is rechecked. Buyers' photos are kept by part 308 (cart_uploads and its private bucket), so run 308 too for photo fields. Run after the products table exists. Until it runs, the editor saves products as before and leaves the fields unsaved, and no product page asks for anything. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 307: the products table is not there yet.'; RETURN; END IF; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS personalization jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_personalization_shape, ADD CONSTRAINT products_personalization_shape CHECK (jsonb_typeof(personalization) = 'array' AND jsonb_array_length(personalization) <= 5 AND pg_column_size(personalization) < 16384) NOT VALID; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('307', '307_product_personalization.sql', 'c1641d127b9f2553927e5f511ea3f4c68e522e092593639d598c7fc9a2634b64') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 308_cart_uploads.sql
/* Buyers' pictures on cart lines (round AG3, run after `164`): a product form's photo upload (an imported theme's `properties[Photo]` file, the Storelib theme's Personalization block, POST /cart/upload) is kept in the new PRIVATE `cart-uploads` bucket (10 MB, JPEG, PNG and WebP only, no storage policy at all, so only the server reads or writes it) under the store and a random id, with its row in the new `cart_uploads` table (the store, the SHA-256 of the browser's own cart id, the file's name, type, size and pixels, its path while in a cart and its path once a paid order took it). No anon or authenticated access: row level security on, nothing granted but to the service role. New table and bucket only; no existing row changes. Until it runs, a product form with a picture is told uploads are not available yet and everything else works as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.cart_uploads (id uuid PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, visitor_hash text NOT NULL CHECK (visitor_hash ~ '^[0-9a-f]{64}$'), file_name text NOT NULL CHECK (length(file_name) BETWEEN 1 AND 90), content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')), bytes integer NOT NULL CHECK (bytes > 0 AND bytes <= 10485760), width integer CHECK (width IS NULL OR width > 0), height integer CHECK (height IS NULL OR height > 0), cart_path text CHECK (cart_path IS NULL OR (cart_path LIKE 'cart/%' AND position('..' in cart_path) = 0)), order_path text CHECK (order_path IS NULL OR (order_path LIKE 'orders/%' AND position('..' in order_path) = 0)), checkout_id uuid REFERENCES public.commerce_checkouts(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, attached_at timestamptz);
CREATE INDEX IF NOT EXISTS cart_uploads_creator_idx ON public.cart_uploads (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS cart_uploads_unattached_idx ON public.cart_uploads (created_at) WHERE attached_at IS NULL;
CREATE INDEX IF NOT EXISTS cart_uploads_checkout_idx ON public.cart_uploads (checkout_id) WHERE checkout_id IS NOT NULL;
ALTER TABLE public.cart_uploads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cart_uploads FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cart_uploads TO service_role;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('cart-uploads', 'cart-uploads', false, 10485760, ARRAY['image/jpeg', 'image/png', 'image/webp']) ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 10485760, allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp'];
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('308', '308_cart_uploads.sql', '9169f708b6a985282676b02e1ed8102b9c7df1a827badc9d65cb99a28034bc14') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 309_size_chart_rules.sql
/* Size charts by collection and category (round 13, run after part 283): a size chart can also be given to every product in some of the store's collections (size_charts.collection_ids, a list of collection ids, at most 50) or with some categories (size_charts.categories, a list of category names as the product editor files them, like T-Shirts, at most 50). A product page shows the chart chosen on the product first, then a chart set for one of its collections, then one set for its category, then the size guide block's own table. Two new columns with an empty list as their default, so every chart saved before keeps showing only on the products it was given. Read by the product page on Storelib themes, imported themes and the OnePage, written by Products > Size charts through /api/size-charts. Row level security and grants are as part 283 left them. Until it runs a chart shows only on the products it was given, and the chart editor says this part is needed for collections and categories. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.size_charts') IS NULL THEN RAISE NOTICE 'part 309: size_charts is not here yet; run part 283 first, then this again.'; RETURN; END IF; ALTER TABLE public.size_charts ADD COLUMN IF NOT EXISTS collection_ids uuid[] NOT NULL DEFAULT '{}'::uuid[]; ALTER TABLE public.size_charts ADD COLUMN IF NOT EXISTS categories text[] NOT NULL DEFAULT '{}'::text[]; ALTER TABLE public.size_charts DROP CONSTRAINT IF EXISTS size_charts_rules_len; ALTER TABLE public.size_charts ADD CONSTRAINT size_charts_rules_len CHECK (coalesce(array_length(collection_ids, 1), 0) <= 50 AND coalesce(array_length(categories, 1), 0) <= 50); END $do$;
DO $do$ BEGIN IF to_regclass('public.size_charts') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS size_charts_collection_ids_idx ON public.size_charts USING gin (collection_ids); END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('309', '309_size_chart_rules.sql', 'c25b897e8cca72e7052a3f246d68c035aa713b6aa92ff0ed4d72356c780d91b7') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 315_onepage_integrations.sql
/* The tools a OnePage's signups are sent to as they happen (round 40): new `onepage_integrations`, one row per store and tool (Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets or a webhook of the creator's own), holding the chosen list or form (`config`), the API key or the webhook address and signing secret sealed by the server (`secret_ciphertext`, AES-256-GCM, never readable by a browser), and what happened to the signups sent (`sent_count`, `failed_count`, `last_sent_at`, `last_error`, `last_error_at`). Written and read only by the server for the signed in owner (/api/onepage/integrations) and by the signup routes (lib/onepage/integrations/deliver-server): row level security on, nothing granted to anon or authenticated, so no key can be read from a browser even by its owner. `onepage_integration_note` counts one send in one step, so two signups at once both count; only the service role may run it. New table and function only; no existing row changes. Until it runs, the editor's Settings › Integrations says this part is needed and signups are kept on Storelib as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.onepage_integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'zapier', 'make', 'sheets', 'webhook')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'paused')), account_label text CHECK (account_label IS NULL OR length(account_label) <= 200), config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), secret_ciphertext text CHECK (secret_ciphertext IS NULL OR secret_ciphertext LIKE 'v1.%'), sent_count integer NOT NULL DEFAULT 0 CHECK (sent_count >= 0), failed_count integer NOT NULL DEFAULT 0 CHECK (failed_count >= 0), last_sent_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 500), last_error_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT onepage_integrations_one_per_tool UNIQUE (creator_id, provider));
CREATE INDEX IF NOT EXISTS onepage_integrations_connected_idx ON public.onepage_integrations (creator_id) WHERE status = 'connected';
ALTER TABLE public.onepage_integrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.onepage_integrations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.onepage_integrations TO service_role;
CREATE OR REPLACE FUNCTION public.onepage_integration_note(p_id uuid, p_ok boolean, p_error text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $fn$ UPDATE public.onepage_integrations SET sent_count = sent_count + CASE WHEN p_ok THEN 1 ELSE 0 END, failed_count = failed_count + CASE WHEN p_ok THEN 0 ELSE 1 END, last_sent_at = CASE WHEN p_ok THEN now() ELSE last_sent_at END, last_error = CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'Not sent.'), 500) END, last_error_at = CASE WHEN p_ok THEN NULL ELSE now() END, updated_at = now() WHERE id = p_id; $fn$;
REVOKE ALL ON FUNCTION public.onepage_integration_note(uuid, boolean, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.onepage_integration_note(uuid, boolean, text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('315', '315_onepage_integrations.sql', '1892c8279ddba3df7fce27a4ccebe790102c48298b5a605f607c6ad62101d3f8') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 316_onepage_lead_magnets.sql
/* What a OnePage signup was for (round 40): `onepage_leads` takes `magnet_kind` (download, discount or waitlist, from the new lead magnet block; empty for the email signup) and `magnet_label` (the waitlist's name, or the discount's "15% off"; never the code), written by /api/onepage/lead-magnet, so Leads can tell a waitlist from a newsletter. Two new columns, empty by default; no row changes. Until it runs the route keeps the lead without them. Does nothing if public.onepage_leads does not exist. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NULL THEN RAISE NOTICE 'part 316: onepage_leads is not here; nothing to do.'; RETURN; END IF; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS magnet_kind text; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS magnet_label text; ALTER TABLE public.onepage_leads DROP CONSTRAINT IF EXISTS onepage_leads_magnet_kind_check; ALTER TABLE public.onepage_leads ADD CONSTRAINT onepage_leads_magnet_kind_check CHECK (magnet_kind IS NULL OR magnet_kind IN ('download', 'discount', 'waitlist')) NOT VALID; ALTER TABLE public.onepage_leads DROP CONSTRAINT IF EXISTS onepage_leads_magnet_label_len; ALTER TABLE public.onepage_leads ADD CONSTRAINT onepage_leads_magnet_label_len CHECK (magnet_label IS NULL OR length(magnet_label) <= 200) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepage_leads_magnet_idx ON public.onepage_leads (onepage_id, magnet_kind, created_at DESC) WHERE magnet_kind IS NOT NULL; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('316', '316_onepage_lead_magnets.sql', 'e12ce21392053524798b722562ebb30e4cd9432439149a8f2830a690d6d87727') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 319_team_store_areas.sql
/* The team in the OnePage and the community (round 40, run after part 135; before or after part 320): two functions that answer, inside a row level security policy, whether the signed in person is on a store's team with a permission. public.team_store_ids(area) returns the stores (creators.id) where the signed in account is an active member whose permissions hold that area; public.team_can(store, area) answers for one store. Both read store_team_members.permissions through to_jsonb, so they work before part 320 has added the column (and then answer no, as a row from before part 320 holds no area but Orders) and need nothing run again after it. Both are security definer, answer only for auth.uid() (never for a visitor), and only for the twelve area keys. One policy uses them: "storelib team reads store products", so the OnePage editor's product picker, opened by a team member with OnePage, lists the store's products, drafts too, as it does for the owner. It only adds reading; nothing is written through it and nothing changes for the owner or for visitors. The OnePage's own reads and writes go through the server with the member's permissions checked on each request (lib/team/onepage.ts), and the communities are server only already (lib/communities/server/team.ts). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 319: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; EXECUTE $f$create or replace function public.team_store_ids(p_area text) returns setof uuid language sql stable security definer set search_path = public as $b$ select m.creator_id from public.store_team_members m where (select auth.uid()) is not null and m.user_id = (select auth.uid()) and m.status = 'active' and p_area = any (array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']) and coalesce(to_jsonb(m) -> 'permissions', '[]'::jsonb) ? p_area $b$$f$; EXECUTE $f$create or replace function public.team_can(p_creator uuid, p_area text) returns boolean language sql stable security definer set search_path = public as $b$ select p_creator is not null and exists (select 1 from public.team_store_ids(p_area) s where s = p_creator) $b$$f$; COMMENT ON FUNCTION public.team_store_ids(text) IS 'The stores where the signed in account is an active team member holding this area (store_team_members.permissions, part 320). For row level security policies (part 319).'; COMMENT ON FUNCTION public.team_can(uuid, text) IS 'Whether the signed in account is an active team member of this store holding this area (part 319).'; REVOKE ALL ON FUNCTION public.team_store_ids(text) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_can(uuid, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_store_ids(text) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_can(uuid, text) TO authenticated, service_role; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 319: there is no products table here, no policy to add.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team reads store products') THEN CREATE POLICY "storelib team reads store products" ON public.products FOR SELECT TO authenticated USING (creator_id IN (SELECT public.team_store_ids('onepage'))); END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('319', '319_team_store_areas.sql', 'a2ef77929675c44f56b54b1b06fe549c04c7b9126e3b99cfbf1732ea973851f4') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 320_team_permissions.sql
/* Team permissions, like Shopify's staff permissions (round 40, run after part 135): each person on a store's team gets their own list of what they may do, in a new column `store_team_members.permissions` (text[], from website, onepage, creator_pages, products, orders, customers, marketing, community, analytics, settings, team, payouts_billing), chosen in Settings > Team from a preset (Full access, Content editor, Support) or ticked one by one, and changed there later. Everyone already on a team keeps exactly what they could use before: a Manager gets orders, Staff (never open to invite) gets nothing; the old role column stays as it is. A row the app writes without the column reads as its role, so nothing breaks while an older server is still running. The table stays server only: row level security on, no policy, nothing granted to anon or signed in users; every page and route checks the member's permissions on the server on each request (lib/team/server requireTeamPermission). Until it runs, Settings > Team can only give Orders and says permissions are not set up for anything else. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 320: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; ALTER TABLE public.store_team_members ADD COLUMN IF NOT EXISTS permissions text[]; UPDATE public.store_team_members SET permissions = CASE WHEN role = 'manager' THEN ARRAY['orders']::text[] ELSE '{}'::text[] END WHERE permissions IS NULL; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_team_members_permissions_check' AND conrelid = 'public.store_team_members'::regclass) THEN ALTER TABLE public.store_team_members ADD CONSTRAINT store_team_members_permissions_check CHECK (permissions IS NULL OR (permissions <@ ARRAY['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']::text[] AND cardinality(permissions) <= 12)); END IF; COMMENT ON COLUMN public.store_team_members.permissions IS 'What this member may do in the store (lib/team/permissions.ts). NULL: read as the role (manager: orders).'; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('320', '320_team_permissions.sql', 'e9804b7c41d653dd2f00d2cd0652e01e39c4da35ce6043c86eb3e63da2053e7c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 321_store_invoice_numbers.sql
/* Invoice numbers that run in sequence for each store (round docs-1028): an invoice in the EU must carry a number that is unique and follows on from the store's previous one, and the PDF used to be numbered from the order's day and id ("SL-20260923-1A2B3C4D"), unique but not in sequence. New store_invoice_series (one row per store, the last number given) and store_invoice_numbers (one row per order, its number and when it was issued, unique per store), both server only (row level security on, no policy, nothing granted to anon or signed in users), and public.storelib_invoice_number(order, store), called by the server when a receipt or invoice PDF is first drawn (lib/checkout/invoice.ts): it hands out the store's next number under a lock on the store's row, so two drawings at the same moment never share or skip one, and gives the same number every time after. Orders written before this part ran keep the number their PDF already carried (store_invoice_numbering.started_at is when it first ran); until it runs every PDF is numbered as before. Safe to run again. */
create table if not exists public.store_invoice_numbering (id boolean primary key default true check (id), started_at timestamptz not null default now());
insert into public.store_invoice_numbering (id) values (true) on conflict (id) do nothing;
create table if not exists public.store_invoice_series (creator_id uuid primary key, last_seq integer not null default 0 check (last_seq >= 0), updated_at timestamptz not null default now());
create table if not exists public.store_invoice_numbers (order_id uuid primary key, creator_id uuid not null, seq integer not null check (seq > 0), issued_at timestamptz not null default now(), constraint store_invoice_numbers_creator_seq_key unique (creator_id, seq));
alter table public.store_invoice_numbering enable row level security;
alter table public.store_invoice_series enable row level security;
alter table public.store_invoice_numbers enable row level security;
revoke all on public.store_invoice_numbering from anon, authenticated;
revoke all on public.store_invoice_series from anon, authenticated;
revoke all on public.store_invoice_numbers from anon, authenticated;
create or replace function public.storelib_invoice_number(p_order uuid, p_creator uuid) returns jsonb language plpgsql security definer set search_path = public as $f$ declare v_seq integer; v_at timestamptz; v_start timestamptz; v_created timestamptz; begin if p_order is null or p_creator is null then return null; end if; select n.seq, n.issued_at into v_seq, v_at from public.store_invoice_numbers n where n.order_id = p_order; if v_seq is not null then return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end if; select s.started_at into v_start from public.store_invoice_numbering s where s.id; select o.created_at into v_created from public.orders o join public.products p on p.id = o.product_id where o.id = p_order and p.creator_id = p_creator; if v_start is null or v_created is null or v_created < v_start then return null; end if; insert into public.store_invoice_series (creator_id) values (p_creator) on conflict (creator_id) do nothing; perform 1 from public.store_invoice_series s where s.creator_id = p_creator for update; select n.seq, n.issued_at into v_seq, v_at from public.store_invoice_numbers n where n.order_id = p_order; if v_seq is not null then return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end if; update public.store_invoice_series s set last_seq = s.last_seq + 1, updated_at = now() where s.creator_id = p_creator returning s.last_seq into v_seq; insert into public.store_invoice_numbers (order_id, creator_id, seq) values (p_order, p_creator, v_seq) returning issued_at into v_at; return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end $f$;
revoke all on function public.storelib_invoice_number(uuid, uuid) from public, anon, authenticated;
grant execute on function public.storelib_invoice_number(uuid, uuid) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('321', '321_store_invoice_numbers.sql', '6398fbb627f85551d0bc06251ef39de14727612fd45c25d9ea7c8a3df746cc61') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 323_onepage_integrations_more_tools.sql
/* MailerLite, Brevo and Flodesk for a OnePage's signups (round 41, run after `315`): the `onepage_integrations` provider check takes 'mailerlite', 'brevo' and 'flodesk' beside Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets and a webhook. The check made by part 315 (named onepage_integrations_provider_check by Postgres) is dropped and added again NOT VALID, then validated, so the table is never locked against writes while old rows are read; every row already there holds one of the old seven and passes. One constraint changes; no row, column, grant or policy does. Until it runs, connecting one of the three says this part is needed and the other tools work as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 323: run part 315 first.'; RETURN; END IF; ALTER TABLE public.onepage_integrations DROP CONSTRAINT IF EXISTS onepage_integrations_provider_check; ALTER TABLE public.onepage_integrations ADD CONSTRAINT onepage_integrations_provider_check CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'mailerlite', 'brevo', 'flodesk', 'zapier', 'make', 'sheets', 'webhook')) NOT VALID; ALTER TABLE public.onepage_integrations VALIDATE CONSTRAINT onepage_integrations_provider_check; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('323', '323_onepage_integrations_more_tools.sql', '587203ab415208526b9a823367141cbb253c4a8f9b39676bb6cbca5e8870c02c') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 324_onepage_integration_sends.sql
/* One OnePage signup, one delivery to each tool (round 41, run after `315`): new `onepage_integration_sends`, one row per connected tool (`integration_id`, deleted with it) and signup (`send_key`, a SHA-256 of the address, the form and the block, so it holds no address), written by the server just before a signup is sent (lib/onepage/integrations/deliver-server) and removed again when the send did not go. The same person signing up on the same block again is then not a second Zapier run, a second Make scenario or a second Google Sheets row. Row level security on, nothing granted to anon or authenticated; only the service role reads or writes it. New table only; no existing row changes. Until it runs, every signup is sent as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 324: run part 315 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_integration_sends (integration_id uuid NOT NULL REFERENCES public.onepage_integrations(id) ON DELETE CASCADE, send_key text NOT NULL CHECK (send_key ~ '^[0-9a-f]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (integration_id, send_key)); ALTER TABLE public.onepage_integration_sends ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_integration_sends FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, DELETE ON public.onepage_integration_sends TO service_role; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('324', '324_onepage_integration_sends.sql', 'f2685220f8adb7606dde956256f2bb1159042c3a4090eb84dfba52c52723dfa4') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 327_team_products.sql
/* Products for the team (round 41, run after part 319; before or after part 320): a team member whose permissions hold Products edits the store's catalogue from the browser as the owner does, under row level security. Three security definer functions (team_owns_product, team_owns_variant, team_variant_file_ok) answer, for the signed in account only, whether a product or a variant is in a store where they hold Products. Policies for signed in people only, never anon: products (read, add, change; never delete: a delete goes through the server, which archives a product with sales instead, as it does for the owner), product_variants (read, add, change, delete), product_variant_files (read, add, delete; a file is linked only to a variant of the product it belongs to), digital_assets (read the file's name and size; the file itself stays in the private bucket, read only by its buyers through the download routes, as before). A trigger keeps a product in its store and a variant on its product: a signed in account changes creator_id only between stores it owns, and product_id only between products of stores it owns, so a member cannot move the store's product into their own store. The service role is not held by it. Nothing changes for the owner or for visitors: the owner's own policies are left as they are and every new one only adds for team members. Safe to run again. */
DO $do$ BEGIN IF to_regprocedure('public.team_store_ids(text)') IS NULL THEN RAISE NOTICE 'part 327: team_store_ids is not here yet; run part 319 first, then this again.'; RETURN; END IF; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 327: there is no products table here, nothing to add.'; RETURN; END IF; EXECUTE $f$create or replace function public.team_owns_product(p_product uuid) returns boolean language sql stable security definer set search_path = public as $b$ select p_product is not null and exists (select 1 from public.products p where p.id = p_product and p.creator_id in (select public.team_store_ids('products'))) $b$$f$; EXECUTE $f$create or replace function public.team_owns_variant(p_variant uuid) returns boolean language plpgsql stable security definer set search_path = public as $b$ begin if p_variant is null or to_regclass('public.product_variants') is null then return false; end if; return exists (select 1 from public.product_variants v join public.products p on p.id = v.product_id where v.id = p_variant and p.creator_id in (select public.team_store_ids('products'))); end $b$$f$; EXECUTE $f$create or replace function public.team_variant_file_ok(p_variant uuid, p_asset uuid) returns boolean language plpgsql stable security definer set search_path = public as $b$ begin if p_variant is null or p_asset is null or to_regclass('public.product_variants') is null or to_regclass('public.digital_assets') is null then return false; end if; return exists (select 1 from public.product_variants v join public.products p on p.id = v.product_id join public.digital_assets da on da.product_id = v.product_id where v.id = p_variant and da.id = p_asset and p.creator_id in (select public.team_store_ids('products'))); end $b$$f$; EXECUTE $f$create or replace function public.team_keeps_store() returns trigger language plpgsql security definer set search_path = public as $b$ declare me uuid := (select auth.uid()); begin if me is null then return new; end if; if tg_table_name = 'products' then if new.creator_id is distinct from old.creator_id and not (exists (select 1 from public.creators c where c.id = old.creator_id and c.user_id = me) and exists (select 1 from public.creators c where c.id = new.creator_id and c.user_id = me)) then raise exception 'A product stays in its store.' using errcode = '42501'; end if; elsif tg_table_name = 'product_variants' then if new.product_id is distinct from old.product_id and not (exists (select 1 from public.products p join public.creators c on c.id = p.creator_id where p.id = old.product_id and c.user_id = me) and exists (select 1 from public.products p join public.creators c on c.id = p.creator_id where p.id = new.product_id and c.user_id = me)) then raise exception 'A variant stays on its product.' using errcode = '42501'; end if; end if; return new; end $b$$f$; COMMENT ON FUNCTION public.team_owns_product(uuid) IS 'Whether this product is in a store where the signed in account is an active team member holding Products (part 327).'; COMMENT ON FUNCTION public.team_owns_variant(uuid) IS 'Whether this variant is on a product of a store where the signed in account holds Products (part 327).'; COMMENT ON FUNCTION public.team_variant_file_ok(uuid, uuid) IS 'Whether this file may be linked to this variant by a team member: the variant is in a store where they hold Products, and the file belongs to the same product (part 327).'; COMMENT ON FUNCTION public.team_keeps_store() IS 'Keeps a product in its store and a variant on its product when a signed in account changes them (part 327).'; REVOKE ALL ON FUNCTION public.team_owns_product(uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_owns_variant(uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_variant_file_ok(uuid, uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_keeps_store() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_owns_product(uuid) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_owns_variant(uuid) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_variant_file_ok(uuid, uuid) TO authenticated, service_role; IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'storelib_team_keeps_store' AND tgrelid = 'public.products'::regclass) THEN CREATE TRIGGER storelib_team_keeps_store BEFORE UPDATE OF creator_id ON public.products FOR EACH ROW EXECUTE FUNCTION public.team_keeps_store(); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team reads products') THEN CREATE POLICY "storelib team reads products" ON public.products FOR SELECT TO authenticated USING (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team adds products') THEN CREATE POLICY "storelib team adds products" ON public.products FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team changes products') THEN CREATE POLICY "storelib team changes products" ON public.products FOR UPDATE TO authenticated USING (creator_id IN (SELECT public.team_store_ids('products'))) WITH CHECK (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF to_regclass('public.product_variants') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'storelib_team_keeps_store' AND tgrelid = 'public.product_variants'::regclass) THEN CREATE TRIGGER storelib_team_keeps_store BEFORE UPDATE OF product_id ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.team_keeps_store(); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team reads variants') THEN CREATE POLICY "storelib team reads variants" ON public.product_variants FOR SELECT TO authenticated USING (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team adds variants') THEN CREATE POLICY "storelib team adds variants" ON public.product_variants FOR INSERT TO authenticated WITH CHECK (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team changes variants') THEN CREATE POLICY "storelib team changes variants" ON public.product_variants FOR UPDATE TO authenticated USING (public.team_owns_product(product_id)) WITH CHECK (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team deletes variants') THEN CREATE POLICY "storelib team deletes variants" ON public.product_variants FOR DELETE TO authenticated USING (public.team_owns_product(product_id)); END IF; END IF; IF to_regclass('public.product_variant_files') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team reads variant files') THEN CREATE POLICY "storelib team reads variant files" ON public.product_variant_files FOR SELECT TO authenticated USING (public.team_owns_variant(variant_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team links variant files') THEN CREATE POLICY "storelib team links variant files" ON public.product_variant_files FOR INSERT TO authenticated WITH CHECK (public.team_variant_file_ok(variant_id, digital_asset_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team unlinks variant files') THEN CREATE POLICY "storelib team unlinks variant files" ON public.product_variant_files FOR DELETE TO authenticated USING (public.team_owns_variant(variant_id)); END IF; END IF; IF to_regclass('public.digital_assets') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'digital_assets' AND policyname = 'storelib team reads file details') THEN CREATE POLICY "storelib team reads file details" ON public.digital_assets FOR SELECT TO authenticated USING (public.team_owns_product(product_id)); END IF; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('327', '327_team_products.sql', '530216cdacce417d2b693be13ebcc2ea658a32594a306ea8eaedce3fd98237fb') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 328_analytics_test_sales_and_refund_reads.sql
/* Analytics counts buyers' orders only, and reads refunds quickly (round ana-1028, run after part 61): the all time line under Revenue and Orders (`analytics_all_time`, Home's sales totals too) leaves out an admin's Test sale (an order whose `source_detail` says surface `admin`, written by the admin console's sales trigger), as every Analytics read in the app now does (lib/analytics/test-sales.ts); the function is otherwise part 61's, word for word. And a partial index on `orders (creator_id, refunded_at) WHERE status = 'refunded'`, for the read every Analytics answer makes of refunds given in the period of orders placed before it (lib/analytics/report-read refundedEarlier), which scanned all of a store's orders, and one on `ledger_events (creator_id, created_at) WHERE event_type = 'refund'` for the refunds dated on the seller's ledger in the period (lib/analytics/refund-history-server refundedOrderIds), which scanned every ledger row of the store; each skipped where its table or columns are not there yet. No row changes. Until it runs, the all time line still counts test sales as orders (they never carried any money).*/
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) AND coalesce(o.source_detail ->> 'surface', '') <> 'admin' ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status, 'pending') = 'pending') AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'refunded_at') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 328: orders has no refunded_at or creator_id here; the refunds index is skipped.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_creator_refunded_at ON public.orders (creator_id, refunded_at) WHERE status = 'refunded'; END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'ledger_events' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 328: there is no ledger_events with creator_id here; the ledger refunds index is skipped.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS ledger_events_creator_refund_time ON public.ledger_events (creator_id, created_at) WHERE event_type = 'refund'; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('328', '328_analytics_test_sales_and_refund_reads.sql', 'b103748ef74f967ec4c6ac595f71e243c3c52c570818f0b64746db21d652a5f0') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 329_store_credit_notes.sql
/* Credit notes for refunds, in the store's invoice sequence (round cn-1028, run after part 321): every refund, full or partial, made from the Orders page, the Stripe dashboard or the admin, gets one credit note that names the invoice it corrects and the lines and tax it gives back, numbered from the same per store counter as invoices (store_invoice_series), so an accountant reads 000153 Invoice, 000154 Credit note, 000155 Invoice. New store_credit_notes (one row per refund: the purchase's first order, the refund it is for, its number, amount, currency and how the refund was split over the order's lines; unique per store and refund, and per store and number), server only (row level security on, no policy, nothing granted to anon or signed in users), and public.storelib_credit_note(store, order, refund, amount, currency, shares), for the service role only, which hands out the store's next number under the same lock on the store's row as invoices and gives the same note every time after for that refund, so a webhook retried or a refund seen from two places is credited once. Until it runs refunds are recorded as before, with no credit note. Safe to run again. */
create table if not exists public.store_credit_notes (id uuid primary key default gen_random_uuid(), creator_id uuid not null, order_id uuid not null, refund_key text not null check (length(refund_key) between 1 and 200), seq integer not null check (seq > 0), amount_cents integer not null check (amount_cents > 0), currency text not null check (currency ~ '^[A-Za-z]{3}$'), shares jsonb not null default '[]'::jsonb, issued_at timestamptz not null default now(), constraint store_credit_notes_refund_key unique (creator_id, refund_key), constraint store_credit_notes_creator_seq_key unique (creator_id, seq));
create index if not exists store_credit_notes_order on public.store_credit_notes (order_id, issued_at);
create table if not exists public.store_invoice_series (creator_id uuid primary key, last_seq integer not null default 0 check (last_seq >= 0), updated_at timestamptz not null default now());
alter table public.store_credit_notes enable row level security;
alter table public.store_invoice_series enable row level security;
revoke all on public.store_credit_notes from anon, authenticated;
revoke all on public.store_invoice_series from anon, authenticated;
create or replace function public.storelib_credit_note(p_creator uuid, p_order uuid, p_refund text, p_amount integer, p_currency text, p_shares jsonb) returns jsonb language plpgsql security definer set search_path = public as $f$ declare v_row public.store_credit_notes%rowtype; v_seq integer; begin if p_creator is null or p_order is null or p_refund is null or length(p_refund) = 0 or p_amount is null or p_amount <= 0 or p_currency is null then return null; end if; select * into v_row from public.store_credit_notes n where n.creator_id = p_creator and n.refund_key = p_refund; if v_row.id is not null then return to_jsonb(v_row); end if; perform 1 from public.orders o join public.products p on p.id = o.product_id where o.id = p_order and p.creator_id = p_creator; if not found then return null; end if; insert into public.store_invoice_series (creator_id) values (p_creator) on conflict (creator_id) do nothing; perform 1 from public.store_invoice_series s where s.creator_id = p_creator for update; select * into v_row from public.store_credit_notes n where n.creator_id = p_creator and n.refund_key = p_refund; if v_row.id is not null then return to_jsonb(v_row); end if; update public.store_invoice_series s set last_seq = s.last_seq + 1, updated_at = now() where s.creator_id = p_creator returning s.last_seq into v_seq; insert into public.store_credit_notes (creator_id, order_id, refund_key, seq, amount_cents, currency, shares) values (p_creator, p_order, p_refund, v_seq, p_amount, upper(p_currency), case when jsonb_typeof(p_shares) = 'array' then p_shares else '[]'::jsonb end) returning * into v_row; return to_jsonb(v_row); end $f$;
revoke all on function public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb) from public, anon, authenticated;
grant execute on function public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('329', '329_store_credit_notes.sql', 'abf126c22a8973a1a4c918b31bac012fed9d818ed50b042e012e5d57f4b32b7a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 331_analytics_clicks_between_pages_and_row_lines.sql
/* Analytics: clicks between pages, and each row's own line (round ana-1028b, run after part 61). A link or a button on a website that leads to another page of the same site is recorded as a `nav_click` event (the event type check allows it; `analytics_events.link_label`, at most 80 characters, keeps the button's words; `path` is the page it was on and `link_url` the page it led to) and `analytics_nav_clicks` counts them for the Clicks report (both periods, the 100 most clicked buttons, with the people who clicked), with a partial index on `analytics_events (creator_id, created_at) WHERE event_type = 'nav_click'`. `analytics_row_series` counts one report's rows over the chart's buckets for an opened report (a page's views, a link's or a button's clicks, a source's, referrer's, campaign's, device's, country's or browser's visits, where each visit began), the 100 busiest rows. Both are server only (service role). No existing row changes. Until it runs, internal clicks are not recorded and an opened report's rows are counted from the events by the app. Safe to run again. */
ALTER TABLE public.analytics_events ADD COLUMN IF NOT EXISTS link_label text;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_link_label_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_link_label_check CHECK (link_label IS NULL OR char_length(link_label) <= 80) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (event_type IN ('view', 'purchase', 'session_start', 'store_view', 'product_view', 'add_to_cart', 'checkout_start', 'buy_click', 'checkout_complete', 'download', 'link_click', 'nav_click')) NOT VALID;
CREATE INDEX IF NOT EXISTS idx_analytics_events_nav_click_time ON public.analytics_events (creator_id, created_at) WHERE event_type = 'nav_click';
CREATE OR REPLACE FUNCTION public.analytics_nav_clicks(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_cur_start timestamptz, p_cur_end timestamptz, p_prev_start timestamptz DEFAULT NULL, p_prev_end timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public AS $fn$ DECLARE v_pred text := ''; v_out jsonb; v_ps timestamptz := coalesce(p_prev_start, p_cur_start); v_pe timestamptz := greatest(coalesce(p_prev_start, p_cur_start), coalesce(p_prev_end, p_cur_start)); BEGIN IF p_creator_id IS NULL OR p_cur_start IS NULL OR p_cur_end IS NULL OR p_cur_end <= p_cur_start THEN RAISE EXCEPTION 'analytics_nav_clicks: a creator and a period are needed'; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_nav_clicks: unknown property type %', p_property_type; END IF; /* The property is a condition of its own, so each read is planned for what it is asked; a website row that never knew its install is the live website's. */ IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; EXECUTE format($q$ WITH ev AS ( SELECT e.id, e.created_at, e.property_type AS pt, e.property_id AS pid, e.path, e.link_url, e.link_label, coalesce(nullif(e.visitor_id::text, ''), nullif(e.session_id::text, ''), 'e:' || e.id::text) AS who, (e.created_at >= $4 AND e.created_at < $5) AS now_ FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'nav_click' AND e.property_type IS NOT NULL %s AND ((e.created_at >= $4 AND e.created_at < $5) OR (e.created_at >= $6 AND e.created_at < $7)) ), cur AS (SELECT * FROM ev WHERE now_), prev AS (SELECT * FROM ev WHERE NOT now_ AND created_at >= $6 AND created_at < $7), grouped AS ( SELECT c.pt, c.pid, c.path, c.link_url, c.link_label, count(*)::int AS clicks, count(DISTINCT c.who)::int AS people, (coalesce(c.pt, '') || '|' || coalesce(c.pid::text, '') || '|' || coalesce(c.path, '') || '|' || coalesce(c.link_url, '') || '|' || coalesce(c.link_label, '')) COLLATE "C" AS k FROM cur c GROUP BY c.pt, c.pid, c.path, c.link_url, c.link_label ), top AS (SELECT * FROM grouped ORDER BY clicks DESC, k LIMIT 100) SELECT jsonb_build_object( 'cur', (SELECT count(*) FROM cur), 'prev', (SELECT count(*) FROM prev), 'rows', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.path, t.link_url, t.link_label, t.clicks, t.people, (SELECT count(*) FROM prev p WHERE p.pt = t.pt AND p.pid IS NOT DISTINCT FROM t.pid AND p.path IS NOT DISTINCT FROM t.path AND p.link_url IS NOT DISTINCT FROM t.link_url AND p.link_label IS NOT DISTINCT FROM t.link_label)) ORDER BY t.clicks DESC, t.k) FROM top t), '[]'::jsonb)) $q$, v_pred) INTO v_out USING p_creator_id, p_property_type, p_property_id, p_cur_start, p_cur_end, v_ps, v_pe; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_nav_clicks(uuid, text, uuid, uuid, timestamptz, timestamptz, timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_nav_clicks(uuid, text, uuid, uuid, timestamptz, timestamptz, timestamptz, timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_row_series(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_start timestamptz, p_end timestamptz, p_starts timestamptz[], p_dim text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public SET work_mem = '64MB' AS $fn$ DECLARE v_pred text := ''; v_n integer := coalesce(cardinality(p_starts), 0); v_rows text; v_out jsonb; BEGIN IF p_creator_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN RAISE EXCEPTION 'analytics_row_series: a creator and a period are needed'; END IF; IF p_dim IS NULL OR p_dim NOT IN ('page', 'link', 'nav', 'source', 'referrer', 'campaign', 'device', 'country', 'browser') THEN RAISE EXCEPTION 'analytics_row_series: unknown dimension %', p_dim; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_row_series: unknown property type %', p_property_type; END IF; IF v_n = 0 OR v_n > 1000 THEN RETURN '{}'::jsonb; END IF; /* A click is not of a product: with a product chosen there are none (lib/analytics/reports wireFromRows). */ IF p_product_id IS NOT NULL AND p_dim IN ('link', 'nav') THEN RETURN '{}'::jsonb; END IF; IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; IF p_product_id IS NOT NULL THEN v_pred := v_pred || ' AND e.product_id = $4'; END IF; /* The rows: (key, moment) for each counted thing. A page's views and a link's or a button's clicks where they happened; a breakdown's visits where each began (its first page, or the first after more than the previous UTC day without one), on its 15 minute slot, keyed by that first page, as analytics_property_counts keys them. */ v_rows := CASE p_dim WHEN 'page' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(e.path, '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) WHEN 'link' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(nullif(e.link_id, ''), nullif(e.link_url, ''), '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'link_click' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) WHEN 'nav' THEN format($r$SELECT (e.property_type || '|' || coalesce(e.property_id::text, '') || '|' || coalesce(e.path, '') || '|' || coalesce(e.link_url, '') || '|' || coalesce(e.link_label, '')) AS k, e.created_at AS at FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'nav_click' AND e.property_type IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %s$r$, v_pred) ELSE format($r$SELECT s.k, to_timestamp(floor(extract(epoch FROM s.created_at) / 900) * 900) AS at FROM ( SELECT v.created_at, v.k, lag(v.created_at) OVER (PARTITION BY v.pk, v.skey ORDER BY v.created_at, v.id) AS before FROM (SELECT e.id, e.created_at, e.property_type || ':' || coalesce(e.property_id::text, '') AS pk, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') ELSE 'e:' || e.id::text END) COLLATE "C" AS skey, %s AS k FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.property_type IS NOT NULL AND e.created_at >= $5 - interval '1 day' AND e.created_at < $6 %s) v ) s WHERE s.created_at >= $5 AND s.k IS NOT NULL AND (s.before IS NULL OR s.before < (((s.created_at AT TIME ZONE 'UTC')::date - 1)::timestamp AT TIME ZONE 'UTC'))$r$, CASE p_dim WHEN 'source' THEN $k$coalesce(nullif(e.source_category, ''), 'direct')$k$ WHEN 'referrer' THEN $k$coalesce(nullif(lower(regexp_replace(coalesce(e.referrer_domain, ''), '^www\.', '')), ''), 'direct')$k$ WHEN 'campaign' THEN $k$nullif(e.utm_campaign, '')$k$ WHEN 'device' THEN $k$coalesce(nullif(lower(e.device_type), ''), 'unknown')$k$ WHEN 'country' THEN $k$coalesce(nullif(upper(e.country_code), ''), 'unknown')$k$ ELSE $k$coalesce(nullif(lower(e.browser), ''), 'unknown')$k$ END, v_pred) END; EXECUTE format($q$ WITH r AS (%s), b AS (SELECT r.k COLLATE "C" AS k, width_bucket(r.at, $7) - 1 AS i, count(*)::int AS n FROM r GROUP BY 1, 2), kept AS (SELECT b.k, b.i, b.n FROM b WHERE b.i >= 0 AND b.i < $8), top AS (SELECT kept.k, sum(kept.n) AS total FROM kept GROUP BY kept.k ORDER BY sum(kept.n) DESC, kept.k LIMIT 100) SELECT coalesce(jsonb_object_agg(t.k, (SELECT jsonb_agg(coalesce(x.n, 0) ORDER BY g.i) FROM generate_series(0, $8 - 1) g(i) LEFT JOIN kept x ON x.k = t.k AND x.i = g.i)), '{}'::jsonb) FROM top t $q$, v_rows) INTO v_out USING p_creator_id, p_property_type, p_property_id, p_product_id, p_start, p_end, p_starts, v_n; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_row_series(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz, timestamptz[], text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_row_series(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz, timestamptz[], text) TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('331', '331_analytics_clicks_between_pages_and_row_lines.sql', 'd4e8d4f5f6d05e91c7f1ac9bc23cea08a50910338f02c1d23c1f0871a6c666fc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 333_team_money_areas.sql
/* The website, the creator page, payouts and billing for the team (round 42, run after parts 319 and 320): the four parts of a store still closed to a team member open, and money is given in two steps each. A member's permissions (store_team_members.permissions) may now also hold payouts (see the balance and payouts), payouts_manage (cash out and change the payout bank), billing (see the plan and invoices) and billing_manage (change the plan and the card); the old payouts_billing key stays allowed, so no row stops being valid, and the app no longer gives it. The check on the column is replaced with one that knows the new keys, and public.team_store_ids answers for them too. Nothing is written to any row, no policy is added and nothing changes for the owner or for visitors: the website and the creator page are read and written by the server with the member's permissions checked on each request (lib/team/website, lib/team/creator-page), and payouts and billing are server only (lib/team/money). The table stays server only. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 333: store_team_members is not here yet; run part 135, then 319 and 320, then this again.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_team_members' AND column_name = 'permissions') THEN RAISE NOTICE 'part 333: store_team_members.permissions is not here yet; run part 320 first, then this again.'; RETURN; END IF; ALTER TABLE public.store_team_members DROP CONSTRAINT IF EXISTS store_team_members_permissions_check; ALTER TABLE public.store_team_members ADD CONSTRAINT store_team_members_permissions_check CHECK (permissions IS NULL OR (permissions <@ ARRAY['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts', 'payouts_manage', 'billing', 'billing_manage', 'payouts_billing']::text[] AND cardinality(permissions) <= 16)); COMMENT ON COLUMN public.store_team_members.permissions IS 'What this member may do in the store (lib/team/permissions.ts). payouts_manage and billing_manage always come with payouts and billing (part 333). NULL: read as the role (manager: orders).'; IF to_regprocedure('public.team_store_ids(text)') IS NOT NULL THEN EXECUTE $f$create or replace function public.team_store_ids(p_area text) returns setof uuid language sql stable security definer set search_path = public as $b$ select m.creator_id from public.store_team_members m where (select auth.uid()) is not null and m.user_id = (select auth.uid()) and m.status = 'active' and p_area = any (array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts', 'payouts_manage', 'billing', 'billing_manage']) and coalesce(to_jsonb(m) -> 'permissions', '[]'::jsonb) ? p_area $b$$f$; REVOKE ALL ON FUNCTION public.team_store_ids(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_store_ids(text) TO authenticated, service_role; ELSE RAISE NOTICE 'part 333: public.team_store_ids is not here yet; run part 319, then this again for it.'; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('333', '333_team_money_areas.sql', '5c8705d9c89ace4c9ffd487c1b8291cf2c1f1b934b428f48ca61c70407ff62e5') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 334_database_load_and_isolation.sql
/* Database load and store isolation (round rel-db). Indexes for reads and deletes that searched a whole table: the Emails page's activity (commerce_order_events by store and kind, email_flow_sends by store and status), a sale's attribution and the shop page builder (onepages by creator_id and seller_id), a community's messages by community and time (orphaned uploads, a community deleted), the reply link on chat messages (deleting one message searched every message for replies to it, so deleting a space or a community took time in the square of its messages), a subscriber's campaign and email recipients (an account deleted unlinked each subscriber with a search of both tables), and the links a product, an order, a variant or a space leaves behind when it is deleted. Then store isolation: functions that run with their owner's rights and take any store's id (raise sales and view counts, write a customer into any store's list, read a store's email or OnePage figures, set up a store's themes) or rebuild whole tables (the rollups, the partition swap) are closed to the public key and signed in accounts; the server calls every one with the service role, as before. Policies that let any signed in account read and change every store's customers, or anybody read every verification code and security event, or write notifications into any seller's bell, are dropped; each owner's own policies stay. The public key now reads only a digital file's id, product, name and date (what a product page lists), and a signed in account reads only its own store's files and the ones it bought, no longer every store's. The unused partitioned copies of the analytics tables get row level security and lose public access, and the indexability view is the server's. Last, a statement timeout for the API roles where none is set (anon 3s and authenticated 8s as Supabase sets them, service_role 120s, past the app's own 60s limit on a request), so a query nobody waits for any more stops. No row changes. LOCKS: a plain CREATE INDEX stops writes to its table while it builds and the editor holds that to the end of the paste: on a large database run supabase/sql/RUN_REL_DB_INDEXES_CONCURRENTLY.sql first, line by line, and this part then finds every index made. Each index is made only when its table and columns are there. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.commerce_order_events') IS NULL THEN RAISE NOTICE 'part 334: commerce_order_events_creator_kind_idx skipped, public.commerce_order_events does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'creator_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'kind') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_order_events' AND column_name = 'created_at') THEN RAISE NOTICE 'part 334: commerce_order_events_creator_kind_idx skipped, public.commerce_order_events lacks a column it needs'; RETURN; END IF; IF to_regclass('public.commerce_order_events_creator_kind_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_order_events_creator_kind_idx ON public.commerce_order_events (creator_id, kind, created_at); END $do$;
DO $do$ BEGIN IF to_regclass('public.email_flow_sends') IS NULL THEN RAISE NOTICE 'part 334: email_flow_sends_creator_status_idx skipped, public.email_flow_sends does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'creator_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'email_flow_sends' AND column_name = 'sent_at') THEN RAISE NOTICE 'part 334: email_flow_sends_creator_status_idx skipped, public.email_flow_sends lacks a column it needs'; RETURN; END IF; IF to_regclass('public.email_flow_sends_creator_status_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS email_flow_sends_creator_status_idx ON public.email_flow_sends (creator_id, status, sent_at); END $do$;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 334: onepages_creator_idx skipped, public.onepages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 334: onepages_creator_idx skipped, public.onepages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.onepages_creator_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepages_creator_idx ON public.onepages (creator_id) WHERE creator_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 334: onepages_seller_idx skipped, public.onepages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'seller_id') THEN RAISE NOTICE 'part 334: onepages_seller_idx skipped, public.onepages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.onepages_seller_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepages_seller_idx ON public.onepages (seller_id) WHERE seller_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_messages') IS NULL THEN RAISE NOTICE 'part 334: community_messages_community_created_idx skipped, public.community_messages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_messages' AND column_name = 'community_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_messages' AND column_name = 'created_at') THEN RAISE NOTICE 'part 334: community_messages_community_created_idx skipped, public.community_messages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.community_messages_community_created_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_messages_community_created_idx ON public.community_messages (community_id, created_at); END $do$;
