DO $do$ BEGIN IF to_regclass('public.community_messages') IS NULL THEN RAISE NOTICE 'part 334: community_messages_reply_idx skipped, public.community_messages does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_messages' AND column_name = 'reply_to_id') THEN RAISE NOTICE 'part 334: community_messages_reply_idx skipped, public.community_messages lacks a column it needs'; RETURN; END IF; IF to_regclass('public.community_messages_reply_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_messages_reply_idx ON public.community_messages (reply_to_id) WHERE reply_to_id IS NOT NULL; END $do$;
