DO $do$ BEGIN IF to_regclass('public.community_space_reads') IS NULL THEN RAISE NOTICE 'part 334: community_space_reads_space_idx skipped, public.community_space_reads does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_space_reads' AND column_name = 'space_id') THEN RAISE NOTICE 'part 334: community_space_reads_space_idx skipped, public.community_space_reads lacks a column it needs'; RETURN; END IF; IF to_regclass('public.community_space_reads_space_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_space_reads_space_idx ON public.community_space_reads (space_id); END $do$;
DO $do$ BEGIN IF to_regclass('public.checkout_starts') IS NULL THEN RAISE NOTICE 'part 334: checkout_starts_product_idx skipped, public.checkout_starts does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'checkout_starts' AND column_name = 'product_id') THEN RAISE NOTICE 'part 334: checkout_starts_product_idx skipped, public.checkout_starts lacks a column it needs'; RETURN; END IF; IF to_regclass('public.checkout_starts_product_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS checkout_starts_product_idx ON public.checkout_starts (product_id) WHERE product_id IS NOT NULL; END $do$;
