DO $do$ BEGIN IF to_regclass('public.review_requests') IS NULL THEN RAISE NOTICE 'part 334: review_requests_product_idx skipped, public.review_requests does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'review_requests' AND column_name = 'product_id') THEN RAISE NOTICE 'part 334: review_requests_product_idx skipped, public.review_requests lacks a column it needs'; RETURN; END IF; IF to_regclass('public.review_requests_product_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS review_requests_product_idx ON public.review_requests (product_id) WHERE product_id IS NOT NULL; END $do$;
