DO $do$ BEGIN IF to_regclass('public.inventory_reservations') IS NULL THEN RAISE NOTICE 'part 334: inventory_reservations_variant_idx skipped, public.inventory_reservations does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'inventory_reservations' AND column_name = 'variant_id') THEN RAISE NOTICE 'part 334: inventory_reservations_variant_idx skipped, public.inventory_reservations lacks a column it needs'; RETURN; END IF; IF to_regclass('public.inventory_reservations_variant_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS inventory_reservations_variant_idx ON public.inventory_reservations (variant_id) WHERE variant_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.product_channel_listings') IS NULL THEN RAISE NOTICE 'part 334: product_channel_listings_product_idx skipped, public.product_channel_listings does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'product_channel_listings' AND column_name = 'product_id') THEN RAISE NOTICE 'part 334: product_channel_listings_product_idx skipped, public.product_channel_listings lacks a column it needs'; RETURN; END IF; IF to_regclass('public.product_channel_listings_product_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS product_channel_listings_product_idx ON public.product_channel_listings (product_id); END $do$;
DO $do$ BEGIN IF to_regprocedure('public.increment_product_sales(uuid)') IS NULL THEN RETURN; END IF; REVOKE ALL ON FUNCTION public.increment_product_sales(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.increment_product_sales(uuid) TO service_role; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.upsert_customer(uuid, text, text, text, text, text, integer)') IS NULL THEN RETURN; END IF; REVOKE ALL ON FUNCTION public.upsert_customer(uuid, text, text, text, text, text, integer) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.upsert_customer(uuid, text, text, text, text, text, integer) TO service_role; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.increment_creator_views(uuid, text)') IS NULL THEN RETURN; END IF; REVOKE ALL ON FUNCTION public.increment_creator_views(uuid, text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.increment_creator_views(uuid, text) TO service_role; END $do$;
