-- part 356_public_snapshots.sql
/* Stored copies of public pages (round 49, lib/edge/public-snapshot.ts). A private Storage bucket, public-snapshots: one JSON object per page of a published website, a OnePage or a community's public page, as a stranger is shown it, plus a small index per site and a record per website host (which site a connected domain is). The proxy serves a copy when the database does not answer, instead of "One moment". Written and read only by the server with the service role, which needs no policy; nothing is granted to anon or authenticated, and the bucket is not public. 4 MB per object, JSON only. Until it runs, every copy write fails quietly and pages answer exactly as before. No rows change. Safe to run again. */
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('public-snapshots', 'public-snapshots', false, 4194304, ARRAY['application/json'])
ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 4194304, allowed_mime_types = ARRAY['application/json'];
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('356', '356_public_snapshots.sql', '7ac641a31e8cb0e76929c8fbee2317f22c5fc3c969abd8f8c46cf5fbf1bc3dbb') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 360_theme_publish_jobs.sql
/* Publish as a job with a deadline (round 51, lib/website-builder/publish-job.ts). One row per press of Publish, named by the editor (its own id, so the same press sent twice is one publish): running, done or failed, with the moment it must have ended by. The editor asks for its row when the answer to its press was lost or slow, instead of spinning. Written and read only by the server with the service role; row level security on with no policy, and nothing granted to anon or authenticated. Until it runs, Publish works exactly as before and a lost answer is asked again. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_publish_jobs ( id uuid PRIMARY KEY, install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, creator_id uuid NOT NULL, status text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'failed')), error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, deadline_at timestamptz NOT NULL DEFAULT (now() + interval '150 seconds') );
CREATE INDEX IF NOT EXISTS idx_theme_publish_jobs_install ON public.theme_publish_jobs (install_id, started_at DESC);
ALTER TABLE public.theme_publish_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.theme_publish_jobs FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('360', '360_theme_publish_jobs.sql', 'd704893a20d2954e2e5f8e3f2fbc18cf0b9ae1e0033876da402f8b0cf7138add') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 363_membership_livemode.sql
/* Memberships made with Stripe's test keys (round 51, lib/memberships/sync.ts, lib/communities/membership-money.ts payingAt). One new column, memberships.livemode (boolean, empty by default): the membership sync writes false on a subscription Stripe says is in test mode, and the community MRR, paying members and the Analytics money then leave that row out. Empty means a live subscription, as every row was read before. Nothing else changes: no row is rewritten, no rule or policy. Until it runs, memberships read and sync as before. Needs part 75 (memberships); skips itself with a notice without it. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.memberships') IS NULL THEN RAISE NOTICE 'memberships.livemode skipped: public.memberships does not exist here (part 75)'; RETURN; END IF; ALTER TABLE public.memberships ADD COLUMN IF NOT EXISTS livemode boolean; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('363', '363_membership_livemode.sql', '8a09a2f61d5284b703738fae2a4fc718a8afb2fe92200ef5f23e6bdf57139bce') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 366_deleted_community_notifications.sql
/* A deleted community leaves nobody's bell (round 51, lib/communities/server/community-gone.ts). From now on a community's notifications are deleted the moment it is deleted; this clears the ones left by communities deleted before: their community_notifications rows, and the user_notifications rows that open one of their addresses (its own, below it, with a query, or an address it used to have). Rows of communities that are not deleted are not touched. A table that is not there yet is skipped. Nothing else changes. Safe to run again. */
DO $f$ BEGIN IF to_regclass('public.community_notifications') IS NOT NULL AND to_regclass('public.communities') IS NOT NULL THEN DELETE FROM public.community_notifications n USING public.communities c WHERE n.community_id = c.id AND c.deleted_at IS NOT NULL; END IF; END $f$;
DO $f$ BEGIN IF to_regclass('public.user_notifications') IS NOT NULL AND to_regclass('public.communities') IS NOT NULL THEN DELETE FROM public.user_notifications u USING public.communities c WHERE c.deleted_at IS NOT NULL AND (u.url = '/community/' || c.slug OR u.url LIKE '/community/' || c.slug || '/%' OR u.url LIKE '/community/' || c.slug || '?%'); END IF; END $f$;
DO $f$ BEGIN IF to_regclass('public.user_notifications') IS NOT NULL AND to_regclass('public.community_slug_history') IS NOT NULL THEN DELETE FROM public.user_notifications u USING public.community_slug_history h, public.communities c WHERE h.community_id = c.id AND c.deleted_at IS NOT NULL AND (u.url = '/community/' || h.slug OR u.url LIKE '/community/' || h.slug || '/%' OR u.url LIKE '/community/' || h.slug || '?%'); END IF; END $f$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('366', '366_deleted_community_notifications.sql', '49628cf429f5668299f6c6096a649f1727e7fb33c397966692f747a4f5b7fb1b') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 370_realtime_own_topic.sql
/* Live updates by broadcast, not by watching tables (round 55, lib/realtime/own-topic.ts). The bell, a community's inbox, Home's orders and a plan set from /admin used to listen with Realtime postgres_changes, which makes the database check every listener's row level security on every change to those tables (Home listened to every order of every store). Now a trigger tells only the person concerned, on their own private broadcast topic `user:<their user id>`, that something changed and which row: `notification` { table, op, id, unread, community_id for a community's }, `order` { op, id, creator_id }, `plan` { op, creator_id }. Nothing else travels; the browser reads the row again through the API it already uses. `public.storelib_own_topic_ok(topic)` lets a signed in person join only their own topic (policy "storelib own topic read" on realtime.messages, read only: nobody can send on it from a browser). `public.storelib_tell_owner` sends the message and is the server's only (no browser role may call it); a failed send never fails the write that caused it. Triggers: `storelib_tell_owner` on user_notifications (a new row, and a row raised again unread), community_notifications (a new row), orders (a new or deleted order, and a change to its status, amount or refund) and creator_plan_overrides. Until it runs, and wherever realtime.messages or realtime.send is not there or this role may not add the policy, nothing is created and the app keeps listening the old way (it notices the join is refused). A table that is not there is skipped. No rows change. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_own_topic_ok(p_topic text) RETURNS boolean LANGUAGE sql STABLE SET search_path = '' AS $f$ SELECT (SELECT auth.uid()) IS NOT NULL AND p_topic = 'user:' || (SELECT auth.uid())::text $f$;
REVOKE ALL ON FUNCTION public.storelib_own_topic_ok(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_own_topic_ok(text) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.storelib_tell_owner(p_user uuid, p_event text, p_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN IF p_user IS NULL OR p_event IS NULL THEN RETURN; END IF; PERFORM realtime.send(coalesce(p_payload, '{}'::jsonb), p_event, 'user:' || p_user::text, true); EXCEPTION WHEN OTHERS THEN RETURN; END $f$;
REVOKE ALL ON FUNCTION public.storelib_tell_owner(uuid, text, jsonb) FROM PUBLIC, anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.storelib_tell_user_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN PERFORM public.storelib_tell_owner(NEW.user_id, 'notification', jsonb_build_object('table', 'user_notifications', 'op', lower(TG_OP), 'id', NEW.id, 'unread', NEW.read_at IS NULL)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_community_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN PERFORM public.storelib_tell_owner(NEW.user_id, 'notification', jsonb_build_object('table', 'community_notifications', 'op', lower(TG_OP), 'id', NEW.id, 'unread', NEW.read_at IS NULL, 'community_id', NEW.community_id)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE v_row jsonb; v_creator uuid; v_user uuid; BEGIN v_row := to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END); v_creator := nullif(v_row ->> 'creator_id', '')::uuid; IF v_creator IS NULL AND nullif(v_row ->> 'product_id', '') IS NOT NULL THEN SELECT p.creator_id INTO v_creator FROM public.products p WHERE p.id = (v_row ->> 'product_id')::uuid; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; PERFORM public.storelib_tell_owner(v_user, 'order', jsonb_build_object('op', lower(TG_OP), 'id', v_row ->> 'id', 'creator_id', v_creator)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE v_creator uuid; v_user uuid; BEGIN v_creator := CASE WHEN TG_OP = 'DELETE' THEN OLD.creator_id ELSE NEW.creator_id END; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; PERFORM public.storelib_tell_owner(v_user, 'plan', jsonb_build_object('op', lower(TG_OP), 'creator_id', v_creator)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_tell_user_notification() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_community_notification() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_order() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_plan() FROM PUBLIC, anon, authenticated, service_role;
DO $do$ DECLARE v_when text; BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL OR to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NULL THEN RAISE NOTICE 'own topics: realtime.messages or realtime.send is not here, nothing is sent and the app keeps listening the old way.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib own topic read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib own topic read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''broadcast'' AND public.storelib_own_topic_ok(realtime.topic()))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'own topics: this role may not add policies to realtime.messages, nothing is sent and the app keeps listening the old way.'; RETURN; END; IF to_regclass('public.user_notifications') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.user_notifications'; EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner_raised ON public.user_notifications'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT ON public.user_notifications FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_user_notification()'; EXECUTE 'CREATE TRIGGER storelib_tell_owner_raised AFTER UPDATE ON public.user_notifications FOR EACH ROW WHEN (NEW.read_at IS NULL) EXECUTE FUNCTION public.storelib_tell_user_notification()'; END IF; IF to_regclass('public.community_notifications') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.community_notifications'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT ON public.community_notifications FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_community_notification()'; END IF; IF to_regclass('public.orders') IS NOT NULL AND to_regclass('public.creators') IS NOT NULL THEN SELECT string_agg(format('OLD.%1$I IS DISTINCT FROM NEW.%1$I', c.column_name), ' OR ' ORDER BY c.column_name) INTO v_when FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = 'orders' AND c.column_name IN ('status', 'amount_cents', 'refund_amount_cents', 'refunded_at', 'creator_id', 'product_id'); EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.orders'; EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner_changed ON public.orders'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT OR DELETE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_order()'; EXECUTE 'CREATE TRIGGER storelib_tell_owner_changed AFTER UPDATE ON public.orders FOR EACH ROW ' || CASE WHEN v_when IS NULL THEN '' ELSE 'WHEN (' || v_when || ') ' END || 'EXECUTE FUNCTION public.storelib_tell_order()'; END IF; IF to_regclass('public.creator_plan_overrides') IS NOT NULL AND to_regclass('public.creators') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.creator_plan_overrides'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT OR UPDATE OR DELETE ON public.creator_plan_overrides FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_plan()'; END IF; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('370', '370_realtime_own_topic.sql', 'c01c181f307567506f5fe3818e76b8eaf2cf7896900bbf63de648ff61dfc04cc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 371_warm_visited_websites.sql
/* The sites warmed after a deploy are the ones visitors used (round 55, lib/website-builder/warm-sites.ts). The server only function `public.warm_visited_websites(since)` adds up the daily analytics rollup (analytics_property_daily, part 61) per creator for websites since that day: creator_id, its page views, and its views of /products, busiest first, in one read instead of a row per site and day. The warm after each deploy then draws only those sites' front pages, and /products where it was opened, instead of every published site's six pages. Only the server may call it (service_role); nothing is stored and no rows change. Until it runs the warm reads the rollup's rows itself and draws front pages only. Needs part 61; skips itself with a notice without it. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.analytics_property_daily') IS NULL THEN RAISE NOTICE 'warm_visited_websites skipped: public.analytics_property_daily does not exist here (part 61)'; RETURN; END IF; EXECUTE $q$CREATE OR REPLACE FUNCTION public.warm_visited_websites(p_since date) RETURNS TABLE (creator_id uuid, views bigint, shop_views bigint) LANGUAGE sql STABLE SET search_path = '' AS $f$ SELECT d.creator_id, sum(d.page_views)::bigint AS views, sum(CASE WHEN jsonb_typeof(d.paths -> '/products') = 'number' THEN (d.paths ->> '/products')::numeric ELSE 0 END + CASE WHEN jsonb_typeof(d.paths -> '/products/') = 'number' THEN (d.paths ->> '/products/')::numeric ELSE 0 END)::bigint AS shop_views FROM public.analytics_property_daily d WHERE d.property_type = 'website' AND d.day >= p_since AND d.page_views > 0 GROUP BY d.creator_id ORDER BY 2 DESC, 1 $f$$q$; EXECUTE 'REVOKE ALL ON FUNCTION public.warm_visited_websites(date) FROM PUBLIC, anon, authenticated'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.warm_visited_websites(date) TO service_role'; END $do$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('371', '371_warm_visited_websites.sql', '25fbab66c2678870c77527f35a0a4d1277e886dfb489587b72c4c8755e9c9102') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 372_native_forms_leads.sql
/* Native forms/quizzes, private lead answers and prepared integrations. No anonymous direct table access. Public reads and writes use validated, rate-limited server routes. Owners see only their own definitions/leads. New tables only; no existing products, pages, contacts or orders change. Safe to run again. */
create table if not exists public.native_forms (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references auth.users(id) on delete cascade,
 title text not null default '' check (char_length(title)<=160),
 draft jsonb not null,
 published jsonb,
 revision integer not null default 0 check (revision>=0),
 status text not null default 'draft' check(status in ('draft','published','archived')),
 integration_settings jsonb not null default '{}',
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists native_forms_owner_created on public.native_forms(owner_id,created_at desc);
create table if not exists public.form_submissions (
 id uuid primary key default gen_random_uuid(),
 form_id uuid not null references public.native_forms(id) on delete cascade,
 owner_id uuid not null references auth.users(id) on delete cascade,
 form_revision integer not null,
 form_title text not null,
 answers jsonb not null,
 contact_name text,contact_email text,contact_phone text,
 score integer not null default 0,
 consent jsonb not null,
 status text not null default 'new' check(status in ('new','contacted','qualified','converted')),
 source_kind text not null default 'form' check(source_kind in ('onepage','website','creator_page','form')),
 source_url text check(char_length(source_url)<=2048),
 dedupe_key uuid not null,
 submitted_at timestamptz not null default now(),
 unique(form_id,dedupe_key)
);
create index if not exists form_submissions_owner_time on public.form_submissions(owner_id,submitted_at desc,id desc);
create index if not exists form_submissions_owner_status on public.form_submissions(owner_id,status,submitted_at desc);
create index if not exists form_submissions_form on public.form_submissions(form_id,submitted_at desc);
create table if not exists public.form_integration_jobs (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references auth.users(id) on delete cascade,
 form_id uuid not null references public.native_forms(id) on delete cascade,
 submission_id uuid not null references public.form_submissions(id) on delete cascade,
 provider text not null check(provider in ('webhook','google_sheets')),
 state text not null default 'pending_setup' check(state in ('pending_setup','ready','delivered','failed')),
 attempts integer not null default 0,
 created_at timestamptz not null default now(),
 unique(submission_id,provider)
);
alter table public.native_forms enable row level security;
alter table public.form_submissions enable row level security;
alter table public.form_integration_jobs enable row level security;
revoke all on public.native_forms,public.form_submissions,public.form_integration_jobs from public,anon,authenticated;
grant select,insert,update,delete on public.native_forms to authenticated;
grant select,delete on public.form_submissions to authenticated;
grant update(status) on public.form_submissions to authenticated;
grant select on public.form_integration_jobs to authenticated;
grant all on public.native_forms,public.form_submissions,public.form_integration_jobs to service_role;
do $f$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='native_forms' and policyname='native_forms_owner') then
 create policy native_forms_owner on public.native_forms for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid()); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='form_submissions' and policyname='form_leads_owner_read') then
 create policy form_leads_owner_read on public.form_submissions for select to authenticated using(owner_id=auth.uid()); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='form_submissions' and policyname='form_leads_owner_update') then
 create policy form_leads_owner_update on public.form_submissions for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid() and exists(select 1 from public.native_forms f where f.id=form_id and f.owner_id=auth.uid())); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='form_submissions' and policyname='form_leads_owner_delete') then
 create policy form_leads_owner_delete on public.form_submissions for delete to authenticated using(owner_id=auth.uid()); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='form_integration_jobs' and policyname='form_jobs_owner_read') then
 create policy form_jobs_owner_read on public.form_integration_jobs for select to authenticated using(owner_id=auth.uid()); end if;
end $f$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('372', '372_native_forms_leads.sql', '3f924617f7153eed4c5a949797ab0d1d8e793eacb971d7b0fef15a6ae3830311') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 373_variant_catalog_prices.sql
/* Read-only variant price facts for published products. A single Free variant is zero, never its product's old base price. Unavailable limited variants do not set a card's advertised price. No product/variant/order rows are changed. Original base prices remain intact for products with variants removed. Bounded to 500 requested products; no PII or file paths. */
create or replace function public.variant_catalog_prices(p_products uuid[])
returns table(id uuid,product_id uuid,name text,price_cents bigint,compare_at_price_cents bigint,pay_what_you_want boolean,pwyw_min_price_cents bigint,active boolean,available boolean)
language plpgsql stable security definer set search_path=public,pg_temp as $f$
declare stock_check text := 'true';
begin
 if to_regclass('public.inventory_levels') is not null and to_regclass('public.inventory_locations') is not null then
 stock_check := $stock$ (v.product_type <> 'physical' or not coalesce((to_jsonb(v)->>'track_inventory')::boolean,v.product_tracks,true) or coalesce((to_jsonb(v)->>'inventory_policy')='continue',false) or v.product_continues or coalesce((select sum(greatest(l.available,0)) from public.inventory_levels l join public.inventory_locations loc on loc.id=l.location_id where l.variant_id=v.id and loc.creator_id=v.product_creator and loc.active and loc.fulfills_orders),0)>0) $stock$;
 end if;
 return query execute $query$
 with requested as(select unnest(($1::uuid[])[1:500]) as id),
 public_variants as (
 select v.*,coalesce((to_jsonb(v)->>'active')::boolean,true) and coalesce(v.name,'') not like 'Archived %' as is_live,
 coalesce(to_jsonb(p)->>'type','digital') as product_type,
 (to_jsonb(p)->>'creator_id')::uuid as product_creator,
 coalesce((to_jsonb(p)->>'track_inventory')::boolean,true) as product_tracks,
 coalesce((to_jsonb(p)->>'continue_selling')::boolean,false) as product_continues
 from public.product_variants v join public.products p on p.id=v.product_id
 where p.id in(select r.id from requested r) and p.status='published'
 and coalesce((to_jsonb(p)->>'archived')::boolean,false)=false
 ),
 sold as (
 select o.variant_id,count(*) as n from public.orders o
 where o.status='completed' and o.variant_id in(select v.id from public_variants v where coalesce(v.max_purchases,0)>0)
 group by o.variant_id
 )
 select v.id,v.product_id,v.name,v.price_cents::bigint,
 (to_jsonb(v)->>'compare_at_price_cents')::bigint,
 coalesce((to_jsonb(v)->>'pay_what_you_want')::boolean,false),
 (to_jsonb(v)->>'pwyw_min_price_cents')::bigint,v.is_live,
 v.is_live and (coalesce(v.max_purchases,0)<=0 or coalesce(s.n,0)<v.max_purchases) and ($query$ || stock_check || $query$)
 from public_variants v left join sold s on s.variant_id=v.id $query$ using p_products;
end;
$f$;
revoke all on function public.variant_catalog_prices(uuid[]) from public;
grant execute on function public.variant_catalog_prices(uuid[]) to anon,authenticated,service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('373', '373_variant_catalog_prices.sql', 'a22d8966a3c721ddac6197f80b2e7005aaa92d0615c5474ff594aecb099dcaa5') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 374_atomic_product_channels.sql
/* Atomic product sales-channel settings. Creates only missing channel infrastructure, preserves all existing listings, and resolves channel keys inside one locked transaction. The server derives the creator from the authenticated caller. Only service_role may call the writer; anonymous visitors cannot read either table directly. Invalid keys roll the whole write back. Safe to run again. */
create table if not exists public.sales_channels(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.creators(id) on delete cascade,name text not null,description text,is_storefront boolean not null default false,enabled boolean not null default true,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.sales_channels add column if not exists kind text not null default 'custom';
update public.sales_channels set kind='storefront' where is_storefront and kind='custom';
create unique index if not exists sales_channels_one_of_kind on public.sales_channels(creator_id,kind) where kind<>'custom';
create table if not exists public.product_channel_listings(channel_id uuid not null references public.sales_channels(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,creator_id uuid not null references public.creators(id) on delete cascade,listed boolean not null default true,updated_at timestamptz not null default now(),primary key(channel_id,product_id));
create index if not exists product_channel_listings_off_idx on public.product_channel_listings(creator_id,product_id) where not listed;
alter table public.sales_channels enable row level security;
alter table public.product_channel_listings enable row level security;
revoke all on public.sales_channels,public.product_channel_listings from public,anon;
revoke insert,update,delete on public.sales_channels,public.product_channel_listings from authenticated;
grant select on public.sales_channels,public.product_channel_listings to authenticated;
grant all on public.sales_channels,public.product_channel_listings to service_role;
DO $p$ BEGIN IF NOT EXISTS(select 1 from pg_policies where schemaname='public' and tablename='sales_channels' and policyname='sales_channels_owner_read') THEN CREATE POLICY sales_channels_owner_read ON public.sales_channels FOR SELECT TO authenticated USING(EXISTS(select 1 from public.creators c where c.id=creator_id and c.user_id=auth.uid())); END IF; IF NOT EXISTS(select 1 from pg_policies where schemaname='public' and tablename='product_channel_listings' and policyname='product_channel_listings_owner_read') THEN CREATE POLICY product_channel_listings_owner_read ON public.product_channel_listings FOR SELECT TO authenticated USING(EXISTS(select 1 from public.creators c where c.id=creator_id and c.user_id=auth.uid())); END IF; END $p$;
create or replace function public.set_product_channels_atomic(p_creator uuid,p_product uuid,p_off text[])
returns uuid[] language plpgsql security definer set search_path=public,pg_temp as $f$
declare channel_key text;channel uuid;kept uuid[]:='{}';channel_name text;
begin
 if p_off is null or coalesce(array_length(p_off,1),0)>64 then raise exception 'Invalid channel selection' using errcode='22023';end if;
 perform 1 from public.products where id=p_product and creator_id=p_creator for update;
 if not found then raise exception 'Product not found' using errcode='P0002';end if;
 foreach channel_key in array p_off loop
  channel:=null;
  if channel_key in('storefront','creator_page','marketplace') then
   channel_name:=case channel_key when 'storefront' then 'Online store' when 'creator_page' then 'Creator page' else 'Marketplace' end;
   insert into public.sales_channels(creator_id,kind,name,is_storefront,enabled,position) values(p_creator,channel_key,channel_name,channel_key='storefront',true,case channel_key when 'storefront' then 0 when 'creator_page' then 1 else 2 end) on conflict(creator_id,kind) where kind<>'custom' do nothing;
   select id into channel from public.sales_channels where creator_id=p_creator and kind=channel_key;
  elsif channel_key~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   select id into channel from public.sales_channels where id=channel_key::uuid and creator_id=p_creator;
  end if;
  if channel is null then raise exception 'Unknown sales channel' using errcode='22023';end if;
  if not channel=any(kept) then kept:=array_append(kept,channel);end if;
 end loop;
 delete from public.product_channel_listings where creator_id=p_creator and product_id=p_product and not(channel_id=any(kept));
 insert into public.product_channel_listings(channel_id,product_id,creator_id,listed,updated_at) select k,p_product,p_creator,false,now() from unnest(kept) k on conflict(channel_id,product_id) do update set listed=false,updated_at=excluded.updated_at;
 return kept;
end;
$f$;
revoke all on function public.set_product_channels_atomic(uuid,uuid,text[]) from public,anon,authenticated;
grant execute on function public.set_product_channels_atomic(uuid,uuid,text[]) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('374', '374_atomic_product_channels.sql', '0f41aab50031f3114dd2510d648d63d33cc4608f97e9ecb08683854b367b3ed5') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 376_business_handoff.sql
/* Business handoff: a founder gives a business they built for a client (a business account on the founder's login, part 39) to the client's own login, through a claim link. Two new server only tables: business_handoffs (one open claim link per business, only the SHA-256 of its token kept, optionally bound to the recipient's email, an expiry, and whether the founder stays on the team) and business_handoff_events (created, sent, renewed, viewed, accepted, finished, revoked and failed, with who, from where and when). And business_handoff_accept, which hands the business over in one transaction after checking the link, its expiry and single use, the recipient's email, that the recipient is not the founder, and the recipient's three business limit: the business's link in business_links moves from the founder's login to the recipient's and nothing the business owns is rewritten, so its account id, creator id, username, OnePage, store, domains and file paths stay exactly as they are. The founder's payout accounts (Stripe Connect, PayPal, Airwallex), billing customer and saved cards, AI keys, agent and analytics tokens, GitHub link, devices and pending sign in codes are detached from it, its team is cleared, and the founder is added back as a team member only when they chose to stay. A business on a running paid plan or with live paid memberships is refused, so nobody keeps paying for somebody else's business. Any failed check raises and nothing changes. Only the service role may call it. Additive: no existing column changes, and no existing row changes until a handoff is accepted. */
create table if not exists public.business_handoffs (id uuid primary key default gen_random_uuid(), business_user_id uuid not null references auth.users(id) on delete cascade, creator_id uuid references public.creators(id) on delete cascade, from_owner_id uuid not null references auth.users(id) on delete cascade, created_by uuid references auth.users(id) on delete set null, token_hash text not null, recipient_email text, keep_founder boolean not null default false, founder_access text not null default 'full', ttl_days integer not null default 7, status text not null default 'pending', expires_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_sent_at timestamptz, send_count integer not null default 0, accepted_at timestamptz, accepted_by uuid references auth.users(id) on delete set null, revoked_at timestamptz, revoked_by uuid references auth.users(id) on delete set null, finished_at timestamptz, result jsonb, constraint business_handoffs_token_hash_key unique (token_hash), constraint business_handoffs_token_hash_check check (token_hash ~ '^[0-9a-f]{64}$'), constraint business_handoffs_status_check check (status in ('pending', 'accepted', 'revoked', 'expired')), constraint business_handoffs_access_check check (founder_access in ('full', 'content', 'support')), constraint business_handoffs_ttl_check check (ttl_days between 1 and 30), constraint business_handoffs_send_count_check check (send_count between 0 and 1000), constraint business_handoffs_email_check check (recipient_email is null or (recipient_email = lower(recipient_email) and char_length(recipient_email) between 3 and 254 and position('@' in recipient_email) > 1)), constraint business_handoffs_not_self check (business_user_id <> from_owner_id));
create unique index if not exists business_handoffs_one_open on public.business_handoffs (business_user_id) where status = 'pending';
create index if not exists business_handoffs_business_created on public.business_handoffs (business_user_id, created_at desc);
create index if not exists business_handoffs_owner_created on public.business_handoffs (from_owner_id, created_at desc);
create index if not exists business_handoffs_accepted_by on public.business_handoffs (accepted_by, accepted_at desc) where status = 'accepted';
create table if not exists public.business_handoff_events (id bigint generated always as identity primary key, handoff_id uuid references public.business_handoffs(id) on delete set null, business_user_id uuid, event text not null, actor_id uuid, ip text, user_agent text, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), constraint business_handoff_events_event_check check (event in ('created', 'sent', 'renewed', 'viewed', 'accepted', 'finished', 'revoked', 'failed')), constraint business_handoff_events_ip_check check (ip is null or char_length(ip) <= 64), constraint business_handoff_events_ua_check check (user_agent is null or char_length(user_agent) <= 300));
create index if not exists business_handoff_events_handoff_created on public.business_handoff_events (handoff_id, created_at desc);
create index if not exists business_handoff_events_business_created on public.business_handoff_events (business_user_id, created_at desc);
alter table public.business_handoffs enable row level security;
alter table public.business_handoff_events enable row level security;
revoke all on public.business_handoffs, public.business_handoff_events from public, anon, authenticated;
grant all on public.business_handoffs, public.business_handoff_events to service_role;
grant usage, select on sequence public.business_handoff_events_id_seq to service_role;
grant select (id, business_user_id, creator_id, from_owner_id, recipient_email, keep_founder, founder_access, ttl_days, status, expires_at, created_at, updated_at, last_sent_at, send_count, accepted_at, revoked_at, finished_at) on public.business_handoffs to authenticated;
grant select (id, handoff_id, business_user_id, event, created_at) on public.business_handoff_events to authenticated;
drop policy if exists business_handoffs_owner_read on public.business_handoffs;
create policy business_handoffs_owner_read on public.business_handoffs for select to authenticated using ((select auth.uid()) = business_user_id or (select auth.uid()) = from_owner_id);
drop policy if exists business_handoff_events_owner_read on public.business_handoff_events;
create policy business_handoff_events_owner_read on public.business_handoff_events for select to authenticated using ((select auth.uid()) = business_user_id);
create or replace function public.business_handoff_accept(p_handoff uuid, p_token_hash text, p_recipient uuid, p_recipient_email text, p_founder_email text, p_ip text, p_user_agent text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $f$
declare
 h public.business_handoffs%rowtype;
 v_creator uuid;
 v_row jsonb := '{}'::jsonb;
 v_stripe text;
 v_email text := lower(btrim(coalesce(p_recipient_email, '')));
 v_auth_email text;
 v_count integer;
 v_n integer;
 v_col text;
 v_val text;
 v_counts jsonb := '{}'::jsonb;
 v_detached jsonb := '{}'::jsonb;
 v_perms text[];
 v_accounts jsonb;
 v_result jsonb;
begin
 if p_handoff is null or p_recipient is null or coalesce(p_token_hash, '') !~ '^[0-9a-f]{64}$' then
  raise exception 'handoff_invalid' using errcode = '22023';
 end if;
 select * into h from public.business_handoffs where id = p_handoff and token_hash = p_token_hash for update;
 if not found then raise exception 'handoff_not_found' using errcode = 'P0002'; end if;
 if h.status = 'accepted' then raise exception 'handoff_used' using errcode = '55000'; end if;
 if h.status = 'revoked' then raise exception 'handoff_revoked' using errcode = '55000'; end if;
 if h.status = 'expired' or h.expires_at <= now() then raise exception 'handoff_expired' using errcode = '55000'; end if;
 perform 1 from public.business_links where member_id = h.business_user_id and owner_id = h.from_owner_id for update;
 if not found then raise exception 'handoff_stale' using errcode = '55000'; end if;
 if p_recipient = h.business_user_id or p_recipient = h.from_owner_id or exists (select 1 from public.business_links where owner_id = h.from_owner_id and member_id = p_recipient) then
  raise exception 'handoff_self' using errcode = '42501';
 end if;
 if exists (select 1 from public.business_links where member_id = p_recipient) then
  raise exception 'handoff_recipient_is_business' using errcode = '42501';
 end if;
 select lower(u.email) into v_auth_email from auth.users u where u.id = p_recipient;
 if not found then raise exception 'handoff_recipient_missing' using errcode = 'P0002'; end if;
 if v_email <> '' and v_auth_email is distinct from v_email then raise exception 'handoff_wrong_email' using errcode = '42501'; end if;
 if h.recipient_email is not null and v_email is distinct from h.recipient_email then raise exception 'handoff_wrong_email' using errcode = '42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('business_links ' || p_recipient::text, 0));
 select count(*) into v_count from public.business_links where owner_id = p_recipient;
 if 1 + v_count >= 3 then raise exception 'handoff_limit' using errcode = '23514'; end if;
 select c.id into v_creator from public.creators c where c.user_id = h.business_user_id for update;
 if v_creator is not null then
  select to_jsonb(c) into v_row from public.creators c where c.id = v_creator;
  if to_regclass('public.subscriptions') is not null and exists (select 1 from public.subscriptions s where s.creator_id = v_creator and s.stripe_subscription_id is not null and s.status in ('active', 'trialing', 'past_due', 'unpaid', 'incomplete')) then
   raise exception 'handoff_paid_plan' using errcode = '55000';
  end if;
  if to_regclass('public.memberships') is not null and exists (select 1 from public.memberships m where m.creator_id = v_creator and m.status in ('active', 'trialing', 'past_due')) then
   raise exception 'handoff_live_memberships' using errcode = '55000';
  end if;
 end if;
 delete from public.business_links where member_id = h.business_user_id;
 insert into public.business_links (owner_id, member_id) values (p_recipient, h.business_user_id);
 if v_creator is not null then
  v_stripe := nullif(v_row ->> 'stripe_account_id', '');
  v_detached := jsonb_strip_nulls(jsonb_build_object('stripe_account_id', v_stripe, 'stripe_customer_id', nullif(v_row ->> 'stripe_customer_id', ''), 'paypal_merchant_id', nullif(v_row ->> 'paypal_merchant_id', '')));
  for v_col, v_val in select k, v from (values
   ('stripe_customer_id', null), ('paypal_merchant_id', null)
  ) as t(k, v) loop
   if v_row ? v_col then execute format('update public.creators set %I = %L where id = $1', v_col, v_val) using v_creator; end if;
  end loop;
  if v_stripe is not null then
   for v_col, v_val in select k, v from (values
    ('stripe_account_id', null), ('stripe_onboarding_status', 'not_connected'), ('charges_enabled', 'false'), ('payouts_enabled', 'false'), ('details_submitted', 'false'),
    ('stripe_requirements', '{}'), ('stripe_requirements_due_at', null), ('stripe_requirements_updated_at', now()::text), ('payments_status', 'NOT_STARTED'), ('last_stripe_sync_at', now()::text),
    ('can_accept_payments', 'false'), ('stripe_transfers_status', null), ('stripe_disabled_reason', null), ('stripe_pending_verification', '{}'), ('stripe_eventually_due', '{}'),
    ('stripe_requirement_errors', '{}'), ('payout_destination', null), ('stripe_previous_account_id', v_stripe), ('stripe_account_reset_at', now()::text), ('stripe_account_reset_reason', 'creator_disconnect')
   ) as t(k, v) loop
    if v_row ? v_col then execute format('update public.creators set %I = %L where id = $1', v_col, v_val) using v_creator; end if;
   end loop;
  end if;
  if to_regclass('public.payment_accounts') is not null then
   select coalesce(jsonb_agg(jsonb_build_object('provider', a.provider, 'account', a.provider_account_id, 'status', a.lifecycle_status)), '[]'::jsonb) into v_accounts from public.payment_accounts a where a.creator_id = v_creator;
   if v_accounts <> '[]'::jsonb then v_detached := v_detached || jsonb_build_object('payment_accounts', v_accounts); end if;
   delete from public.payment_accounts where creator_id = v_creator;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('payment_accounts', v_n);
  end if;
  if to_regclass('public.payment_balances') is not null then
   delete from public.payment_balances where creator_id = v_creator;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('payment_balances', v_n);
  end if;
  if to_regclass('public.payment_methods') is not null then
   delete from public.payment_methods where creator_id = v_creator;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('payment_methods', v_n);
  end if;
  if to_regclass('public.creator_ai_keys') is not null then
   delete from public.creator_ai_keys where creator_id = v_creator;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('creator_ai_keys', v_n);
  end if;
  if to_regclass('public.theme_github_links') is not null then
   delete from public.theme_github_links where creator_id = v_creator;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('theme_github_links', v_n);
  end if;
  if to_regclass('public.theme_agent_tokens') is not null then
   update public.theme_agent_tokens set revoked_at = now() where creator_id = v_creator and revoked_at is null;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('theme_agent_tokens', v_n);
  end if;
  if to_regclass('public.analytics_api_tokens') is not null then
   update public.analytics_api_tokens set revoked_at = now() where creator_id = v_creator and revoked_at is null;
   get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('analytics_api_tokens', v_n);
  end if;
 end if;
 if to_regclass('public.store_team_members') is not null then
  delete from public.store_team_members where creator_id = v_creator or user_id = h.business_user_id;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('store_team_members', v_n);
 end if;
 if to_regclass('public.push_tokens') is not null then
  delete from public.push_tokens where user_id = h.business_user_id;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('push_tokens', v_n);
 end if;
 if to_regclass('public.account_delete_codes') is not null then
  delete from public.account_delete_codes where user_id = h.business_user_id;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('account_delete_codes', v_n);
 end if;
 if to_regclass('public.email_change_codes') is not null then
  delete from public.email_change_codes where user_id = h.business_user_id;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('email_change_codes', v_n);
 end if;
 if to_regclass('public.password_reset_requests') is not null then
  delete from public.password_reset_requests where user_id = h.business_user_id and coalesce(used, false) = false;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('password_reset_requests', v_n);
 end if;
 if to_regclass('public.verification_codes') is not null then
  delete from public.verification_codes where user_id = h.business_user_id and used_at is null;
  get diagnostics v_n = row_count; v_counts := v_counts || jsonb_build_object('verification_codes', v_n);
 end if;
 if h.keep_founder and v_creator is not null then
  if to_regclass('public.store_team_members') is null then raise exception 'handoff_team_missing' using errcode = '55000'; end if;
  if coalesce(p_founder_email, '') !~ '^[^@[:space:]]+@[^@[:space:]]+$' then raise exception 'handoff_founder_email' using errcode = '22023'; end if;
  v_perms := case h.founder_access
   when 'content' then array['website', 'onepage', 'creator_pages', 'products', 'community']
   when 'support' then array['orders', 'customers']
   else array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings'] end;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'store_team_members' and column_name = 'permissions') then
   execute 'insert into public.store_team_members (creator_id, email, user_id, role, permissions, status, invited_by, invited_at, accepted_at) values ($1, $2, $3, $4, $5, ''active'', $3, now(), now())'
    using v_creator, lower(btrim(p_founder_email)), h.from_owner_id, case h.founder_access when 'content' then 'staff' else 'manager' end, v_perms;
  else
   insert into public.store_team_members (creator_id, email, user_id, role, status, invited_by, invited_at, accepted_at) values (v_creator, lower(btrim(p_founder_email)), h.from_owner_id, 'manager', 'active', h.from_owner_id, now(), now());
  end if;
 end if;
 v_result := jsonb_build_object('business_user_id', h.business_user_id, 'creator_id', v_creator, 'from_owner_id', h.from_owner_id, 'recipient_id', p_recipient, 'kept_founder', h.keep_founder and v_creator is not null, 'founder_access', h.founder_access, 'cleared', v_counts, 'detached', v_detached);
 update public.business_handoffs set status = 'accepted', accepted_at = now(), accepted_by = p_recipient, updated_at = now(), creator_id = coalesce(v_creator, creator_id), result = v_result where id = h.id;
 insert into public.business_handoff_events (handoff_id, business_user_id, event, actor_id, ip, user_agent, detail) values (h.id, h.business_user_id, 'accepted', p_recipient, left(p_ip, 64), left(p_user_agent, 300), v_result);
 return v_result;
end;
$f$;
revoke all on function public.business_handoff_accept(uuid, text, uuid, text, text, text, text) from public, anon, authenticated;
grant execute on function public.business_handoff_accept(uuid, text, uuid, text, text, text, text) to service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('376', '376_business_handoff.sql', 'c23c2e5d02d360a25a8c480af5722829c2390412d5db0b7af0824a668d75fa07') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

notify pgrst, 'reload schema';
select 'Storelib file 3 of 4 ran. Next file.' as done;
